                    .addi => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127; // sC2int
                        if (lb == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int +% imm };
                        } else if (lb == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num + @as(f64, @floatFromInt(imm)) };
                        } else {
                            @branchHint(.unlikely);
                            // Peek the next instruction (MMBINI) to determine
                            // whether this ADDI encodes a genuine `+` (TMS_ADD)
                            // or a `-` transformed via finishbinexpneg (TMS_SUB).
                            // When TMS_SUB, the original operand is K
                            // (non-negated), stored in the MMBINI's B field as
                            // int2sC(K); the metamethod is __sub, not __add.
                            var tm_str: []const u8 = "__add";
                            var tm_name: []const u8 = "add";
                            var orig_imm = imm;
                            const next_pc = ctx.pc + 1;
                            if (next_pc < ctx.cur_proto.code.len) {
                                const next_inst = ctx.cur_proto.code[next_pc];
                                if (@as(bc.Op, @enumFromInt(next_inst.op)) == .mmbini) {
                                    const event = next_inst.c;
                                    if (event == TMS_SUB) {
                                        tm_str = "__sub";
                                        tm_name = "sub";
                                        // MMBINI's B field carries int2sC(K)
                                        // (the original, non-negated K).
                                        orig_imm = @as(i64, next_inst.b) - 127;
                                    }
                                }
                            }
                            const rc: Value = .{ .Int = orig_imm };
                            const flip = inst.k != 0;
                            const m1 = if (flip) rc else lb;
                            const m2 = if (flip) lb else rc;
                            if (coerceArithmeticValue(lb) == null and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                m1,
                                m2,
                                tm_str,
                                tm_name,
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            // For the eval path, use the original operator
                            // (.Minus when TMS_SUB, .Plus otherwise) so error
                            // messages and fallback semantics match the
                            // source-level operation.
                            const orig_op: TokenKind = if (std.mem.eql(u8, tm_str, "__sub")) .Minus else .Plus;
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, orig_op, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // ADDK: R[A] = R[B] + K[C]:number
                    .addk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int +% rc.Int };
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num + rc.Num };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) + rc.Num };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num + @as(f64, @floatFromInt(rc.Int)) };
                        } else {
                            @branchHint(.unlikely);
                            // PUC flip: if next instruction is MMBINK with
                            // flip bit (C & 0x80), swap metamethod operands
                            // to match original source order.
                            const flip = inst.k != 0;
                            const m1 = if (flip) rc else lb;
                            const m2 = if (flip) lb else rc;
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                m1,
                                m2,
                                "__add",
                                "add",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Plus, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // SUBK: R[A] = R[B] - K[C]:number
                    .subk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int -% rc.Int };
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num - rc.Num };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) - rc.Num };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num - @as(f64, @floatFromInt(rc.Int)) };
                        } else {
                            @branchHint(.unlikely);
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                "__sub",
                                "sub",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Minus, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // MULK: R[A] = R[B] * K[C]:number
                    .mulk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Int = lb.Int *% rc.Int };
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num * rc.Num };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) * rc.Num };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num * @as(f64, @floatFromInt(rc.Int)) };
                        } else {
                            @branchHint(.unlikely);
                            const flip = inst.k != 0;
                            const m1 = if (flip) rc else lb;
                            const m2 = if (flip) lb else rc;
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                m1,
                                m2,
                                "__mul",
                                "mul",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Star, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // MODK: R[A] = R[B] % K[C]:number
                    .modk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            const li = lb.Int;
                            const ri = rc.Int;
                            if (ri == 0) {
                                exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                                return self.fail("attempt to perform 'n%0'", .{});
                            }
                            if (li == std.math.minInt(i64) and ri == -1) {
                                ctx.regs[a] = .{ .Int = 0 };
                            } else {
                                @branchHint(.unlikely);
                                var rem = @rem(li, ri);
                                if (rem != 0 and ((rem ^ ri) < 0)) rem += ri;
                                ctx.regs[a] = .{ .Int = rem };
                            }
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = luaNumMod(lb.Num, rc.Num) };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = luaNumMod(@as(f64, @floatFromInt(lb.Int)), rc.Num) };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = luaNumMod(lb.Num, @as(f64, @floatFromInt(rc.Int))) };
                        } else {
                            @branchHint(.unlikely);
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                "__mod",
                                "mod",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Percent, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // POWK: R[A] = R[B] ^ K[C]:number
                    .powk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, @as(f64, @floatFromInt(lb.Int)), @as(f64, @floatFromInt(rc.Int))) };
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, lb.Num, rc.Num) };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, @as(f64, @floatFromInt(lb.Int)), rc.Num) };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = std.math.pow(f64, lb.Num, @as(f64, @floatFromInt(rc.Int))) };
                        } else {
                            @branchHint(.unlikely);
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                "__pow",
                                "pow",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Caret, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // DIVK: R[A] = R[B] / K[C]:number
                    .divk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) / @as(f64, @floatFromInt(rc.Int)) };
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = lb.Num / rc.Num };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @as(f64, @floatFromInt(lb.Int)) / rc.Num };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = lb.Num / @as(f64, @floatFromInt(rc.Int)) };
                        } else {
                            @branchHint(.unlikely);
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                "__div",
                                "div",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Slash, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // IDIVK: R[A] = R[B] // K[C]:number
                    .idivk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        if (lb == .Int and rc == .Int) {
                            const ri = rc.Int;
                            if (ri == 0) {
                                exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                                return self.fail("attempt to divide by zero", .{});
                            }
                            if (lb.Int == std.math.minInt(i64) and ri == -1) {
                                ctx.regs[a] = .{ .Int = std.math.minInt(i64) };
                            } else {
                                @branchHint(.unlikely);
                                ctx.regs[a] = .{ .Int = @divFloor(lb.Int, ri) };
                            }
                        } else if (lb == .Num and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @floor(lb.Num / rc.Num) };
                        } else if (lb == .Int and rc == .Num) {
                            ctx.regs[a] = .{ .Num = @floor(@as(f64, @floatFromInt(lb.Int)) / rc.Num) };
                        } else if (lb == .Num and rc == .Int) {
                            ctx.regs[a] = .{ .Num = @floor(lb.Num / @as(f64, @floatFromInt(rc.Int))) };
                        } else {
                            @branchHint(.unlikely);
                            if ((coerceArithmeticValue(lb) == null or coerceArithmeticValue(rc) == null) and try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                "__idiv",
                                "idiv",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Idiv, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // --- Bitwise: constant variants ---
                    // BANDK: R[A] = R[B] & K[C]:integer
                    .bandk => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        const li = valueToIntForBitwise(lb);
                        const ri = valueToIntForBitwise(rc);
                        if (li != null and ri != null) {
                            ctx.regs[a] = .{ .Int = li.? & ri.? };
                        } else {
                            @branchHint(.unlikely);
                            const flip = inst.k != 0;
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                if (flip) rc else lb,
                                if (flip) lb else rc,
                                "__band",
                                "band",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Amp, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },
                    .bork => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        const li = valueToIntForBitwise(lb);
                        const ri = valueToIntForBitwise(rc);
                        if (li != null and ri != null) {
                            ctx.regs[a] = .{ .Int = li.? | ri.? };
                        } else {
                            @branchHint(.unlikely);
                            const flip = inst.k != 0;
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                if (flip) rc else lb,
                                if (flip) lb else rc,
                                "__bor",
                                "bor",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Pipe, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },
                    .bxork => {
                        const lb = ctx.regs[b];
                        const rc = ctx.cur_proto.resolved_values[c];
                        const li = valueToIntForBitwise(lb);
                        const ri = valueToIntForBitwise(rc);
                        if (li != null and ri != null) {
                            ctx.regs[a] = .{ .Int = li.? ^ ri.? };
                        } else {
                            @branchHint(.unlikely);
                            const flip = inst.k != 0;
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                if (flip) rc else lb,
                                if (flip) lb else rc,
                                "__bxor",
                                "bxor",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Tilde, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // --- Shifts: immediate variants ---
                    // SHLI: R[A] = sC << R[B]  (sC = C - 127)
                    .shli => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127;
                        const ri = valueToIntForBitwise(lb);
                        if (ri != null) {
                            ctx.regs[a] = .{ .Int = shiftLeft(imm, ri.?) };
                        } else {
                            @branchHint(.unlikely);
                            const rc: Value = .{ .Int = imm };
                            // PUC 5.5: k-bit carries the commutative flip flag.
                            // SHLI always has k=1 (constant on LEFT), so the
                            // metamethod receives (constant, register) = (LHS, RHS).
                            const flip = inst.k != 0;
                            const m1 = if (flip) rc else lb;
                            const m2 = if (flip) lb else rc;
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                m1,
                                m2,
                                "__shl",
                                "shl",
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, .Shl, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },
                    // SHRI: R[A] = R[B] >> sC  (sC = C - 127)
                    // Also used for `x << K` via finishbinexpneg: the shift is
                    // coded as `x >> (-K)`, with the following MMBINI carrying
                    // TMS_SHL (not TMS_SHR) and B = int2sC(K) (original K).
                    // The handler peeks the next MMBINI to determine which
                    // metamethod to call and what the original operand was.
                    .shri => {
                        const lb = ctx.regs[b];
                        const imm: i64 = @as(i64, c) - 127;
                        const li = valueToIntForBitwise(lb);
                        if (li != null) {
                            ctx.regs[a] = .{ .Int = shiftRight(li.?, imm) };
                        } else {
                            @branchHint(.unlikely);
                            // Peek the next instruction (MMBINI) to determine
                            // whether this SHRI encodes a genuine `>>` (TMS_SHR)
                            // or a `<<` transformed via finishbinexpneg (TMS_SHL).
                            // When TMS_SHL, the original shift amount is K
                            // (non-negated), stored in the MMBINI's B field as
                            // int2sC(K); the metamethod is __shl, not __shr.
                            var tm_str: []const u8 = "__shr";
                            var tm_name: []const u8 = "shr";
                            var orig_imm = imm;
                            const next_pc = ctx.pc + 1;
                            if (next_pc < ctx.cur_proto.code.len) {
                                const next_inst = ctx.cur_proto.code[next_pc];
                                if (@as(bc.Op, @enumFromInt(next_inst.op)) == .mmbini) {
                                    const event = next_inst.c;
                                    if (event == TMS_SHL) {
                                        tm_str = "__shl";
                                        tm_name = "shl";
                                        // MMBINI's B field carries int2sC(K)
                                        // (the original, non-negated K).
                                        orig_imm = @as(i64, next_inst.b) - 127;
                                    }
                                }
                            }
                            const rc: Value = .{ .Int = orig_imm };
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                lb,
                                rc,
                                tm_str,
                                tm_name,
                                .{ .value = .{ .dst = a } },
                            )) {
                                continue :frame_loop;
                            }
                            // For the eval path, use the original operator
                            // (.Shl when TMS_SHL, .Shr otherwise) so error
                            // messages and fallback semantics match the
                            // source-level operation.
                            const orig_op: TokenKind = if (std.mem.eql(u8, tm_str, "__shl")) .Shl else .Shr;
                            const result = try self.evalBytecodeBinOpValues(ctx.cur_proto, ctx.pc, orig_op, b, lb, rc);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },

                    // --- Metamethod bookkeeping (PUC 5.5 MMBIN family) ---
                    // No-ops in luazig: metamethods are handled inline in the
                    // arithmetic/bitwise opcodes above. These exist for bytecode
                    // parity with PUC 5.5 and will be emitted by the compiler
                    // in a later task.
                    .mmbin, .mmbini, .mmbink => {},

                    .unm => {
                        const val = ctx.regs[b];
                        // Fast path: numeric operands avoid coerceArithmeticValue
                        // and function call overhead.
                        if (val == .Int) {
                            ctx.regs[a] = .{ .Int = -%val.Int };
                        } else if (val == .Num) {
                            ctx.regs[a] = .{ .Num = -val.Num };
                        } else {
                            @branchHint(.unlikely);
                            if (coerceArithmeticValue(val) == null and try self.tryPushBytecodeUnaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                val,
                                "__unm",
                                "unm",
                                a,
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeUnOp(ctx.cur_proto, ctx.pc, .Minus, b, val);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },
                    .bnot => {
                        const val = ctx.regs[b];
                        if (val == .Int) {
                            ctx.regs[a] = .{ .Int = ~val.Int };
                        } else {
                            @branchHint(.unlikely);
                            if (valueToIntForBitwise(val) == null and try self.tryPushBytecodeUnaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                val,
                                "__bnot",
                                "bnot",
                                a,
                            )) {
                                continue :frame_loop;
                            }
                            const result = try self.evalBytecodeUnOp(ctx.cur_proto, ctx.pc, .Tilde, b, val);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[a] = result;
                        }
                    },
                    .not => ctx.regs[a] = try self.evalUnOp(.Not, ctx.regs[b]),
                    .len => {
                        const val = ctx.regs[b];
                        const needs_len_metamethod = val != .String and metamethodValue(self, val, "__len") != null;
                        if (needs_len_metamethod and try self.tryPushBytecodeUnaryMetamethod(
                            exec_frames,
                            ctx.frame_index,
                            val,
                            "__len",
                            "len",
                            a,
                        )) {
                            continue :frame_loop;
                        }
                        const result = try self.evalUnOp(.Hash, val);
                        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                        ctx.regs[a] = result;
                    },

                    .concat => {
                        switch (try self.opConcat(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                        // PUC: checkGC(L, L->top.p) after luaV_concat.
                        try self.condGcFromDispatch(&ctx);
                    },

                    // --- Comparisons ---
                    // EQ/LT/LE: if (R[A] op R[B]) != (C!=0) then ctx.pc++
                    // Snapshot operands — comparison may trigger metamethod.
                    .eq => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        // Fast path: valuesEqual handles Int/Num/Bool/String/Nil
                        // comparisons directly. Only Table==Table and
                        // Userdata==Userdata with different identity need
                        // the __eq metamethod (PUC luaV_equalobj).
                        const result: bool = blk: {
                            if (valuesEqual(la, lb)) break :blk true;
                            // PUC luaV_equalobj: __eq only when both operands
                            // are the same type (Table/Table or Userdata/Userdata).
                            if ((la == .Table and lb == .Table) or
                                (la == .Userdata and lb == .Userdata))
                            {
                                if (try self.tryPushBytecodeBinaryMetamethod(
                                    exec_frames,
                                    ctx.frame_index,
                                    la,
                                    lb,
                                    "__eq",
                                    "eq",
                                    .{ .compare = .{ .invert = c != 0 } },
                                ))
                                {
                                    continue :frame_loop;
                                }
                            }
                            break :blk false;
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },
                    .lt => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        // Fast path: inline numeric and string comparisons to
                        // avoid bytecodeComparisonHasFastPath + cmpLt overhead.
                        const result: bool = blk: {
                            if (la == .Int and lb == .Int) break :blk la.Int < lb.Int;
                            if (la == .Num and lb == .Num) break :blk la.Num < lb.Num;
                            if (la == .Int and lb == .Num) break :blk intLtNum(la.Int, lb.Num);
                            if (la == .Num and lb == .Int) break :blk numLtInt(la.Num, lb.Int);
                            if (la == .String and lb == .String) break :blk std.mem.order(u8, la.String.bytes(), lb.String.bytes()) == .lt;
                            // Slow path: metamethod or error.
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                la,
                                lb,
                                "__lt",
                                "lt",
                                .{ .compare = .{ .invert = c != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLt(la, lb);
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },
                    .le => {
                        const la = ctx.regs[a];
                        const lb = ctx.regs[b];
                        const result: bool = blk: {
                            if (la == .Int and lb == .Int) break :blk la.Int <= lb.Int;
                            if (la == .Num and lb == .Num) break :blk la.Num <= lb.Num;
                            if (la == .Int and lb == .Num) break :blk intLeNum(la.Int, lb.Num);
                            if (la == .Num and lb == .Int) break :blk numLeInt(la.Num, lb.Int);
                            if (la == .String and lb == .String) {
                                const ord = std.mem.order(u8, la.String.bytes(), lb.String.bytes());
                                break :blk ord == .lt or ord == .eq;
                            }
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                la,
                                lb,
                                "__le",
                                "le",
                                .{ .compare = .{ .invert = c != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLte(la, lb);
                        };
                        const invert = (c != 0);
                        if (result != invert) ctx.pc += 1;
                    },

                    // P15.38d: Immediate comparison opcodes (PUC EQI/LTI/LEI/GTI/GEI/EQK).
                    // These compare R[A] against a signed immediate (sB) or constant
                    // pool entry (K[B]), eliminating a preceding LOADI/LOADK.
                    // sB is decoded the same way as sC: actual = stored - 127.
                    .eqi => {
                        // PUC OP_EQI: if ((R[A] == sB) ~= (C&1) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat (immediate
                        // originated from a float literal, e.g. 5.0).
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127; // sB2int (same encoding as sC)
                        const result: bool = switch (la) {
                            .Int => |v| v == im,
                            .Num => |v| v == @as(f64, @floatFromInt(im)),
                            else => false,
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .eqk => {
                        // PUC OP_EQK: if ((R[A] == K[B]) ~= (C&1)) then ctx.pc++
                        // Raw equality (no __eq metamethod) — basic types don't use __eq.
                        const la = ctx.regs[a];
                        const rb = ctx.cur_proto.resolved_values[b];
                        const result = valuesEqual(la, rb);
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .lti => {
                        // PUC OP_LTI: if ((R[A] < sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat (sB originated
                        // from a float literal like 5.0; metamethod must
                        // receive a float, not an integer).
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int < im;
                            if (la == .Num) break :blk la.Num < @as(f64, @floatFromInt(im));
                            // Slow path: metamethod or error.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                la,
                                rb_val,
                                "__lt",
                                "lt",
                                .{ .compare = .{ .invert = (c & 1) != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLt(la, rb_val);
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .lei => {
                        // PUC OP_LEI: if ((R[A] <= sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int <= im;
                            if (la == .Num) break :blk la.Num <= @as(f64, @floatFromInt(im));
                            // Slow path: metamethod or error.
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                la,
                                rb_val,
                                "__le",
                                "le",
                                .{ .compare = .{ .invert = (c & 1) != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLte(la, rb_val);
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .gti => {
                        // PUC OP_GTI: if ((R[A] > sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int > im;
                            if (la == .Num) break :blk la.Num > @as(f64, @floatFromInt(im));
                            // Slow path: metamethod or error.
                            // GTI uses __lt with swapped operands: (im < la).
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                rb_val,
                                la,
                                "__lt",
                                "lt",
                                .{ .compare = .{ .invert = (c & 1) != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLt(rb_val, la);
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },
                    .gei => {
                        // PUC OP_GEI: if ((R[A] >= sB) ~= (C&1)) then ctx.pc++
                        // C bit 0 = invert, C bit 1 = isfloat.
                        const la = ctx.regs[a];
                        const im: i64 = @as(i64, b) - 127;
                        const isfloat = (c & 2) != 0;
                        const result: bool = blk: {
                            if (la == .Int) break :blk la.Int >= im;
                            if (la == .Num) break :blk la.Num >= @as(f64, @floatFromInt(im));
                            // Slow path: metamethod or error.
                            // GEI uses __le with swapped operands: (im <= la).
                            const rb_val: Value = if (isfloat)
                                .{ .Num = @as(f64, @floatFromInt(im)) }
                            else
                                .{ .Int = im };
                            if (try self.tryPushBytecodeBinaryMetamethod(
                                exec_frames,
                                ctx.frame_index,
                                rb_val,
                                la,
                                "__le",
                                "le",
                                .{ .compare = .{ .invert = (c & 1) != 0 } },
                            )) {
                                continue :frame_loop;
                            }
                            break :blk try self.cmpLte(rb_val, la);
                        };
                        const invert = (c & 1) != 0;
                        if (result != invert) ctx.pc += 1;
                    },

                    // --- Test / testset ---
                    .test_ => {
                        const is_truthy = isTruthy(ctx.regs[a]);
                        const skip_if_falsy = (c != 0);
                        if (!is_truthy == skip_if_falsy) ctx.pc += 1;
                    },
                    .testset => {
                        const is_truthy = isTruthy(ctx.regs[b]);
                        const skip_if_falsy = (c != 0);
                        if (!is_truthy == skip_if_falsy) {
                            ctx.pc += 1;
                        } else {
                            @branchHint(.unlikely);
                            ctx.regs[a] = ctx.regs[b];
                        }
                    },

                    // --- Control flow ---
                    .jmp => {
                        ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + inst.jumpOffset() + 1);
                        continue;
                    },

                    // --- Calls / returns ---
                    .call => {
                        // ── Inline fast path: Lua closure, no hooks, no
                        // coroutine resume. Avoids calling the 200-line opCall
                        // function and DispatchResult enum switch for the
                        // overwhelmingly common case. Mirrors PUC's OP_CALL
                        // which is handled directly in luaV_execute's switch.
                        const callee = ctx.regs[a];
                        if (callee == .Closure and !ctx.hooks_active and !ctx.resumed_direct_yield) {
                            const cl = callee.Closure;
                            if (cl.proto) |proto| {
                                const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
                                const nargs: usize = if (b == 0) ctx.reg_top - a - 1 else b - 1;

                                // Pre-grow shared stack for child frame (PUC
                                // luaD_precall stack check). Usually a no-op
                                // because EXTRA_MARGIN covers typical calls.
                                const child_frame_cap: usize = proto.maxstacksize + EXTRA_MARGIN;
                                const child_nextra: usize = if (proto.is_vararg and nargs > proto.numparams)
                                    nargs - proto.numparams
                                else
                                    0;
                                try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
                                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                                ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];

                                // Set return continuation on parent frame —
                                // when the child returns, applyBytecodePendingResults
                                // stores results at reg[a] and advances pc.
                                const rargs = ctx.regs[a + 1 .. a + 1 + nargs];
                                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.set(.{
                                    .callee = callee,
                                    .completion = .{ .results = .{
                                        .dst = a,
                                        .nresults = nresults,
                                    } },
                                });
                                try self.pushBytecodeExecFrame(
                                    ctx.exec_frames, proto, cl.upvalues, rargs, cl, ctx.base + a, nresults,
                                );
                                // Defer block syncs parent frame state (pc,
                                // regs, etc.) before the frame_loop starts
                                // executing the child frame.
                                continue :frame_loop;
                            }
                        }

                        // ── Slow path: Builtin callee, __call metamethod,
                        // hooks active, or coroutine resume ──
                        switch (try self.opCall(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .tailcall => {
                        switch (try self.opTailcall(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return_ => {
                        switch (try self.opReturn(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return0 => {
                        switch (try self.opReturn0(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .return1 => {
                        switch (try self.opReturn1(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },

                    // --- For-loops ---
                    //
                    // PUC Lua has two numeric for-loop modes:
                    //  1. Integer loop: both init and step are integers.
                    //     Uses a count-based approach to avoid overflow.
                    //  2. Float loop: fallback when not all values are integers.
                    //     Includes string-to-number coercion (tonumber).
                    //
                    // Our register layout (codegen_bc):
                    //   R[A]   = init   → (after FORPREP) limit or count
                    //   R[A+1] = limit  → (after FORPREP) step
                    //   R[A+2] = step   → (after FORPREP) control variable (idx)
                    //   R[A+3] = loop variable (user-visible, set by FORPREP/FORLOOP)
                    //
                    .forprep => {
                        switch (try self.opForprep(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .forloop => {
                        // After FORPREP, R[A+1] tells us the mode:
                        //   Int  → integer loop (R[A]=count, R[A+1]=step, R[A+2]=idx)
                        //   Num  → float loop   (R[A]=limit, R[A+1]=step, R[A+2]=idx)
                        if (ctx.regs[a + 1] == .Int) {
                            // ── Integer loop ──
                            const count = @as(u64, @bitCast(ctx.regs[a].Int));
                            if (count > 0) {
                                const step_i = ctx.regs[a + 1].Int;
                                const idx = ctx.regs[a + 2].Int;
                                ctx.regs[a] = .{ .Int = @bitCast(count -% 1) };
                                const new_idx = idx +% step_i;
                                ctx.regs[a + 2] = .{ .Int = new_idx };
                                ctx.regs[a + 3] = .{ .Int = new_idx };
                                const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                                const off: i16 = @bitCast(off_bits);
                                ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                                continue;
                            }
                        } else {
                            @branchHint(.unlikely);
                            // ── Float loop ──
                            const limit_f = ctx.regs[a].Num;
                            const step_f = ctx.regs[a + 1].Num;
                            const idx = ctx.regs[a + 2].Num;
                            const next_idx = idx + step_f;
                            const continues = if (step_f > 0) next_idx <= limit_f else next_idx >= limit_f;
                            if (continues) {
                                ctx.regs[a + 2] = .{ .Num = next_idx };
                                ctx.regs[a + 3] = .{ .Num = next_idx };
                                const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                                const off: i16 = @bitCast(off_bits);
                                ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                                continue;
                            }
                        }
                    },

                    .tforcall => {
                        switch (try self.opTforcall(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .tforloop => {
                        // A=ctx.base, offset in B:C. If R[ctx.base+2] != nil, loop continues.
                        const ctrl = ctx.regs[a + 2];
                        if (ctrl != .Nil) {
                            ctx.regs[a] = ctrl;
                            const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                            const off: i16 = @bitCast(off_bits);
                            ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                            continue;
                        }
                    },
                    .tforprep => {
                        // A=ctx.base, offset in B:C. Jump forward to after loop.
                        const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                        const off: i16 = @bitCast(off_bits);
                        ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off) + 1);
                        continue;
                    },

                    // --- Table constructor ---
                    .setlist => {
                        switch (try self.opSetlist(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },

                    // --- Closures ---
                    .closure => {
                        switch (try self.opClosure(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                        // PUC: checkGC(L, ra + 1) after pushclosure.
                        try self.condGcFromDispatch(&ctx);
                    },

                    // --- Upvalue / scope management ---
                    .close => {
                        // Close all to-be-closed variables >= R[A], then close
                        // all upvalues >= R[A]. TBC variables get their __close
                        // metamethod called; upvalue cells just get unlinked.
                        //
                        // PUC Lua: luaF_close(L, level, status, yy) — closes
                        // all TBC upvalues and regular upvalues >= level.
                        // We process TBC in reverse declaration order (LIFO).

                        switch (try self.beginBytecodeClose(
                            exec_frames,
                            boundary_depth,
                            ctx.frame_index,
                            a,
                            null,
                            false,
                            .advance_instruction,
                        )) {
                            .resume_dispatch => {
                                // continueBytecodeClose no longer writes
                                // parent.pc (PUC-faithful: dispatch loop owns
                                // pc). Increment ctx.pc here; the defer will
                                // persist it to the frame.
                                ctx.pc += 1;
                                continue :frame_loop;
                            },
                            .final => |final| return final,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .tbc => {
                        const value = ctx.regs[a];
                        // Lua permits nil/false as inert <close> sentinels. Any
                        // other value must already provide __close when the
                        // declaration becomes active; validating only at scope
                        // exit would incorrectly execute the function body.
                        if (value != .Nil and !(value == .Bool and !value.Bool)) {
                            if (self.metamethodValue(value, "__close") == null) {
                                const local_name = bytecodeLocalNameAt(ctx.cur_proto, a, ctx.pc) orelse "?";
                                exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                                return self.fail("variable '{s}' got a non-closable value", .{local_name});
                            }
                            self.bc_tbc_regs.append(self.alloc, a) catch return error.OutOfMemory;
                        }
                    },

                    // --- Varargs ---
                    .vararg => {
                        switch (try self.opVararg(&ctx)) {
                            .continue_dispatch => {},
                            .continue_no_advance => continue,
                            .continue_frame_loop => continue :frame_loop,
                            .return_results => |r| return r,
                            .propagate_error => return error.RuntimeError,
                        }
                    },
                    .varargprep => {
                        // First instruction of a vararg function.
                        // If the function has a named vararg table (vararg_table_reg),
                        // create the table and store it in the designated register.
                        if (ctx.cur_proto.vararg_table_reg) |va_reg| {
                            try self.testcConsumeAllocCount(); // Table struct
                            const t = try self.allocTableEphemeral();
                            // PUC model (VATAB): extra args at base+numparams
                            const va_slice: []Value = if (ctx.nextraargs != 0) blk: {
                                const np = ctx.cur_proto.numparams;
                                const va_start = ctx.base + np;
                                break :blk self.bc_stack[va_start .. va_start + ctx.nextraargs];
                            } else
                                &.{};
                            try self.tableResizeArray(t, @intCast(va_slice.len));
                            for (va_slice, 0..) |v, i| {
                                t.array[i] = v;
                            }
                            try self.setIndexValue(.{ .Table = t }, .{ .String = try self.internStr("n") }, .{ .Int = @intCast(va_slice.len) });
                            // Allocations above (allocTableEphemeral, tableResizeArray,
                            // setIndexValue, internStr) may trigger GC which
                            // reallocates bc_stack. Refresh ctx.regs before writing
                            // the table to the register.
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.regs[va_reg] = .{ .Table = t };
                            ctx.reg_top = @max(ctx.reg_top, va_reg + 1);
                        }
                    },

                    // --- Error ---
                    .errdefined => {
                        if (ctx.regs[a] != .Nil) {
                            var constant_index: u32 = if (b > 0) @as(u32, b - 1) else 0;
                            if (b == 0) {
                                if (ctx.pc + 1 >= ctx.cur_proto.code.len or ctx.cur_proto.code[ctx.pc + 1].op != @intFromEnum(bc.Op.extraarg)) {
                                    exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                                    return self.fail("malformed ERRDEFINED instruction", .{});
                                }
                                constant_index = ctx.cur_proto.code[ctx.pc + 1].extraArg();
                                ctx.pc += 1;
                            }
                            const name = if (constant_index < ctx.cur_proto.k.len)
                                ctx.cur_proto.k[constant_index]
                            else
                                bc.Constant.nil;
                            const name_str = if (name == .str) name.str.bytes() else "<global>";
                            exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                            return self.fail("global '{s}' already defined", .{name_str});
                        }
                    },
                    .errnnil => {
                        if (ctx.regs[a] == .Nil) {
                            const name = if (b > 0) ctx.cur_proto.k[b - 1] else bc.Constant.nil;
                            const name_str = if (name == .str) name.str.bytes() else "<global>";
                            exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                            return self.fail("attempt to use a nil value (global '{s}')", .{name_str});
                        }
                    },

                    // --- Extended argument ---
                    .extraarg => {
                        // Should be consumed by the preceding instruction.
                    },
                }

                ctx.pc += 1;
            }

            // Should not happen (codegen ensures a terminating return), but
            // preserve the old empty-return fallback for malformed Protos.
            const ret = try self.alloc.alloc(Value, 0);
            if (try self.completeBytecodeExecFrame(exec_frames, boundary_depth, ret)) |final| return final;
        }

        unreachable;
    }

    // ─────────────────────────────────────────────────────────────────────
    // P15.42 extracted opcode handlers.
    //
    // Each handler reads `inst` from `ctx.cur_proto.code[ctx.pc]`, mutates
    // ctx fields directly, and returns a DispatchResult. The dispatcher
    // switch unwraps the result to drive the inner loop. Handlers must
    // re-derive ctx.regs/ctx.boxed after any call that may realloc bc_stack.
    // ─────────────────────────────────────────────────────────────────────

    /// OP_RETURN: return `b-1` values (or all from a..reg_top if b==0) from
    /// the current frame. Runs pending __close metamethods via
    /// beginBytecodeClose before completing the frame.
    fn opReturn(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;

        // Preserve return values before running closers; __close can execute
        // Lua and grow the shared bytecode stack.
        const nvals: usize = if (b == 0) ctx.reg_top - a else b - 1;
        const ret = try self.alloc.dupe(Value, ctx.regs[a .. a + nvals]);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;

        // Sync pc and reg_top to the heap CallFrame so GC (which may run
        // inside __close finalizers via collectgarbage()) sees the correct
        // live_reg_top[pc] for the parent frame. Without this, the parent
        // frame's pc is stale and live_reg_top[pc] may not include
        // to-be-closed variables, causing GC to clear them.
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.pc = ctx.pc;
            fr.reg_top = ctx.reg_top;
        }

        const close_outcome = try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        );
        return switch (close_outcome) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_SETLIST: R[A][C+i] := R[A+i] for 1<=i<=B. When C==255, the actual
    /// base index is in the following EXTRAARG instruction (consumed here).
    /// Returns `.continue_dispatch` so the dispatcher advances past SETLIST.
    fn opSetlist(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const table_val = ctx.regs[a];
        const count: usize = if (b == 0) ctx.reg_top - a - 1 else b;
        const base_idx: u32 = if (c == 255) blk: {
            if (ctx.pc + 1 >= ctx.cur_proto.code.len or
                @as(bc.Op, @enumFromInt(ctx.cur_proto.code[ctx.pc + 1].op)) != .extraarg)
            {
                return self.fail("SETLIST missing EXTRAARG", .{});
            }
            ctx.pc += 1;
            break :blk ctx.cur_proto.code[ctx.pc].extraArg();
        } else c;

        if (table_val == .Table) {
            const tbl = table_val.Table;
            // Fast path: table without metatable — preallocate array part
            // and write directly, mirroring PUC's SETLIST (luaH_resizearray
            // + obj2arr). Skips the per-element tableGetRawValue probe in
            // setIndexValueDepth and the per-element rawSet rehash path.
            if (tbl.metatable == null) {
                const start = base_idx;
                const end = base_idx + @as(u32, @intCast(count));
                // Extend array part if needed (PUC: luaH_resizearray).
                if (end > tbl.asize) {
                    try self.tableResizeArray(tbl, end);
                }
                for (0..count) |i| {
                    const idx = start + i;
                    tbl.array[idx] = ctx.regs[a + 1 + i];
                    // PUC backward barrier on the table being written to.
                    try self.gcWriteBarrierTable(tbl, ctx.regs[a + 1 + i]);
                }
                tbl.flags &= ~TableFlags.MASK;
            } else {
                for (0..count) |i| {
                    try self.setIndexValue(table_val, .{ .Int = @intCast(base_idx + i + 1) }, ctx.regs[a + 1 + i]);
                }
            }
        }
        return .continue_dispatch;
    }

    /// OP_RETURN0: return zero values from the current frame.
    /// P15.35 fast path: when no TBC closers and no debug hooks, skip
    /// beginBytecodeClose and use a zero-length slice into bc_return_scratch
    /// (pointer-identity detected, never freed). This eliminates the
    /// alloc(Value, 0)/free pair on every no-value return.
    fn opReturn0(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const has_pending_tbc = self.bc_tbc_regs.items.len >
            ctx.exec_frames.getPtr(ctx.frame_index).tbc_mark;
        if (!has_pending_tbc and !ctx.hooks_active) {
            const empty: []Value = self.bc_return_scratch[0..0];
            if (try self.completeBytecodeExecFrame(
                ctx.exec_frames,
                ctx.boundary_depth,
                empty,
            )) |final| return .{ .return_results = final };
            return .continue_frame_loop;
        }
        const ret = try self.alloc.alloc(Value, 0);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        // Sync pc and reg_top so GC (which may run inside __close
        // finalizers via collectgarbage()) sees the correct live_reg_top[pc].
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.pc = ctx.pc;
            fr.reg_top = ctx.reg_top;
        }
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_RETURN1: return a single value (R[A]) from the current frame.
    /// P15.35 fast path: stash the single return value in bc_return_scratch
    /// (stable across frame pop) and go straight to completeBytecodeExecFrame.
    /// Eliminates the alloc(Value, 1)/free pair on every single-value return
    /// — the hottest return path (e.g. `return s + 1`).
    fn opReturn1(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;

        const has_pending_tbc = self.bc_tbc_regs.items.len >
            ctx.exec_frames.getPtr(ctx.frame_index).tbc_mark;
        if (!has_pending_tbc and !ctx.hooks_active) {
            self.bc_return_scratch[0] = ctx.regs[a];
            if (try self.completeBytecodeExecFrame(
                ctx.exec_frames,
                ctx.boundary_depth,
                self.bc_return_scratch[0..1],
            )) |final| return .{ .return_results = final };
            return .continue_frame_loop;
        }
        const ret = try self.alloc.alloc(Value, 1);
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        ret[0] = ctx.regs[a];
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        // Sync pc and reg_top so GC (which may run inside __close
        // finalizers via collectgarbage()) sees the correct live_reg_top[pc].
        {
            const fr = ctx.exec_frames.getPtr(ctx.frame_index);
            fr.pc = ctx.pc;
            fr.reg_top = ctx.reg_top;
        }
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_VARARG: R[A..A+C-2] = varargs. C-1 results wanted; C==0 means
    /// multret (copy all). Frame may grow to hold the values.
    fn opVararg(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const c: u8 = inst.c;

        const named_varargs = try self.getBytecodeVarargTable(ctx.cur_proto, ctx.regs);
        // PUC model: hidden varargs at [func_slot - nextraargs .. func_slot].
        const va_slice: []Value = if (ctx.nextraargs != 0)
            self.bc_stack[ctx.func_slot - ctx.nextraargs .. ctx.func_slot]
        else
            &.{};
        const source_len = if (named_varargs) |src| src.len else va_slice.len;
        const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
        if (nresults >= 0) {
            const nr: usize = @intCast(nresults);
            try self.bcGrowFrame(ctx.base, a + nr, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
            const ncopy2 = @min(nr, source_len);
            for (0..ncopy2) |i| {
                ctx.regs[a + i] = if (named_varargs) |src|
                    try self.tableGetRawValue(src.table, .{ .Int = @intCast(i + 1) })
                else
                    va_slice[i];
            }
            for (ncopy2..nr) |i| ctx.regs[a + i] = .Nil;
            ctx.reg_top = @max(ctx.reg_top, @as(u32, @intCast(a + nr)));
        } else {
            // All varargs — grow frame, then copy.
            try self.bcGrowFrame(ctx.base, a + source_len, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
            for (0..source_len) |i| {
                ctx.regs[a + i] = if (named_varargs) |src|
                    try self.tableGetRawValue(src.table, .{ .Int = @intCast(i + 1) })
                else
                    va_slice[i];
            }
            ctx.reg_top = @intCast(@as(usize, a) + source_len);
        }
        return .continue_dispatch;
    }

    /// OP_CLOSURE: R[A] = closure(P[B]). Creates upvalue cells from the
    /// child Proto's upvalue descriptions. Instack upvalues capture from the
    /// current frame's registers; others proxy from current upvalues.
    /// Recursive closures (local f = function() ... f() ... end) require
    /// syncing the boxed cell after the closure is stored in its own slot.
    fn opClosure(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: usize = inst.a;
        const b: u8 = inst.b;

        const child_proto = ctx.cur_proto.p[b];

        // Create upvalue cells from child's upvalue descriptions.
        const nups = child_proto.upvalues.len;
        const cells = try self.alloc.alloc(*Cell, nups);
        for (child_proto.upvalues, 0..) |uv, i| {
            if (uv.instack) {
                // Capture from current frame's register.
                if (ctx.boxed[uv.idx]) |cell| {
                    cells[i] = cell;
                } else {
                    const cell = try self.alloc.create(Cell);
                    // PUC luaF_findupval: create an OPEN upvalue that points
                    // to the stack slot. The cell's bc_stack_idx is the
                    // absolute index into the owning thread's stack.
                    // bc_stack_thread identifies which thread's stack to use
                    // (needed when the owning coroutine is suspended).
                    const th = self.activeBytecodeThread();
                    cell.* = .{
                        .value = ctx.regs[uv.idx],
                        .bc_stack_idx = ctx.base + uv.idx,
                        .bc_stack_thread = th,
                    };
                    try self.gcRegisterCell(cell);
                    ctx.boxed[uv.idx] = cell;
                    cells[i] = cell;
                    // Mark the frame as having open upvalues so that
                    // closeBytecodeUpvaluesFrom knows to scan on return.
                    // Also update ctx.has_open_upvalues so the dispatch
                    // loop's fast path (OP_MOVE etc.) takes the slow path
                    // that syncs through boxed[] cells.
                    ctx.exec_frames.getPtr(ctx.frame_index).has_open_upvalues = true;
                    ctx.has_open_upvalues = true;
                }
            } else {
                // Proxy from current frame's upvalues.
                cells[i] = ctx.cur_upvalues[uv.idx];
            }
        }

        const cl = try self.alloc.create(Closure);
        cl.* = .{
            .proto = child_proto,
            .upvalues = cells,
        };
        try self.gcRegisterClosure(cl);
        // PUC luaM_*: every allocation decrements GCdebt via gcNoteAlloc.
        // Without this, condGcFromDispatch never triggers for closure-heavy
        // loops, and the table with __gc metatable is never collected.
        self.gcNoteAlloc(@sizeOf(Closure) + nups * @sizeOf(*Cell));
        self.testc_obj_functions += 1;
        ctx.regs[a] = .{ .Closure = cl };
        // If this register was captured as an upvalue (ctx.boxed), update the
        // cell to reflect the new value. Essential for recursive closures.
        // For OPEN cells, the register write already updated the stack slot.
        // For CLOSED cells, sync the cell value and fire the write barrier.
        if (ctx.boxed[a]) |cell| {
            if (!cell.isOpen()) {
                try self.gcStoreCellValue(cell, ctx.regs[a]);
            }
        }
        return .continue_dispatch;
    }

    /// OP_TFORCALL: R[A+4..A+3+C] := R[A](R[A+1], R[A+2]).
    /// Generic-for iterator call. PUC luaV_execute TFORCALL has 2 fixed args
    /// (state, ctrl) at R[A+1..A+3]; iterator is at R[A]. Arg count is not
    /// encoded — always 2. Resolves `__call` metamethod chain (up to 16 deep).
    /// Bytecode iterators push a child frame via the iterative dispatch stack;
    /// builtins and IR closures are called synchronously via runClosure.
    fn opTforcall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const c: u8 = inst.c;

        const nresults: u8 = if (c == 0) 0 else c - 1;

        // PUC-faithful TFORCALL: copy func+state+control ABOVE the close value
        // (R[A+3]) BEFORE __call resolution. This preserves R[A..A+3] (iterator,
        // state, control, close value) from being corrupted by __call's
        // in-place shift (tryCallMetamethodInPlace shifts callee+args up by 1,
        // which would overwrite the close value at R[A+3]).
        // PUC luaV_execute copies to ra+3..ra+5 and calls from there; luazig's
        // layout has close at R[A+3] (no TFORPREP swap), so we copy to
        // R[A+4..A+6] and resolve/call from func_slot = A+4.
        ctx.regs[a + 4] = ctx.regs[a]; // func
        ctx.regs[a + 5] = ctx.regs[a + 1]; // state
        ctx.regs[a + 6] = ctx.regs[a + 2]; // control

        // ── PUC luaD_precall: inline callee type resolution ──
        // Resolve on the copy at R[A+4], not the original at R[A].
        var effective_nargs: usize = 2;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a + 4]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a + 4];
                    self.tryCallMetamethodInPlace(
                        ctx.base, a + 4, &effective_nargs, &ctx.frame_cap, &ctx.regs, &ctx.boxed, &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            return self.fail(
                                "attempt to call a {s} value (iterator)",
                                .{current_callee.typeName()},
                            );
                        }
                        return err;
                    };
                },
            }
        }

        const callee_val = ctx.regs[a + 4];

        // Pre-grow bc_stack so the rargs slice stays valid across pushBytecodeExecFrame.
        const child_frame_cap: usize = switch (callee_val) {
            .Closure => |cl| if (cl.proto) |p| p.maxstacksize + EXTRA_MARGIN else 0,
            else => 0,
        };
        const child_nextra: usize = switch (callee_val) {
            .Closure => |cl| if (cl.proto) |p| (if (p.is_vararg and effective_nargs > p.numparams) effective_nargs - p.numparams else 0) else 0,
            else => 0,
        };
        try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
        ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];
        // rargs are at R[A+5..] (after the copy at A+4 which may have been
        // replaced by __call resolution).
        const rargs_builtin = ctx.regs[a + 5 .. a + 5 + effective_nargs];

        // Bytecode iterators join the iterative dispatch stack (same as OP_CALL).
        if (callee_val == .Closure) {
            const cl = callee_val.Closure;
            if (cl.proto) |child_proto| {
                const rargs = ctx.regs[a + 5 .. a + 5 + effective_nargs];
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.set(.{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a + 4,
                        .nresults = @intCast(nresults),
                        .min_reg_top = @as(u32, a) + 4 + nresults,
                    } },
                });
                // Call from R[A+4] — above the close value at R[A+3].
                try self.pushBytecodeExecFrame(ctx.exec_frames, child_proto, cl.upvalues, rargs, cl, ctx.base + a + 4, @intCast(nresults));
                return .continue_frame_loop;
            }
        }

        // Builtins and frozen IR closures remain synchronous.
        const ret = switch (callee_val) {
            .Builtin => |id| blk: {
                const out_len = @max(self.builtinOutLen(id, rargs_builtin), @as(usize, nresults));
                var outs_small: [8]Value = undefined;
                var outs_heap: ?[]Value = null;
                const outs = if (out_len <= outs_small.len) outs_small[0..out_len] else blk2: {
                    outs_heap = try self.alloc.alloc(Value, out_len);
                    break :blk2 outs_heap.?;
                };
                defer if (outs_heap) |h| self.alloc.free(h);
                ctx.exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                ctx.exec_frames.getPtr(ctx.frame_index).reg_top = ctx.reg_top;
                ctx.exec_frames.getPtr(ctx.frame_index).nvarstack = ctx.nvarstack;
                try self.callBuiltin(id, rargs_builtin, outs);
                const produced: usize = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    out_len;
                break :blk try self.alloc.dupe(Value, outs[0..produced]);
            },
            .Closure => |cl| blk: {
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.set(.{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a + 4,
                        .nresults = @intCast(nresults),
                        .min_reg_top = @as(u32, a) + 4 + nresults,
                    } },
                });
                const values = self.runClosure(cl, rargs_builtin) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                        return call_err;
                    },
                };
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                break :blk values;
            },
            else => unreachable,
        };
        defer self.alloc.free(ret);

        // Refresh ctx.regs after potential realloc, then write results.
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
        if (nresults < 0) {
            // LUA_MULTRET: copy all results, adjust reg_top.
            const n = ret.len;
            for (0..n) |i| ctx.regs[a + 4 + i] = ret[i];
            ctx.reg_top = @max(ctx.reg_top, @as(u32, a) + 4 + @as(u32, @intCast(n)));
        } else {
            const n_results_u: usize = @intCast(nresults);
            const n = @min(ret.len, n_results_u);
            for (0..n) |i| ctx.regs[a + 4 + i] = ret[i];
            for (n..n_results_u) |i| ctx.regs[a + 4 + i] = .Nil;
            ctx.reg_top = @max(ctx.reg_top, @as(u32, a) + 4 + @as(u32, @intCast(n_results_u)));
        }
        return .continue_dispatch;
    }

    /// OP_FORPREP: numeric for-loop setup. Reads R[A]=init, R[A+1]=limit,
    /// R[A+2]=step. Rearranges into the runtime form (count/limit + step +
    /// loop var) and jumps to the loop body (skips by B:C offset). The
    /// `+1` offset is implicit: the dispatcher's `ctx.pc += 1` advances past
    /// FORPREP, so the handler sets `ctx.pc += off` (no extra +1).
    /// Returns `.continue_dispatch` (normal advance) for the loop body and
    /// skip paths.
    fn opForprep(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const init_val = ctx.regs[a];
        const limit_val = ctx.regs[a + 1];
        const step_val = ctx.regs[a + 2];

        if (init_val == .Int and step_val == .Int) {
            // ── Integer loop path ──
            const init_i = init_val.Int;
            const step_i = step_val.Int;
            if (step_i == 0) return self.fail("'for' step is zero", .{});

            // Try to convert limit to integer (matching PUC forlimit).
            const limit_i: ?i64 = blk: {
                if (limit_val == .Int) break :blk limit_val.Int;
                if (limit_val == .Num) {
                    const f = limit_val.Num;
                    if (step_i < 0) {
                        const r = @ceil(f);
                        if (r >= @as(f64, @floatFromInt(std.math.minInt(i64))) and
                            r <= @as(f64, @floatFromInt(std.math.maxInt(i64))))
                            break :blk @as(i64, @intFromFloat(r));
                    } else {
                        const r = @floor(f);
                        if (r >= @as(f64, @floatFromInt(std.math.minInt(i64))) and
                            r <= @as(f64, @floatFromInt(std.math.maxInt(i64))))
                            break :blk @as(i64, @intFromFloat(r));
                    }
                    if (f > 0) {
                        if (step_i < 0) break :blk null; // skip via float path
                        break :blk std.math.maxInt(i64);
                    }
                    if (step_i > 0) break :blk null; // skip via float path
                    break :blk std.math.minInt(i64);
                }
                if (limit_val == .String) {
                    const s = limit_val.String.bytes();
                    const parsed = luaStrToNum(s) orelse {
                        return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
                    };
                    if (step_i < 0) {
                        break :blk @as(i64, @intFromFloat(@ceil(parsed)));
                    } else {
                        break :blk @as(i64, @intFromFloat(@floor(parsed)));
                    }
                }
                break :blk null;
            };

            if (limit_i) |li| {
                const should_skip = if (step_i > 0) init_i > li else init_i < li;
                if (should_skip) {
                    const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
                    const off: i16 = @bitCast(off_bits);
                    // +1 is supplied by dispatcher's ctx.pc += 1 after return.
                    ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off));
                    return .continue_dispatch;
                }

                // Compute iteration count (PUC approach, avoids overflow).
                const count: u64 = if (step_i > 0) blk: {
                    const n = @as(u64, @bitCast(li)) -% @as(u64, @bitCast(init_i));
                    break :blk if (step_i != 1) n / @as(u64, @bitCast(step_i)) else n;
                } else blk: {
                    const n = @as(u64, @bitCast(init_i)) -% @as(u64, @bitCast(li));
                    break :blk n / (@as(u64, @bitCast(-(step_i + 1))) +% 1);
                };

                // Rearrange registers: R[A]=count, R[A+1]=step, R[A+2]=init.
                ctx.regs[a] = .{ .Int = @bitCast(count) };
                ctx.regs[a + 1] = .{ .Int = step_i };
                ctx.regs[a + 2] = .{ .Int = init_i };
                ctx.regs[a + 3] = .{ .Int = init_i }; // loop variable
                ctx.nvarstack = a + 4;
                ctx.reg_top = @max(ctx.reg_top, @as(u32, a) + 4);
                return .continue_dispatch;
            }
        }

        // ── Float loop path (with string coercion) ──
        const init_f = blk: {
            if (init_val == .Int) break :blk @as(f64, @floatFromInt(init_val.Int));
            if (init_val == .Num) break :blk init_val.Num;
            if (init_val == .String) {
                break :blk luaStrToNum(init_val.String.bytes()) orelse
                    return self.fail("bad 'for' initial value (number expected, got {s})", .{self.valueTypeName(init_val)});
            }
            return self.fail("bad 'for' initial value (number expected, got {s})", .{self.valueTypeName(init_val)});
        };
        const limit_f = blk: {
            if (limit_val == .Int) break :blk @as(f64, @floatFromInt(limit_val.Int));
            if (limit_val == .Num) break :blk limit_val.Num;
            if (limit_val == .String) {
                break :blk luaStrToNum(limit_val.String.bytes()) orelse
                    return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
            }
            return self.fail("bad 'for' limit (number expected, got {s})", .{self.valueTypeName(limit_val)});
        };
        const step_f = blk: {
            if (step_val == .Int) break :blk @as(f64, @floatFromInt(step_val.Int));
            if (step_val == .Num) break :blk step_val.Num;
            if (step_val == .String) {
                break :blk luaStrToNum(step_val.String.bytes()) orelse
                    return self.fail("bad 'for' step (number expected, got {s})", .{self.valueTypeName(step_val)});
            }
            return self.fail("bad 'for' step (number expected, got {s})", .{self.valueTypeName(step_val)});
        };

        if (step_f == 0) return self.fail("'for' step is zero", .{});

        const should_run = if (step_f > 0) init_f <= limit_f else init_f >= limit_f;
        if (!should_run) {
            const off_bits: u16 = @as(u16, b) | (@as(u16, c) << 8);
            const off: i16 = @bitCast(off_bits);
            // +1 is supplied by dispatcher's ctx.pc += 1 after return.
            ctx.pc = @intCast(@as(i64, @intCast(ctx.pc)) + @as(i64, off));
            return .continue_dispatch;
        }

        // Rearrange: R[A]=limit, R[A+1]=step, R[A+2]=idx (control var).
        ctx.regs[a] = .{ .Num = limit_f };
        ctx.regs[a + 1] = .{ .Num = step_f };
        ctx.regs[a + 2] = .{ .Num = init_f };
        ctx.regs[a + 3] = .{ .Num = init_f }; // loop variable
        ctx.nvarstack = a + 4;
        ctx.reg_top = @max(ctx.reg_top, @as(u32, a) + 4);
        return .continue_dispatch;
    }

    /// OP_CONCAT: R[A] := R[A].. ... ..R[A+B-2]. The whole range is duplicated
    /// to continuation-owned storage because a bytecode __concat metamethod
    /// can yield or call arbitrarily deep — no Zig activation may retain the
    /// accumulator. `advanceBytecodeConcat` either pushes a metamethod frame
    /// (returns `.continue_frame_loop`) or completes synchronously (returns
    /// `.continue_dispatch` with the result written to R[A]).
    fn opConcat(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;

        const concat_vals = try self.alloc.dupe(Value, ctx.regs[a .. a + b]);
        const outcome = try self.advanceBytecodeConcat(
            ctx.exec_frames,
            ctx.frame_index,
            a,
            concat_vals,
            if (concat_vals.len == 0) 0 else concat_vals.len - 1,
            if (concat_vals.len == 0)
                .{ .String = try self.internLiteral("") }
            else
                concat_vals[concat_vals.len - 1],
        );
        return switch (outcome) {
            .pushed => .continue_frame_loop,
            .value => |result| blk: {
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                ctx.regs[a] = result;
                break :blk .continue_dispatch;
            },
        };
    }

    /// OP_TAILCALL: return R[A](R[A+1..A+B-1]). Implements PUC's tail-call
    /// semantics: reuse current frame for bytecode-to-bytecode calls (no C
    /// stack growth), host-recursion for builtins/IR closures. Handles:
    ///   - resumed_direct_yield early-return path (coroutine.yield resume)
    ///   - inline callee type resolution with __call metamethod chain
    ///   - tail-call debug hook
    ///   - pending TBC closer scan via beginBytecodeClose
    ///   - pairs/pcall/coroutine fast paths
    ///   - bytecode-to-bytecode frame reuse (the common case)
    ///   - builtin/IR closure fallback via runClosure
    /// Returns `.continue_no_advance` after frame reuse (pc was reset to 0).
    fn opTailcall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;

        if (ctx.resumed_direct_yield and ctx.pc == ctx.resume_pc) {
            const vals = if (self.current_thread) |th| takeBytecodeResumeValues(th) orelse try self.alloc.alloc(Value, 0) else try self.alloc.alloc(Value, 0);
            var vals_owned = true;
            errdefer if (vals_owned) self.alloc.free(vals);
            ctx.resumed_direct_yield = false;
            _ = &vals_owned;
            return switch (try self.beginBytecodeClose(
                ctx.exec_frames,
                ctx.boundary_depth,
                ctx.frame_index,
                0,
                null,
                true,
                .{ .return_frame = vals },
            )) {
                .resume_dispatch => .continue_frame_loop,
                .final => |final| .{ .return_results = final },
                .propagate_error => .propagate_error,
            };
        }
        const nargs: usize = if (b == 0) ctx.reg_top - a - 1 else b - 1;

        // ── PUC luaD_precall: inline callee type resolution ──
        var effective_nargs = nargs;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a];
                    self.tryCallMetamethodInPlace(
                        ctx.base, a, &effective_nargs, &ctx.frame_cap, &ctx.regs, &ctx.boxed, &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            const inferred = debugBytecodeOperandName(ctx.cur_proto, ctx.pc, a);
                            if (inferred.name) |name| {
                                return self.fail(
                                    "attempt to call a {s} value ({s} '{s}')",
                                    .{ current_callee.typeName(), inferred.namewhat, name },
                                );
                            }
                        }
                        return err;
                    };
                },
            }
        }

        const callee_val = ctx.regs[a];
        const call_args = ctx.regs[a + 1 .. a + 1 + effective_nargs];

        const hook_args = switch (callee_val) {
            .Closure => |cl| debugCallTransferArgsForClosure(cl, call_args),
            else => call_args,
        };
        const skip_tail_hook = ctx.exec_frames.getPtr(ctx.frame_index).skip_call_hook_pc == ctx.pc;
        if (skip_tail_hook) {
            ctx.exec_frames.getPtr(ctx.frame_index).skip_call_hook_pc = null;
        } else if (try self.tryPushBytecodeDebugHook(
            ctx.exec_frames,
            ctx.frame_index,
            "tail call",
            null,
            callee_val,
            hook_args,
            1,
            .retry_call,
        )) {
            return .continue_frame_loop;
        } else {
            try self.debugDispatchHookWithCalleeTransfer(
                "tail call",
                null,
                callee_val,
                hook_args,
                1,
            );
        }

        const has_pending_tbc = self.bc_tbc_regs.items.len > ctx.tbc_mark;
        if (has_pending_tbc) {
            return switch (try self.beginBytecodeClose(
                ctx.exec_frames,
                ctx.boundary_depth,
                ctx.frame_index,
                0,
                null,
                true,
                .retry_tailcall,
            )) {
                .resume_dispatch => .continue_frame_loop,
                .final => |final| .{ .return_results = final },
                .propagate_error => .propagate_error,
            };
        }
        if (callee_val == .Builtin and
            callee_val.Builtin == .pairs and
            try self.tryPushBytecodePairsMetamethod(
                ctx.exec_frames,
                ctx.frame_index,
                call_args,
                .{ .dst = a, .nresults = -1, .tail_return = true },
            ))
        {
            return .continue_frame_loop;
        }
        if (callee_val == .Builtin and
            try self.tryPushBytecodeProtectedCall(
                ctx.exec_frames,
                ctx.frame_index,
                a,
                -1,
                callee_val.Builtin,
                call_args,
                true,
            ))
        {
            return .continue_frame_loop;
        }
        if (callee_val == .Builtin and
            try self.tryRequestBytecodeCoroutineSwitch(
                ctx.exec_frames,
                ctx.frame_index,
                a,
                -1,
                callee_val.Builtin,
                call_args,
                true,
            )) return error.ThreadSwitch;

        switch (callee_val) {
            .Closure => |cl| if (cl.proto) |new_proto| {
                // ── Bytecode-to-bytecode tail call: frame reuse ──
                try self.resolveProtoConstants(@constCast(new_proto));

                // 1. Close all ctx.boxed upvalues.
                for (ctx.boxed) |*bc_slot| {
                    if (bc_slot.*) |cell| {
                        cell.close(self);
                        self.gcWriteBarrierCell(cell, cell.value) catch {};
                        bc_slot.* = null;
                    }
                }

                // 2. Grow frame if needed.
                const new_max = new_proto.maxstacksize;
                const new_cap: usize = new_max;
                try self.bcGrowFrame(ctx.base, new_cap, &ctx.frame_cap, &ctx.regs, &ctx.boxed);

                // 3. PUC-faithful tail-call: reuse frame, re-setup varargs.
                //    Step 1: copy func+args from R[A..] down to func_slot_base
                //    (the ORIGINAL position, before any previous buildhiddenargs
                //    shift). This prevents cumulative shifting across repeated
                //    tail calls.
                //    Step 2: if new proto is VAHID, buildhiddenargs shifts
                //    func+params UP past the extra args.
                const np = new_proto.numparams;
                const new_nextra: usize = if (new_proto.is_vararg and effective_nargs > np)
                    effective_nargs - np
                else
                    0;
                const new_is_vahid = new_proto.is_vararg and new_nextra > 0 and
                    new_proto.vararg_table_reg == null;

                // Reset to the original (unshifted) func_slot_base.
                const reset_slot = ctx.exec_frames.getPtr(ctx.frame_index).func_slot_base;
                const reset_base = reset_slot + 1;
                try self.ensureBcStackCap(reset_base + @max(new_cap, effective_nargs + 1));

                // Copy func + args from regs[a..a+1+effective_nargs] down to
                // [reset_slot..reset_slot+1+effective_nargs].
                const total_move = effective_nargs + 1;
                std.mem.copyForwards(
                    Value,
                    self.bc_stack[reset_slot .. reset_slot + total_move],
                    self.bc_stack[ctx.base + a .. ctx.base + a + total_move],
                );
                // Nil-fill missing params at the copied position.
                const nc = @min(np, effective_nargs);
                for (nc..np) |i| {
                    self.bc_stack[reset_slot + 1 + i] = .Nil;
                }

                // VAHID buildhiddenargs: shift func+params up past extra args.
                var new_func_slot = reset_slot;
                var new_base = new_func_slot + 1;
                if (new_is_vahid) {
                    new_func_slot = reset_slot + effective_nargs + 1;
                    new_base = new_func_slot + 1;
                    try self.ensureBcStackCap(new_base + new_cap);
                    self.bc_stack[new_func_slot] = self.bc_stack[reset_slot];
                    for (0..np) |i| {
                        self.bc_stack[new_base + i] = self.bc_stack[reset_slot + 1 + i];
                        self.bc_stack[reset_slot + 1 + i] = .Nil;
                    }
                }

                // Grow frame to new proto's register needs.
                try self.bcGrowFrame(new_base, new_cap, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
                ctx.base = new_base;
                ctx.func_slot = new_func_slot;
                self.bc_stack_top = new_base + ctx.frame_cap;

                // Re-derive register slices after potential base change.
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];

                ctx.nextraargs = @intCast(new_nextra);
                ctx.exec_frames.getPtr(ctx.frame_index).nextraargs = ctx.nextraargs;
                ctx.exec_frames.getPtr(ctx.frame_index).frame_cap = ctx.frame_cap;

                // Nil-fill remaining registers.
                for (ctx.regs[np..new_max]) |*r| r.* = .Nil;
                for (ctx.boxed[0..new_max]) |*bc_slot| bc_slot.* = null;

                // 6. Update frame state.
                ctx.cur_proto = new_proto;
                ctx.cur_upvalues = cl.upvalues;
                ctx.is_tailcall = true;

                // 7. Update Frame struct on exec_frames.
                const fr2 = ctx.exec_frames.getPtr(ctx.exec_frames.len() - 1);
                fr2.proto = new_proto;
                fr2.upvalues = ctx.cur_upvalues;
                fr2.base = ctx.base;
                fr2.func_slot = ctx.func_slot;
                fr2.func_slot_base = reset_slot;
                fr2.regs = ctx.regs;
                fr2.boxed = ctx.boxed;
                fr2.callee = .{ .Closure = cl };
                fr2.pc = 0;
                fr2.reg_top = np;
                fr2.is_tailcall = true;
                fr2.nextraargs = ctx.nextraargs;

                // 8. Reset dispatch state. pc=0; skip dispatcher's pc+=1.
                ctx.pc = 0;
                ctx.nvarstack = np;
                ctx.reg_top = np;
                return .continue_no_advance;
            },
            .Builtin => {},
            else => {},
        }

        // Non-bytecode tail call: execute the callee and return its results.
        const ret = switch (callee_val) {
            .Builtin => |id| blk: {
                const out_len = @max(self.builtinOutLen(id, call_args), 1);
                var outs_small: [8]Value = undefined;
                var outs_heap: ?[]Value = null;
                const outs = if (out_len <= outs_small.len) outs_small[0..out_len] else heap: {
                    outs_heap = try self.alloc.alloc(Value, out_len);
                    break :heap outs_heap.?;
                };
                defer if (outs_heap) |h| self.alloc.free(h);
                ctx.exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                ctx.exec_frames.getPtr(ctx.frame_index).reg_top = ctx.reg_top;
                ctx.exec_frames.getPtr(ctx.frame_index).nvarstack = ctx.nvarstack;
                self.callBuiltin(id, call_args, outs) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                            const th = self.current_thread.?;
                            self.parkDirectBytecodeYield(
                                th,
                                ctx.pc,
                                &ctx.resume_pc,
                                &ctx.resumed_direct_yield,
                                ctx.boundary_depth,
                            );
                            ctx.yielded_in_place.* = true;
                        }
                        return error.Yield;
                    },
                    error.OutOfMemory => return error.OutOfMemory,
                    error.RuntimeError => return error.RuntimeError,
                    error.ThreadSwitch => return error.ThreadSwitch,
                };
                const used = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    outs.len;
                break :blk try self.alloc.dupe(Value, outs[0..used]);
            },
            .Closure => |cl| blk: {
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.set(.{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a,
                        .nresults = -1,
                        .tail_return = true,
                    } },
                });
                const values = self.runClosure(cl, call_args) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                        return call_err;
                    },
                };
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                break :blk values;
            },
            else => unreachable,
        };
        var ret_owned = true;
        errdefer if (ret_owned) self.alloc.free(ret);
        // beginBytecodeClose takes ownership of `ret` (stored in
        // close_state.post.return_frame). The errdefer must not free it
        // if beginBytecodeClose accepted the slice — even on error.Yield,
        // the close continuation retains the slice for resume.
        ret_owned = false;
        return switch (try self.beginBytecodeClose(
            ctx.exec_frames,
            ctx.boundary_depth,
            ctx.frame_index,
            0,
            null,
            true,
            .{ .return_frame = ret },
        )) {
            .resume_dispatch => .continue_frame_loop,
            .final => |final| .{ .return_results = final },
            .propagate_error => .propagate_error,
        };
    }

    /// OP_CALL: R[A..A+C-2] := R[A](R[A+1..A+B-1]). The main function-call
    /// opcode. Implements PUC luaD_precall inline callee type resolution:
    ///   1. Resolve `__call` metamethod chain (up to 16 deep) via in-place
    ///      bc_stack shift — no heap allocation.
    ///   2. Pre-grow bc_stack so rargs slice stays valid.
    ///   3. Dispatch call/return debug hooks.
    ///   4. Branch on callee type:
    ///      - Builtin: pairs/pcall/coroutine fast paths, then synchronous
    ///        callBuiltin + moveresults.
    ///      - Closure w/ proto: push iterative dispatch frame (continue_frame_loop).
    ///      - Closure IR: host-recursion via runClosure.
    /// Returns `.continue_dispatch` for the synchronous paths (dispatcher's
    /// pc+=1 advances past OP_CALL). Returns `.continue_frame_loop` when
    /// pushing a child frame for iterative dispatch.
    fn opCall(self: *Vm, ctx: *BytecodeDispatchCtx) DispatchError!DispatchResult {
        const inst = ctx.cur_proto.code[ctx.pc];
        const a: u8 = inst.a;
        const b: u8 = inst.b;
        const c: u8 = inst.c;

        const nresults: i32 = if (c == 0) -1 else @intCast(c - 1);
        if (ctx.resumed_direct_yield and ctx.pc == ctx.resume_pc) {
            const vals = if (self.current_thread) |th| takeBytecodeResumeValues(th) orelse try self.alloc.alloc(Value, 0) else try self.alloc.alloc(Value, 0);
            var vals_owned = true;
            errdefer if (vals_owned) self.alloc.free(vals);
            ctx.resumed_direct_yield = false;
            if (try self.tryPushBytecodeDebugHook(
                ctx.exec_frames,
                ctx.frame_index,
                "return",
                null,
                ctx.regs[a],
                vals,
                1,
                .{ .store_results = .{
                    .continuation = .{ .dst = a, .nresults = nresults },
                    .values = vals,
                } },
            )) {
                vals_owned = false;
                return .continue_frame_loop;
            }
            try self.dispatchBytecodeHookWithCallee("return", ctx.regs[a], vals);
            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
            ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];
            const nstore: usize = if (nresults >= 0) @intCast(nresults) else vals.len;
            try self.bcGrowFrame(ctx.base, a + nstore, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
            for (0..nstore) |i| ctx.regs[a + i] = if (i < vals.len) vals[i] else .Nil;
            // PUC Lua sets L->top = ci->top (maxstacksize) after calls.
            // We track reg_top as the runtime stack top. For multi-return
            // (nresults < 0), reg_top = a + actual count. For fixed nresults,
            // reg_top must include the stored results so GC marks them.
            if (nresults < 0)
                ctx.reg_top = @intCast(@as(usize, a) + vals.len)
            else
                ctx.reg_top = @max(ctx.reg_top, @as(u32, @intCast(a + nstore)));
            self.alloc.free(vals);
            _ = &vals_owned;
            // Original code did `ctx.pc += 1; continue;` — skip dispatcher +1.
            // Returning `.continue_dispatch` adds the +1 from the dispatcher,
            // giving the same final pc.
            return .continue_dispatch;
        }
        const nargs: usize = if (b == 0) ctx.reg_top - a - 1 else b - 1;

        // ── PUC luaD_precall: inline callee type resolution ──
        var effective_nargs = nargs;
        var chain_depth: usize = 0;
        while (true) {
            switch (ctx.regs[a]) {
                .Closure, .Builtin => break,
                else => {
                    if (chain_depth >= 16) return self.fail("'__call' chain too long", .{});
                    const current_callee = ctx.regs[a];
                    self.tryCallMetamethodInPlace(
                        ctx.base, a, &effective_nargs, &ctx.frame_cap, &ctx.regs, &ctx.boxed, &chain_depth,
                    ) catch |err| {
                        if (err == error.RuntimeError and self.err != null and
                            std.mem.startsWith(u8, self.err.?, "attempt to call a "))
                        {
                            const inferred = debugBytecodeOperandName(ctx.cur_proto, ctx.pc, a);
                            if (inferred.name) |name| {
                                return self.fail(
                                    "attempt to call a {s} value ({s} '{s}')",
                                    .{ current_callee.typeName(), inferred.namewhat, name },
                                );
                            }
                        }
                        return err;
                    };
                },
            }
        }

        // Pre-grow bc_stack so rargs stays valid across pushBytecodeExecFrame.
        // Include EXTRA_MARGIN because pushBytecodeExecFrame uses
        // proto.maxstacksize + EXTRA_MARGIN for frame_cap.
        const child_frame_cap: usize = switch (ctx.regs[a]) {
            .Closure => |cl| if (cl.proto) |p| p.maxstacksize + EXTRA_MARGIN else 0,
            else => 0,
        };
        const child_nextra: usize = switch (ctx.regs[a]) {
            .Closure => |cl| if (cl.proto) |p| (if (p.is_vararg and nargs > p.numparams) nargs - p.numparams else 0) else 0,
            else => 0,
        };
        try self.ensureBcStackCap(self.bc_stack_top + child_frame_cap + child_nextra);
        ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
        ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];

        const rargs = ctx.regs[a + 1 .. a + 1 + effective_nargs];

        const resolved_callee = ctx.regs[a];
        const skip_call_hook = ctx.exec_frames.getPtr(ctx.frame_index).skip_call_hook_pc == ctx.pc;
        if (skip_call_hook) {
            ctx.exec_frames.getPtr(ctx.frame_index).skip_call_hook_pc = null;
        } else if (!self.hooks_active_cached) {
            // No hooks active — skip both noinline hook-dispatch calls.
        } else if (try self.tryPushBytecodeDebugHook(
            ctx.exec_frames,
            ctx.frame_index,
            "call",
            null,
            resolved_callee,
            rargs,
            1,
            .retry_call,
        )) {
            return .continue_frame_loop;
        } else {
            try self.dispatchBytecodeHookWithCallee("call", resolved_callee, rargs);
        }

        const callee_val = resolved_callee;
        switch (callee_val) {
            .Builtin => |id| {
                if (id == .pairs and try self.tryPushBytecodePairsMetamethod(
                    ctx.exec_frames,
                    ctx.frame_index,
                    rargs,
                    .{ .dst = a, .nresults = nresults },
                )) {
                    return .continue_frame_loop;
                }
                if (try self.tryPushBytecodeProtectedCall(
                    ctx.exec_frames,
                    ctx.frame_index,
                    a,
                    nresults,
                    id,
                    rargs,
                    false,
                )) {
                    return .continue_frame_loop;
                }
                if (try self.tryRequestBytecodeCoroutineSwitch(
                    ctx.exec_frames,
                    ctx.frame_index,
                    a,
                    nresults,
                    id,
                    rargs,
                    false,
                )) return error.ThreadSwitch;

                if (id == .string_gsub) {
                    switch (try self.tryStartBytecodeGsub(
                        ctx.exec_frames,
                        ctx.frame_index,
                        rargs,
                        .{ .dst = a, .nresults = nresults },
                    )) {
                        .not_handled => {},
                        .pushed => return .continue_frame_loop,
                        .returned => |values| {
                            var values_owned = true;
                            errdefer if (values_owned) self.alloc.free(values);
                            if (try self.tryPushBytecodeDebugHook(
                                ctx.exec_frames,
                                ctx.frame_index,
                                "return",
                                null,
                                callee_val,
                                values,
                                1,
                                .{ .store_results = .{
                                    .continuation = .{ .dst = a, .nresults = nresults },
                                    .values = values,
                                } },
                            )) {
                                values_owned = false;
                                return .continue_frame_loop;
                            }
                            try self.dispatchBytecodeHookWithCallee("return", callee_val, values);
                            ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                            ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];
                            const nstore: usize = if (nresults >= 0) @intCast(nresults) else values.len;
                            try self.bcGrowFrame(ctx.base, a + nstore, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
                            for (0..nstore) |i| ctx.regs[a + i] = if (i < values.len) values[i] else .Nil;
                            if (nresults < 0) ctx.reg_top = @intCast(@as(usize, a) + values.len);
                            self.alloc.free(values);
                            _ = &values_owned;
                            return .continue_dispatch;
                        },
                    }
                }

                const out_len: usize = if (nresults >= 0)
                    @max(@as(usize, @intCast(nresults)), self.builtinOutLen(id, rargs))
                else
                    self.builtinOutLen(id, rargs);
                const outs_start = a + 1 + effective_nargs;
                try self.bcGrowFrame(ctx.base, outs_start + out_len, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
                // Re-derive rargs after bcGrowFrame: it may have reallocated
                // bc_stack, invalidating the old rargs slice (use-after-free).
                const rargs_fresh = ctx.regs[a + 1 .. a + 1 + effective_nargs];
                var outs = ctx.regs[outs_start .. outs_start + out_len];
                // Sync pc/reg_top/nvarstack to frame before callBuiltin — the
                // builtin may trigger GC, which reads live_reg_top[pc] from
                // the frame to determine which registers are roots.
                ctx.exec_frames.getPtr(ctx.frame_index).pc = ctx.pc;
                ctx.exec_frames.getPtr(ctx.frame_index).reg_top = ctx.reg_top;
                ctx.exec_frames.getPtr(ctx.frame_index).nvarstack = ctx.nvarstack;
                self.callBuiltin(id, rargs_fresh, outs) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (self.canParkDirectBytecodeYield(ctx.boundary_depth, id)) {
                            const th = self.current_thread.?;
                            self.parkDirectBytecodeYield(
                                th,
                                ctx.pc,
                                &ctx.resume_pc,
                                &ctx.resumed_direct_yield,
                                ctx.boundary_depth,
                            );
                            ctx.yielded_in_place.* = true;
                        }
                        return error.Yield;
                    },
                    error.OutOfMemory => return error.OutOfMemory,
                    error.RuntimeError => return error.RuntimeError,
                    error.ThreadSwitch => return error.ThreadSwitch,
                };
                ctx.regs = self.bc_stack[ctx.base .. ctx.base + ctx.frame_cap];
                ctx.boxed = self.bc_boxed[ctx.base .. ctx.base + ctx.frame_cap];
                outs = ctx.regs[outs_start .. outs_start + out_len];
                const produced: usize = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, outs.len)
                else
                    out_len;
                if (try self.tryPushBytecodeDebugHook(
                    ctx.exec_frames,
                    ctx.frame_index,
                    "return",
                    null,
                    callee_val,
                    outs[0..produced],
                    1,
                    .{ .store_results = .{
                        .continuation = .{ .dst = a, .nresults = nresults },
                        .values = outs[0..produced],
                    } },
                )) {
                    const pc2 = &ctx.exec_frames.getPtr(ctx.frame_index).pending_call;
                    if (pc2.getPtr()) |pending| {
                        if (pending.completion == .hook and pending.completion.hook.post == .store_results) {
                            const old_values = pending.completion.hook.post.store_results.values;
                            if (self.returnSliceIsOwned(old_values)) {
                                // Already scratch-owned, no free needed
                            } else if (@intFromPtr(old_values.ptr) >= @intFromPtr(self.bc_stack.ptr) and
                                @intFromPtr(old_values.ptr) < @intFromPtr(self.bc_stack.ptr) + self.bc_stack.len * @sizeOf(Value))
                            {
                                const owned = try self.alloc.dupe(Value, old_values);
                                pending.completion.hook.post.store_results.values = owned;
                            }
                        }
                    }
                    return .continue_frame_loop;
                }
                try self.dispatchBytecodeHookWithCallee("return", callee_val, outs[0..produced]);
                const nstore: usize = if (nresults >= 0) @intCast(nresults) else produced;
                for (0..nstore) |i| {
                    ctx.regs[a + i] = if (i < produced) outs[i] else .Nil;
                }
                if (nresults < 0) ctx.reg_top = @intCast(@as(usize, a) + produced);
                // P15.36: Extend live_reg_top[pc] to cover the just-written
                // result registers before condGcFromDispatch runs GC. Without
                // this, gcClearDeadFrameRegisters nilles registers above the
                // compile-time live_reg_top[pc], including multret results
                // from coroutine.resume/table.unpack that hold GC objects.
                // Protos are heap-allocated, so @constCast is safe (see 6529).
                {
                    const proto = ctx.cur_proto;
                    if (ctx.pc < proto.live_reg_top.len) {
                        const new_top: u8 = @intCast(@min(
                            @as(usize, a) + nstore,
                            @as(usize, std.math.maxInt(u8)),
                        ));
                        const live_top: []u8 = @constCast(proto.live_reg_top);
                        if (new_top > live_top[ctx.pc]) {
                            live_top[ctx.pc] = new_top;
                        }
                        // Also update the next instruction's live_reg_top,
                        // since GC may run there (e.g. inside a subsequent
                        // CALL that uses these results as arguments).
                        const next_pc = ctx.pc + 1;
                        if (next_pc < live_top.len and new_top > live_top[next_pc]) {
                            live_top[next_pc] = new_top;
                        }
                    }
                }
                // PUC: builtins call luaC_checkGC internally (via string/table
                // allocators). We cannot safely run GC from inside builtins
                // (no L->top equivalent to protect just-allocated objects),
                // so run a GC step here after results are stored in registers
                // and ctx is synced.
                try self.condGcFromDispatch(ctx);
            },
            .Closure => |cl| {
                if (cl.proto) |proto2| {
                    // PUC-faithful: result contract is in callee's callstatus
                    // (CIST_NRESULTS) and func_slot (dst derivation). No
                    // pending_call needed for ordinary Lua CALL.
                    try self.pushBytecodeExecFrame(ctx.exec_frames, proto2, cl.upvalues, rargs, cl, ctx.base + a, nresults);
                    return .continue_frame_loop;
                }

                // IR closure: host-recursion via runClosure. (Frozen IR
                // closures are equivalent to PUC's C-function calls — they
                // cross the C/Lua boundary and DO use host recursion.)
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.set(.{
                    .callee = callee_val,
                    .completion = .{ .results = .{
                        .dst = a,
                        .nresults = nresults,
                    } },
                });
                const ret = self.runClosure(cl, rargs) catch |call_err| switch (call_err) {
                    error.Yield => {
                        if (ctx.boundary_depth == 0) {
                            if (self.current_thread) |th| {
                                th.bytecode_inplace_suspended = true;
                                ctx.yielded_in_place.* = true;
                            }
                        }
                        return error.Yield;
                    },
                    else => {
                        ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                        return call_err;
                    },
                };
                ctx.exec_frames.getPtr(ctx.frame_index).pending_call.clear();
                var ret_owned = true;
                errdefer if (ret_owned) self.alloc.free(ret);
                if (try self.tryPushBytecodeDebugHook(
                    ctx.exec_frames,
                    ctx.frame_index,
                    "return",
                    null,
                    callee_val,
                    ret,
                    1,
                    .{ .store_results = .{
                        .continuation = .{ .dst = a, .nresults = nresults },
                        .values = ret,
                    } },
                )) {
                    ret_owned = false;
                    return .continue_frame_loop;
                }
                try self.dispatchBytecodeHookWithCallee("return", callee_val, ret);
                const nstore: usize = if (nresults >= 0) @intCast(nresults) else ret.len;
                try self.bcGrowFrame(ctx.base, a + nstore, &ctx.frame_cap, &ctx.regs, &ctx.boxed);
                for (0..nstore) |i| {
                    ctx.regs[a + i] = if (i < ret.len) ret[i] else .Nil;
                }
                if (nresults < 0) ctx.reg_top = @intCast(@as(usize, a) + ret.len);
                self.alloc.free(ret);
                _ = &ret_owned;
            },
            else => unreachable,
        }
        return .continue_dispatch;
    }

    /// Direct string concatenation — all values must be String/Int/Num.
    fn concatValuesDirect(self: *Vm, vals: []Value) DispatchError!Value {
        if (vals.len == 0) return .{ .String = try self.internLiteral("") };
        if (vals.len == 1) return vals[0];

        // Convert all values to strings and compute total length.
        var bufs: [16][]const u8 = undefined;
        var heap_bufs: ?std.ArrayListUnmanaged([]const u8) = null;
        defer if (heap_bufs) |*hb| {
            for (hb.items) |b| self.alloc.free(b);
            hb.deinit(self.alloc);
        };
        var total: usize = 0;
        for (vals, 0..) |v, i| {
            const s = switch (v) {
                .String => |ls| ls.bytes(),
                .Int => blk: {
                    var buf: [32]u8 = undefined;
                    const s = std.fmt.bufPrint(&buf, "{d}", .{v.Int}) catch unreachable;
                    const owned = try self.alloc.dupe(u8, s);
                    if (heap_bufs == null) heap_bufs = .empty;
                    try heap_bufs.?.append(self.alloc, owned);
                    break :blk owned;
                },
                .Num => blk: {
                    const owned = try self.numberToStringAlloc(v.Num);
                    if (heap_bufs == null) heap_bufs = .empty;
                    try heap_bufs.?.append(self.alloc, owned);
                    break :blk owned;
                },
                else => return self.fail("attempt to concatenate a {s} value", .{v.typeName()}),
            };
            if (i < bufs.len) bufs[i] = s;
            total += s.len;
        }

        // Build result.
        var result = try self.alloc.alloc(u8, total);
        var pos: usize = 0;
        for (vals, 0..) |v, i| {
            const s = if (i < bufs.len) bufs[i] else switch (v) {
                .String => |ls| ls.bytes(),
                else => unreachable,
            };
            @memcpy(result[pos..][0..s.len], s);
            pos += s.len;
        }

        return .{ .String = try self.internStr(result) };
    }

    // Intern `raw` and return the canonical *LuaString. ALL string-creating
    // sites must go through here so two equal-content strings share one
    // pointer (then string equality is pointer comparison). Seed from the
    // per-VM RNG so the cached hash is randomized (matches PUC Lua's
    // random-seed string hashing).
    pub fn internStr(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        const seed = self.rng_state[0] ^ self.rng_state[2];
        var h = std.hash.Wyhash.init(seed);
        h.update(raw);
        const hash = h.final();
        // Short strings are interned (dedup => pointer identity) in the
        // string_intern table, matching PUC's internshrstr.
        // Long strings are allocated fresh every time, matching PUC
        // luaS_createlngstrobj (not interned).
        if (raw.len <= lua_string_max_short_len) {
            if (self.string_intern.table.get(raw)) |existing| {
                if (self.gc_mode == .generational and self.gc_gen_phase == .minor) existing.gc_age = .old;
                return existing;
            }
            const ls = try createLuaString(self.alloc, raw, hash);
            // PUC luaC_newobj: set current=white on all new objects.
            ls.gc_marked = self.gc_current_white & WHITEBITS;
            if (self.gc_mode == .generational and self.gc_gen_phase == .minor) ls.gc_age = .old;
            try self.string_intern.table.put(self.alloc, ls.bytes(), ls);
            // Register in gc_objects (PUC allgc) so the normal per-object
            // incremental sweep handles short string collection. This is the
            // PUC-faithful approach: PUC keeps all short strings in allgc.
            try self.gcRegisterString(ls);
            self.gcNoteAlloc(@sizeOf(LuaString) + raw.len);
            self.testcNoteMemory(@sizeOf(LuaString) + raw.len + 24);
            self.testc_obj_strings += 1;
            return ls;
        }
        const ls = try createLuaString(self.alloc, raw, hash);
        try self.gcRegisterString(ls);
        self.gcNoteAlloc(@sizeOf(LuaString) + raw.len);
        self.testcNoteMemory(@sizeOf(LuaString) + raw.len + 24);
        self.testc_obj_strings += 1;
        return ls;
    }

    /// Create an external LuaString (PUC 5.5 `lua_pushexternalstring` /
    /// `luaS_newextlstr` with `LSTRMEM`). The content at `content[0..len]` is
    /// NOT copied — it must remain valid until the dealloc callback `falloc`
    /// is invoked during GC of this string. The LuaString header itself is a
    /// normal GC-managed allocation (freed by `destroyLuaString` after the
    /// callback runs).
    ///
    /// PUC always creates external strings as `LUA_VLNGSTR` (long), regardless
    /// of actual length — they are never interned. Equality between two
    /// external strings (or an external and a regular long string) is by
    /// content, handled by `luaStringEq` via the `is_short == false` path.
    ///
    /// The hash is computed with the same per-VM seed as `internStr` so that
    /// table-key lookups involving an external string are consistent with the
    /// interned-string hash space.
    ///
    /// `falloc` has the PUC `lua_Alloc` signature and is called as
    /// `falloc(ud, content, len+1, 0)` when the string is collected. If
    /// `falloc` is null, the string is "fixed" (PUC `LSTRFIX`) — the content
    /// is assumed to be static and no dealloc runs.
    pub fn createExternalLuaString(
        self: *Vm,
        content: [*]const u8,
        len: usize,
        falloc: ?*const fn (?*anyopaque, ?*anyopaque, usize, usize) callconv(.c) ?*anyopaque,
        ud: ?*anyopaque,
    ) std.mem.Allocator.Error!*LuaString {
        const seed = self.rng_state[0] ^ self.rng_state[2];
        var h = std.hash.Wyhash.init(seed);
        h.update(content[0..len]);
        // PUC lstring.c:327-330: if header creation fails (OOM), the caller has
        // already transferred ownership of the external content to Lua, so Lua
        // must give it back by invoking falloc before propagating the error.
        // Without this, the external memory is silently leaked on allocation
        // failure.
        const ls = self.alloc.create(LuaString) catch |e| {
            if (falloc) |fa| {
                _ = fa(ud, @ptrCast(@constCast(content)), len + 1, 0);
            }
            return e;
        };
        // If GC registration fails after the header was allocated, free both
        // the header and the external content (same ownership-transfer logic).
        errdefer {
            if (falloc) |fa| {
                _ = fa(ud, @ptrCast(@constCast(content)), len + 1, 0);
            }
            self.alloc.destroy(ls);
        }
        ls.* = .{
            .hash = h.final(),
            .len = len,
            .is_short = false, // external strings are always "long" (PUC VLNGSTR)
            .is_external = true,
            .external_ptr = content,
            .falloc = falloc,
            .falloc_ud = ud,
        };
        try self.gcRegisterString(ls);
        // Only the header is owned by the GC; the external content is accounted
        // for by the caller (and released via `falloc`).
        self.gcNoteAlloc(@sizeOf(LuaString));
        self.testcNoteMemory(@sizeOf(LuaString));
        self.testc_obj_strings += 1;
        return ls;
    }

    /// Like internStr, but also deduplicates long strings. Used for
    /// bytecode constant pool loads where PUC Lua shares long string
    /// constants across functions in the same chunk.
    ///
    /// P15.35 fix: the cache key must point into the long-lived interned
    /// LuaString's body (which is owned by the VM and never freed while the
    /// cache holds it), NOT into the caller's borrowed `raw` slice. The
    /// previous implementation stored `raw` as the key — but `resolveProtoConstants`
    /// frees the source LuaString right after this call, leaving the cache key
    /// dangling. On the next grow/rehash, the map compared keys through freed
    /// memory, corrupting the table and tripping `assert(!containsContext(...))`.
    fn internStrAll(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        if (raw.len <= lua_string_max_short_len) return self.internStr(raw);
        // For long strings, deduplicate via a separate cache so identical
        // constants share pointer identity (matching PUC's constant pool sharing).
        if (self.long_string_cache.get(raw)) |existing| return existing;
        const ls = try self.internStr(raw);
        // Store ls.bytes() as the key — it points into the interned LuaString's
        // inline body, which is stable for the string's lifetime (GC-managed,
        // rooted via long_string_cache itself in gcMarkMutableRoots).
        try self.long_string_cache.put(self.alloc, ls.bytes(), ls);
        return ls;
    }

    // Intern a string LITERAL (loaded from source via ConstString / bytecode
    // const pool). Short literals go through the global short-string intern
    // table (so a short literal and a short runtime string with the same content
    // share a pointer, as in PUC). Long literals are deduped by content in a
    // separate table — they share a pointer with equal long literals but NOT
    // with equal long runtime strings. Mirrors PUC's compile-time constant
    // folding (luaK_stringK), which dedups literals per Proto regardless of
    // length; we dedup globally (observable only via %p across functions).
    pub fn internLiteral(self: *Vm, raw: []const u8) std.mem.Allocator.Error!*LuaString {
        if (raw.len <= lua_string_max_short_len) return self.internStr(raw);
        if (self.long_literals.table.get(raw)) |existing| {
            if (self.gc_mode == .generational and self.gc_gen_phase == .minor) existing.gc_age = .old;
            return existing;
        }
        const seed = self.rng_state[0] ^ self.rng_state[2];
        var h = std.hash.Wyhash.init(seed);
        h.update(raw);
        const ls = try createLuaString(self.alloc, raw, h.final());
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) ls.gc_age = .old;
        try self.long_literals.table.put(self.alloc, ls.bytes(), ls);
        self.testcNoteMemory(@sizeOf(LuaString) + raw.len + 24);
        self.testc_obj_strings += 1;
        return ls;
    }

    // Intern `raw` from a context that cannot propagate errors (a `void` or
    // bare-`Value` returning function, e.g. the OOM-error setter or a global
    // accessor). These sites only ever feed short constant strings or
    // already-interned messages, so on the rare first-time allocation we
    // abort — exactly what `Vm.init` does for its own allocations. This keeps
    // the call sites free of `try` without introducing a parallel interning
    // path: it routes through `internStr`, so dedup/pointer-identity still hold.
    fn internStrAssume(self: *Vm, raw: []const u8) *LuaString {
        return self.internStr(raw) catch @panic("luazig: oom interning constant string");
    }

    fn expectTable(self: *Vm, v: Value) DispatchError!*Table {
        return switch (v) {
            .Table => |t| t,
            else => self.fail("type error: expected table, got {s}", .{v.typeName()}),
        };
    }

    fn expectThread(self: *Vm, v: Value) DispatchError!*Thread {
        return switch (v) {
            .Thread => |t| t,
            else => self.fail("type error: expected thread, got {s}", .{v.typeName()}),
        };
    }

    fn getGlobal(self: *Vm, name: []const u8) Value {
        if (std.mem.eql(u8, name, "_G")) return .{ .Table = self.global_env };
        if (std.mem.eql(u8, name, "_ENV")) return .{ .Table = self.global_env };
        const v = self.getField(self.global_env, name);
        if (v != .Nil) return v;
        if (std.mem.eql(u8, name, "_VERSION")) return .{ .String = self.internStrAssume("Lua 5.5") };
        return .Nil;
    }

    fn setGlobal(self: *Vm, name: []const u8, v: Value) DispatchError!void {
        // Writing Nil removes the entry (rawSet semantics); no separate dup of
        // the name is needed — the key lives inside the interned LuaString.
        try self.setField(self.global_env, name, v);
    }

    fn errorLocationFrameIndex(self: *const Vm, level: usize) ?*const CallFrame {
        // Walk Thread.call_frames (bytecode). The level semantics match PUC
        // Lua's getfuncname: level 1 = the frame calling error(), etc.
        if (level == 0) return null;
        var remaining = level;

        // Lua frame depth = bytecode frames only (IR frames array is empty).
        const bc_count = self.activeBytecodeThreadConst().call_frames.len();
        const lua_top = bc_count;
        var protected_index = self.protected_c_frame_count;

        // Walk the conceptual Lua/C call chain from top to bottom. A recorded
        // depth is the insertion point of one native pcall/xpcall activation.
        // `combined_index` is a 0-based index from the bottom of the bytecode
        // frame stack.
        while (protected_index != 0) {
            protected_index -= 1;
            const boundary = @min(self.protected_c_frame_depths[protected_index], lua_top);
            const lua_above = lua_top - boundary;
            if (remaining <= lua_above) return self.frameAtCombinedIndex(lua_top - remaining, bc_count);
            remaining -= lua_above;

            // The next conceptual frame is native and has no Lua source.
            if (remaining == 1) return null;
            remaining -= 1;
        }

        if (remaining <= lua_top) return self.frameAtCombinedIndex(lua_top - remaining, bc_count);
        return null;
    }

    /// Resolve a combined 0-based index (from bottom) to a *const CallFrame
    /// pointer. Only bytecode frames exist (in Thread.call_frames).
    fn frameAtCombinedIndex(self: *const Vm, combined_index: usize, bc_count: usize) ?*const CallFrame {
        if (combined_index < bc_count) {
            return self.activeBytecodeThreadConst().call_frames.getConstPtr(combined_index);
        }
        return null;
    }

    /// Const variant of activeBytecodeThread for use in const methods.
    fn activeBytecodeThreadConst(self: *const Vm) *const Thread {
        return self.current_thread orelse self.main_thread.?;
    }

    fn enterProtectedCFrame(self: *Vm) void {
        std.debug.assert(self.protected_c_frame_count < self.protected_c_frame_depths.len);
        // Record the bytecode Lua frame depth so errorLocationFrameIndex can
        // walk the frame stack correctly.
        const bc_count = self.activeBytecodeThread().call_frames.len();
        self.protected_c_frame_depths[self.protected_c_frame_count] = bc_count;
        self.protected_c_frame_count += 1;
    }

    fn leaveProtectedCFrame(self: *Vm) void {
        std.debug.assert(self.protected_c_frame_count != 0);
        self.protected_c_frame_count -= 1;
    }

    /// P15.38i: Re-derive the builtin outs slice from bc_stack after a nested
    /// Lua call that may have triggered bc_stack realloc. Only valid when
    /// builtin_outs_on_bc_stack is true (set by callBuiltin when outs points
    /// into bc_stack). Returns null when outs is not on bc_stack (internal
    /// callers that pass local buffers). Mirrors PUC Lua's restorestack macro.
    fn refreshBuiltinOuts(self: *Vm) ?[]Value {
        if (!self.builtin_outs_on_bc_stack) return null;
        return self.bc_stack[self.builtin_outs_base..self.builtin_outs_base + self.builtin_outs_len];
    }

    fn callBuiltin(self: *Vm, id: BuiltinId, args: []const Value, outs: []Value) DispatchError!void {
        // P15.38i: Track whether outs points into bc_stack. When true, builtins
        // with re-entry (pcall, xpcall, tostring with __tostring, etc.) can
        // re-derive their outs slice via refreshBuiltinOuts() after nested Lua
        // calls that may realloc bc_stack. This mirrors PUC Lua's
        // savestack/restorestack mechanism (ldo.c:277-282).
        const outs_ptr = @intFromPtr(outs.ptr);
        const bc_start = @intFromPtr(self.bc_stack.ptr);
        const bc_end = bc_start + self.bc_stack.len * @sizeOf(Value);
        const prev_on_bc = self.builtin_outs_on_bc_stack;
        const prev_base = self.builtin_outs_base;
        const prev_len = self.builtin_outs_len;
        if (outs_ptr >= bc_start and outs_ptr < bc_end) {
            self.builtin_outs_on_bc_stack = true;
            self.builtin_outs_base = (outs_ptr - bc_start) / @sizeOf(Value);
            self.builtin_outs_len = outs.len;
        } else {
            self.builtin_outs_on_bc_stack = false;
        }
        defer {
            self.builtin_outs_on_bc_stack = prev_on_bc;
            self.builtin_outs_base = prev_base;
            self.builtin_outs_len = prev_len;
        }

        // P15.38i: Helper for builtins with re-entry. After a nested Lua call
        // that may realloc bc_stack, call this to get a fresh outs slice.
        // Usage: const outs = self.refreshBuiltinOuts();

        // Initialize outputs to nil.
        for (outs) |*o| o.* = .Nil;
        self.last_builtin_out_count = outs.len;
        // fr.pc is already current — the dispatch loop writes ctx.pc
        // directly (fr.pc IS the sole program counter). Update current_line
        // from lineinfo so builtins like debug.getinfo, error, and assert
        // see the correct source line.
        {
            const th = self.activeBytecodeThread();
            if (th.call_frames.len() != 0) {
                var fr = th.call_frames.getPtr(th.call_frames.len() - 1);
                if (fr.proto) |proto| {
                    if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                        fr.current_line = @intCast(proto.lineinfo[fr.pc]);
                    }
                }
            }
        }
        const prev_active_builtin = self.active_builtin;
        const prev_active_builtin_args = self.active_builtin_args;
        self.active_builtin = id;
        self.active_builtin_args = args;
        defer {
            self.active_builtin = prev_active_builtin;
            self.active_builtin_args = prev_active_builtin_args;
        }
        switch (id) {
            .print => try self.builtinPrint(args),
            .warn => try self.builtinWarn(args, outs),
            .tostring => {
                if (outs.len == 0) return;
                if (args.len == 0) return self.fail("bad argument #1 to 'tostring' (value expected)", .{});
                if (metamethodValue(self, args[0], "__tostring")) |mm| {
                    var call_args = [_]Value{args[0]};
                    const v = try self.callMetamethod(mm, "__tostring", call_args[0..]);
                    if (v != .String) return self.fail("'__tostring' must return a string", .{});
                    // P15.38i: Re-derive outs — callMetamethod may trigger realloc.
                    const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                    outs_fresh[0] = v;
                } else {
                    // P15.38h: Use stack-buffer fast path for Int/Num to avoid
                    // heap allocation (PUC luaO_tostring model).
                    outs[0] = .{ .String = try self.valueToInternedStr(args[0]) };
                }
            },
            .tonumber => try self.builtinTonumber(args, outs),
            .rawlen => try self.builtinRawlen(args, outs),
            .rawequal => try self.builtinRawequal(args, outs),
            .@"error" => {
                if (args.len == 0 or args[0] == .Nil) {
                    self.err = null;
                    self.err_obj = .Nil;
                    self.err_has_obj = false;
                    self.err_source = null;
                    self.err_line = -1;
                    self.clearErrorTraceback();
                    return error.RuntimeError;
                }
                const msg = switch (args[0]) {
                    .String => |s| s.bytes(),
                    else => "",
                };
                const level: i64 = if (args.len >= 2) switch (args[1]) {
                    .Int => |i| i,
                    .Num => |n| @intFromFloat(n),
                    else => 1,
                } else 1;
                const location_frame = if (args[0] == .String and level > 0)
                    self.errorLocationFrameIndex(@intCast(level))
                else
                    null;
                if (location_frame) |fr_ptr| {
                    const fr = fr_ptr.*;
                    const src = fr.sourceName();
                    // PUC luaG_addinfo uses luaO_chunkid for the source name.
                    var id_buf: [59]u8 = undefined;
                    const chunk = diag.chunkId(id_buf[0..], src);
                    // fr.pc is already current — the dispatch loop writes
                    // ctx.pc directly (fr.pc IS the sole program counter).
                    const pc: usize = fr.pc;
                    const line: i64 = if (fr.proto) |proto| blk: {
                        if (pc < proto.lineinfo.len and proto.lineinfo[pc] != 0) {
                            break :blk @intCast(proto.lineinfo[pc]);
                        }
                        break :blk fr.current_line;
                    } else fr.current_line;
                    var msg_tmp: [256]u8 = undefined;
                    const mlen = @min(msg.len, msg_tmp.len);
                    var mi: usize = 0;
                    while (mi < mlen) : (mi += 1) msg_tmp[mi] = msg[mi];
                    const msg_copy = msg_tmp[0..mlen];
                    self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}:{d}: {s}", .{ chunk, line, msg_copy }) catch blk: {
                        // Never retain `msg_copy`: it points into this stack
                        // frame.  Iterative dispatch makes that dangling slice
                        // visible immediately after the builtin returns.
                        const stable_len = @min(msg_copy.len, self.err_buf.len);
                        @memcpy(self.err_buf[0..stable_len], msg_copy[0..stable_len]);
                        break :blk self.err_buf[0..stable_len];
                    };
                    self.err_obj = .{ .String = try self.internStr(self.err.?) };
                } else {
                    self.err = if (args[0] == .String) msg else null;
                    self.err_obj = args[0];
                }
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                self.err_cfunc_label = "global 'error'";
                // fr.pc is already current — no sync needed.
                // Bytecode frames are in Thread.call_frames.
                {
                    const th = self.activeBytecodeThread();
                    if (th.call_frames.len() != 0) {
                        var fr = th.call_frames.getPtr(th.call_frames.len() - 1);
                        if (fr.proto) |proto| {
                            if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                                fr.current_line = @intCast(proto.lineinfo[fr.pc]);
                            }
                        }
                    }
                }
                // Capture traceback. The error C-frame is not pushed at runtime
                // (it causes stack management issues). Instead, captureErrorTraceback
                // and debugBuildCurrentTraceback synthetically insert
                // [C]: in global 'error' by checking err_cfunc_label.
                self.captureErrorTraceback();
                try self.invokeErrfunc();
                return error.RuntimeError;
            },
            .assert => try self.builtinAssert(args, outs),
            .select => try self.builtinSelect(args, outs),
            .type => try self.builtinType(args, outs),
            .collectgarbage => try self.builtinCollectgarbage(args, outs),
