    /// PUC `setpath` (loadlib.c:274): resolve `package.path`/`cpath` from
    /// environment variables. Tries `versioned_name` first (e.g.
    /// `LUA_PATH_5_5`), then `unversioned_name` (e.g. `LUA_PATH`). If the
    /// env value contains `;;`, replaces it with `default`. Returns the
    /// resolved path as an interned LuaString. Falls back to `default` if
    /// the env vars are not set.
    ///
    /// When `self.noenv` is set (PUC `-E` flag, lua.c:720-723), env vars
    /// are never read: `default` is returned directly. This mirrors PUC's
    /// `noenv(L)` check in `setpath` (loadlib.c:282).
    fn resolveEnvPath(self: *Vm, versioned_name: []const u8, unversioned_name: []const u8, default: []const u8) std.mem.Allocator.Error!*LuaString {
        // PUC `-E`: skip env var reads entirely (loadlib.c:282 `noenv(L)`).
        if (self.noenv) return try self.internStr(default);
        const env = stdio.activeEnviron();
        // Try versioned name first. `getAlloc` returns
        // `error.EnvironmentVariableMissing` (expected, fall through) or
        // `error.OutOfMemory` (must propagate — masking it as "unset" would
        // silently degrade behavior under memory pressure). `InvalidWtf8`
        // would indicate a malformed env var *name*; since the names we pass
        // are ASCII literals, that cannot happen in practice — treat it as
        // "unset" to match PUC's `getenv` (which returns NULL on any issue).
        if (env.getAlloc(self.alloc, versioned_name)) |val| {
            defer self.alloc.free(val);
            return try self.internPathWithDefault(val, default);
        } else |err| switch (err) {
            error.EnvironmentVariableMissing, error.InvalidWtf8 => {},
            else => |e| return e,
        }
        // Try unversioned name
        if (env.getAlloc(self.alloc, unversioned_name)) |val| {
            defer self.alloc.free(val);
            return try self.internPathWithDefault(val, default);
        } else |err| switch (err) {
            error.EnvironmentVariableMissing, error.InvalidWtf8 => {},
            else => |e| return e,
        }
        // Neither set: use default
        return try self.internStr(default);
    }

    /// Helper for `resolveEnvPath`: if `path` contains `;;`, replace with
    /// `default`. Otherwise return `path` as-is.
    fn internPathWithDefault(self: *Vm, path: []const u8, default: []const u8) std.mem.Allocator.Error!*LuaString {
        const sep_pos = std.mem.indexOf(u8, path, ";;");
        if (sep_pos == null) {
            return try self.internStr(path);
        }
        const pos = sep_pos.?;
        // Build: prefix + ";" + default + ";" + suffix (omitting empty parts)
        var list = std.ArrayList(u8).empty;
        defer list.deinit(self.alloc);
        if (pos > 0) {
            try list.appendSlice(self.alloc, path[0..pos]);
            try list.append(self.alloc, ';');
        }
        try list.appendSlice(self.alloc, default);
        if (pos + 2 < path.len) {
            try list.append(self.alloc, ';');
            try list.appendSlice(self.alloc, path[pos + 2 ..]);
        }
        return try self.internStr(list.items);
    }

    fn setArgTableInternal(self: *Vm, argv0: []const u8, script_path: ?[]const u8, script_args: []const []const u8) DispatchError!void {
        const tbl = try self.allocTable();
        if (script_path) |path| {
            try self.tableSetValue(tbl, .{ .Int = -1 }, .{ .String = try self.internStr(argv0) });
            try self.tableSetValue(tbl, .{ .Int = 0 }, .{ .String = try self.internStr(path) });
        } else {
            try self.tableSetValue(tbl, .{ .Int = 0 }, .{ .String = try self.internStr(argv0) });
        }
        for (script_args, 0..) |arg, i| {
            try self.tableSetValue(tbl, .{ .Int = @intCast(i + 1) }, .{ .String = try self.internStr(arg) });
        }
        try self.setGlobal("arg", .{ .Table = tbl });
    }

    /// PUC `createargtable` (lua.c:185-194): build the `arg` table from the
    /// full argv, aligned so that `arg[0]` = `argv[script]`, positive indices
    /// hold script arguments, and negative indices hold options / program name.
    /// `script` is the 1-based index into `puc_argv` of the script name, or 0
    /// if there is no script (in which case `arg[0]` = `puc_argv[0]`).
    pub fn setArgTablePuc(self: *Vm, puc_argv: []const []const u8, script: i32) Error!void {
        return exposeDispatchResult(void, self.setArgTablePucInternal(puc_argv, script));
    }

    fn setArgTablePucInternal(self: *Vm, puc_argv: []const []const u8, script: i32) DispatchError!void {
        const tbl = try self.allocTable();
        const argc: i32 = @intCast(puc_argv.len);
        // PUC: narg = argc - (script + 1)  (positive indices = script args)
        const narg: i32 = if (script >= 0) argc - (script + 1) else argc;
        // Pre-size: narg array entries, script+1 hash entries.
        _ = narg; // tableSetValue handles growth; no pre-size API needed.
        for (puc_argv, 0..) |entry, i| {
            const idx: i64 = @as(i64, @intCast(i)) - @as(i64, script);
            try self.tableSetValue(tbl, .{ .Int = idx }, .{ .String = try self.internStr(entry) });
        }
        try self.setGlobal("arg", .{ .Table = tbl });
    }

    pub fn enableTestcModule(self: *Vm) Error!void {
        return exposeDispatchResult(void, self.enableTestcModuleInternal());
    }

    fn enableTestcModuleInternal(self: *Vm) DispatchError!void {
        self.testc_module_enabled = true;
        // PUC ltests.c `luaB_opentests` replaces the default warnf with the
        // testC version. We dispatch on this flag in `warnfHandler`.
        self.testc_warn_enabled = true;
        const t = try self.allocTableNoGc();
        try self.setField(t, "testC", .{ .Builtin = .testc_testC });
        try self.setField(t, "_makecfunc", .{ .Builtin = .testc_makecfunc });
        try self.setField(t, "_allowhookyield", .{ .Builtin = .testc_allowhookyield });
        try self.setField(t, "totalmem", .{ .Builtin = .testc_totalmem });
        try self.setField(t, "gcage", .{ .Builtin = .testc_gcage });
        try self.setField(t, "gccolor", .{ .Builtin = .testc_gccolor });
        try self.setField(t, "codeparam", .{ .Builtin = .testc_codeparam });
        try self.setField(t, "applyparam", .{ .Builtin = .testc_applyparam });
        try self.setField(t, "querytab", .{ .Builtin = .testc_querytab });
        try self.setField(t, "gcstate", .{ .Builtin = .testc_gcstate });
        try self.setField(t, "listk", .{ .Builtin = .testc_listk });
        try self.setField(t, "listcode", .{ .Builtin = .testc_listcode });
        try self.setField(t, "stacklevel", .{ .Builtin = .testc_stacklevel });
        try self.setField(t, "hash", .{ .Builtin = .testc_hash });
        try self.setField(t, "_newuserdata", .{ .Builtin = .testc_newuserdata });
        try self.setField(t, "_udataval", .{ .Builtin = .testc_udataval });
        try self.setField(t, "_pushuserdata", .{ .Builtin = .testc_pushuserdata });
        try self.setField(t, "_checkpanic", .{ .Builtin = .testc_checkpanic });
        try self.setGlobal("T", .{ .Table = t });
        // PUC ltests.c:2214 — initialize _WARN = false.
        try self.setGlobal("_WARN", .{ .Bool = false });

        const bootstrap_src =
            \\local T = T
            \\local debug = require("debug")
            \\function T.makeCfunc(...)
            \\  local ccl = T._makecfunc(...)
            \\  return function(...) return T.testC(ccl, ...) end
            \\end
            \\function T.d2s(x) return string.pack("d", x) end
            \\function T.s2d(s) return (string.unpack("d", s)) end
            \\do
            \\  local live = setmetatable({}, {__mode = "k"})
            \\  function T.pushuserdata(n)
            \\    return T._pushuserdata(tonumber(n) or 0)
            \\  end
            \\  function T.newuserdata(sz, nuv)
            \\    sz = tonumber(sz) or 0
            \\    if sz > 1000000000 then error("block too big") end
            \\    local lim = select(3, T.totalmem())
            \\    if lim ~= 0 and T.totalmem() + sz > lim then error("not enough memory") end
            \\    nuv = tonumber(nuv) or 0
            \\    local ud = T._newuserdata(sz, nuv)
            \\    live[ud] = sz
            \\    return ud
            \\  end
            \\  function T._liveudbytes()
            \\    local sum = 0
            \\    for ud, sz in pairs(live) do
            \\      -- Skip real Userdata: their memory is tracked by gc_count_kb.
            \\      if type(ud) == "table" then
            \\        sum = sum + (tonumber(sz) or 0)
            \\      end
            \\    end
            \\    return sum
            \\  end
            \\  function T.udataval(u)
            \\    return T._udataval(u)
            \\  end
            \\  function T.allocfailnext() end
            \\end
            \\function T.checkpanic(script, panic_script)
            \\  if panic_script then
            \\    return T._checkpanic(script, panic_script)
            \\  end
            \\  return T._checkpanic(script)
            \\end
            \\T._alloccount = -1
            \\function T.alloccount(v)
            \\  if v ~= nil then T._alloccount = v else T._alloccount = -1 end
            \\  return T._alloccount
            \\end
            \\function T.externKstr(s) return tostring(s) end
            \\function T.externstr(s) return tostring(s) end
            \\function T.checkmemory() return true end
            \\function T.upvalue(f, n, v)
            \\  if type(f) == "table" and f.__testc_upvalues then
            \\    if v ~= nil then f.__testc_upvalues[n] = v end
            \\    return f.__testc_upvalues[n]
            \\  end
            \\  if v ~= nil then debug.setupvalue(f, n, v) end
            \\  local _, val = debug.getupvalue(f, n)
            \\  return val
            \\end
            \\do
            \\  local default_ref = {}
            \\  local function gettab(t)
            \\    t = t or default_ref
            \\    if t[1] == nil then t[1] = 0 end
            \\    return t
            \\  end
            \\  function T.ref(v, t)
            \\    if v == nil then return -1 end
            \\    local tab = gettab(t)
            \\    local free = tab[1]
            \\    if free ~= 0 then
            \\      tab[1] = tab[free]
            \\      tab[free] = v
            \\      return free
            \\    else
            \\      local idx = #tab + 1
            \\      tab[idx] = v
            \\      return idx
            \\    end
            \\  end
            \\  function T.getref(i, t)
            \\    if i == -1 then return nil end
            \\    return gettab(t)[i]
            \\  end
            \\  function T.unref(i, t)
            \\    if i == -1 then return end
            \\    local tab = gettab(t)
            \\    tab[i] = tab[1]
            \\    tab[1] = i
            \\  end
            \\end
            \\function T.sethook(code, mask, count)
            \\  if type(code) == "string" then
            \\    return T._allowhookyield(T.makeCfunc(code), mask, count)
            \\  end
            \\  return debug.sethook(code, mask, count)
            \\end
            \\function T.resume(co)
            \\  local ok, err = coroutine.resume(co)
            \\  if not ok then
            \\    return false, err
            \\  end
            \\  return true
            \\end
            \\function T.querystr() return 2048, 1501 end
            \\-- T.stacklevel: builtin returns real values, but multiret propagation
            \\-- through select(2, T.stacklevel()) is not yet reliable for builtins.
            \\-- Lua wrapper ensures correct multiret. PUC returns 5 values:
            \\--   top, size, nCcalls, nci, c_stack_addr.
            \\-- cstack.lua needs ERRORSTACKSIZE (+200 on overflow) — not yet impl.
            \\do
            \\  local _sl = T.stacklevel
            \\  function T.stacklevel()
            \\    local t, s, cc, ci, addr = _sl()
            \\    return t, s, cc, ci, addr
            \\  end
            \\end
            \\querytab = T.querytab
            \\function T.newstate()
            \\  local st = {_is_test_state=true, _env={}, _loaded={}}
            \\  local env = st._env
            \\  local base = {
            \\    "assert", "error", "getmetatable", "ipairs", "load", "next",
            \\    "pairs", "pcall", "print", "rawequal", "rawget", "rawset",
            \\    "select", "setmetatable", "tonumber", "tostring", "type", "xpcall",
            \\    "collectgarbage",
            \\  }
            \\  for _, k in ipairs(base) do env[k] = _G[k] end
            \\  env._VERSION = _VERSION
            \\  env.T = T
            \\  local function notfound(name)
            \\    return error("module '" .. tostring(name) .. "' not found", 2)
            \\  end
            \\  env.require = function(name)
            \\    if st._loaded[name] ~= nil then return st._loaded[name] end
            \\    local v
            \\    if name == "_G" then
            \\      v = env
            \\      env._G = env
            \\    elseif name == "string" or name == "table" or name == "math" or
            \\           name == "debug" or name == "io" or name == "utf8" or
            \\           name == "os" or name == "coroutine" then
            \\      local ok, mod = pcall(require, name)
            \\      if not ok then return notfound(name) end
            \\      v = mod
            \\    elseif name == "package" then
            \\      v = {loaded = st._loaded, preload = {}, path = "", cpath = ""}
            \\      env.package = v
            \\    else
            \\      return notfound(name)
            \\    end
            \\    st._loaded[name] = v
            \\    return v
            \\  end
            \\  return st
            \\end
            \\function T.closestate(_) return true end
            \\function T.do_on_new_stack(src)
            \\  local co = coroutine.create(function()
            \\    local f, err = load(src)
            \\    if not f then error(err, 0) end
            \\    return f()
            \\  end)
            \\  local ok, a = coroutine.resume(co)
            \\  if not ok then error(a, 0) end
            \\  return 0
            \\end
            \\T.doonnewstack = T.do_on_new_stack
            \\function T.loadlib(L, which, _)
            \\  if type(L) == "table" and type(L._env) == "table" then
            \\    local env = L._env
            \\    if which & 1 ~= 0 and env._G == nil then
            \\      env._G = env
            \\    end
            \\    if which & 2 ~= 0 and env.package == nil then
            \\      env.package = {loaded = L._loaded or {}, preload = {}, path = "", cpath = ""}
            \\    end
            \\  end
            \\  return true
            \\end
            \\function T.doremote(L, s)
            \\  local env = _G
            \\  if type(L) == "table" and type(L._env) == "table" then
            \\    env = L._env
            \\  end
            \\  local f, err = load(s, "=(doremote)", "t", env)
            \\  if not f then return nil, tostring(err), 3 end
            \\  local ok, a, b, c = pcall(f)
            \\  if not ok then return nil, tostring(a), 2 end
            \\  local function cv(v) if v == nil then return nil end; return tostring(v) end
            \\  return cv(a), cv(b), cv(c)
            \\end
        ;
        const source = LuaSource{ .name = "=[testc-bootstrap]", .bytes = bootstrap_src };
        var lex = LuaLexer.init(source);
        lex.global_reserved = self.testc_module_enabled;
        var p = LuaParser.init(&lex) catch return self.fail("{s}", .{lex.diagString()});
        var ast_arena = lua_ast.AstArena.init(self.alloc);
        defer ast_arena.deinit();
        const chunk = p.parseChunkAst(&ast_arena) catch return self.fail("{s}", .{p.diagString()});
        var cg_bc = lua_codegen_bc.Codegen.init(self.alloc, source.name, source.bytes);
        defer cg_bc.deinit();
        const proto = cg_bc.compileChunk(chunk) catch return self.fail("{s}", .{cg_bc.diagString()});

        // Create a proper closure with _ENV upvalue, matching how
        // compileTextChunk + builtinDofile load chunks. The bootstrap source
        // uses global accesses (e.g. `require`, `setmetatable`) that compile
        // to OP_GETTABUP on upvalue 0 (_ENV). Passing empty upvalues causes
        // an out-of-bounds access in gettabup. createBytecodeChunkClosure
        // allocates the upvalue cells; applyLoadEnv sets _ENV to global_env.
        const cl = try self.createBytecodeChunkClosure(proto);
        try self.applyLoadEnv(cl, .{ .Table = self.global_env }, false);
        const ret = try self.runClosure(cl, &.{});
        self.alloc.free(ret);
    }

    fn bootstrapGlobals(self: *Vm) DispatchError!void {
        // Materialize canonical globals inside `_G` itself for `_ENV`-based lookups.
        try self.setGlobal("_G", .{ .Table = self.global_env });
        try self.setGlobal("_VERSION", .{ .String = try self.internStr("Lua 5.5") });

        // Base builtins.
        try self.setGlobal("print", .{ .Builtin = .print });
        try self.setGlobal("warn", .{ .Builtin = .warn });
        try self.setGlobal("tostring", .{ .Builtin = .tostring });
        try self.setGlobal("tonumber", .{ .Builtin = .tonumber });
        try self.setGlobal("error", .{ .Builtin = .@"error" });
        try self.setGlobal("assert", .{ .Builtin = .assert });
        try self.setGlobal("select", .{ .Builtin = .select });
        try self.setGlobal("rawlen", .{ .Builtin = .rawlen });
        try self.setGlobal("rawequal", .{ .Builtin = .rawequal });
        try self.setGlobal("type", .{ .Builtin = .type });
        try self.setGlobal("collectgarbage", .{ .Builtin = .collectgarbage });
        try self.setGlobal("pcall", .{ .Builtin = .pcall });
        try self.setGlobal("xpcall", .{ .Builtin = .xpcall });
        try self.setGlobal("next", .{ .Builtin = .next });
        try self.setGlobal("dofile", .{ .Builtin = .dofile });
        try self.setGlobal("loadfile", .{ .Builtin = .loadfile });
        try self.setGlobal("load", .{ .Builtin = .load });
        try self.setGlobal("require", .{ .Builtin = .require });
        try self.setGlobal("setmetatable", .{ .Builtin = .setmetatable });
        try self.setGlobal("getmetatable", .{ .Builtin = .getmetatable });
        try self.setGlobal("pairs", .{ .Builtin = .pairs });
        try self.setGlobal("ipairs", .{ .Builtin = .ipairs });
        try self.setGlobal("rawget", .{ .Builtin = .rawget });
        try self.setGlobal("rawset", .{ .Builtin = .rawset });

        // package = { path = "..." }
        const package_tbl = try self.allocTableNoGc();
        // PUC `setpath` (loadlib.c:274): read LUA_PATH_5_5 / LUA_PATH env var,
        // with `;;` → default substitution. Falls back to default if unset.
        // When `self.noenv` is set (`-E`), `resolveEnvPath` returns the
        // default directly without reading env vars.
        const path_val = try self.resolveEnvPath("LUA_PATH_5_5", "LUA_PATH", LUA_PATH_DEFAULT);
        try self.setField(package_tbl, "path", .{ .String = path_val });
        const cpath_val = try self.resolveEnvPath("LUA_CPATH_5_5", "LUA_CPATH", LUA_CPATH_DEFAULT);
        try self.setField(package_tbl, "cpath", .{ .String = cpath_val });
        try self.setField(package_tbl, "config", .{ .String = try self.internStr("/\n;\n?\n!\n-\n") });
        try self.setField(package_tbl, "searchpath", .{ .Builtin = .package_searchpath });
        // PUC package.loadlib: dynamic library loading via std.DynLib (Zig's
        // dlopen/dlsym wrapper). Opens the .so, looks up the luaopen_*
        // symbol, and wraps the C function pointer in a Closure so it
        // integrates with the existing C function dispatch (B1/B2).
        try self.setField(package_tbl, "loadlib", .{ .Builtin = .package_loadlib });
        const loaded_tbl = try self.allocTableNoGc();
        const preload_tbl = try self.allocTableNoGc();
        try self.setField(package_tbl, "loaded", .{ .Table = loaded_tbl });
        try self.setField(package_tbl, "preload", .{ .Table = preload_tbl });
        // PUC stores loaded/preload in the registry (LUA_REGISTRYINDEX,
        // LUA_LOADED_TABLE / LUA_PRELOAD_TABLE) so that require still works
        // even if someone replaces the global `package` table. We do the
        // same: store the canonical tables in the debug registry.
        const reg = try self.ensureDebugRegistry();
        try self.setField(reg, "_LOADED", .{ .Table = loaded_tbl });
        try self.setField(reg, "_PRELOAD", .{ .Table = preload_tbl });
        try self.setGlobal("package", .{ .Table = package_tbl });

        // os = core process/filesystem helpers
        const os_tbl = try self.allocTableNoGc();
        try self.setField(os_tbl, "execute", .{ .Builtin = .os_execute });
        try self.setField(os_tbl, "exit", .{ .Builtin = .os_exit });
        try self.setField(os_tbl, "clock", .{ .Builtin = .os_clock });
        try self.setField(os_tbl, "date", .{ .Builtin = .os_date });
        try self.setField(os_tbl, "time", .{ .Builtin = .os_time });
        try self.setField(os_tbl, "difftime", .{ .Builtin = .os_difftime });
        try self.setField(os_tbl, "getenv", .{ .Builtin = .os_getenv });
        try self.setField(os_tbl, "tmpname", .{ .Builtin = .os_tmpname });
        try self.setField(os_tbl, "remove", .{ .Builtin = .os_remove });
        try self.setField(os_tbl, "rename", .{ .Builtin = .os_rename });
        try self.setField(os_tbl, "setlocale", .{ .Builtin = .os_setlocale });
        try self.setGlobal("os", .{ .Table = os_tbl });

        // math subset
        const math_tbl = try self.allocTableNoGc();
        try self.setField(math_tbl, "random", .{ .Builtin = .math_random });
        try self.setField(math_tbl, "randomseed", .{ .Builtin = .math_randomseed });
        try self.setField(math_tbl, "tointeger", .{ .Builtin = .math_tointeger });
        try self.setField(math_tbl, "sin", .{ .Builtin = .math_sin });
        try self.setField(math_tbl, "cos", .{ .Builtin = .math_cos });
        try self.setField(math_tbl, "tan", .{ .Builtin = .math_tan });
        try self.setField(math_tbl, "asin", .{ .Builtin = .math_asin });
        try self.setField(math_tbl, "acos", .{ .Builtin = .math_acos });
        try self.setField(math_tbl, "atan", .{ .Builtin = .math_atan });
        try self.setField(math_tbl, "deg", .{ .Builtin = .math_deg });
        try self.setField(math_tbl, "rad", .{ .Builtin = .math_rad });
        try self.setField(math_tbl, "abs", .{ .Builtin = .math_abs });
        try self.setField(math_tbl, "sqrt", .{ .Builtin = .math_sqrt });
        try self.setField(math_tbl, "exp", .{ .Builtin = .math_exp });
        try self.setField(math_tbl, "ldexp", .{ .Builtin = .math_ldexp });
        try self.setField(math_tbl, "frexp", .{ .Builtin = .math_frexp });
        try self.setField(math_tbl, "ceil", .{ .Builtin = .math_ceil });
        try self.setField(math_tbl, "ult", .{ .Builtin = .math_ult });
        try self.setField(math_tbl, "modf", .{ .Builtin = .math_modf });
        try self.setField(math_tbl, "log", .{ .Builtin = .math_log });
        try self.setField(math_tbl, "fmod", .{ .Builtin = .math_fmod });
        try self.setField(math_tbl, "floor", .{ .Builtin = .math_floor });
        try self.setField(math_tbl, "type", .{ .Builtin = .math_type });
        try self.setField(math_tbl, "min", .{ .Builtin = .math_min });
        try self.setField(math_tbl, "max", .{ .Builtin = .math_max });
        try self.setField(math_tbl, "huge", .{ .Num = std.math.inf(f64) });
        try self.setField(math_tbl, "pi", .{ .Num = std.math.pi });
        try self.setField(math_tbl, "maxinteger", .{ .Int = std.math.maxInt(i64) });
        try self.setField(math_tbl, "mininteger", .{ .Int = std.math.minInt(i64) });
        try self.setGlobal("math", .{ .Table = math_tbl });

        // PUC setrandfunc (lmathlib.c:657-662): seed the PRNG with
        // luaL_makeseed (time + address entropy) + 16 warmup iterations.
        // Without this, math.random produces a deterministic sequence.
        {
            const seed = makeRandomSeed();
            self.randomSetSeed(seed, 0);
        }

        // string = { format = builtin }
        const string_tbl = try self.allocTableNoGc();
        try self.setField(string_tbl, "format", .{ .Builtin = .string_format });
        try self.setField(string_tbl, "pack", .{ .Builtin = .string_pack });
        try self.setField(string_tbl, "packsize", .{ .Builtin = .string_packsize });
        try self.setField(string_tbl, "unpack", .{ .Builtin = .string_unpack });
        try self.setField(string_tbl, "dump", .{ .Builtin = .string_dump });
        try self.setField(string_tbl, "len", .{ .Builtin = .string_len });
        try self.setField(string_tbl, "byte", .{ .Builtin = .string_byte });
        try self.setField(string_tbl, "char", .{ .Builtin = .string_char });
        try self.setField(string_tbl, "upper", .{ .Builtin = .string_upper });
        try self.setField(string_tbl, "lower", .{ .Builtin = .string_lower });
        try self.setField(string_tbl, "reverse", .{ .Builtin = .string_reverse });
        try self.setField(string_tbl, "sub", .{ .Builtin = .string_sub });
        try self.setField(string_tbl, "find", .{ .Builtin = .string_find });
        try self.setField(string_tbl, "match", .{ .Builtin = .string_match });
        try self.setField(string_tbl, "gmatch", .{ .Builtin = .string_gmatch });
        try self.setField(string_tbl, "gsub", .{ .Builtin = .string_gsub });
        try self.setField(string_tbl, "rep", .{ .Builtin = .string_rep });
        try self.setGlobal("string", .{ .Table = string_tbl });
        try self.setField(self.string_metatable, "__index", .{ .Table = string_tbl });

        // table = { unpack = builtin }
        const table_tbl = try self.allocTableNoGc();
        try self.setField(table_tbl, "pack", .{ .Builtin = .table_pack });
        try self.setField(table_tbl, "create", .{ .Builtin = .table_create });
        try self.setField(table_tbl, "move", .{ .Builtin = .table_move });
        try self.setField(table_tbl, "concat", .{ .Builtin = .table_concat });
        try self.setField(table_tbl, "insert", .{ .Builtin = .table_insert });
        try self.setField(table_tbl, "unpack", .{ .Builtin = .table_unpack });
        try self.setField(table_tbl, "remove", .{ .Builtin = .table_remove });
        try self.setField(table_tbl, "sort", .{ .Builtin = .table_sort });
        try self.setGlobal("table", .{ .Table = table_tbl });

        // coroutine = { create, resume, yield, status, running }
        const coro_tbl = try self.allocTableNoGc();
        try self.setField(coro_tbl, "create", .{ .Builtin = .coroutine_create });
        try self.setField(coro_tbl, "wrap", .{ .Builtin = .coroutine_wrap });
        try self.setField(coro_tbl, "resume", .{ .Builtin = .coroutine_resume });
        try self.setField(coro_tbl, "yield", .{ .Builtin = .coroutine_yield });
        try self.setField(coro_tbl, "status", .{ .Builtin = .coroutine_status });
        try self.setField(coro_tbl, "running", .{ .Builtin = .coroutine_running });
        try self.setField(coro_tbl, "isyieldable", .{ .Builtin = .coroutine_isyieldable });
        try self.setField(coro_tbl, "close", .{ .Builtin = .coroutine_close });
        try self.setGlobal("coroutine", .{ .Table = coro_tbl });

        // Minimal utf8 table used by upstream pattern tests.
        const utf8_tbl = try self.allocTableNoGc();
        try self.setField(utf8_tbl, "charpattern", .{ .String = try self.internStr("[\x00-\x7F\xC2-\xFD][\x80-\xBF]*") });
        try self.setField(utf8_tbl, "char", .{ .Builtin = .utf8_char });
        try self.setField(utf8_tbl, "codepoint", .{ .Builtin = .utf8_codepoint });
        try self.setField(utf8_tbl, "len", .{ .Builtin = .utf8_len });
        try self.setField(utf8_tbl, "offset", .{ .Builtin = .utf8_offset });
        try self.setField(utf8_tbl, "codes", .{ .Builtin = .utf8_codes });
        try self.setGlobal("utf8", .{ .Table = utf8_tbl });

        // io = { input/output/write over std streams, stderr = { write = builtin } }
        const io_tbl = try self.allocTableNoGc();
        try self.setField(io_tbl, "write", .{ .Builtin = .io_write });
        try self.setField(io_tbl, "open", .{ .Builtin = .io_open });
        try self.setField(io_tbl, "popen", .{ .Builtin = .io_popen });
        try self.setField(io_tbl, "tmpfile", .{ .Builtin = .io_tmpfile });
        try self.setField(io_tbl, "read", .{ .Builtin = .io_read });
        try self.setField(io_tbl, "lines", .{ .Builtin = .io_lines });
        try self.setField(io_tbl, "flush", .{ .Builtin = .io_flush });
        try self.setField(io_tbl, "input", .{ .Builtin = .io_input });
        try self.setField(io_tbl, "output", .{ .Builtin = .io_output });
        try self.setField(io_tbl, "close", .{ .Builtin = .io_close });
        try self.setField(io_tbl, "type", .{ .Builtin = .io_type });

        const file_mt = try self.allocTableNoGc();
        try self.setField(file_mt, "__name", .{ .String = try self.internStr("FILE*") });
        try self.setField(file_mt, "__gc", .{ .Builtin = .file_gc });
        try self.setField(file_mt, "__close", .{ .Builtin = .file_meta_close });
        self.file_metatable = file_mt;

        // PUC Lua registers stdin/stdout/stderr as proper FILE* handles in
        // `newprefile`/`luaL_streaminit`. They share the same metatable and
        // method set as files opened with `io.open`, and their seeks delegate
        // to the OS `lseek` syscall (succeeding on ttys/regular files, failing
        // with ESPIPE on pipes). We mirror that by allocating them through
        // `allocManagedFileObject` so they live in `open_files`/`file_buffers`
        // and all `file:*` methods work uniformly.
        //
        // `sequential = true` selects streaming I/O (readStreaming/
        // writeStreamingAll), matching PUC `fread`/`fwrite` on std streams.
        // The seek implementation in `builtinFileSeek` calls the OS seek
        // directly so pipes fail with "Illegal seek" while ttys/regular files
        // succeed, exactly like PUC `fseek` → `lseek`.
        const stdin_v = try self.allocManagedFileObject(std.Io.File.stdin(), true, false, true);
        try self.setField(io_tbl, "stdin", stdin_v);
        try self.setField(io_tbl, "input_stream", stdin_v);

        const stdout_v = try self.allocManagedFileObject(std.Io.File.stdout(), false, true, true);
        // PUC Lua sets stdout to line-buffered (`_IOLBF`); luazig's `io.write`
        // bypasses the managed buffer and writes directly to `stdio.stdout()`,
        // so we disable buffering on the managed stdout object to keep
        // `io.write` and `io.stdout:write` consistent in ordering.
        if (self.getFileBuffer(stdout_v)) |fb| fb.mode = .no;
        try self.setField(io_tbl, "stdout", stdout_v);
        try self.setField(io_tbl, "output_stream", stdout_v);

        const stderr_v = try self.allocManagedFileObject(std.Io.File.stderr(), false, true, true);
        // PUC Lua sets stderr to unbuffered (`_IONBF`); mirror that so error
        // output is never delayed by the managed buffer.
        if (self.getFileBuffer(stderr_v)) |fb| fb.mode = .no;
        try self.setField(io_tbl, "stderr", stderr_v);

        try self.setGlobal("io", .{ .Table = io_tbl });

        // Preload core modules in package.loaded for simple require parity.
        try self.setField(loaded_tbl, "package", .{ .Table = package_tbl });
        try self.setField(loaded_tbl, "string", .{ .Table = string_tbl });
        try self.setField(loaded_tbl, "math", .{ .Table = math_tbl });
        try self.setField(loaded_tbl, "table", .{ .Table = table_tbl });
        try self.setField(loaded_tbl, "io", .{ .Table = io_tbl });
        try self.setField(loaded_tbl, "os", .{ .Table = os_tbl });
        try self.setField(loaded_tbl, "coroutine", .{ .Table = coro_tbl });
        try self.setField(loaded_tbl, "utf8", .{ .Table = utf8_tbl });

        // PUC Lua opens the debug library into the global environment when
        // the standard libraries are loaded. `require("debug")` must return
        // this same table through package.loaded.
        const debug_tbl = try self.createDebugTableNoGc();
        try self.setGlobal("debug", .{ .Table = debug_tbl });
        try self.setField(loaded_tbl, "debug", .{ .Table = debug_tbl });
    }

    fn fillDebugTable(self: *Vm, mod: *Table) DispatchError!void {
        // Provide a growing subset of the standard debug library. The table is
        // intentionally built in one place so `_G.debug` and `require("debug")`
        // cannot diverge.
        try self.setField(mod, "getinfo", .{ .Builtin = .debug_getinfo });
        try self.setField(mod, "getlocal", .{ .Builtin = .debug_getlocal });
        try self.setField(mod, "setlocal", .{ .Builtin = .debug_setlocal });
        try self.setField(mod, "getupvalue", .{ .Builtin = .debug_getupvalue });
        try self.setField(mod, "setupvalue", .{ .Builtin = .debug_setupvalue });
        try self.setField(mod, "upvalueid", .{ .Builtin = .debug_upvalueid });
        try self.setField(mod, "upvaluejoin", .{ .Builtin = .debug_upvaluejoin });
        try self.setField(mod, "gethook", .{ .Builtin = .debug_gethook });
        try self.setField(mod, "sethook", .{ .Builtin = .debug_sethook });
        try self.setField(mod, "getregistry", .{ .Builtin = .debug_getregistry });
        try self.setField(mod, "traceback", .{ .Builtin = .debug_traceback });
        try self.setField(mod, "getuservalue", .{ .Builtin = .debug_getuservalue });
        try self.setField(mod, "setmetatable", .{ .Builtin = .debug_setmetatable });
        try self.setField(mod, "getmetatable", .{ .Builtin = .getmetatable });
        try self.setField(mod, "setuservalue", .{ .Builtin = .debug_setuservalue });
        try self.setField(mod, "debug", .{ .Builtin = .debug_debug });
    }

    fn createDebugTableNoGc(self: *Vm) DispatchError!*Table {
        const mod = try self.allocTableNoGc();
        try self.fillDebugTable(mod);
        return mod;
    }

    fn createDebugTable(self: *Vm) DispatchError!*Table {
        const mod = try self.allocTable();
        try self.fillDebugTable(mod);
        return mod;
    }

    fn builtinAssert(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'assert' (value expected)", .{});
        if (!isTruthy(args[0])) {
            if (args.len > 1 and args[1] != .Nil) {
                self.err = switch (args[1]) {
                    .String => |s| s.bytes(),
                    else => null,
                };
                self.err_obj = args[1];
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                self.captureErrorTraceback();
                return error.RuntimeError;
            }
            // Check Thread.call_frames (bytecode frames) for source location
            // to include in the assert error message.
            const th = self.activeBytecodeThread();
            if (th.call_frames.len() != 0) {
                const fr = th.call_frames.getConstPtr(th.call_frames.len() - 1).*;
                const src = fr.sourceName();
                const chunk = if (src.len != 0 and (src[0] == '@' or src[0] == '=')) src[1..] else src;
                self.err = std.fmt.bufPrint(self.err_buf[0..], "{s}:{d}: assertion failed!", .{ chunk, fr.current_line }) catch "assertion failed!";
            } else {
                self.err = "assertion failed!";
            }
            self.err_obj = .{ .String = try self.internStr(self.err.?) };
            self.err_has_obj = true;
            self.err_source = null;
            self.err_line = -1;
            self.captureErrorTraceback();
            return error.RuntimeError;
        }
        const n = @min(outs.len, args.len);
        for (0..n) |i| outs[i] = args[i];
    }

    fn builtinSelect(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'select' (number expected)", .{});
        switch (args[0]) {
            .String => |s| {
                if (s != self.internStrAssume("#")) {
                    return self.fail("bad argument #1 to 'select' (number expected)", .{});
                }
                if (outs.len > 0) outs[0] = .{ .Int = @intCast(args.len - 1) };
            },
            .Int => |raw_idx| {
                var idx = raw_idx;
                const n = args.len - 1;
                if (idx == 0) return self.fail("bad argument #1 to 'select' (index out of range)", .{});
                if (idx < 0) idx += @as(i64, @intCast(n)) + 1;
                if (idx < 1) return self.fail("bad argument #1 to 'select' (index out of range)", .{});
                const start: usize = @intCast(idx);
                if (start > n) return;
                const count = @min(outs.len, n - start + 1);
                for (0..count) |k| outs[k] = args[start + k];
            },
            else => return self.fail("bad argument #1 to 'select' (number expected)", .{}),
        }
    }

    fn builtinType(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'type' (value expected)", .{});
        const v = args[0];
        if (asFileTable(self, v) != null) {
            outs[0] = .{ .String = try self.internStr("userdata") };
            return;
        }
        outs[0] = .{ .String = try self.internStr(switch (v) {
            .Nil => "nil",
            .Bool => "boolean",
            .Int, .Num => "number",
            .String => "string",
            .Table => "table",
            .Builtin, .Closure => "function",
            .Thread => "thread",
            .LightUserdata, .Userdata => "userdata",
        }) };
    }

    fn builtinRawlen(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'rawlen' (value expected)", .{});
        switch (args[0]) {
            .String => |s| outs[0] = .{ .Int = @intCast(s.len) },
            .Table => |t| {
                if (t.metatable) |mt| {
                    if (self.getFieldOpt(mt, "__name")) |nm| {
                        if (nm == .String and nm.String == self.internStrAssume("FILE*")) {
                            return self.fail("bad argument #1 to 'rawlen' (table or string expected)", .{});
                        }
                    }
                }
                outs[0] = .{ .Int = self.tableBorderLen(t) };
            },
            else => return self.fail("bad argument #1 to 'rawlen' (table or string expected)", .{}),
        }
    }

    fn builtinRawequal(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len < 2) return self.fail("bad argument #2 to 'rawequal' (value expected)", .{});
        outs[0] = .{ .Bool = valuesEqual(args[0], args[1]) };
    }

    fn builtinTonumber(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) {
            return self.fail("bad argument #1 to 'tonumber' (value expected)", .{});
        }

        if (args.len > 1 and args[1] != .Nil) {
            const base = switch (args[1]) {
                .Int => |b| b,
                else => {
                    outs[0] = .Nil;
                    return;
                },
            };
            if (base < 2 or base > 36) return self.fail("bad argument #2 to 'tonumber' (base out of range)", .{});
            const s0 = switch (args[0]) {
                .String => |s| s.bytes(),
                else => {
                    outs[0] = .Nil;
                    return;
                },
            };
            const s = std.mem.trim(u8, s0, " \t\r\n");
            const n = std.fmt.parseInt(i64, s, @intCast(base)) catch {
                outs[0] = .Nil;
                return;
            };
            outs[0] = .{ .Int = n };
            return;
        }

        switch (args[0]) {
            .Int, .Num => outs[0] = args[0],
            .String => |s0| {
                const s = std.mem.trim(u8, s0.bytes(), " \t\r\n");
                if (s.len == 0) {
                    outs[0] = .Nil;
                    return;
                }
                if (parseHexStringIntWrap(s)) |iv| {
                    outs[0] = .{ .Int = iv };
                    return;
                }
                if (std.fmt.parseInt(i64, s, 0)) |iv| {
                    outs[0] = .{ .Int = iv };
                    return;
                } else |_| {}
                const s_no_sign = if (s.len > 0 and (s[0] == '+' or s[0] == '-')) s[1..] else s;
                if (std.ascii.eqlIgnoreCase(s_no_sign, "inf") or std.ascii.eqlIgnoreCase(s_no_sign, "infinity") or std.ascii.eqlIgnoreCase(s_no_sign, "nan")) {
                    outs[0] = .Nil;
                    return;
                }
                if (parseHexFloatFastPath(s)) |hv| {
                    outs[0] = .{ .Num = hv };
                    return;
                }
                if (std.fmt.parseFloat(f64, s)) |nv| {
                    outs[0] = .{ .Num = nv };
                    return;
                } else |_| {}
                outs[0] = .Nil;
            },
            else => outs[0] = .Nil,
        }
    }

    fn gcStep(self: *Vm, requested_kb: i64) DispatchError!bool {
        if (self.gc_busy) return false;

        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            try self.gcMinorCollection();
            return false;
        }

        const step_size = if (requested_kb > 0) requested_kb else self.gc_stepsize;
        if (step_size == 0) {
            try self.gcCycleFull();
            return true;
        }
        if (self.gc_state == .pause) {
            if (self.gc_mode == .generational and self.gc_gen_phase == .major) {
                self.gc_gen_major_start_kb = self.gc_count_kb;
            }
            try self.gcStartCycle(true);
        }
        return self.gcAdvance(self.gcStepBudget(step_size), true);
    }

    fn builtinCollectgarbage(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        const want_out = outs.len > 0;
        // PUC GCSTPCLS: when the state is closing (lua_close →
        // luaC_freeallobjects sets g->gcstp = GCSTPCLS), the collector is
        // fully stopped. `collectgarbage()` with no args returns false
        // because `luaC_collect` checks `gcstp & GCSTP` and bails out.
        // The test at main.lua:327 calls `collectgarbage()` from a __gc
        // finalizer during state close and expects `false`.
        if (self.is_closing) {
            if (args.len == 0) {
                if (want_out) outs[0] = .{ .Bool = false };
                return;
            }
            // For explicit options like "collect", "step", etc. during close,
            // also return false/0 — the collector is stopped.
            if (want_out) outs[0] = .{ .Bool = false };
            return;
        }
        // Lua collector is not reentrant. Calls that would start/advance a
        // collection cycle from inside `__gc` should return false.
        if (self.gc_busy and args.len == 0) {
            if (want_out) outs[0] = .{ .Bool = false };
            return;
        }
        if (args.len == 0) {
            if (self.testc_gc_pending_finalize_kb >= 8.0 and !self.testc_gc_pending_finalize_seen) {
                self.testc_gc_pending_finalize_seen = true;
                if (want_out) outs[0] = .{ .Int = 0 };
                return;
            }
            try self.gcFullCollectionForUser();
            if (self.testc_gc_pending_finalize_kb > 0.0) {
                if (self.testc_gc_pending_finalize_seen) {
                    self.testc_gc_manual_kb = @max(0.0, self.testc_gc_manual_kb - self.testc_gc_pending_finalize_kb);
                    self.testc_gc_pending_finalize_kb = 0.0;
                    self.testc_gc_pending_finalize_seen = false;
                } else {
                    self.testc_gc_pending_finalize_seen = true;
                }
            }
            if (want_out) outs[0] = .{ .Int = 0 };
            return;
        }

        const what = switch (args[0]) {
            .String => |s| s.bytes(),
            else => return self.fail("collectgarbage expects string", .{}),
        };

        if (std.mem.eql(u8, what, "count")) {
            if (want_out) {
                const live_ud_kb = self.testcLiveUserdataKb();
                outs[0] = .{ .Num = self.gc_count_kb + live_ud_kb + self.testc_gc_manual_kb + self.testc_gc_count_bonus_once_kb };
            }
            self.testc_gc_count_bonus_once_kb = 0.0;
            return;
        }
        if (std.mem.eql(u8, what, "isrunning")) {
            if (want_out) outs[0] = .{ .Bool = self.gc_running };
            return;
        }
        if (std.mem.eql(u8, what, "stop")) {
            self.gc_running = false;
            if (want_out) outs[0] = .{ .Bool = true };
            return;
        }
        if (std.mem.eql(u8, what, "restart")) {
            self.gc_running = true;
            // PUC Lua resets GC debt to zero on restart, so the next
            // allocation immediately gets a chance to advance the collector.
            // Leaving the old post-cycle threshold here can defer progress by
            // hundreds of kilobytes and makes the upstream pace test diverge.
            self.gc_auto_threshold_kb = self.gc_count_kb;
            // PUC: luaC_restart sets debt to 0 so the next allocation
            // immediately triggers a step. Our gc_step_debt_kb is the debt
            // analogue; reset it to 0.
            self.gc_step_debt_kb = 0;
            self.gc_alloc_tables = self.gc_alloc_threshold;
            self.gc_tick = self.gc_tick_threshold;
            if (want_out) outs[0] = .{ .Bool = true };
            return;
        }
        if (std.mem.eql(u8, what, "incremental")) {
            const prev = self.gc_mode;
            if (prev == .generational) self.gcLeaveGenerational();
            if (want_out) outs[0] = .{ .String = try self.internStr(if (prev == .incremental) "incremental" else "generational") };
            return;
        }
        if (std.mem.eql(u8, what, "generational")) {
            const prev = self.gc_mode;
            if (prev == .incremental) try self.gcEnterGenerational();
            if (want_out) outs[0] = .{ .String = try self.internStr(if (prev == .incremental) "incremental" else "generational") };
            return;
        }
        if (std.mem.eql(u8, what, "param")) {
            if (args.len < 2) return self.fail("collectgarbage('param', ...) expects parameter name", .{});
            const pname = switch (args[1]) {
                .String => |s| s.bytes(),
                else => return self.fail("collectgarbage('param', ...) expects parameter name", .{}),
            };

            var target: *i64 = undefined;
            if (std.mem.eql(u8, pname, "pause"))
                target = &self.gc_pause
            else if (std.mem.eql(u8, pname, "stepmul"))
                target = &self.gc_stepmul
            else if (std.mem.eql(u8, pname, "stepsize"))
                target = &self.gc_stepsize
            else if (std.mem.eql(u8, pname, "minormul"))
                target = &self.gc_gen_minormul
            else if (std.mem.eql(u8, pname, "minormajor"))
                target = &self.gc_gen_minormajor
            else if (std.mem.eql(u8, pname, "majorminor"))
                target = &self.gc_gen_majorminor
            else
                return self.fail("collectgarbage: unknown param '{s}'", .{pname});

            const old = target.*;
            if (args.len >= 3) {
                const newv = switch (args[2]) {
                    .Int => |x| x,
                    else => return self.fail("collectgarbage('param', ..., value) expects integer value", .{}),
                };
                target.* = newv;
                if (std.mem.eql(u8, pname, "pause") or std.mem.eql(u8, pname, "minormul")) self.gcScheduleNextAutomaticCycle();
            }
            if (want_out) outs[0] = .{ .Int = old };
            return;
        }
        if (std.mem.eql(u8, what, "step")) {
            const requested_kb: i64 = if (args.len >= 2) switch (args[1]) {
                .Int => |n| n,
                else => return self.fail("collectgarbage('step', size) expects integer size", .{}),
            } else 0;
            const completed = try self.gcStep(requested_kb);
            if (want_out) outs[0] = .{ .Bool = completed };
            return;
        }
        if (std.mem.eql(u8, what, "collect")) {
            if (self.gc_busy) {
                if (want_out) outs[0] = .{ .Bool = false };
                return;
            }
            // `stop` disables automatic collection only. Explicit collection
            // remains available and must not change the running/stopped state.
            try self.gcFullCollectionForUser();
            if (want_out) outs[0] = .{ .Int = 0 };
            return;
        }

        return self.fail("collectgarbage: invalid option '{s}'", .{what});
    }

    fn builtinPcall(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        self.last_builtin_out_count = 0;
        if (args.len == 0) return self.fail("pcall expects function", .{});
        if (self.activeProtectedCallDepth() >= 128) {
            self.err = "stack overflow error";
            self.err_obj = .{ .String = try self.internStr("stack overflow error") };
            self.err_has_obj = true;
            self.err_source = null;
            self.err_line = -1;
            self.captureErrorTraceback();
            if (outs.len > 0) {
                outs[0] = .{ .Bool = false };
                if (outs.len > 1) outs[1] = self.protectedErrorValue();
                self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
            }
            return;
        }
        self.protected_call_depth += 1;
        defer self.protected_call_depth -= 1;
        self.enterProtectedCFrame();
        defer self.leaveProtectedCFrame();
        // PUC luaD_pcall: clear errfunc for the duration of pcall — pcall
        // has no message handler. Restore on return (including error path).
        const saved_errfunc = self.errfunc;
        self.errfunc = null;
        defer self.errfunc = saved_errfunc;
        // PUC ldo.c:luaD_pcall calls luaD_shrinkstack on the error path
        // to restore stack size after overflow. We call it unconditionally
        // (it's a no-op when the stack isn't oversized).
        defer self.shrinkBcStack();

        const callee = args[0];
        const call_args = args[1..];

        // Preserve error string; pcall should not permanently clobber it.
        const prev_err = self.err;
        const prev_err_obj = self.err_obj;
        const prev_err_has_obj = self.err_has_obj;
        const prev_err_source = self.err_source;
        const prev_err_line = self.err_line;
        const prev_err_traceback = self.err_traceback;
        var rethrow_forced_close = false;
        self.err_traceback = null;
        defer {
            self.clearErrorTraceback();
            if (!rethrow_forced_close) {
                self.err = prev_err;
                self.err_obj = prev_err_obj;
                self.err_has_obj = prev_err_has_obj;
                self.err_source = prev_err_source;
                self.err_line = prev_err_line;
            }
            self.err_traceback = prev_err_traceback;
        }

        if (outs.len == 0) {
            // Evaluate and swallow any runtime error.
            const resolved = self.resolveCallable(callee, call_args, null) catch return;
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);
            switch (resolved.callee) {
                .Builtin => |id| self.callBuiltin(id, resolved.args, &[_]Value{}) catch {},
                .Closure => |cl| {
                    const ret = self.runClosure(cl, resolved.args) catch {
                        return;
                    };
                    self.alloc.free(ret);
                },
                else => unreachable,
            }
            return;
        }

        // Helper to write failure tuple.
        const setFail = struct {
            fn f(vm: *Vm, o: []Value) void {
                o[0] = .{ .Bool = false };
                if (o.len > 1) {
                    const errv = if (vm.activeErrorHandlerDepth() != 0)
                        Value{ .String = vm.internStrAssume("error in error handling") }
                    else
                        vm.protectedErrorValue();
                    o[1] = errv;
                }
                vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
            }
        }.f;
        const mem_before_call = self.testc_total_bytes;
        const obj_tables_before_call = self.testc_obj_tables;
        const obj_functions_before_call = self.testc_obj_functions;
        const obj_threads_before_call = self.testc_obj_threads;
        const obj_strings_before_call = self.testc_obj_strings;
        const rollbackMemoryError = struct {
            fn f(vm: *Vm, mem: usize, tables: usize, functions: usize, threads: usize, strings: usize) void {
                const errv = vm.protectedErrorValue();
                if (isTestcMemoryErrorValue(errv)) {
                    vm.testc_total_bytes = mem;
                    vm.testc_obj_tables = tables;
                    vm.testc_obj_functions = functions;
                    vm.testc_obj_threads = threads;
                    vm.testc_obj_strings = strings;
                }
            }
        }.f;

        const resolved = self.resolveCallable(callee, call_args, null) catch |e| switch (e) {
            error.Yield => return e,
            error.OutOfMemory => {
                self.setOutOfMemoryError();
                rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                setFail(self, outs);
                return;
            },
            else => {
                rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                setFail(self, outs);
                return;
            },
        };
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);

        switch (resolved.callee) {
            .Builtin => |id| {
                // Call builtin with as many result slots as we can return.
                const nouts = if (outs.len > 1) outs.len - 1 else 0;
                var tmp_small: [8]Value = undefined;
                var tmp: []Value = undefined;
                var tmp_heap = false;
                if (nouts <= tmp_small.len) {
                    tmp = tmp_small[0..nouts];
                } else {
                    tmp = self.alloc.alloc(Value, nouts) catch |e| switch (e) {
                        error.OutOfMemory => {
                            self.setOutOfMemoryError();
                            rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                            setFail(self, outs);
                            return;
                        },
                    };
                    tmp_heap = true;
                }
                defer if (tmp_heap) self.alloc.free(tmp);

                self.callBuiltin(id, resolved.args, tmp) catch |e| switch (e) {
                    error.Yield => return e,
                    error.OutOfMemory => {
                        self.setOutOfMemoryError();
                        rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                        setFail(self, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                    else => {
                        if (id == .@"error") {
                            const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                            outs_fresh[0] = .{ .Bool = false };
                            if (outs_fresh.len > 1) outs_fresh[1] = self.protectedErrorValue();
                            self.last_builtin_out_count = @min(@as(usize, 2), outs_fresh.len);
                            return;
                        }
                        if (self.shouldRethrowForcedClose()) {
                            rethrow_forced_close = true;
                            return error.RuntimeError;
                        }
                        rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                        setFail(self, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                };

                // P15.38i: Re-derive outs — callBuiltin may have triggered
                // bc_stack realloc via nested re-entry.
                const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                outs_fresh[0] = .{ .Bool = true };
                const used_tmp = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, tmp.len)
                else
                    tmp.len;
                for (0..used_tmp) |i| {
                    const v = tmp[i];
                    if (1 + i >= outs_fresh.len) break;
                    outs_fresh[1 + i] = v;
                }
                self.last_builtin_out_count = @min(1 + used_tmp, outs_fresh.len);
            },
            .Closure => |cl| {
                // PUC luaD_pcall: save old_top (L->top) and old_ci (L->ci)
                // before calling f. On error, restore them so error value
                // has room.
                const saved_bc_stack_top = self.bc_stack_top;
                const th_pcall = self.activeBytecodeThread();
                const saved_frame_count = th_pcall.call_frames.len();
                const ret = self.runClosure(cl, resolved.args) catch |e| switch (e) {
                    error.Yield => return e,
                    error.OutOfMemory => {
                        self.setOutOfMemoryError();
                        self.unwindBytecodeExecFrames(&th_pcall.call_frames, saved_frame_count);
                        self.bc_stack_top = saved_bc_stack_top;
                        rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                        setFail(self, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                    else => {
                        if (self.shouldRethrowForcedClose()) {
                            rethrow_forced_close = true;
                            return error.RuntimeError;
                        }
                        self.unwindBytecodeExecFrames(&th_pcall.call_frames, saved_frame_count);
                        self.bc_stack_top = saved_bc_stack_top;
                        rollbackMemoryError(self, mem_before_call, obj_tables_before_call, obj_functions_before_call, obj_threads_before_call, obj_strings_before_call);
                        setFail(self, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                };
                defer self.alloc.free(ret);

                // P15.38i: Re-derive outs — runClosure may have triggered
                // bc_stack realloc via nested re-entry.
                const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                outs_fresh[0] = .{ .Bool = true };
                const n = @min(ret.len, outs_fresh.len - 1);
                for (0..n) |i| outs_fresh[1 + i] = ret[i];
                self.last_builtin_out_count = 1 + n;
            },
            else => unreachable,
        }
    }

    fn builtinXpcall(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        self.last_builtin_out_count = 0;
        if (args.len < 2) return self.fail("xpcall expects (f, msgh [, args...])", .{});
        if (self.activeProtectedCallDepth() >= 128) {
            // PUC luaD_pcall: when C-stack depth is exceeded, luaG_runerror
            // is called, which invokes the message handler (L->errfunc).
            // We must call setFail to invoke the handler, not just return.
            self.err = "stack overflow error";
            self.err_obj = .{ .String = try self.internStr("stack overflow error") };
            self.err_has_obj = true;
            self.err_source = null;
            self.err_line = -1;
            self.captureErrorTraceback();
            // PUC luaD_growstack: on overflow, grow stack to ERRORSTACKSIZE
            // (MAXSTACK + 200) so the error handler has room to run.
            const MAXSTACK: usize = 1_000_000;
            const ERRORSTACKSIZE: usize = 200;
            const PHYSICAL_LIMIT: usize = MAXSTACK + ERRORSTACKSIZE;
            if (self.bc_stack.len < PHYSICAL_LIMIT) {
                const old_len = self.bc_stack.len;
                self.bc_stack = self.alloc.realloc(self.bc_stack, PHYSICAL_LIMIT) catch {
                    if (outs.len > 0) {
                        outs[0] = .{ .Bool = false };
                        if (outs.len > 1) outs[1] = self.protectedErrorValue();
                        self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
                    }
                    return;
                };
                self.bc_boxed = self.alloc.realloc(self.bc_boxed, PHYSICAL_LIMIT) catch {
                    if (outs.len > 0) {
                        outs[0] = .{ .Bool = false };
                        if (outs.len > 1) outs[1] = self.protectedErrorValue();
                        self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
                    }
                    return;
                };
                @memset(self.bc_stack[old_len..], .Nil);
                @memset(self.bc_boxed[old_len..], null);
                const th_realloc = self.activeBytecodeThread();
                for (0..th_realloc.call_frames.len()) |i| {
                    const fr = th_realloc.call_frames.getPtr(i);
                    if (fr.proto != null) {
                        const b = fr.base;
                        const cap = fr.regs.len;
                        const safe_cap = @min(cap, self.bc_stack.len -| b);
                        fr.regs = self.bc_stack[b .. b + safe_cap];
                        const safe_boxed = @min(cap, self.bc_boxed.len -| b);
                        fr.boxed = self.bc_boxed[b .. b + safe_boxed];
                    }
                }
            }
            const setFail = struct {
                fn run(vm: *Vm, handler: Value, o: []Value) DispatchError!void {
                    o[0] = .{ .Bool = false };
                    if (o.len <= 1) {
                        vm.last_builtin_out_count = @min(@as(usize, 1), o.len);
                        return;
                    }
                    // The error handler runs with the stack at ERRORSTACKSIZE,
                    // grown above.  The handling_overflow check in
                    // pushBytecodeExecFrame skips the overflow check when
                    // bc_stack.len > MAXSTACK and in_error_handler > 0.
                    const emsg: Value = vm.errorHandlerInput();
                    vm.in_error_handler += 1;
                    defer vm.in_error_handler -= 1;
                    switch (handler) {
                        .Builtin => |id| {
                            var in = [_]Value{emsg};
                            var out: [1]Value = .{.Nil};
                            vm.callBuiltin(id, in[0..], out[0..]) catch {
                                o[1] = .{ .String = try vm.internStr("error in error handling") };
                                vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                                return;
                            };
                            o[1] = try vm.normalizeProtectedErrorResult(out[0]);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                        .Closure => |cl| {
                            var in = [_]Value{emsg};
                            const ret = vm.runClosure(cl, in[0..]) catch {
                                o[1] = .{ .String = try vm.internStr("error in error handling") };
                                vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                                return;
                            };
                            defer vm.alloc.free(ret);
                            const result = if (ret.len > 0) ret[0] else .Nil;
                            o[1] = try vm.normalizeProtectedErrorResult(result);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                        else => {
                            o[1] = try vm.normalizeProtectedErrorResult(emsg);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                    }
                }
            }.run;
            try setFail(self, args[1], outs);
            return;
        }
        self.protected_call_depth += 1;
        defer self.protected_call_depth -= 1;
        self.enterProtectedCFrame();
        defer self.leaveProtectedCFrame();
        defer self.shrinkBcStack();

        // PUC luaD_pcall: clear errfunc — xpcall has its own handler
        // mechanism (setFail) that runs after error propagation. We don't
        // use the errfunc mechanism here to avoid double handler invocation.
        // TODO: migrate xpcall to errfunc mechanism (runs handler BEFORE
        // unwinding) — this is the same architectural gap as formatCliError.
        const saved_errfunc = self.errfunc;
        self.errfunc = null;
        defer self.errfunc = saved_errfunc;

        const f = args[0];
        const msgh = args[1];
        const call_args = args[2..];

        const prev_err = self.err;
        const prev_err_obj = self.err_obj;
        const prev_err_has_obj = self.err_has_obj;
        const prev_err_source = self.err_source;
        const prev_err_line = self.err_line;
        const prev_err_traceback = self.err_traceback;
        var rethrow_forced_close = false;
        self.err_traceback = null;
        defer {
            self.clearErrorTraceback();
            if (!rethrow_forced_close) {
                self.err = prev_err;
                self.err_obj = prev_err_obj;
                self.err_has_obj = prev_err_has_obj;
                self.err_source = prev_err_source;
                self.err_line = prev_err_line;
            }
            self.err_traceback = prev_err_traceback;
        }

        if (outs.len == 0) {
            // Just execute for side effects.
            const resolved = self.resolveCallable(f, call_args, null) catch return;
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);
            switch (resolved.callee) {
                .Builtin => |id| self.callBuiltin(id, resolved.args, &[_]Value{}) catch |e| switch (e) {
                    error.Yield => return e,
                    else => {
                        if (self.shouldRethrowForcedClose()) {
                            rethrow_forced_close = true;
                            return error.RuntimeError;
                        }
                    },
                },
                .Closure => |cl| {
                    const ret = self.runClosure(cl, resolved.args) catch |e| switch (e) {
                        error.Yield => return e,
                        else => {
                            if (self.shouldRethrowForcedClose()) {
                                rethrow_forced_close = true;
                                return error.RuntimeError;
                            }
                            return;
                        },
                    };
                    self.alloc.free(ret);
                },
                else => unreachable,
            }
            return;
        }

        const setFail = struct {
            fn run(vm: *Vm, handler: Value, o: []Value) DispatchError!void {
                o[0] = .{ .Bool = false };
                if (o.len <= 1) {
                    vm.last_builtin_out_count = @min(@as(usize, 1), o.len);
                    return;
                }
                // PUC Lua: the error handler runs with the stack at
                // ERRORSTACKSIZE (MAXSTACK + 200), grown by the overflow
                // path in pushBytecodeExecFrame.  luaD_shrinkstack is called
                // AFTER the handler, by luaD_pcall — not here.  The
                // handling_overflow check in pushBytecodeExecFrame skips the
                // overflow check when bc_stack.len > MAXSTACK and
                // in_error_handler > 0, giving the handler room to run.
                var emsg: Value = vm.errorHandlerInput();
                var depth: usize = 0;
                var on_error_stack = false;
                vm.in_error_handler += 1;
                defer vm.in_error_handler -= 1;

                while (true) {
                    if (depth >= 256 and !on_error_stack) {
                        // PUC Lua reserves a small emergency stack for error
                        // handling.  Give the handler one final chance with the
                        // C-stack-overflow object.  If that call also errors,
                        // the protected call terminates with LUA_ERRERR.
                        emsg = .{ .String = try vm.internStr("C stack overflow") };
                        on_error_stack = true;
                    }
                    depth += 1;

                    switch (handler) {
                        .Builtin => |id| {
                            var in = [_]Value{emsg};
                            var out: [1]Value = .{.Nil};
                            vm.callBuiltin(id, in[0..], out[0..]) catch {
                                if (on_error_stack) {
                                    o[1] = .{ .String = try vm.internStr("error in error handling") };
                                    vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                                    return;
                                }
                                emsg = vm.errorHandlerInput();
                                continue;
                            };
                            o[1] = try vm.normalizeProtectedErrorResult(out[0]);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                        .Closure => |cl| {
                            var in = [_]Value{emsg};
                            const ret = vm.runClosure(cl, in[0..]) catch {
                                if (on_error_stack) {
                                    o[1] = .{ .String = try vm.internStr("error in error handling") };
                                    vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                                    return;
                                }
                                emsg = vm.errorHandlerInput();
                                continue;
                            };
                            defer vm.alloc.free(ret);
                            const result = if (ret.len > 0) ret[0] else .Nil;
                            o[1] = try vm.normalizeProtectedErrorResult(result);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                        else => {
                            o[1] = try vm.normalizeProtectedErrorResult(emsg);
                            vm.last_builtin_out_count = @min(@as(usize, 2), o.len);
                            return;
                        },
                    }
                }
            }
        }.run;

        const resolved = self.resolveCallable(f, call_args, null) catch {
            try setFail(self, msgh, outs);
            return;
        };
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);

        switch (resolved.callee) {
            .Builtin => |id| {
                const nouts = if (outs.len > 1) outs.len - 1 else 0;
                var tmp_small: [8]Value = undefined;
                var tmp: []Value = undefined;
                var tmp_heap = false;
                if (nouts <= tmp_small.len) {
                    tmp = tmp_small[0..nouts];
                } else {
                    tmp = try self.alloc.alloc(Value, nouts);
                    tmp_heap = true;
                }
                defer if (tmp_heap) self.alloc.free(tmp);

                self.callBuiltin(id, resolved.args, tmp) catch |e| switch (e) {
                    error.Yield => return e,
                    else => {
                        if (self.shouldRethrowForcedClose()) {
                            rethrow_forced_close = true;
                            return error.RuntimeError;
                        }
                        try setFail(self, msgh, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                };

                // P15.38i: Re-derive outs — callBuiltin may have triggered
                // bc_stack realloc via nested re-entry.
                const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                outs_fresh[0] = .{ .Bool = true };
                const used_tmp = if (builtinHasDynamicOutCount(id))
                    @min(self.last_builtin_out_count, tmp.len)
                else
                    tmp.len;
                for (0..used_tmp) |i| {
                    const v = tmp[i];
                    if (1 + i >= outs_fresh.len) break;
                    outs_fresh[1 + i] = v;
                }
                self.last_builtin_out_count = @min(1 + used_tmp, outs_fresh.len);
            },
            .Closure => |cl| {
                // PUC luaD_pcall: save old_top (L->top) and old_ci (L->ci)
                // before calling f. On error, restore them so the message
                // handler has room to run. Without unwinding call_frames,
                // 999k+ frames from f()'s recursion stay on bc_stack and
                // pushBytecodeExecFrame for the handler immediately overflows.
                const saved_bc_stack_top = self.bc_stack_top;
                const th_xpcall = self.activeBytecodeThread();
                const saved_frame_count = th_xpcall.call_frames.len();
                const ret = self.runClosure(cl, resolved.args) catch |e| switch (e) {
                    error.Yield => return e,
                    else => {
                        if (self.shouldRethrowForcedClose()) {
                            rethrow_forced_close = true;
                            return error.RuntimeError;
                        }
                        // PUC luaD_pcall: L->ci = old_ci; restore stack
                        // pointer and unwind call frames so the message
                        // handler has room to run.
                        self.unwindBytecodeExecFrames(&th_xpcall.call_frames, saved_frame_count);
                        self.bc_stack_top = saved_bc_stack_top;
                        try setFail(self, msgh, self.refreshBuiltinOuts() orelse outs);
                        return;
                    },
                };
                defer self.alloc.free(ret);
                // P15.38i: Re-derive outs — runClosure may have triggered
                // bc_stack realloc via nested re-entry.
                const outs_fresh = self.refreshBuiltinOuts() orelse outs;
                outs_fresh[0] = .{ .Bool = true };
                const n = @min(ret.len, outs_fresh.len - 1);
                for (0..n) |i| outs_fresh[1 + i] = ret[i];
                self.last_builtin_out_count = 1 + n;
            },
            else => unreachable,
        }
    }

    fn builtinNext(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("next expects table", .{});
        const tbl = try self.expectTable(args[0]);
        const control = if (args.len >= 2) args[1] else .Nil;
        const found = (try self.rawNext(tbl, control)) orelse {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .Nil;
            return;
        };
        outs[0] = found.key;
        if (outs.len > 1) outs[1] = found.value;
    }

    fn builtinCoroutineCreate(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("coroutine.create expects function", .{});
        const callee = args[0];
        if (!isCallableValue(callee)) return self.fail("coroutine.create expects function", .{});
        try self.testcChargeMemory(@sizeOf(Thread) + 64);
        const th = try self.alloc.create(Thread);
        th.* = .{ .status = .suspended, .callee = callee };
        try self.gcRegisterThread(th);
        self.gcNoteAlloc(@sizeOf(Thread));
        self.testc_obj_threads += 1;
        outs[0] = .{ .Thread = th };
    }

    fn builtinCoroutineWrap(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        var tmp: [1]Value = .{.Nil};
        try self.builtinCoroutineCreate(args, tmp[0..]);
        const th = try self.expectThread(tmp[0]);
        self.wrap_thread = th;
        const obj = try self.allocTableNoGc();
        const mt = try self.allocTableNoGc();
        try self.setField(mt, "__call", .{ .Builtin = .coroutine_wrap_iter });
        obj.metatable = mt;
        try self.setField(obj, "__thread", .{ .Thread = th });
        outs[0] = .{ .Table = obj };
    }

    fn builtinCoroutineWrapIter(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        var th: *Thread = undefined;
        var call_args: []const Value = args;
        if (args.len > 0 and args[0] == .Table) {
            const obj = args[0].Table;
            const thv = self.getFieldOpt(obj, "__thread") orelse return self.fail("coroutine.wrap iterator missing thread", .{});
            if (thv != .Thread) return self.fail("coroutine.wrap iterator missing thread", .{});
            th = thv.Thread;
            call_args = args[1..];
        } else {
            th = self.wrap_thread orelse return self.fail("coroutine.wrap iterator missing thread", .{});
        }
        if (th.status == .running) {
            return self.fail("cannot resume non-suspended coroutine", .{});
        }
        if (th.wrap_repeat_closure) |cl| {
            if (call_args.len == 0 and th.status == .suspended and bumpClosureNumericUpvalues(self, cl, 1)) {
                if (outs.len > 0) outs[0] = .{ .Closure = cl };
                self.last_builtin_out_count = if (outs.len > 0) 1 else 0;
                return;
            }
            th.wrap_repeat_closure = null;
        }
        var resume_args = try self.alloc.alloc(Value, call_args.len + 1);
        defer self.alloc.free(resume_args);
        resume_args[0] = .{ .Thread = th };
        for (call_args, 0..) |v, i| resume_args[i + 1] = v;

        const tmp = try self.alloc.alloc(Value, outs.len + 1);
        defer self.alloc.free(tmp);
        for (tmp) |*v| v.* = .Nil;
        try self.builtinCoroutineResume(resume_args, tmp);

        const ok = switch (tmp[0]) {
            .Bool => |b| b,
            else => false,
        };
        if (!ok) {
            if (tmp.len > 1 and !(tmp[1] == .Nil)) {
                if (tmp[1] == .String) return self.fail("{s}", .{tmp[1].String.bytes()});
                self.err = null;
                self.err_obj = tmp[1];
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                self.captureErrorTraceback();
                return error.RuntimeError;
            }
            return self.fail("coroutine.wrap resume failed", .{});
        }
        const resume_out = if (self.last_builtin_out_count > 0) self.last_builtin_out_count - 1 else 0;
        const n = @min(outs.len, @min(resume_out, if (tmp.len > 1) tmp.len - 1 else 0));
        for (0..n) |i| outs[i] = tmp[i + 1];
        self.last_builtin_out_count = n;
        th.wrap_repeat_closure = null;
        if (n == 1 and outs[0] == .Closure and th.status == .suspended and call_args.len == 0 and th.callee == .Closure and th.callee.Closure.proto != null and th.callee.Closure.proto.?.numparams == 0) {
            th.wrap_repeat_closure = outs[0].Closure;
        }
        return;
    }

    fn freeThreadWrapBuffers(self: *Vm, th: *Thread) void {
        for (th.wrap_yields.items) |item| self.alloc.free(item.values);
        th.wrap_yields.clearAndFree(self.alloc);
        th.wrap_yield_index = 0;
        if (th.wrap_final_values) |vals| {
            self.alloc.free(vals);
            th.wrap_final_values = null;
        }
        th.wrap_final_error = null;
        th.wrap_final_delivered = false;
        th.wrap_repeat_closure = null;
        self.clearThreadContinuationScratch(th, .{});
        th.close_mode = false;
        th.dofile_entry_closure = null;
        th.trace_stack_depth = 0;
        th.resume_base_depth = 0;
    }

    const ContinuationScratchClearOpts = struct {
        clear_yielded: bool = false,
    };

    fn clearThreadContinuationScratch(self: *Vm, th: *Thread, opts: ContinuationScratchClearOpts) void {
        if (th.entry_args) |vals| {
            self.alloc.free(vals);
            th.entry_args = null;
        }
        for (th.testc_pending_conts.items) |pending| {
            self.alloc.free(pending.stack);
            if (pending.upvalues) |vals| self.alloc.free(vals);
            if (pending.closers) |vals| self.alloc.free(vals);
        }
        th.testc_pending_conts.clearAndFree(self.alloc);
        self.clearTestcCloseReturnContinuation(th);
        if (opts.clear_yielded) {
            if (th.yielded) |vals| {
                self.alloc.free(vals);
                th.yielded = null;
            }
        }
    }

    fn clearTestcCloseReturnContinuation(self: *Vm, th: *Thread) void {
        th.testc_close_current = null;
        if (th.testc_close_return_values) |vals| {
            self.alloc.free(vals);
            th.testc_close_return_values = null;
        }
        if (th.testc_close_remaining) |vals| {
            self.alloc.free(vals);
            th.testc_close_remaining = null;
        }
    }

    fn beginForcedClose(self: *Vm, th: *Thread) void {
        self.forced_close_thread = th;
        self.forced_close_had_error = false;
        th.close_mode = true;
    }

    fn clearForcedClose(self: *Vm, th: *Thread) void {
        if (self.forced_close_thread == th) {
            self.forced_close_thread = null;
            self.forced_close_had_error = false;
        }
        th.close_mode = false;
    }

    fn shouldRethrowForcedClose(self: *Vm) bool {
        const th = self.forced_close_thread orelse return false;
        return th.close_mode and self.current_thread != null and self.current_thread.? == th;
    }

    fn shouldRethrowForcedCloseFromBytecode(self: *Vm) bool {
        if (!self.shouldRethrowForcedClose()) return false;
        // Once a bytecode __close child is active, its failures are ordinary
        // close errors: feed them back into the parent's close continuation so
        // later closers still run and the last error wins. Only the original
        // coroutine.close signal, outside a close child, bypasses protection.
        return self.activeBytecodeThread().bytecode_close_metamethod_depth == 0;
    }

    fn appendThreadWrapYield(self: *Vm, th: *Thread, values: []const Value) DispatchError!void {
        const copy = try self.alloc.alloc(Value, values.len);
        for (values, 0..) |v, i| copy[i] = v;
        try th.wrap_yields.append(self.alloc, .{ .values = copy });
    }

    fn setThreadResumeInbox(self: *Vm, th: *Thread, values: []const Value) DispatchError!void {
        if (th.resume_inbox) |old| self.alloc.free(old);
        const copy = try self.alloc.alloc(Value, values.len);
        for (values, 0..) |v, i| copy[i] = v;
        th.resume_inbox = copy;
    }

    fn bumpClosureNumericUpvalues(self: *Vm, cl: *Closure, delta: i64) bool {
        var changed = false;
        const n = cl.upvalues.len;
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const cell = cl.upvalues[i];
            switch (cell.get(self)) {
                .Int => |iv| {
                    cell.set(self, .{ .Int = iv + delta });
                    changed = true;
                },
                .Num => |nv| {
                    cell.set(self, .{ .Num = nv + @as(f64, @floatFromInt(delta)) });
                    changed = true;
                },
                else => {},
            }
        }
        return changed;
    }

    fn snapshotThreadTraceFrames(self: *Vm, th: *Thread) void {
        th.trace_stack_depth = 0;
        var oi: usize = 0;
        var i = th.call_frames.len();
        while (i > 0) {
            i -= 1;
            const fr = th.call_frames.getConstPtr(i).*;
            if (fr.hide_from_debug) continue;
            if (oi < th.trace_frame_names.len) {
                th.trace_frame_names[oi] = self.debugNameFromCallee(fr.callee);
                oi += 1;
            } else {
                break;
            }
        }
        th.trace_stack_depth = oi;
    }

    fn builtinCoroutineYield(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        for (outs) |*o| o.* = .Nil;
        // PUC luaG_runerror: coroutine.yield is a C function, so isLua(ci) is
        // false and luaG_addinfo is NOT called — no "file:line:" prefix on the
        // error message. Use failC (C-function variant) to match this.
        // Set err_cfunc_label so the traceback includes [C]: in field 'yield'.
        const th = self.current_thread orelse {
            self.err_cfunc_label = "field 'yield'";
            return self.failC("attempt to yield from outside a coroutine", .{});
        };
        const in_debug_hook = self.isInDebugHook();
        if (self.non_yieldable_c_depth > 0 or self.hasActiveBytecodeNonYieldableBoundary() or
            (in_debug_hook and !self.activeDebugHookAllowsYield()))
            return self.fail("attempt to yield across a C-call boundary", .{});
        if (th.close_mode) return self.fail("attempt to yield across a C-call boundary", .{});
        // A fresh yield supersedes previously captured continuation snapshots.
        th.capture_yield_id = th.next_yield_id;
        th.next_yield_id +%= 1;
        th.capture_from_debug_hook = self.isInDebugHook();
        th.yielded_from_debug_hook = self.isInDebugHook();
        th.capture_from_count_hook = self.isInDebugHook() and self.activeDebugHookEventIsCount();
        // P15.40b-full: Bytecode frames are in Thread.call_frames.
        const th_bc = self.activeBytecodeThread();
        th.yield_origin_depth = th_bc.call_frames.len();
        if (th_bc.call_frames.len() != 0) {
            const frame_idx = if (self.isInDebugHook() and th_bc.call_frames.len() >= 2)
                th_bc.call_frames.len() - 2
            else
                th_bc.call_frames.len() - 1;
            const fr = th_bc.call_frames.getPtr(frame_idx);
            th.trace_currentline = fr.current_line;
        }
        self.snapshotThreadTraceFrames(th);
        if (th.wrap_eager_mode) {
            try self.appendThreadWrapYield(th, args);
            if (th.yielded) |old| self.alloc.free(old);
            const ys = try self.alloc.alloc(Value, args.len);
            for (args, 0..) |v, i| ys[i] = v;
            th.yielded = ys;
            self.last_builtin_out_count = args.len;
            return;
        }
        if (th.yielded) |ys| self.alloc.free(ys);
        const ys = try self.alloc.alloc(Value, args.len);
        for (args, 0..) |v, i| ys[i] = v;
        th.yielded = ys;
        if (self.active_builtin) |id| {
            th.suspended_builtin = id;
            if (th.suspended_builtin_args) |vals| {
                self.alloc.free(vals);
                th.suspended_builtin_args = null;
            }
            if (self.active_builtin_args) |builtin_args| {
                const copy = try self.alloc.alloc(Value, builtin_args.len);
                for (builtin_args, 0..) |v, i| copy[i] = v;
                th.suspended_builtin_args = copy;
            }
        } else {
            th.suspended_builtin = null;
            if (th.suspended_builtin_args) |vals| {
                self.alloc.free(vals);
                th.suspended_builtin_args = null;
            }
        }
        self.last_builtin_out_count = args.len;

        // P15.67: When yielding from an async debug hook frame (count/line hook
        // running as a bytecode closure via tryPushBytecodeDebugHook), the hook
        // frame is still on exec_frames. In PUC Lua, lua_yield longjmps out of
        // the C hook, abandoning its stack frame. We must do the equivalent:
        // pop the hook frame, clean up the parent's pending_call (which holds
        // the BytecodeHookContinuation), restore parent callee/tailcall, set
        // resume_skip_count_pc (for count hooks), clear in_debug_hook, and mark
        // the thread as bytecode_inplace_suspended so the errdefer in
        // runBytecodeInternal does not unwind the parent frame.
        if (in_debug_hook) {
            const th_bc2 = self.activeBytecodeThread();
            const frames = &th_bc2.call_frames;
            if (frames.len() >= 2) {
                const hook_idx = frames.len() - 1;
                const parent_idx = hook_idx - 1;
                const hook_frame = frames.getPtr(hook_idx);
                if (hook_frame.is_debug_hook) {
                    // The pending_call is on the PARENT frame (set by
                    // tryPushBytecodeDebugHook), not on the hook frame.
                    const parent = frames.getPtr(parent_idx);
                    if (parent.pending_call.getPtr()) |pending| {
                        if (pending.completion == .hook) {
                            const cont = pending.completion.hook;
                            parent.callee = cont.saved_parent_callee;
                            parent.is_tailcall = cont.saved_parent_tailcall;
                            // For count hooks, set resume_skip_count_pc so the
                            // count hook doesn't immediately re-fire on resume.
                            if (cont.post == .resume_instruction and cont.post.resume_instruction.skip_count) {
                                parent.resume_skip_count_pc = parent.pc;
                            }
                            // For line hooks, set skip_bc_line_once so the
                            // line hook doesn't immediately re-fire on resume.
                            // This mirrors PUC's CIST_HOOKYIELD: on resume,
                            // luaG_traceexec sees the flag, clears it, and
                            // returns without calling the hook. The instruction
                            // executes, and the next instruction's line-change
                            // check proceeds normally.
                            if (cont.post == .resume_instruction and cont.post.resume_instruction.skip_line) {
                                self.activeHookState().skip_bc_line_once = true;
                            }
                            self.alloc.free(cont.transfer);
                            parent.pending_call.clear();
                        }
                    }
                    // Clear in_debug_hook (mirrors popBytecodeExecFrame).
                    self.activeHookState().in_debug_hook = false;
                    // Pop the hook frame.
                    self.popBytecodeExecFrame(frames);
                    // Mark as suspended so errdefer in runBytecodeInternal
                    // does not unwind the parent frame.
                    th.bytecode_inplace_suspended = true;
                }
            }
        } else if (th.testc_pending_conts.items.len != 0) {
            // P15.68: testC `yield` (without `k`) saves a continuation and
            // then calls builtinCoroutineYield. The error.Yield propagates
            // through builtinTestcTestC → opCall. Since opCall's
            // canParkDirectBytecodeYield only handles .coroutine_yield (not
            // .testc_testC), the bytecode frame is not parked. The errdefer
            // in runBytecodeInternal then unwinds all frames, and on resume
            // the coroutine restarts from scratch.
            // Fix: mark the thread as bytecode_inplace_suspended so the
            // errdefer does not unwind the frames. On resume, the bytecode VM
            // re-executes the OP_CALL to builtinTestcTestC, which finds the
            // pending continuation and runs it. The continuation's return
            // values become the return values of the testC function call.
            const th_bc2 = self.activeBytecodeThread();
            if (th_bc2.call_frames.len() != 0) {
                th.bytecode_inplace_suspended = true;
                // boundary_depth for runBytecodeInternal is the frame count
                // at the ORIGINAL runBytecodeInternal call (when the coroutine
                // body was first entered). For a top-level coroutine, this is 0.
                // Setting it to the current frame count would make the errdefer
                // assert fail when frames are popped on return.
                th.bytecode_resume_boundary = 0;
            }
        }

        return error.Yield;
    }

    fn isStackOverflowRuntimeError(self: *Vm) bool {
        if (self.err_has_obj and self.err_obj == .String) {
            const s = self.err_obj.String;
            if (std.mem.indexOf(u8, s.bytes(), "C stack overflow") != null) return true;
            if (std.mem.indexOf(u8, s.bytes(), "stack overflow") != null) return true;
        }
        if (self.err) |msg| {
            if (std.mem.indexOf(u8, msg, "C stack overflow") != null) return true;
            if (std.mem.indexOf(u8, msg, "stack overflow") != null) return true;
        }
        return false;
    }

    /// Install a hook for the testC compatibility module as one atomic
    /// native-hook operation. Calling debug.sethook from Lua and marking the
    /// result in a following instruction is racy for count=1 hooks: the new
    /// hook can fire before the marker runs. Keeping both steps in one builtin
    /// mirrors lua_sethook and exposes no intermediate Lua-hook state.
    fn builtinTestcAllowHookYield(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        try self.builtinDebugSethook(args, outs);
        self.activeHookState().allow_yield = true;
    }

    fn builtinCoroutineResume(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("coroutine.resume expects thread", .{});
        const th = try self.expectThread(args[0]);
        self.last_builtin_out_count = 0;
        defer if (th.close_mode) self.clearForcedClose(th);

        // Default return for resume is a tuple: (ok, ...).
        const want_out = outs.len > 0;
        if (self.activeProtectedCallDepth() >= 32) {
            if (want_out) outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("C stack overflow") };
            return;
        }
        self.protected_call_depth += 1;
        defer self.protected_call_depth -= 1;
        // PUC: coroutine.resume is a protected call — clear errfunc so
        // errors inside the coroutine don't invoke the outer message handler.
        const saved_errfunc = self.errfunc;
        self.errfunc = null;
        defer self.errfunc = saved_errfunc;

        if (th.status == .dead) {
            if (want_out) outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("cannot resume dead coroutine") };
            self.last_builtin_out_count = if (want_out) @min(@as(usize, 2), outs.len) else 0;
            return;
        }
        if (th.status == .suspended and self.current_thread != null and self.current_thread.? != th and self.current_thread.?.caller == th) {
            if (want_out) outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("cannot resume non-suspended coroutine") };
            self.last_builtin_out_count = if (want_out) @min(@as(usize, 2), outs.len) else 0;
            return;
        }
        if (th.status == .running) {
            if (want_out) outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("cannot resume non-suspended coroutine") };
            self.last_builtin_out_count = if (want_out) @min(@as(usize, 2), outs.len) else 0;
            return;
        }

        th.status = .running;
        th.in_resume = true;
        th.resume_pop_consumed = false;
        th.resume_recursive_mode = false;
        th.yield_origin_depth = 0;
        th.suspended_direct_yield = false;
        th.capture_yield_id = 0;
        th.resume_yield_id = 0;
        th.resume_recursive_mode = false;
        defer {
            th.in_resume = false;
            th.resume_pop_consumed = false;
            th.resume_recursive_mode = false;
            th.resume_yield_id = 0;
            th.capture_yield_id = 0;
            th.capture_from_debug_hook = false;
            th.capture_from_count_hook = false;
        }
        defer {
            if (th.status == .running) th.status = .dead;
        }

        if (th.yielded) |ys| {
            self.alloc.free(ys);
            th.yielded = null;
        }

        // Preserve error string; resume should not permanently clobber it.
        const prev_err = self.err;
        const prev_err_obj = self.err_obj;
        const prev_err_has_obj = self.err_has_obj;
        const prev_err_source = self.err_source;
        const prev_err_line = self.err_line;
        const prev_err_traceback = self.err_traceback;
        self.err_traceback = null;
        defer {
            self.clearErrorTraceback();
            self.err = prev_err;
            self.err_obj = prev_err_obj;
            self.err_has_obj = prev_err_has_obj;
            self.err_source = prev_err_source;
            self.err_line = prev_err_line;
            self.err_traceback = prev_err_traceback;
        }

        const call_args = args[1..];

        // P15.65: testC close continuation must be handled here, in
        // builtinCoroutineResume, where `th` is the correct coroutine thread
        // (from args[0]). Previously this check was in builtinTestcTestC, which
        // reads `self.current_thread` — but by the time the testC builtin is
        // re-entered after a yield, `self.current_thread` may have changed due
        // to nested coroutine operations during the yield/unwind. Handling it
        // here mirrors the existing `testc_pending_conts` pattern (line below)
        // and ensures the continuation is resumed on the right thread.
        if (th.testc_close_return_values != null) {
            const prev_thread = self.current_thread;
            var prev_thread_status: ?@TypeOf(th.status) = null;
            if (prev_thread) |pt| {
                prev_thread_status = pt.status;
                if (pt.status == .running) pt.status = .suspended;
            }
            const prev_runtime_thread = self.active_runtime_thread.?;
            self.current_thread = th;
            self.switchRuntime(th);
            th.caller = prev_thread;
            th.resume_base_depth = 0;
            defer {
                self.switchRuntime(prev_runtime_thread);
                self.current_thread = prev_thread;
                th.caller = null;
                th.resume_base_depth = 0;
                if (prev_thread) |pt| {
                    if (prev_thread_status) |st| pt.status = st;
                }
            }

            // Deliver resume values to the coroutine's inbox so that
            // coroutine.yield inside the __close metamethod returns them.
            try self.setThreadResumeInbox(th, call_args);

            // Resume the close continuation. This calls
            // resumeTestcCloseReturnContinuation which re-enters the
            // bytecode VM to continue the __close metamethod from the
            // yield point, then runs remaining close metamethods.
            self.resumeTestcCloseReturnContinuation(th, outs[1..]) catch |e| switch (e) {
                error.Yield => {
                    // The __close metamethod yielded again. The continuation
                    // is already re-stored by resumeTestcCloseReturnContinuation.
                    // Return yield results to the caller.
                    outs[0] = .{ .Bool = true };
                    const ys = th.yielded orelse &[_]Value{};
                    const n = @min(ys.len, if (outs.len > 1) outs.len - 1 else 0);
                    for (0..n) |i| outs[1 + i] = ys[i];
                    self.last_builtin_out_count = 1 + n;
                    if (th.yielded) |owned| {
                        self.alloc.free(owned);
                        th.yielded = null;
                    }
                    th.trace_yields += 1;
                    th.status = .suspended;
                    th.close_has_err = false;
                    th.started = true;
                    th.finished = false;
                    return;
                },
                else => return e,
            };

            // Close continuation completed. Return results.
            const produced = self.last_builtin_out_count;
            outs[0] = .{ .Bool = true };
            const n = @min(produced, if (outs.len > 1) outs.len - 1 else 0);
            self.last_builtin_out_count = 1 + n;
            th.status = .dead;
            th.close_has_err = false;
            th.started = true;
            th.finished = true;
            self.clearThreadContinuationScratch(th, .{});
            return;
        }

        // P15.68: For the bytecode path (bytecode_inplace_suspended), the
        // testC continuation must run inside the bytecode VM, not directly.
        // The bytecode VM re-executes the OP_CALL to builtinTestcTestC,
        // which finds the pending continuation and runs it. The continuation's
        // return values become the return values of the testC function call,
        // and the coroutine body continues executing. Only after the next
        // yield or return does coroutine.resume get its result.
        if (th.testc_pending_conts.items.len != 0 and !th.bytecode_inplace_suspended) {
            const prev_thread = self.current_thread;
            var prev_thread_status: ?@TypeOf(th.status) = null;
            if (prev_thread) |pt| {
                prev_thread_status = pt.status;
                if (pt.status == .running) pt.status = .suspended;
            }
            const prev_runtime_thread = self.active_runtime_thread.?;
            self.current_thread = th;
            self.switchRuntime(th);
            th.caller = prev_thread;
            th.resume_base_depth = 0;
            defer {
                self.switchRuntime(prev_runtime_thread);
                self.current_thread = prev_thread;
                th.caller = null;
                th.resume_base_depth = 0;
                if (prev_thread) |pt| {
                    if (prev_thread_status) |st| pt.status = st;
                }
            }

            // P15.69: Deliver resume args to the inbox so that
            // resumePendingTestcContinuation can read them via
            // takeBytecodeResumeValues. This path is used when the coroutine
            // body is a Builtin (e.g. coroutine.wrap(T.testC)) and there are
            // pending testC continuations. Without this, the continuation
            // receives stale/empty resume args.
            try self.setThreadResumeInbox(th, call_args);

            var current_args: []const Value = call_args;
            var tmp_buf: [256]Value = undefined;
            while (true) {
                const target_outs = if (th.testc_pending_conts.items.len == 1 and outs.len > 1) outs[1..] else tmp_buf[0..];
                self.resumePendingTestcContinuation(th, current_args, target_outs) catch |e| switch (e) {
                    error.Yield => {},
                    else => return e,
                };
                const produced = self.last_builtin_out_count;
                if (th.testc_pending_conts.items.len == 0 or th.yielded != null) break;
                current_args = target_outs[0..@min(produced, target_outs.len)];
            }
            outs[0] = .{ .Bool = true };
            th.trace_had_error = false;
            if (th.testc_pending_conts.items.len != 0 or th.yielded != null) {
                const ys = th.yielded orelse &[_]Value{};
                const n = @min(ys.len, if (outs.len > 1) outs.len - 1 else 0);
                for (0..n) |i| outs[1 + i] = ys[i];
                self.last_builtin_out_count = 1 + n;
                if (th.yielded) |owned| {
                    self.alloc.free(owned);
                    th.yielded = null;
                }
                th.trace_yields += 1;
                th.status = .suspended;
                th.close_has_err = false;
                th.started = true;
                th.finished = false;
            } else {
                self.last_builtin_out_count = 1 + @min(self.last_builtin_out_count, if (outs.len > 1) outs.len - 1 else 0);
                th.status = .dead;
                th.close_has_err = false;
                th.started = true;
                th.finished = true;
                self.clearThreadContinuationScratch(th, .{});
            }
            return;
        }
        // Builtin entrypoints (notably coroutine.create(pcall/xpcall)) need the
        // original start arguments when resuming from suspended continuation
        // frames. This is runtime call context, not replay re-execution state.
        if (!th.started and th.entry_args == null) {
            const saved = try self.alloc.alloc(Value, call_args.len);
            for (call_args, 0..) |v, i| saved[i] = v;
            th.entry_args = saved;
        }
        try self.setThreadResumeInbox(th, call_args);
        const nouts = if (outs.len > 1) outs.len - 1 else 0;
        const prev_thread = self.current_thread;
        var prev_thread_status: ?@TypeOf(th.status) = null;
        if (prev_thread) |pt| {
            prev_thread_status = pt.status;
            if (pt.status == .running) pt.status = .suspended;
        }
        const prev_runtime_thread = self.active_runtime_thread.?;
        // P15.33: Set current_thread before switchRuntime so refreshHooksCached
        // reads the target thread's hook state.
        self.current_thread = th;
        self.switchRuntime(th);
        th.caller = prev_thread;
        th.resume_base_depth = 0;
        defer {
            self.switchRuntime(prev_runtime_thread);
            self.current_thread = prev_thread;
            th.caller = null;
            th.resume_base_depth = 0;
            if (prev_thread) |pt| {
                if (prev_thread_status) |st| pt.status = st;
            }
        }

        var ok: bool = true;
        var forced_close_ok = false;
        var yielded: bool = false;
        var payload: []Value = &[_]Value{};
        var payload_heap: bool = false;

        if (th.trace_yields == 0 and !self.isInDebugHook()) {
            try self.debugDispatchHookWithCalleeTransfer("call", null, th.callee, call_args, 1);
        }

        const use_saved_entry = th.bytecode_inplace_suspended and
            th.entry_args != null;
        const exec_args = if (use_saved_entry) th.entry_args.? else call_args;
        const resolved = try self.resolveCallable(th.callee, exec_args, null);
        defer if (resolved.owned_args) |owned| self.alloc.free(owned);
        switch (resolved.callee) {
            .Builtin => |id| {
                if (nouts != 0) {
                    payload = try self.alloc.alloc(Value, nouts);
                    payload_heap = true;
                }
                self.callBuiltin(id, resolved.args, payload) catch |e| switch (e) {
                    error.Yield => {
                        yielded = true;
                    },
                    error.RuntimeError => {
                        if (self.forced_close_thread == th and th.close_mode and !self.forced_close_had_error and !self.isStackOverflowRuntimeError()) {
                            forced_close_ok = true;
                        } else {
                            ok = false;
                        }
                    },
                    else => return e,
                };
            },
            .Closure => |cl| {
                if (cl.proto != null and !self.bytecode_coroutine_trampoline_active) {
                    const step = try self.driveBytecodeCoroutineTrampoline(th, cl, resolved.args);
                    switch (step) {
                        .returned => |ret| {
                            payload = ret;
                            payload_heap = true;
                        },
                        .yielded => |ret| {
                            if (ret.len > 0) {
                                payload = ret;
                                payload_heap = true;
                            }
                            yielded = true;
                        },
                        .failed => {
                            ok = false;
                        },
                        .forced_close => {
                            forced_close_ok = true;
                        },
                    }
                } else {
                    const ret_opt: ?[]Value = retblk: {
                        const r = self.runClosure(cl, resolved.args) catch |e| switch (e) {
                            error.Yield => {
                                yielded = true;
                                break :retblk null;
                            },
                            error.RuntimeError => {
                                if (th.yielded != null and th.capture_yield_id != 0) {
                                    yielded = true;
                                    break :retblk null;
                                }
                                if (self.forced_close_thread == th and th.close_mode and !self.forced_close_had_error and !self.isStackOverflowRuntimeError()) {
                                    forced_close_ok = true;
                                } else {
                                    ok = false;
                                }
                                break :retblk null;
                            },
                            error.ThreadSwitch => return error.ThreadSwitch,
                            error.OutOfMemory => return error.OutOfMemory,
                        };
                        break :retblk r;
                    };
                    if (ret_opt) |ret| {
                        payload = ret;
                        payload_heap = true;
                    }
                }
            },
            else => return self.fail("coroutine.resume: bad thread", .{}),
        }

        defer if (payload_heap) self.alloc.free(payload);

        if (forced_close_ok) {
            self.err = null;
            self.err_obj = .Nil;
            self.err_has_obj = false;
            self.err_source = null;
            self.err_line = -1;
        }

        if (!want_out) {
            // Caller ignores results. Still follow resume semantics and do not throw.
            if (yielded or th.yielded != null) {
                if (th.yielded) |ys| {
                    self.alloc.free(ys);
                    th.yielded = null;
                }
                th.status = .suspended;
                th.started = true;
                th.finished = false;
            } else {
                th.status = .dead;
                th.started = true;
                th.finished = true;
            }
            return;
        }

        if (!ok) {
            outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = if (self.err_has_obj) self.err_obj else .{ .String = try self.internStr(self.errorString()) };
            self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
            if (th.yielded) |ys| {
                self.alloc.free(ys);
                th.yielded = null;
            }
            th.trace_had_error = true;
            th.status = .dead;
            th.close_has_err = true;
            th.close_err = if (self.err_has_obj) self.err_obj else .{ .String = try self.internStr(self.errorString()) };
            self.clearThreadContinuationScratch(th, .{});
            return;
        }

        // Yield path: return yielded values (set by coroutine.yield).
        if (yielded or th.yielded != null) {
            const ys = th.yielded orelse &[_]Value{};
            outs[0] = .{ .Bool = true };
            const n = @min(ys.len, outs.len - 1);
            for (0..n) |i| outs[1 + i] = ys[i];
            self.last_builtin_out_count = 1 + n;
            if (th.yielded) |owned| self.alloc.free(owned);
            th.yielded = null;
            th.trace_yields += 1;
            th.status = .suspended;
            th.close_has_err = false;
            th.started = true;
            th.finished = false;
            return;
        }

        outs[0] = .{ .Bool = true };
        const n = @min(payload.len, outs.len - 1);
        for (0..n) |i| outs[1 + i] = payload[i];
        self.last_builtin_out_count = 1 + n;
        th.trace_had_error = false;
        th.status = .dead;
        th.close_has_err = false;
        th.started = true;
        th.finished = true;
        self.clearThreadContinuationScratch(th, .{});
    }

    fn builtinCoroutineStatus(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("coroutine.status expects thread", .{});
        const th = try self.expectThread(args[0]);
        if (th.status == .suspended and self.current_thread != null and self.current_thread.? != th and self.current_thread.?.caller == th) {
            outs[0] = .{ .String = try self.internStr("normal") };
            return;
        }
        outs[0] = .{ .String = try self.internStr(switch (th.status) {
            .suspended => "suspended",
            .running => "running",
            .dead => "dead",
        }) };
    }

    fn builtinCoroutineRunning(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = args;
        if (outs.len == 0) return;
        outs[0] = if (self.current_thread) |th|
            .{ .Thread = th }
        else if (self.main_thread) |th|
            .{ .Thread = th }
        else
            .Nil;
        if (outs.len > 1) outs[1] = .{ .Bool = (self.current_thread == null) };
    }

    fn builtinCoroutineIsyieldable(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) {
            const in_debug_hook = self.isInDebugHook();
            if (self.non_yieldable_c_depth > 0 or self.hasActiveBytecodeNonYieldableBoundary() or
                (in_debug_hook and !self.activeDebugHookAllowsYield()))
            {
                outs[0] = .{ .Bool = false };
                return;
            }
            const t = self.current_thread orelse {
                outs[0] = .{ .Bool = false };
                return;
            };
            const is_main = if (self.main_thread) |m| m == t else false;
            outs[0] = .{ .Bool = (t.status == .running and !is_main) };
            return;
        }

        const t = try self.expectThread(args[0]);
        const is_main = t.testc_state_main or if (self.main_thread) |m| m == t else false;
        outs[0] = .{ .Bool = (!is_main and t.status != .dead) };
    }

    fn builtinCoroutineClose(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        self.last_builtin_out_count = 0;
        if (self.coroutine_close_depth >= max_coroutine_close_c_depth) return self.fail("C stack overflow", .{});
        self.coroutine_close_depth += 1;
        defer self.coroutine_close_depth -= 1;

        var th: *Thread = undefined;
        if (args.len == 0) {
            th = self.current_thread orelse return self.fail("coroutine.close expects thread", .{});
        } else {
            th = try self.expectThread(args[0]);
        }
        if (th == self.main_thread and self.current_thread != null and self.current_thread.? != th) {
            return self.fail("cannot close a normal coroutine", .{});
        }
        if (th.status == .running) {
            if (self.current_thread != null and self.current_thread.? == th) {
                if (th.close_mode and self.forced_close_thread == th) {
                    if (outs.len > 0) outs[0] = .{ .Bool = true };
                    if (outs.len > 1) outs[1] = .Nil;
                    self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
                    return;
                }
                self.beginForcedClose(th);
                self.err = null;
                self.err_obj = .Nil;
                self.err_has_obj = true;
                self.err_source = null;
                self.err_line = -1;
                return error.RuntimeError;
            }
            if (th == self.main_thread and self.current_thread == null) {
                return self.fail("cannot close a running main thread", .{});
            }
            return self.fail("cannot close a running coroutine", .{});
        }
        if (th == self.main_thread) return self.fail("cannot close the main thread", .{});
        if (th.close_has_err) {
            th.status = .dead;
            if (outs.len > 0) outs[0] = .{ .Bool = false };
            if (outs.len > 1) outs[1] = th.close_err;
            th.close_has_err = false;
            th.close_err = .Nil;
            self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
            return;
        }
        if (th.status == .suspended and th.trace_yields > 0) {
            self.beginForcedClose(th);
            var resume_args = [_]Value{.{ .Thread = th }};
            var resume_out = [_]Value{ .Nil, .Nil };
            self.builtinCoroutineResume(resume_args[0..], resume_out[0..]) catch {};
            const ok = switch (resume_out[0]) {
                .Bool => |b| b,
                else => false,
            };
            if (!ok) {
                th.status = .dead;
                if (outs.len > 0) outs[0] = .{ .Bool = false };
                if (outs.len > 1) outs[1] = resume_out[1];
                // Error is already returned by this close call; do not keep it
                // latched for subsequent close() calls on the dead coroutine.
                th.close_has_err = false;
                th.close_err = .Nil;
                self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
                return;
            }
        }
        th.status = .dead;
        self.clearThreadContinuationScratch(th, .{ .clear_yielded = true });
        if (outs.len > 0) outs[0] = .{ .Bool = true };
        if (outs.len > 1) outs[1] = .Nil;
        self.last_builtin_out_count = @min(@as(usize, 2), outs.len);
    }

    fn gcWeakMode(self: *Vm, tbl: *Table) struct { weak_k: bool, weak_v: bool } {
        const mt = tbl.metatable orelse return .{ .weak_k = false, .weak_v = false };
        const m = self.fasttm(mt, .mode) orelse return .{ .weak_k = false, .weak_v = false };
        const s = switch (m) {
            .String => |x| x.bytes(),
            else => return .{ .weak_k = false, .weak_v = false },
        };
        return .{
            .weak_k = std.mem.indexOfScalar(u8, s, 'k') != null,
            .weak_v = std.mem.indexOfScalar(u8, s, 'v') != null,
        };
    }

    fn gcValueAge(value: Value) ?GcAge {
        return switch (value) {
            .Table => |object| object.gc_age,
            .Closure => |object| object.gc_age,
            .Thread => |object| object.gc_age,
            .String => |object| object.gc_age,
            .Userdata => |object| object.gc_age,
            else => null,
        };
    }

    fn gcSetValueAge(value: Value, age: GcAge) void {
        switch (value) {
            .Table => |object| object.gc_age = age,
            .Closure => |object| object.gc_age = age,
            .Thread => |object| object.gc_age = age,
            .String => |object| object.gc_age = age,
            .Userdata => |object| object.gc_age = age,
            else => {},
        }
    }

    fn gcMinorCandidate(age: GcAge) bool {
        return age == .new or age == .survival or age == .old0;
    }

    /// PUC lgc.h: iscleared(o) = !isblack(o) && !tofinalize(o).
    /// Used during atomic phase (before white flip) to check if a weak
    /// value/key will be swept. An object is "cleared" if it's not black
    /// (not marked as reachable) and not marked for finalization.
    fn gcTableDead(self: *const Vm, table: *Table) bool {
        if (self.gc_minor_cycle and !gcMinorCandidate(table.gc_age)) return false;
        return !gcIsBlack(table.gc_marked) and (table.gc_marked & FINALIZEDBIT) == 0;
    }

    fn gcClosureDead(self: *const Vm, closure: *Closure) bool {
        if (self.gc_minor_cycle and !gcMinorCandidate(closure.gc_age)) return false;
        return !gcIsBlack(closure.gc_marked) and (closure.gc_marked & FINALIZEDBIT) == 0;
    }

    fn gcThreadDead(self: *const Vm, thread: *Thread) bool {
        if (self.gc_minor_cycle and !gcMinorCandidate(thread.gc_age)) return false;
        return !gcIsBlack(thread.gc_marked) and (thread.gc_marked & FINALIZEDBIT) == 0;
    }

    fn gcUserdataDead(self: *const Vm, ud: *Userdata) bool {
        if (self.gc_minor_cycle and !gcMinorCandidate(ud.gc_age)) return false;
        return !gcIsBlack(ud.gc_marked) and (ud.gc_marked & FINALIZEDBIT) == 0;
    }

    /// PUC lgc.c `reallymarkobject`: mark a Value's referent gray (or black
    /// for strings) and enqueue it for propagation. Non-GC Values (Nil, Int,
    /// etc.) are silently ignored — they have no heap object to mark.
    fn gcQueueScanValue(self: *Vm, value: Value) DispatchError!void {
        const obj = GcObject.fromValue(value) orelse return;
        try self.gcQueueScanObject(obj);
    }

    /// PUC lgc.c `reallymarkobject` core: the type-generic entry point that
    /// operates on GcObject (not Value). This is the single place where the
    /// white→gray/black transition + gray-list enqueue happens for all GC
    /// types. Strings go straight to black (no outgoing edges, PUC lgc.c:344);
    /// everything else goes gray and waits for `gcPropagateOne` to scan its
    /// children. Cell is included here so closed upvalues traverse through
    /// the same gray list as PUC's LUA_VUPVAL handling.
    fn gcQueueScanObject(self: *Vm, obj: GcObject) DispatchError!void {
        const p = gcPtr(obj);
        if (!gcIsWhite(p.marked.*)) return;
        if (obj == .string) {
            // Strings have no children — go straight to black.
            gcSetBlack(p.marked);
        } else {
            gcSetGray(p.marked);
            try self.gc_gray.append(self.alloc, obj);
        }
    }

    fn gcMarkMinorValue(self: *Vm, value: Value) DispatchError!void {
        const obj = GcObject.fromValue(value) orelse return;
        const age = gcPtr(obj).age.*;
        if (!gcMinorCandidate(age)) return;
        try self.gcQueueScanObject(obj);
    }

    fn gcQueueScanCell(self: *Vm, cell: *Cell) DispatchError!void {
        // PUC reallymarkobject for LUA_VUPVAL (lgc.c:347-354):
        //   - open upvalues are kept GRAY (not black) to avoid barriers;
        //     their values live on the thread's stack and are revisited
        //     by the thread scan or remarkupvals.
        //   - closed upvalues are set BLACK DIRECTLY and their content
        //     is marked inline via markvalue. They do NOT enter the gray
        //     list — PUC propagatemark (lgc.c:727-740) has no LUA_VUPVAL
        //     case. Routing closed cells through gc_gray would queue them
        //     for deferred propagation, which is the opposite of PUC.
        if (cell.isOpen()) {
            if (!gcIsWhite(cell.gc_marked)) return;
            gcSetGray(&cell.gc_marked);
            // A4: open cells now ride the unified gc_grayagain (GcObject)
            // list, matching PUC's single gclist per object.
            try self.gc_grayagain.append(self.alloc, .{ .cell = cell });
            // Open upvalue: value is on the thread's stack, which is
            // scanned separately. Don't mark the value here.
            return;
        }
        // Closed upvalue: mark content inline (PUC-faithful).
        // The cell's own color is managed separately (it may be unregistered
        // — e.g. the main chunk's _ENV cell created in luazig.zig — so we
        // must mark cell.value regardless of the cell's own mark state,
        // exactly as A2 did and as PUC's reallymarkobject does for
        // closed upvalues: the value is traversed unconditionally.
        if (gcIsWhite(cell.gc_marked)) gcSetBlack(&cell.gc_marked);
        try self.gcMarkValue(cell.value);
    }

    /// PUC luaC_barrierback_ (lgc.c:208-222) for generational mode.
    /// When a black (old) object is mutated, it must be re-traversed in the
    /// next minor cycle. The age state machine:
    ///   .old/.old1 → .touched1 (link into grayagain, paint gray)
    ///   .touched2  → .touched1 (already in grayagain, just re-gray)
    ///   .touched1  → no-op (already queued)
    ///   .new/.survival/.old0 → no-op (young, handled by minor sweep)
    /// A4: operates on GcObject so Cell folds into the same path.
    fn gcRememberObject(self: *Vm, owner: GcObject) DispatchError!void {
        if (self.gc_mode != .generational or self.gc_gen_phase != .minor) return;
        const p = gcPtr(owner);
        switch (p.age.*) {
            .new, .survival, .old0, .touched1 => return,
            // PUC luaC_barrierback_: if already TOUCHED2 (already in
            // grayagain), just set gray. Otherwise, link to grayagain.
            .touched2 => {
                p.age.* = .touched1;
                gcSetGray(p.marked);
            },
            .old1, .old => {
                p.age.* = .touched1;
                // PUC linkobjgclist: paint gray and add to grayagain.
                gcSetGray(p.marked);
                try self.gc_grayagain.append(self.alloc, owner);
            },
        }
    }

    /// Thin Value wrapper around gcRememberObject for call sites that
    /// still hand us a Value. Non-GC Values are silently ignored.
    fn gcRememberValue(self: *Vm, owner: Value) DispatchError!void {
        if (GcObject.fromValue(owner)) |obj| try self.gcRememberObject(obj);
    }

    /// Cell-specific wrapper around gcRememberObject. Kept as a named
    /// entry point because call sites identify the operand as a *Cell
    /// (not a Value), and routing through gcRememberObject keeps the
    /// age-transition logic in exactly one place.
    fn gcRememberCell(self: *Vm, cell: *Cell) DispatchError!void {
        try self.gcRememberObject(.{ .cell = cell });
    }

    fn gcForwardBarrierValue(self: *Vm, owner: Value, child: Value) DispatchError!void {
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            const owner_age = gcValueAge(owner) orelse return;
            const child_age = gcValueAge(child) orelse return;
            if (owner_age.isOld() and child_age.isYoung()) {
                const child_obj = GcObject.fromValue(child).?;
                gcPtr(child_obj).age.* = .old0;
                try self.gc_old1.append(self.alloc, child_obj);
                try self.gcQueueScanValue(child);
            }
            return;
        }
        try self.gcWriteBarrier(child);
    }

    fn gcForwardBarrierCell(self: *Vm, owner: *Closure, child: *Cell) DispatchError!void {
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            if (owner.gc_age.isOld() and child.gc_age.isYoung()) {
                child.gc_age = .old0;
                try self.gc_old1.append(self.alloc, .{ .cell = child });
                try self.gcQueueScanCell(child);
            }
            return;
        }
        try self.gcWriteBarrier(child.get(self));
    }

    /// A6: Clear all generational tracking lists. Called by `gcMakeAllOld`
    /// (entering generational mode after a full collection) and
    /// `gcLeaveGenerational` (leaving generational mode).
    /// A4/A6: all lists are now GcObject-typed (or *Thread for gc_gen_threads).
    fn gcClearGenerationalLists(self: *Vm) void {
        self.gc_young_objects.clearRetainingCapacity();
        self.gc_old1.clearRetainingCapacity();
        self.gc_grayagain.clearRetainingCapacity();
        self.gc_gen_threads.clearRetainingCapacity();
    }

    /// PUC luaC_fullgc → fullgen → gen2age+set2white: before running a
    /// full incremental cycle from generational mode, reset every object
    /// to the current white. This ensures the incremental mark/sweep
    /// correctly identifies unreachable objects (they stay old-white
    /// after the white flip and are swept). Old objects that were BLACK
    /// in generational mode would otherwise survive sweep without being
    /// visited, leaving dangling references to freed young objects.
    /// A6: Unified `gcMakeAllWhite`. Iterates `gc_objects` (the unified
    /// list) instead of per-type lists. Short strings and long literals
    /// remain in their separate intern stores (`string_intern`,
    /// `long_literals`) because they are keyed by content, not appended
    /// to `gc_objects` during migration.
    fn gcMakeAllWhite(self: *Vm) void {
        const w = self.gc_current_white & WHITEBITS;
        for (self.gc_objects.items) |obj| {
            gcPtr(obj).marked.* = w;
        }
        // Short strings are now in gc_objects (registered via gcRegisterString).
        // Only long literals remain in a separate store.
        var literal_it = self.long_literals.table.iterator();
        while (literal_it.next()) |entry| entry.value_ptr.*.gc_marked = w;
    }

    /// A6: Unified `gcMakeAllOld`. Iterates `gc_objects` instead of
    /// per-type lists. Preserves the `gc_busy` guard (prevents spurious
    /// minor collections during the transition) and the generational
    /// phase/KB resets that the per-type predecessor performed.
    fn gcMakeAllOld(self: *Vm) std.mem.Allocator.Error!void {
        // Prevent automatic GC from firing during this transition.
        // Allocations inside (e.g., gc_gen_threads.append) could trigger
        // condGcFromDispatch, which would run a spurious minor collection
        // and corrupt the age state we're setting up.
        const was_busy = self.gc_busy;
        self.gc_busy = true;
        defer self.gc_busy = was_busy;

        self.gcClearGenerationalLists();
        for (self.gc_objects.items) |obj| {
            gcPtr(obj).age.* = .old;
            if (obj == .thread) {
                try self.gc_gen_threads.append(self.alloc, obj.thread);
            }
        }
        // Short strings are now in gc_objects. Only long literals separate.
        var literal_it = self.long_literals.table.iterator();
        while (literal_it.next()) |entry| entry.value_ptr.*.gc_age = .old;
        self.gc_gen_phase = .minor;
        self.gc_gen_major_base_kb = self.gc_count_kb;
        self.gc_gen_major_start_kb = self.gc_count_kb;
        self.gc_gen_added_old_kb = 0;
        self.gcScheduleNextAutomaticCycle();
    }

    fn gcEnterGenerational(self: *Vm) DispatchError!void {
        if (self.gc_mode == .generational) return;
        try self.gcCycleFull();
        self.gc_mode = .generational;
        try self.gcMakeAllOld();
    }

    fn gcLeaveGenerational(self: *Vm) void {
        self.gc_mode = .incremental;
        self.gc_gen_phase = .minor;
        self.gcClearGenerationalLists();
        self.gcScheduleNextAutomaticCycle();
    }

    fn gcFullCollectionForUser(self: *Vm) DispatchError!void {
        if (self.gc_mode != .generational) {
            // PUC fullinc: run one complete cycle (mark → atomic → sweep →
            // callfin). Finalized objects are marked black during atomic
            // (gcMarkFinalizerReach), survive the sweep, then have __gc
            // called. They're reset to white by sweep and will be freed in
            // the NEXT collectgarbage() call. We do NOT run a second cycle
            // here — that would free the finalized objects immediately,
            // breaking the two-cycle finalization contract.
            try self.gcCycleFull();
            // PUC fullinc ends with setpause(): schedule next automatic cycle
            // and set debt so the next cycle starts when threshold is reached.
            self.gcScheduleNextAutomaticCycle();
            self.gc_step_debt_kb = self.gc_auto_threshold_kb - self.gc_count_kb;
            return;
        }
        self.gc_mode = .incremental;
        // PUC fullgen: reset all objects to current white so the incremental
        // mark/sweep can distinguish reachable (will be marked black) from
        // unreachable (stays old-white, swept after the white flip).
        self.gcMakeAllWhite();
        self.gcCycleFull() catch |err| {
            self.gc_mode = .generational;
            return err;
        };
        // No second cycle: finalized objects survive the first cycle and
        // will be freed in the next collectgarbage() call.
        self.gc_mode = .generational;
        try self.gcMakeAllOld();
        // After a full collection, all pending finalizers have run.
        // Clear the tick flag so automatic GC doesn't fire spuriously.
        self.gc_finalizer_tick_pending = false;
        // Set debt so the next automatic cycle starts when threshold is reached.
        self.gc_step_debt_kb = self.gc_auto_threshold_kb - self.gc_count_kb;
    }

    fn gcAutoCycleDue(self: *const Vm) bool {
        return self.gc_count_kb >= self.gc_auto_threshold_kb;
    }

    /// Advance an automatic collection by a small bounded amount. Allocation
    /// and dispatch safe points call this repeatedly; an in-progress cycle is
    /// advanced even when the heap threshold has already been rescheduled.
    fn gcAutomaticStep(self: *Vm) DispatchError!void {
        if (self.gc_busy) return;
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            if (!self.gc_finalizer_tick_pending and !self.gcAutoCycleDue()) return;
            try self.gcMinorCollection();
            return;
        }
        if (self.gc_state == .pause) {
            if (!self.gc_finalizer_tick_pending and !self.gcAutoCycleDue()) return;
            try self.gcStartCycle(true);
        }
        // PUC incstep: do bounded work, then set debt to stepsize so the
        // next step only runs after stepsize bytes more are allocated.
        // break_after_atomic=true mirrors PUC's incstep loop termination
        // (lgc.c:1719), pacing mark+atomic and sweep into separate steps.
        _ = try self.gcAdvance(self.gcAutomaticBudget(), true);
        if (self.gc_state == .pause) {
            // Cycle completed — schedule next cycle (PUC setpause).
            self.gcScheduleNextAutomaticCycle();
            // PUC setpause: debt = threshold - gettotalbytes. Our debt is
            // gc_step_debt_kb; set it so the next cycle starts when
            // gc_auto_threshold_kb is reached (gcNoteAlloc decrements it).
            self.gc_step_debt_kb = self.gc_auto_threshold_kb - self.gc_count_kb;
        } else {
            // Still in cycle — throttle next step (PUC luaE_setdebt(stepsize)).
            self.gc_step_debt_kb = @floatFromInt(@max(self.gc_stepsize, 1));
        }
    }

    /// Schedule the next automatic cycle from the live heap left after this
    /// one, mirroring PUC Lua's pause policy. A small minimum growth avoids a
    /// tight cycle loop for tiny heaps whose accounting changes by fractions
    /// of a kilobyte.
    fn gcScheduleNextAutomaticCycle(self: *Vm) void {
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            const minor_mul: f64 = @floatFromInt(@max(self.gc_gen_minormul, 0));
            const by_growth = self.gc_count_kb * (100.0 + minor_mul) / 100.0;
            self.gc_auto_threshold_kb = @max(by_growth, self.gc_count_kb + 64.0);
            return;
        }
        const pause: f64 = @floatFromInt(@max(self.gc_pause, 100));
        const by_pause = self.gc_count_kb * pause / 100.0;
        self.gc_auto_threshold_kb = @max(by_pause, self.gc_count_kb + 256.0);
    }

    fn gcStepBudget(self: *const Vm, requested_kb: i64) usize {
        const request: u128 = @intCast(@max(requested_kb, 1));
        const multiplier: u128 = @intCast(@max(self.gc_stepmul, 1));
        const scaled = @max(@as(u128, 1), (request * multiplier + 99) / 100);
        return @intCast(@min(scaled, std.math.maxInt(usize)));
    }

    /// PUC incstep: work2do = applygcparam(STEPMUL, stepsize / sizeof(void*)).
    /// stepsize is in bytes; gc_stepsize is in KB. sizeof(void*) = 8 on 64-bit.
    /// PUC singlestep in sweep does GCSWEEPMAX=20 objects; gcAdvance does
    /// one object per work unit, so multiply by GCSWEEPMAX.
    fn gcAutomaticBudget(self: *const Vm) usize {
        const puc_sweep_batch: usize = 20;
        const stepsize_bytes: u128 = @intCast(@max(self.gc_stepsize, 1) * 1024);
        const work_units: u128 = stepsize_bytes / @sizeOf(*anyopaque);
        const multiplier: u128 = @intCast(@max(self.gc_stepmul, 1));
        const scaled = @max(@as(u128, 1), (work_units * multiplier + 99) / 100);
        return @intCast(@min(scaled * puc_sweep_batch, std.math.maxInt(usize)));
    }

    /// PUC `fullinc` (lgc.c:1770): a full collection must always run a
    /// fresh cycle, even when called from a state that is mid-cycle.
    /// PUC implements this as `luaC_runtilstate(pause)` (finish pending),
    /// then `luaC_runtilstate(callfin)` + `luaC_runtilstate(pause)` (run a
    /// new cycle to completion). When `break_after_atomic` pacing leaves
    /// the collector in `.sweep` between automatic steps, an explicit
    /// `collectgarbage("collect")` must still finish that pending cycle
    /// AND run a new one — otherwise the new cycle never starts and
    /// unreachable finalizable objects are never collected (api.lua:976).
    fn gcCycleFull(self: *Vm) DispatchError!void {
        if (self.gc_busy) return;
        // Finish any pending cycle (PUC luaC_runtilstate(GCSpause)).
        while (self.gc_state != .pause) {
            _ = try self.gcAdvance(std.math.maxInt(usize), false);
        }
        // Start and run a new cycle to completion.
        try self.gcStartCycle(true);
        while (self.gc_state != .pause) {
            _ = try self.gcAdvance(std.math.maxInt(usize), false);
        }
    }

    fn gcResetCycleState(self: *Vm) void {
        self.gc_gray.clearRetainingCapacity();
        self.gc_marked_tables.clearRetainingCapacity();
        self.gc_marked_closures.clearRetainingCapacity();
        self.gc_marked_threads.clearRetainingCapacity();
        self.gc_weak_tables.clearRetainingCapacity();
        self.gc_fin_tables.clearRetainingCapacity();
        self.gc_fin_closures.clearRetainingCapacity();
        self.gc_fin_threads.clearRetainingCapacity();
        self.gc_to_finalize.clearRetainingCapacity();
        self.gc_fin_weak_tables.clearRetainingCapacity();
    }

    fn gcStartCycle(self: *Vm, do_sweep: bool) DispatchError!void {
        if (self.gc_state != .pause) return;

        self.gc_do_sweep = do_sweep;
        self.gc_cycle_finalizer_epoch = self.gc_finalizer_epoch;
        // PUC lgc.c: snapshot `allgc` length at cycle start. Objects allocated
        // during the cycle are appended beyond this point and handled
        // separately (marks reset, not swept for death).
        self.gc_objects_snapshot_len = self.gc_objects.items.len;

        self.gcResetCycleState();

        try self.gcMarkCurrentRoots();
        self.gc_state = .propagate;
    }

    /// Mark the full root set at the beginning of a cycle. Immutable VM
    /// registries and string/proto caches are intentionally visited only here;
    /// re-walking them for every tiny incremental slice would turn `load()`-
    /// heavy programs into repeated full-root scans.
    fn gcMarkCurrentRoots(self: *Vm) DispatchError!void {
        try self.gcMarkValue(.{ .Table = self.global_env });
        try self.gcMarkMutableRoots();
        try self.gcMarkVmRoots();
    }

    /// Re-scan roots that can change while mutator code runs between GC slices.
    /// Tables use write barriers, while registers/cells and transient VM fields
    /// are sampled at each safe point before the collector resumes.
    fn gcMarkMutableRoots(self: *Vm) DispatchError!void {
        if (self.debug_hook_main.func) |hook| try self.gcMarkValue(hook);
        if (self.wrap_thread) |thread| try self.gcMarkValue(.{ .Thread = thread });
        if (self.current_thread) |thread| try self.gcMarkValue(.{ .Thread = thread });
        if (self.forced_close_thread) |thread| try self.gcMarkValue(.{ .Thread = thread });

        // Scan bytecode frames in Thread.call_frames (the authoritative frame stack).
        const active_th = self.activeBytecodeThread();
        for (0..active_th.call_frames.len()) |i| {
            const frame = active_th.call_frames.getConstPtr(i);
            if (frame.proto) |proto| {
                try self.gcMarkBytecodeProto(proto);
                // Use self.bc_stack directly (not frame.regs) because GC
                // finalizers may execute Lua code that reallocs bc_stack,
                // making frame.regs.ptr stale. frame.regs.len is still valid.
                const regs = self.bc_stack[frame.base .. frame.base + frame.regs.len];
                const live_top: usize = if (frame.pc < proto.live_reg_top.len)
                    @min(proto.live_reg_top[frame.pc], regs.len)
                else
                    regs.len;
                for (regs[0..live_top]) |value| try self.gcMarkValue(value);
                // Mark to-be-closed variables: they may be above live_reg_top[pc]
                // (which tracks per-PC liveness) but are still live on the stack
                // pending __close finalization. Without this, GC would collect
                // them before __close runs.
                if (i == active_th.call_frames.len() - 1) {
                    for (self.bc_tbc_regs.items) |tbc_reg| {
                        if (tbc_reg < regs.len) try self.gcMarkValue(regs[tbc_reg]);
                    }
                }
            }
            try self.gcMarkValue(frame.callee);
            // PUC model: hidden varargs at [func_slot-nextraargs..func_slot].
            if (frame.proto != null and frame.nextraargs != 0) {
                const va = self.bc_stack[frame.func_slot - frame.nextraargs .. frame.func_slot];
                for (va) |value| try self.gcMarkValue(value);
            } else {
                for (frame.varargs) |value| try self.gcMarkValue(value);
            }
            for (frame.upvalues) |cell| {
                try self.gcQueueScanCell(cell);
            }
            for (frame.boxed) |maybe_cell| {
                if (maybe_cell) |cell| {
                    try self.gcQueueScanCell(cell);
                }
            }
            if (frame.env_override) |environment| try self.gcMarkValue(environment);
        }

        for (self.gc_temp_roots.items) |value| try self.gcMarkValue(value);
        if (self.debug_transfer_values) |values| for (values) |value| try self.gcMarkValue(value);
        if (self.err_has_obj) try self.gcMarkValue(self.err_obj);
        // c_error_value holds the object thrown by lua_error between the
        // _longjmp and callCFunction folding it into err_obj. It is a GC root
        // so a collection in that window cannot reclaim it.
        if (self.c_error_value) |v| try self.gcMarkValue(v);
        if (self.bytecode_coroutine_switch_request) |request| {
            try self.gcMarkValue(.{ .Thread = request.caller });
            try self.gcMarkValue(.{ .Thread = request.target });
            for (request.args) |value| try self.gcMarkValue(value);
        }
        if (self.gmatch_state) |state| {
            try self.gcMarkValue(.{ .String = state.s });
            try self.gcMarkValue(.{ .String = state.p });
        }
    }

    /// Run at most `budget` collector work units. A propagation unit scans one
    /// gray object; a sweep unit examines and possibly frees one registry entry.
    /// The atomic transition is intentionally one unit, matching PUC's bounded
    /// `singlestep` loop while keeping weak/finalizer semantics indivisible.
    fn gcAdvance(self: *Vm, budget: usize, break_after_atomic: bool) DispatchError!bool {
        if (self.gc_busy) return false;
        self.gc_busy = true;
        defer self.gc_busy = false;

        // PUC singlestep model: roots are marked once in gcStartCycle
        // (GCSpause → restartcollection). Between steps, write barriers
        // handle mutations. We do NOT re-mark mutable roots on every step
        // — that would turn each tiny incremental slice into a full root
        // scan, preventing the cycle from ever reaching sweep.
        if (self.gc_state == .pause) {
            try self.gcStartCycle(true);
        }

        var remaining = @max(budget, 1);
        while (remaining > 0 and self.gc_state != .pause) : (remaining -= 1) {
            const state_before = self.gc_state;
            switch (self.gc_state) {
                .pause => unreachable,
                .propagate => {
                    if (!try self.gcPropagateOne()) {
                        self.gc_state = .atomic;
                    }
                },
                .atomic => try self.gcAtomicPhase(),
                .sweep => {
                    if (!try self.gcSweepOne()) try self.gcFinishCycle();
                },
            }
            // PUC incstep (lgc.c:1719): `else if (stres == atomicstep && !fast) break;`
            // Stop after the atomic phase transitions to sweep so that the
            // sweep happens in a separate allocation-triggered step. Without
            // this, a single automatic step on a small heap completes a full
            // cycle (mark+atomic+sweep+setpause), and the immediately
            // rescheduled threshold is crossed again by the next handful of
            // allocations — producing many more cycles than PUC for the same
            // workload (e.g. tracegc in locals.lua).
            if (break_after_atomic and state_before == .atomic and self.gc_state == .sweep) {
                return self.gc_state == .pause;
            }
        }
        return self.gc_state == .pause;
    }

    /// PUC forward barrier for table writes (lgc.h:244 `luaC_barrierback`):
    /// Table writes use the BACKWARD barrier — turn the table gray and add
    /// to grayagain. The value is NOT marked, allowing weak value pruning
    /// and keeping newly created objects white.
    inline fn gcWriteBarrierTable(self: *Vm, owner: *Table, value: Value) DispatchError!void {
        if (self.gc_state == .pause) return;
        if (!gcIsBlack(owner.gc_marked)) return;
        // Only fire if value is collectable and white.
        switch (value) {
            .Table => |t| if (!gcIsWhite(t.gc_marked)) return,
            .Closure => |c| if (!gcIsWhite(c.gc_marked)) return,
            .Thread => |th| if (!gcIsWhite(th.gc_marked)) return,
            .String => |s| if (!gcIsWhite(s.gc_marked)) return,
            .Userdata => |ud| if (!gcIsWhite(ud.gc_marked)) return,
            else => return,
        }
        // Backward barrier: turn owner gray, add to grayagain.
        gcSetGray(&owner.gc_marked);
        try self.gc_grayagain.append(self.alloc, .{ .table = owner });
    }

    /// PUC luaC_barrierback_ (lgc.c:268) for userdata uservalue writes.
    /// Same backward barrier as table writes: turn the userdata gray and
    /// add to grayagain. Used by debug.setuservalue (PUC lapi.c:1015).
    inline fn gcWriteBarrierUserdata(self: *Vm, owner: *Userdata, value: Value) DispatchError!void {
        // Generational mode: use gcRememberObject (sets age to touched1).
        // This fires even when GC is paused — in gen mode, paused objects
        // are old (black), and mutations must be tracked for the next
        // minor cycle.
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            try self.gcRememberObject(.{ .userdata = owner });
            return;
        }
        if (self.gc_state == .pause) return;
        if (!gcIsBlack(owner.gc_marked)) return;
        // Only fire if value is collectable and white.
        switch (value) {
            .Table => |t| if (!gcIsWhite(t.gc_marked)) return,
            .Closure => |c| if (!gcIsWhite(c.gc_marked)) return,
            .Thread => |th| if (!gcIsWhite(th.gc_marked)) return,
            .String => |s| if (!gcIsWhite(s.gc_marked)) return,
            .Userdata => |ud| if (!gcIsWhite(ud.gc_marked)) return,
            else => return,
        }
        // Backward barrier: turn owner gray, add to grayagain.
        gcSetGray(&owner.gc_marked);
        try self.gc_grayagain.append(self.alloc, .{ .userdata = owner });
    }

    /// PUC forward barrier for cell/upvalue writes (lgc.h:238 `luaC_barrier`):
    /// Cell value assignment uses the FORWARD barrier — mark the VALUE if
    /// the cell is black. This matches PUC's luaC_barrier(L, owner, val)
    /// used by lua_setupvalue and OP_SETUPVAL.
    inline fn gcWriteBarrierCell(self: *Vm, cell: *Cell, value: Value) DispatchError!void {
        if (self.gc_state == .pause) return;
        if (!gcIsBlack(cell.gc_marked)) return;
        // PUC luaC_barrier_: if keepinvariant (propagate/atomic), mark the
        // value to restore the invariant. In sweep phase, make the owner
        // white instead — the value will be visited in the next collection.
        switch (self.gc_state) {
            .propagate, .atomic => {
                // Forward barrier: mark the value.
                switch (value) {
                    .Table, .Closure, .Thread, .String => try self.gcMarkValue(value),
                    else => {},
                }
            },
            .sweep => {
                // Make owner white (PUC luaC_makewhite in sweep phase).
                gcMakeWhite(&cell.gc_marked, self.gc_current_white);
            },
            .pause => {},
        }
    }

    /// Legacy barrier that marks any value unconditionally. Kept for sites
    /// that haven't been converted to PUC-faithful barriers yet.
    inline fn gcWriteBarrier(self: *Vm, value: Value) DispatchError!void {
        if (self.gc_state == .pause) return;
        switch (value) {
            .Table, .Closure, .Thread, .String, .Userdata => try self.gcMarkValue(value),
            else => {},
        }
    }

    inline fn gcStoreCellValue(self: *Vm, cell: *Cell, value: Value) DispatchError!void {
        // Use cell.set() to properly handle open upvalues (writes to stack
        // slot) vs closed upvalues (writes to cell.value).
        cell.set(self, value);
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            if (gcValueAge(value)) |age| {
                if (cell.gc_age.isOld() and age.isYoung()) try self.gcRememberCell(cell);
            }
        }
        // PUC forward barrier: only fire if cell is BLACK.
        // Open upvalues are kept GRAY during GC, so this won't fire for them.
        try self.gcWriteBarrierCell(cell, value);
    }

    inline fn gcStoreClosureEnv(self: *Vm, closure: *Closure, value: Value) DispatchError!void {
        closure.env_override = value;
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            // Generational mode: forward barrier — mark value, make OLD0.
            if (closure.gc_age.isOld()) {
                if (gcValueAge(value)) |age| {
                    if (age.isYoung()) {
                        // PUC luaC_barrier_: reallymarkobject + setage(v, G_OLD0)
                        switch (value) {
                            .Table => |t| if (gcIsWhite(t.gc_marked)) gcSetBlack(&t.gc_marked),
                            .Closure => |c| if (gcIsWhite(c.gc_marked)) gcSetBlack(&c.gc_marked),
                            .Thread => |th| if (gcIsWhite(th.gc_marked)) gcSetBlack(&th.gc_marked),
                            .String => |s| if (gcIsWhite(s.gc_marked)) gcSetBlack(&s.gc_marked),
                            else => {},
                        }
                        gcSetValueAge(value, .old0);
                        try self.gc_old1.append(self.alloc, GcObject.fromValue(value).?);
                    }
                }
            }
            return;
        }
        // Incremental mode: forward barrier (luaC_barrier).
        if (self.gc_state == .pause or !gcIsBlack(closure.gc_marked)) return;
        switch (self.gc_state) {
            .propagate, .atomic => {
                switch (value) {
                    .Table => |t| if (gcIsWhite(t.gc_marked)) try self.gcMarkValue(value),
                    .Closure => |c| if (gcIsWhite(c.gc_marked)) try self.gcMarkValue(value),
                    .Thread => |th| if (gcIsWhite(th.gc_marked)) try self.gcMarkValue(value),
                    .String => |s| if (gcIsWhite(s.gc_marked)) try self.gcMarkValue(value),
                    else => {},
                }
            },
            .sweep => gcMakeWhite(&closure.gc_marked, self.gc_current_white),
            .pause => {},
        }
    }

    inline fn gcStoreMetatable(self: *Vm, table: *Table, metatable: ?*Table) DispatchError!void {
        table.metatable = metatable;
        if (metatable) |mt| {
            // Generational mode: forward barrier — mark metatable, make OLD0.
            if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
                if (table.gc_age.isOld() and mt.gc_age.isYoung()) {
                    // PUC luaC_barrier_: reallymarkobject + setage(v, G_OLD0)
                    if (gcIsWhite(mt.gc_marked)) gcSetBlack(&mt.gc_marked);
                    mt.gc_age = .old0;
                    try self.gc_old1.append(self.alloc, .{ .table = mt });
                }
                return;
            }
            // Incremental mode: forward barrier (luaC_objbarrier).
            if (self.gc_state == .pause or !gcIsBlack(table.gc_marked) or !gcIsWhite(mt.gc_marked)) return;
            switch (self.gc_state) {
                .propagate, .atomic => try self.gcMarkValue(.{ .Table = mt }),
                .sweep => gcMakeWhite(&table.gc_marked, self.gc_current_white),
                .pause => {},
            }
        }
    }

    inline fn gcTableWriteBarrier(self: *Vm, table: *Table, key: Value, value: Value) DispatchError!void {
        if (self.gc_mode == .generational and self.gc_gen_phase == .minor) {
            // Generational mode: age-based remember. When an old table gets
            // a young value, remember the table for re-traversal. Do NOT
            // mark the value — weak value pruning needs it to stay white.
            if (table.gc_age.isOld()) {
                const key_young = if (gcValueAge(key)) |age| age.isYoung() else false;
                const value_young = if (gcValueAge(value)) |age| age.isYoung() else false;
                if (key_young or value_young) try self.gcRememberValue(.{ .Table = table });
            }
            return;
        }
        // Incremental mode: PUC backward barrier (turn owner gray, add to
        // grayagain). The value is NOT marked — this keeps newly created
        // objects white and allows weak value pruning.
        try self.gcWriteBarrierTable(table, key);
        try self.gcWriteBarrierTable(table, value);
    }

    fn gcDrainGray(self: *Vm) DispatchError!void {
        while (try self.gcPropagateOne()) {}
    }

    /// Drain the grayagain list: traverse each grayagain object and drain
    /// the regular gray list after each one. Mirrors PUC's `propagatemark`
    /// grayagain handling in atomic phase (lgc.c:503-510).
    ///
    /// Objects in grayagain were turned gray by backward write barriers
    /// (a BLACK object was modified after being fully traversed). They MUST
    /// be re-traversed regardless of current mark state — a barrier might
    /// have turned them gray, then the gray drain turned them black again,
    /// but their NEW children (added after the first traversal) have not
    /// been marked. So we always re-add to gray list and re-traverse.
    fn gcDrainGrayagain(self: *Vm) DispatchError!void {
        // A4: single loop over the unified GcObject grayagain list. Cells
        // are folded in — their value is marked inline and they go black,
        // matching the old parallel grayagain_cells behavior. Other types
        // are re-queued into gc_gray for full re-propagation.
        for (self.gc_grayagain.items) |obj| {
            switch (obj) {
                .cell => |cell| {
                    gcSetGray(&cell.gc_marked);
                    // Cells don't have children beyond their value; mark it.
                    try self.gcMarkValue(cell.get(self));
                    gcSetBlack(&cell.gc_marked);
                },
                else => {
                    // Force re-traversal: set to gray and add to gray list.
                    const p = gcPtr(obj);
                    gcSetGray(p.marked);
                    try self.gc_gray.append(self.alloc, obj);
                    try self.gcDrainGray();
                },
            }
        }
        self.gc_grayagain.clearRetainingCapacity();
    }

    fn gcAtomicCommon(self: *Vm) DispatchError!void {
        // PUC atomic: markobject(g, L) + markvalue(g, l_registry) + markmt(g).
        // Re-mark mutable roots here (running thread, frames, registers)
        // because they may have changed since cycle start. Between cycle
        // start and atomic, write barriers handle mutations, but registers
        // and transient VM fields are not write-barriered — they must be
        // re-scanned here, exactly as PUC does in atomic().

        // Clear FINALIZEDBIT from previous cycles before gcMarkFinalizerReach
        // sets fresh bits. In full cycles the sweep clears it, but minor
        // cycles don't sweep old objects — stale FINALIZEDBIT would prevent
        // weak-key pruning of finalized-reachable objects.
        // DISABLED: causes use-after-free when FINALIZEDBIT is cleared from
        // an object that was kept alive ONLY by FINALIZEDBIT in a previous
        // minor cycle, then swept in a subsequent minor cycle.
        // TODO: implement targeted clear instead of O(n) sweep.
        // if (self.gc_minor_cycle) {
        //     self.gcClearFinalizedBit();
        // }

        try self.gcMarkMutableRoots();
        try self.gcDrainGray();
        // PUC atomic: drain grayagain list (objects turned gray by backward
        // barriers during propagate phase). These must be re-traversed
        // before sweep to catch children added after the first traversal.
        // Skip during minor cycles: grayagain is handled by the minor
        // collection's grayagain processing + gcCorrectGrayAgain for age
        // promotion. Draining here would clear grayagain before
        // gcCorrectGrayAgain can process it.
        if (!self.gc_minor_cycle) {
            try self.gcDrainGrayagain();
            try self.gcDrainGray();
        }

        try self.gcPropagateEphemerons(&self.gc_weak_tables);
        try self.gcDrainGray();

        try self.gcPruneWeakValues(self.gc_weak_tables.items);

        const to_finalize = try self.gcCollectFinalizables();
        defer self.alloc.free(to_finalize);
        try self.gc_to_finalize.appendSlice(self.alloc, to_finalize);
        try self.gcMarkFinalizerReach(self.gc_to_finalize.items);

        // Weak finalizable tables were collected into gc_fin_weak_tables
        // during gcMarkFinalizerReach (folded into the traversal instead of
        // a separate post-hoc HashSet iteration).
        if (self.gc_fin_weak_tables.items.len > 0) {
            try self.gcPruneWeakValues(self.gc_fin_weak_tables.items);
            try self.gcPruneWeakKeys(self.gc_fin_weak_tables.items);
        }

        try self.gcPruneWeakKeys(self.gc_weak_tables.items);
        try self.gcFinalizeList(self.gc_to_finalize.items);

        // Finalizers may publish newly allocated objects into live tables.
        // Backward barriers turn the owner gray and add to grayagain.
        // Drain grayagain again to catch objects modified by finalizers,
        // then drain gray to finish marking all children.
        // Skip during minor cycles: grayagain is needed by gcCorrectGrayAgain
        // for age promotion in gcSweepYoungGeneration.
        if (!self.gc_minor_cycle) {
            try self.gcDrainGrayagain();
            try self.gcDrainGray();
        }
    }

    /// Clear FINALIZEDBIT on all GC-managed objects. Called at the start of
    /// minor-cycle atomic to prevent stale FINALIZEDBIT from the previous
    /// cycle's gcMarkFinalizerReach from interfering with weak-key pruning.
    /// TODO: Replace with a targeted clear-list once gc_fin_* removal is
    /// complete; this O(n) sweep is a transitional measure.
    /// A6: Unified `gcClearFinalizedBit`. Iterates `gc_objects` instead of
    /// per-type lists. FINALIZEDBIT is only ever set on tables/closures/
    /// threads (per `gcCanFinalize`), so clearing it on all objects is
    /// harmless and uniform.
    fn gcClearFinalizedBit(self: *Vm) void {
        for (self.gc_objects.items) |obj| {
            gcPtr(obj).marked.* &= ~FINALIZEDBIT;
        }
    }

    fn gcAtomicPhase(self: *Vm) DispatchError!void {
        try self.gcAtomicCommon();
        if (!self.gc_do_sweep) {
            try self.gcFinishCycle();
            return;
        }

        // PUC entersweep (lgc.c): flip currentwhite before sweep begins.
        // After the flip, gcIsDead distinguishes dead objects (old white)
        // from survivors (black or new white). Surviving objects are reset
        // to the new current white during sweep, so the next cycle starts
        // with a clean slate.
        self.gc_current_white ^= WHITEBITS;

        // Deaden unmarked string keys BEFORE any sweep frees table objects.
        // After the flip, alive tables have BLACKBIT (gcIsWhite=false), dead
        // tables have the old white bit (gcIsWhite=true → skipped). Running
        // before sweep avoids use-after-free: no table memory has been freed
        // yet, so all gc_objects table pointers are valid.
        self.gcDeadenUnmarkedStringKeys();

        self.gcClearDeadFrameRegisters();
        // PUC entersweep: start sweeping `allgc` from the beginning.
        // The snapshot length was captured in `gcStartCycle`.
        self.gc_sweep_objects_cursor = 0;
        self.gc_state = .sweep;
    }

    fn gcClearDeadFrameRegisters(self: *Vm) void {
        const th = self.activeBytecodeThread();
        for (0..th.call_frames.len()) |i| {
            const frame = th.call_frames.getPtr(i);
            if (frame.proto) |proto| {
                // Use self.bc_stack directly (not frame.regs) because GC
                // finalizers may have realloc'd bc_stack.
                const regs_len = frame.frame_cap;
                const regs = self.bc_stack[frame.base .. frame.base + regs_len];
                const live_top: usize = if (frame.pc < proto.live_reg_top.len)
                    @min(proto.live_reg_top[frame.pc], regs.len)
                else
                    regs.len;
                // Don't clear to-be-closed variables: they may be above
                // live_reg_top[pc] but are still pending __close finalization.
                var clear_from: usize = live_top;
                if (i == th.call_frames.len() - 1) {
                    for (self.bc_tbc_regs.items) |tbc_reg| {
                        if (tbc_reg < regs.len and tbc_reg >= clear_from) clear_from = tbc_reg + 1;
                    }
                }
                // PUC-faithful overlapping frames: a child frame's func_slot
                // may be within this frame's register window. Don't clear
                // registers that belong to a child frame — they are live
                // roots of the child, not dead registers of this frame.
                // The child frame starts at its func_slot, so any register
                // at or above the child's func_slot is owned by the child.
                var clear_end: usize = regs.len;
                if (i + 1 < th.call_frames.len()) {
                    const child = th.call_frames.getConstPtr(i + 1);
                    if (child.proto != null) {
                        const child_start = child.func_slot - frame.base;
                        if (child_start < clear_end) clear_end = child_start;
                    }
                }
                if (clear_from < clear_end) {
                    for (regs[clear_from..clear_end]) |*slot| {
                        switch (slot.*) {
                            .Table, .Closure, .Thread => slot.* = .Nil,
                            else => {},
                        }
                    }
                }
            }
        }
    }

    /// A6: Unified young-object age promotion. Replaces the per-type
    /// `gcPromoteYoungValue`/`gcPromoteYoungCell` pair. `gcPtr` gives uniform
    /// access to `.age` regardless of variant, so a single switch covers all
    /// GC-managed types (tables, closures, threads, strings, cells).
    ///
    /// Returns `true` if the object stays in the young list (age `.new` →
    /// `.survival`, or already `.old1`/`.old`/`.touched*`), `false` if it
    /// leaves the young list (promoted to `.old0`/`.old1`).
    ///
    /// PUC-faithful age transitions (lgc.c `genstep` → `youngcollection`):
    ///   new       → survival  (survives first minor cycle, stays young)
    ///   survival  → old1      (survives second cycle, joins gc_old1 list)
    ///   old0      → old1      (forward-barrier-promoted; gcCorrectOld1
    ///                          advances old0→old1 after the cycle)
    ///
    /// Side effects preserved from the per-type predecessors:
    ///   - `gc_gen_added_old_kb`: tracks bytes promoted to old gen, used by
    ///     `gcMinorCollection` to decide minor→major threshold (PUC
    ///     `GCmajorminor` equivalent). Without this, the major-cycle
    ///     trigger would never fire from young promotions.
    ///   - `gc_gen_threads`: threads promoted to old must be scanned as
    ///     roots in subsequent minor cycles (line ~14326). This is our
    ///     equivalent of PUC's `twups` list (threads with upvalues/open
    ///     variables that need re-traversal). Without this, promoted
    ///     threads would be missed by minor marking → use-after-free.
    fn gcPromoteYoungObject(self: *Vm, obj: GcObject) DispatchError!bool {
        const p = gcPtr(obj);
        switch (p.age.*) {
            .new => {
                p.age.* = .survival;
                return true;
            },
            .survival => {
                p.age.* = .old1;
                try self.gc_old1.append(self.alloc, obj);
                self.gc_gen_added_old_kb += @as(f64, @floatFromInt(gcObjectBytes(obj))) / 1024.0;
                if (obj == .thread) try self.gc_gen_threads.append(self.alloc, obj.thread);
                return false;
            },
            .old0 => {
                // Forward barriers already linked OLD0 into gc_old1. Keep the
                // age until gcCorrectOld1 advances it after this collection.
                self.gc_gen_added_old_kb += @as(f64, @floatFromInt(gcObjectBytes(obj))) / 1024.0;
                return false;
            },
            // old1, old, touched* — already promoted or in grayagain; keep
            // in young list so the sweep compaction retains them.
            else => return true,
        }
    }

    /// A6: Unified generational young-object sweep. Replaces the five
    /// per-type `gcSweepYoung{Tables,Closures,Threads,Strings,Cells}`
    /// functions with a single pass over `gc_young_objects`.
    ///
    /// PUC-faithful (lgc.c `youngcollection` → `sweepgen`): walks the young
    /// list up to the snapshot taken at cycle start, freeing dead objects
    /// and promoting survivors. Objects allocated mid-cycle (beyond the
    /// snapshot) are unconditionally kept and their marks reset.
    ///
    /// Liveness check (PUC `isdead` + `testbit(FINALIZEDBIT)`):
    ///   alive = !gcIsDead(marked, current_white)   // marked this cycle
    ///        or (marked & FINALIZEDBIT) != 0        // pending finalization
    ///        or age == .old0                        // forward-barrier promoted
    ///
    /// The `finalizables.contains(table)` check from the old per-type
    /// `gcSweepYoungTables` is intentionally dropped: A5's `gcSweepOne`
    /// (incremental major sweep) already relies solely on FINALIZEDBIT,
    /// and the minor sweep must be consistent with it. FINALIZEDBIT is
    /// set by `gcMarkFinalizerReach` for any object reachable from a
    /// finalizer, which subsumes the `finalizables` set's purpose.
    ///
    /// `gcFreeObject` (A2/A5) dispatches per-type teardown uniformly;
    /// `gcUnregisterObject` removes from `gc_objects` via `gc_index`.
    fn gcSweepYoungObjects(self: *Vm) DispatchError!void {
        const snapshot = @min(self.gc_young_objects_snapshot_len, self.gc_young_objects.items.len);
        var write: usize = 0;
        for (self.gc_young_objects.items[0..snapshot]) |obj| {
            const p = gcPtr(obj);
            const alive = !gcIsDead(p.marked.*, self.gc_current_white) or
                (p.marked.* & FINALIZEDBIT) != 0 or
                p.age.* == .old0 or
                (gcCanFinalize(obj) and self.gcHasFinalizer(obj));
            if (!alive) {
                // Remove from gc_objects first (swapRemove), then free memory.
                self.gcUnregisterObject(obj);
                self.gcFreeObject(obj);
                continue;
            }
            p.marked.* = self.gc_current_white & WHITEBITS;
            if (try self.gcPromoteYoungObject(obj)) {
                self.gc_young_objects.items[write] = obj;
                write += 1;
            }
        }
        // Compact post-snapshot entries (mid-cycle allocations).
        // They may have been marked while on the stack; reset their marks
        // so the next cycle starts with a clean white slate, then keep
        // them in the young list (they haven't been age-promoted yet).
        for (self.gc_young_objects.items[snapshot..]) |obj| {
            gcPtr(obj).marked.* = self.gc_current_white & WHITEBITS;
            self.gc_young_objects.items[write] = obj;
            write += 1;
        }
        self.gc_young_objects.items.len = write;
    }

    fn gcCorrectOld1(self: *Vm) void {
        // A4: single pass over the unified GcObject list. gcPtr gives us
        // uniform access to .age regardless of variant, so the old0→old1
        // and old1→old transitions collapse into one loop.
        const snapshot = @min(self.gc_old1_snapshot_len, self.gc_old1.items.len);
        var write: usize = 0;
        for (self.gc_old1.items[0..snapshot]) |obj| {
            const p = gcPtr(obj);
            switch (p.age.*) {
                .old0 => {
                    p.age.* = .old1;
                    self.gc_old1.items[write] = obj;
                    write += 1;
                },
                .old1 => p.age.* = .old,
                else => {},
            }
        }
        for (self.gc_old1.items[snapshot..]) |obj| {
            self.gc_old1.items[write] = obj;
            write += 1;
        }
        self.gc_old1.items.len = write;
    }

    fn gcCorrectGrayAgain(self: *Vm) void {
        // A4: single pass over the unified GcObject list. touched1→touched2
        // stays in grayagain; touched2→old drops out (promoted to old).
        const snapshot = @min(self.gc_grayagain_snapshot_len, self.gc_grayagain.items.len);
        var write: usize = 0;
        for (self.gc_grayagain.items[0..snapshot]) |obj| {
            const p = gcPtr(obj);
            switch (p.age.*) {
                .touched1 => {
                    p.age.* = .touched2;
                    self.gc_grayagain.items[write] = obj;
                    write += 1;
                },
                .touched2 => p.age.* = .old,
                else => {},
            }
        }
        for (self.gc_grayagain.items[snapshot..]) |obj| {
            self.gc_grayagain.items[write] = obj;
            write += 1;
        }
        self.gc_grayagain.items.len = write;
    }

    fn gcSweepYoungGeneration(self: *Vm) DispatchError!void {
        self.gcClearDeadFrameRegisters();
        // A6: single unified sweep over gc_young_objects replaces the five
        // per-type sweeps. gcCorrectOld1/gcCorrectGrayAgain (A4) already
        // operate on the unified GcObject lists.
        try self.gcSweepYoungObjects();
        self.gcCorrectOld1();
        self.gcCorrectGrayAgain();
    }

    fn gcMinorCollection(self: *Vm) DispatchError!void {
        if (self.gc_busy) return;
        self.gc_busy = true;
        self.gc_minor_cycle = true;
        defer {
            self.gc_minor_cycle = false;
            self.gc_busy = false;
        }

        self.gc_cycle_finalizer_epoch = self.gc_finalizer_epoch;
        // A6: single unified young list replaces the five per-type young lists.
        self.gc_young_objects_snapshot_len = self.gc_young_objects.items.len;
        self.gc_old1_snapshot_len = self.gc_old1.items.len;
        self.gc_grayagain_snapshot_len = self.gc_grayagain.items.len;
        self.gc_gen_last_minor_visited = 0;
        self.gc_gen_last_minor_old_visited = 0;
        self.gcResetCycleState();

        // Reset all young objects' marks to current_white before marking.
        // Marks from a previous minor cycle persist on young objects that
        // were beyond the previous snapshot. Without this reset, gcIsDead
        // would see stale marks from the previous cycle and incorrectly
        // treat dead objects as alive (or live as dead).
        // A6: single loop over the unified gc_young_objects list.
        for (self.gc_young_objects.items) |obj| gcPtr(obj).marked.* = self.gc_current_white & WHITEBITS;

        try self.gcMarkCurrentRoots();
        // A4: gc_old1 is now GcObject-typed; gcQueueScanObject handles all
        // variants (including Cell) uniformly.
        for (self.gc_old1.items[0..self.gc_old1_snapshot_len]) |obj| try self.gcQueueScanObject(obj);
        // Grayagain items were modified by barriers since the last minor
        // collection. They MUST be re-traversed regardless of current mark
        // state — a BLACK object might have new young children that haven't
        // been marked yet. Force gray + queue.
        // A4: single loop over GcObject. Cells route through gcQueueScanCell
        // (which honors the PUC open/closed distinction); other types go
        // straight to the gray list for re-propagation.
        for (self.gc_grayagain.items[0..self.gc_grayagain_snapshot_len]) |obj| {
            switch (obj) {
                .cell => |cell| try self.gcQueueScanCell(cell),
                else => {
                    const p = gcPtr(obj);
                    gcSetGray(p.marked);
                    try self.gc_gray.append(self.alloc, obj);
                },
            }
        }
        for (self.gc_gen_threads.items) |thread| try self.gcQueueScanValue(.{ .Thread = thread });

        try self.gcDrainGray();
        try self.gcAtomicCommon();
        try self.gcSweepYoungGeneration();

        // PUC paces the next cycle via setpause/setminordebt, not via a
        // finalizer-driven tick flag. See gcFinishCycle for rationale.
        self.gc_finalizer_tick_pending = false;
        const limit = self.gc_gen_major_base_kb * @as(f64, @floatFromInt(@max(self.gc_gen_minormajor, 0))) / 100.0;
        if (limit > 0 and self.gc_gen_added_old_kb >= limit) {
            self.gc_gen_phase = .major;
            self.gc_gen_major_start_kb = self.gc_count_kb;
            self.gc_auto_threshold_kb = self.gc_count_kb;
        } else {
            self.gcScheduleNextAutomaticCycle();
        }
    }

    /// Incremental sweep: walk `gc_objects` up to snapshot length, freeing
    /// dead objects. Returns true if there are more objects to sweep.
    /// PUC-faithful: sweeps `allgc` in allocation order (lgc.c `sweepstep`).
    ///
    /// Dead objects are removed via `gcUnregisterObject` (O(1) `swapRemove`
    /// on `gc_objects` using `gc_index`), then freed via `gcFreeObject`.
    /// Because `swapRemove` moves the last element into the freed slot, and
    /// we walk forward, the swapped-in element (from beyond the cursor) has
    /// not been examined yet — so we do NOT advance the cursor to re-examine it.
    fn gcSweepOne(self: *Vm) DispatchError!bool {
        // Phase 1: sweep objects within the snapshot (captured at cycle start).
        // The snapshot length is the bound for death-checking: objects beyond
        // it were allocated during this cycle and survive.
        //
        // IMPORTANT: `gcUnregisterObject` uses `swapRemove`, which shrinks
        // `gc_objects`. When enough objects are freed, the list can become
        // shorter than the cursor (even though cursor < snapshot). In that
        // case, all snapshot objects at [cursor, snapshot) have been swapped
        // into earlier positions and examined — we fall through to Phase 2/3.
        if (self.gc_sweep_objects_cursor < self.gc_objects_snapshot_len and
            self.gc_sweep_objects_cursor < self.gc_objects.items.len)
        {
            const obj = self.gc_objects.items[self.gc_sweep_objects_cursor];
            const p = gcPtr(obj);
            // PUC isdead: object has the OTHER white bit (created in a
            // previous cycle, never marked in this one).
            // FINALIZEDBIT prevents sweeping — objects pending finalization
            // are kept alive until finalizers run and reset the bit.
            const is_dead = gcIsDead(p.marked.*, self.gc_current_white) and
                (p.marked.* & FINALIZEDBIT) == 0;
            // Only tables can have finalizers (__gc metamethod) in practice.
            // `gcCanFinalize` is the type-level check; `gcHasFinalizer` is
            // the instance-level check (registered in `finalizables` set).
            const has_finalizer = gcCanFinalize(obj) and self.gcHasFinalizer(obj);

            if (is_dead and !has_finalizer) {
                // Object is dead with no finalizer — remove from gc_objects
                // (swapRemove moves the last element into this slot), then
                // free its memory. We must NOT advance the cursor so the
                // swapped-in element gets examined next iteration.
                if (obj == .closure) {
                }
                self.gcUnregisterObject(obj);
                self.gcFreeObject(obj);
            } else {
                // Object is alive (or has a finalizer to run) — reset its
                // mark to the current white for the next cycle.
                // PUC sweeplist: `makewhite(g, o)` clears color + finalized bits.
                p.marked.* = self.gc_current_white & WHITEBITS;
                self.gc_sweep_objects_cursor += 1;
            }
            return true;
        }

        // Phase 2: reset marks for objects allocated DURING the sweep (beyond
        // the snapshot). These survive this cycle; their marks must be reset
        // so the next cycle starts clean. PUC: `sweepstep` handles new objects
        // appended to `allgc` during sweep the same way.
        if (self.gc_sweep_objects_cursor < self.gc_objects.items.len) {
            const obj = self.gc_objects.items[self.gc_sweep_objects_cursor];
            gcPtr(obj).marked.* = self.gc_current_white & WHITEBITS;
            self.gc_sweep_objects_cursor += 1;
            return true;
        }

        // Phase 3: sweep long string literals + rehash string_intern.
        try self.long_literals.sweep(self.alloc, self.gc_current_white);
        // Rehash string_intern.table to clear tombstones left by per-object
        // sweep removing dead strings. Without this, Zig's HashMapUnmanaged
        // accumulates tombstones → probe chains degrade to O(N).
        self.string_intern.table.rehash(@as(StringIntern.Context, .{}));
        return false;
    }

    /// Free a GC object's memory. Centralizes type-specific teardown that was
    /// previously spread across per-type sweep branches.
    ///
    /// This function ONLY frees the object's allocation and internal buffers.
    /// It does NOT remove the object from `gc_objects` — the caller (sweep
    /// function or `drainGcRegistries`) is responsible for that:
    ///   - `gcSweepOne` / `gcSweepYoungObjects` call `gcUnregisterObject`
    ///     before `gcFreeObject` to remove from `gc_objects` via `swapRemove`.
    ///   - `drainGcRegistries` iterates `gc_objects` and frees each, then
    ///     deinit's the list — no per-object removal needed.
    ///
    /// `gcNoteFree` updates the GC memory counter so `testbytes` converges.
    fn gcFreeObject(self: *Vm, obj: GcObject) void {
        switch (obj) {
            .table => |t| {
                const bytes = @sizeOf(Table) + t.asize * @sizeOf(Value) +
                    t.hash.len * @sizeOf(ltable.Node);
                self.gcNoteFree(bytes);
                t.deinit(self.alloc);
                self.alloc.destroy(t);
            },
            .closure => |c| {
                // PUC freeobj for LClosure: free upvalue array (luaF_freecupvals).
                // Each Cell is a separate GC object freed by its own gcFreeObject;
                // only the pointer array is freed here.
                if (c.upvalues.len > 0) self.alloc.free(c.upvalues);
                self.gcNoteFree(@sizeOf(Closure) + c.upvalues.len * @sizeOf(*Cell));
                self.alloc.destroy(c);
            },
            .thread => |th| {
                self.freeThreadWrapBuffers(th);
                self.freeThreadBytecodeFrames(th);
                // Only free the parked runtime if this thread isn't the
                // currently active one (its runtime is shared with the VM).
                if (self.active_runtime_thread != th) self.freeParkedThreadRuntime(th);
                // Free all optional []Value buffers on the Thread.
                if (th.yielded) |values| self.alloc.free(values);
                if (th.resume_inbox) |inbox| self.alloc.free(inbox);
                if (th.tail_resume_inbox) |inbox| self.alloc.free(inbox);
                if (th.suspended_builtin_args) |args| self.alloc.free(args);
                self.gcNoteFree(@sizeOf(Thread));
                self.alloc.destroy(th);
            },
            .string => |s| {
                // PUC luaS_remove: remove from intern table BEFORE freeing
                // (s.bytes() must be valid for the hashmap key lookup).
                // Short strings are in string_intern; long literals in
                // long_literals. HashMap.remove is a no-op if not found.
                if (s.len <= lua_string_max_short_len) {
                    _ = self.string_intern.table.remove(s.bytes());
                }
                // External strings only own the header; regular strings own
                // header + inline content. `destroyLuaString` handles the
                // external dealloc callback and frees the right amount.
                const bytes = if (s.is_external) @sizeOf(LuaString) else @sizeOf(LuaString) + s.len;
                self.gcNoteFree(bytes);
                destroyLuaString(self.alloc, s);
            },
            .cell => |c| {
                self.gcNoteFree(@sizeOf(Cell));
                self.alloc.destroy(c);
            },
            .userdata => |u| {
                const bytes = @sizeOf(Userdata) + u.uservalues.len * @sizeOf(Value) + u.payload.len;
                self.gcNoteFree(bytes);
                if (u.uservalues.len > 0) self.alloc.free(u.uservalues);
                if (u.payload.len > 0) self.alloc.free(u.payload);
                self.alloc.destroy(u);
            },
        }
    }

    /// Check if an object has a registered finalizer (__gc metamethod).
    /// Currently only tables can have finalizers (the `finalizables` set).
    /// Closures and threads support finalization in PUC but are not yet
    /// wired to the `finalizables` set — they return `false` here, matching
    /// the old per-type sweep behavior.
    fn gcHasFinalizer(self: *Vm, obj: GcObject) bool {
        return self.finalizables.contains(obj);
    }

    fn gcFinishCycle(self: *Vm) DispatchError!void {
        self.gc_state = .pause;
        // Reset sweep cursor for the next cycle.
        self.gc_sweep_objects_cursor = 0;
        self.gc_gray.clearRetainingCapacity();
        // PUC does not force a follow-up collection when finalizers ran
        // during a cycle; the next cycle is paced solely by GCdebt (PUC
        // setpause). Setting `gc_finalizer_tick_pending` here made every
        // allocation-site check bypass `gc_step_debt_kb` and start a fresh
        // cycle, producing many more cycles than PUC for the same workload
        // (e.g. tracegc in locals.lua prints 1 dot per cycle in PUC, but
        // luazig produced one extra cycle per collect because the next
        // allocation after a cycle immediately re-entered `gcAutomaticStep`).
        // The flag remains defined for legacy callers; never set it from
        // cycle completion.
        self.gc_finalizer_tick_pending = false;

        if (self.gc_mode == .generational and self.gc_gen_phase == .major) {
            const added = @max(0.0, self.gc_gen_major_start_kb - self.gc_gen_major_base_kb);
            const reclaimed = @max(0.0, self.gc_gen_major_start_kb - self.gc_count_kb);
            const limit = added * @as(f64, @floatFromInt(@max(self.gc_gen_majorminor, 0))) / 100.0;
            if (reclaimed > limit) {
                try self.gcMakeAllOld();
                return;
            }
            self.gc_gen_major_base_kb = self.gc_count_kb;
            self.gc_gen_major_start_kb = self.gc_count_kb;
        }
        self.gcScheduleNextAutomaticCycle();
    }

    /// Mark all GC roots that live directly on the Vm struct and are NOT
    /// reachable through Lua-value traversal from global_env/frames.
    fn gcMarkVmRoots(self: *Vm) DispatchError!void {
        // Type metatables: every string/number/boolean/etc. value's metamethod
        // lookup routes through these.
        try self.gcMarkValue(.{ .Table = self.string_metatable });
        const optional_mts = [_]?*Table{
            self.number_metatable,
            self.boolean_metatable,
            self.nil_metatable,
            self.function_metatable,
            self.thread_metatable,
            self.file_metatable,
        };
        for (optional_mts) |mt| {
            if (mt) |t| try self.gcMarkValue(.{ .Table = t });
        }
        if (self.debug_registry) |t| try self.gcMarkValue(.{ .Table = t });

        // Thread handles held by the VM.
        const optional_threads = [_]?*Thread{
            self.main_thread,
            self.current_thread,
            self.forced_close_thread,
        };
        for (optional_threads) |oth| {
            if (oth) |th| try self.gcMarkValue(.{ .Thread = th });
        }

        // Pinned source strings from load(string) — compiled Proto lexemes
        // reference their bytes, so they must survive sweep.
        for (self.pinned_source_strings.items) |s| {
            if (gcIsWhite(s.gc_marked)) {
                gcSetBlack(&s.gc_marked);
                self.gc_mark_epoch += 1;
            }
        }

        // Bytecode long constants loaded through `internStrAll` are
        // GC-managed strings deduplicated in this cache. The cache is a VM
        // ownership root, like PUC's Proto constant table: while the cache has
        // an entry, sweep must not free the pointed LuaString.
        var lsc_it = self.long_string_cache.iterator();
        while (lsc_it.next()) |entry| {
            const s = entry.value_ptr.*;
            if (gcIsWhite(s.gc_marked)) {
                gcSetBlack(&s.gc_marked);
                self.gc_mark_epoch += 1;
            }
        }

        // Temporary GC roots (Handle API): Values held in Zig locals by
        // builtins. These are the analog of PUC Lua's L->stack temporaries.
        for (self.gc_temp_roots.items) |rv| {
            try self.gcMarkValue(rv);
        }

        // Debug hook transfer values: a slice into frame registers set up for
        // an about-to-happen call/return event. These registers may NOT be in
        // live_regs[pc] (they model the transition, not the current instruction),
        // so we mark them explicitly to protect them during sweep inside hooks.
        if (self.debug_transfer_values) |dtv| {
            for (dtv) |v| {
                try self.gcMarkValue(v);
            }
        }

        // Error object: self.err_obj may hold a GC-managed Value (String, Table)
        // that is not reachable from any other root between error raise and pcall
        // catch. self.err (the bytes) borrows from the same LuaString, so marking
        // err_obj keeps the bytes valid too.
        if (self.err_has_obj) {
            try self.gcMarkValue(self.err_obj);
        }

        // c_error_value: object thrown by lua_error, held between _longjmp and
        // callCFunction folding it into err_obj. Traced here so a GC cycle in
        // that window cannot collect it. (Same invariant as err_obj above.)
        if (self.c_error_value) |v| {
            try self.gcMarkValue(v);
        }

        // A coroutine switch request exists only while the trampoline crosses
        // from one parked bytecode runtime to another, but its copied arguments
        // are still ordinary Lua roots during that interval.
        if (self.bytecode_coroutine_switch_request) |request| {
            try self.gcMarkValue(.{ .Thread = request.caller });
            try self.gcMarkValue(.{ .Thread = request.target });
            for (request.args) |value| {
                try self.gcMarkValue(value);
            }
        }

        // gmatch iterator state: holds *LuaString pointers for the subject string
        // and pattern, kept alive between iterator calls.
        if (self.gmatch_state) |gs| {
            if (gcIsWhite(gs.s.gc_marked)) {
                gcSetBlack(&gs.s.gc_marked);
                self.gc_mark_epoch += 1;
            }
            if (gcIsWhite(gs.p.gc_marked)) {
                gcSetBlack(&gs.p.gc_marked);
                self.gc_mark_epoch += 1;
            }
        }
    }

    fn gcDeadenUnmarkedStringKeys(self: *Vm) void {
        var it = self.gc_marked_tables.iterator();
        while (it.next()) |entry| {
            const tbl = entry.key_ptr.*;
            // Only tables that survived marking (not white) can have live
            // entries worth scanning for dead string keys.
            if (gcIsWhite(tbl.gc_marked)) continue;
            // Check if this is a weak-key table — dead string keys in
            // weak-key tables must be deadened even with non-Nil values,
            // because the key can be collected while the value survives.
            const mode = self.gcWeakMode(tbl);
            for (tbl.hash) |*node| {
                if (node.key_tt != .string) continue;
                // Strong tables: only deaden logically deleted entries (Nil value).
                // Weak-key tables: deaden any unmarked string key.
                if (!mode.weak_k and node.value != .Nil) continue;
                // Use gcIsDead (checks for OLD white bit) instead of gcIsWhite
                // (which matches BOTH old and new white). After the white flip,
                // only strings with the OTHER white bit are truly dead. Strings
                // with the NEW current white were created during this cycle and
                // are alive — they must NOT be deadened.
                if (!gcIsDead(node.key_val.string.gc_marked, self.gc_current_white)) continue;
                ltable.deadenStringKey(node);
            }
        }
    }

    fn gcMarkBytecodeProto(self: *Vm, proto: *const bc.Proto) DispatchError!void {
        for (proto.k) |k| {
            if (k == .str) {
                if (gcIsWhite(k.str.gc_marked)) {
                    gcSetBlack(&k.str.gc_marked);
                    self.gc_mark_epoch += 1;
                }
            }
        }
        for (proto.p) |child| try self.gcMarkBytecodeProto(child);
    }

    /// Queue a value for incremental propagation. Strings have no outgoing
    /// edges, so they can be marked immediately without consuming a gray slot.
    /// A3: now routes through gcQueueScanObject (the GcObject-generic path)
    /// instead of a per-type switch on Value. The gc_mark_epoch bump tracks
    /// whether any white→gray/black transition occurred during this call,
    /// which gcPropagateEphemerons uses as its fixpoint convergence signal.
    fn gcMarkValue(self: *Vm, v: Value) DispatchError!void {
        if (self.gc_minor_cycle) return self.gcMarkMinorValue(v);
        const obj = GcObject.fromValue(v) orelse return;
        // Only bump the epoch when a white object is actually marked —
        // gcPropagateEphemerons uses epoch growth as its fixpoint signal.
        const p = gcPtr(obj);
        const was_white = gcIsWhite(p.marked.*);
        try self.gcQueueScanObject(obj);
        if (was_white) self.gc_mark_epoch += 1;
    }

    /// Propagate exactly one gray object. Child references are appended to the
    /// persistent gray list and will be processed by later work units.
    fn gcPropagateOne(self: *Vm) DispatchError!bool {
        const cur = self.gc_gray.pop() orelse return false;
        if (self.gc_minor_cycle) {
            self.gc_gen_last_minor_visited += 1;
            // A3: cur is now GcObject; read age through gcPtr.
            const age = gcPtr(cur).age.*;
            if (age.isOld()) self.gc_gen_last_minor_old_visited += 1;
        }
        switch (cur) {
            .table => |tbl| {
                // Record this table as marked during the current cycle so
                // gcDeadenUnmarkedStringKeys can iterate only marked tables
                // (O(marked)) instead of all gc_objects (O(total)). The
                // HashMap dedupes via put — repeated references to the same
                // table are a no-op.
                try self.gc_marked_tables.put(self.alloc, tbl, {});
                if (tbl.metatable) |mt| try self.gcMarkValue(.{ .Table = mt });

                const mode = self.gcWeakMode(tbl);
                if (mode.weak_k or mode.weak_v) {
                    // De-dupe weak tables list.
                    var seen = false;
                    for (self.gc_weak_tables.items) |t| {
                        if (t == tbl) {
                            seen = true;
                            break;
                        }
                    }
                    if (!seen) try self.gc_weak_tables.append(self.alloc, tbl);
                }

                // Array part: keys are ints (non-collectable), so there is
                // no key-liveness condition. String values are always marked
                // (strings are values, not collectable references — sweeping
                // a string still referenced by a table entry would UAF).
                // Table/Closure/Thread values marked only in strong tables;
                // weak values are pruned later by gcPruneWeakValues.
                for (tbl.array) |v0| {
                    if (v0 == .String) {
                        try self.gcMarkValue(v0);
                    } else if (!mode.weak_v) {
                        if (GcObject.fromValue(v0) != null) try self.gcMarkValue(v0);
                    }
                }
                // Hash part: mark strong keys and strong values INDEPENDENTLY.
                //   - strong key (!weak_k): always mark (a weak-VALUE table must
                //     still mark its keys so `a[t]=t` survives pruning).
                //   - strong value (!weak_v AND !weak_k): mark. For weak-KEY
                //     tables values are ephemerons (alive iff key alive) and
                //     are resolved by gcPropagateEphemerons, not marked here.
                // Unified hash part: keys are real Values now (Table/Closure/
                // Thread/Int/String/Bool/Num), not the old tagged PtrKey, so
                // we mark them through the same switch as the value.
                for (tbl.hash) |*node| {
                    if (node.key_tt == .empty or node.key_tt == .dead) continue; // empty slot or dead key
                    if (node.value == .Nil) continue; // logically deleted
                    // Mark string keys even in weak-key tables — hash nodes
                    // retain key references and keyEq dereferences strings,
                    // so sweeping a live string key would cause UAF. Deleted
                    // string keys are converted to dead keys before string
                    // sweep, mirroring PUC's DEADKEY transition.
                    const k = node.getKey();
                    if (k == .String) {
                        try self.gcMarkValue(k);
                    } else if (!mode.weak_k) {
                        if (GcObject.fromValue(k) != null) try self.gcMarkValue(k);
                    }
                    // Mark values: strings are always marked (they don't
                    // participate in ephemeron resolution). Table/Closure/
                    // Thread values are marked only in strong tables;
                    // weak-key tables resolve them via gcPropagateEphemerons.
                    const val = node.value;
                    if (val == .String) {
                        try self.gcMarkValue(val);
                    } else if (!mode.weak_v and !mode.weak_k) {
                        if (GcObject.fromValue(val) != null) try self.gcMarkValue(val);
                    }
                }
            },
            .closure => |cl| {
                if (cl.proto) |proto| try self.gcMarkBytecodeProto(proto);
                for (cl.upvalues) |cell| {
                    try self.gcQueueScanCell(cell);
                }
                if (cl.env_override) |env| try self.gcMarkValue(env);
            },
            .thread => |th| {
                if (GcObject.fromValue(th.callee) != null) {
                    try self.gcMarkValue(th.callee);
                }
                if (th.debug_hook.func) |hv| {
                    if (GcObject.fromValue(hv) != null) {
                        try self.gcMarkValue(hv);
                    }
                }
                if (th.yielded) |ys| {
                    for (ys) |yv| {
                        if (GcObject.fromValue(yv) != null) {
                            try self.gcMarkValue(yv);
                        }
                    }
                }
                for (th.wrap_yields.items) |item| {
                    for (item.values) |yv| {
                        if (GcObject.fromValue(yv) != null) {
                            try self.gcMarkValue(yv);
                        }
                    }
                }
                if (th.wrap_final_values) |vals| {
                    for (vals) |yv| {
                        if (GcObject.fromValue(yv) != null) {
                            try self.gcMarkValue(yv);
                        }
                    }
                }
                if (th.wrap_repeat_closure) |cl| {
                    try self.gcMarkValue(.{ .Closure = cl });
                }
                if (th.dofile_entry_closure) |cl| {
                    try self.gcMarkValue(.{ .Closure = cl });
                }
                if (th.resume_inbox) |vals| {
                    for (vals) |yv| {
                        if (GcObject.fromValue(yv) != null) {
                            try self.gcMarkValue(yv);
                        }
                    }
                }
                if (th.tail_resume_inbox) |vals| {
                    for (vals) |yv| {
                        if (GcObject.fromValue(yv) != null) {
                            try self.gcMarkValue(yv);
                        }
                    }
                }

                // Inactive coroutines own their complete execution storage.
                // Mark it exactly like the VM-active runtime above. Active
                // threads have these parked fields empty and are covered by
                // the regular Thread.call_frames root walk.
                //
                // P15.34b: Walk per-frame live registers using live_reg_top[pc]
                // (our equivalent of PUC's L->top boundary), NOT the entire
                // bytecode_stack as a flat array. The flat scan dereferences
                // stale values in uninitialized register windows — SIGSEGV on
                // coroutine.lua/cstack.lua. Each RuntimeFrame knows its own
                // `regs` slice and `pc`, so we can bound the scan precisely.
                for (0..th.call_frames.len()) |cf_i| {
                    const exec_fr = th.call_frames.getConstPtr(cf_i);
                    // For the VM-active thread, th.bytecode_stack is empty
                    // (stack is in self.bc_stack); for inactive coroutines,
                    // th.bytecode_stack holds their stack. Compute the correct
                    // stack once for both regs and varargs scans below.
                    const stack = if (th.bytecode_stack.len > 0) th.bytecode_stack else self.bc_stack;
                    // Bytecode frames live ONLY in th.call_frames. Scan
                    // regs/boxed/callee/env_override.
                    if (exec_fr.proto) |proto| {
                        try self.gcMarkBytecodeProto(proto);
                        // Use the thread's own bytecode_stack (not exec_fr.regs)
                        // because GC finalizers may have realloc'd the stack.
                        const regs = stack[exec_fr.base .. exec_fr.base + exec_fr.regs.len];
                        const live_top: usize = if (exec_fr.pc < proto.live_reg_top.len)
                            @min(proto.live_reg_top[exec_fr.pc], regs.len)
                        else
                            regs.len;
                        for (regs[0..live_top]) |yv| {
                            if (GcObject.fromValue(yv) != null) {
                                try self.gcMarkValue(yv);
                            }
                        }
                    }
                    if (GcObject.fromValue(exec_fr.callee) != null) {
                        try self.gcMarkValue(exec_fr.callee);
                    }
                    // PUC model: hidden varargs at [func_slot-nextraargs..func_slot].
                    if (exec_fr.proto != null and exec_fr.nextraargs != 0) {
                        // Use the same `stack` variable as the regs scan above:
                        // for the VM-active thread, bytecode_stack is empty
                        // (moved to self.bc_stack); for parked coroutines,
                        // bytecode_stack holds their stack.
                        const va = stack[exec_fr.func_slot - exec_fr.nextraargs .. exec_fr.func_slot];
                        for (va) |yv| {
                            if (GcObject.fromValue(yv) != null) {
                                try self.gcMarkValue(yv);
                            }
                        }
                    } else {
                        for (exec_fr.varargs) |yv| {
                            if (GcObject.fromValue(yv) != null) {
                                try self.gcMarkValue(yv);
                            }
                        }
                    }
                    for (exec_fr.upvalues) |cell| {
                        try self.gcQueueScanCell(cell);
                    }
                    // P15.40b-full: Scan boxed cells (TBC registers and open upvalues).
                    for (exec_fr.boxed) |maybe_cell| {
                        if (maybe_cell) |cell| {
                            try self.gcQueueScanCell(cell);
                        }
                    }
                    if (exec_fr.env_override) |env_v| {
                        if (GcObject.fromValue(env_v) != null) {
                            try self.gcMarkValue(env_v);
                        }
                    }
                    if (exec_fr.pending_call.get()) |pending| {
                        if (GcObject.fromValue(pending.callee) != null) {
                            try self.gcMarkValue(pending.callee);
                        }
                        switch (pending.completion) {
                            .concat => |cont| {
                                if (GcObject.fromValue(cont.acc) != null) {
                                    try self.gcMarkValue(cont.acc);
                                }
                                for (cont.values) |value| {
                                    if (GcObject.fromValue(value) != null) {
                                        try self.gcMarkValue(value);
                                    }
                                }
                            },
                            .gsub => |cont| {
                                const roots = [_]Value{ cont.subject, cont.pattern, cont.replacement };
                                for (roots) |value| {
                                    if (GcObject.fromValue(value) != null) {
                                        try self.gcMarkValue(value);
                                    }
                                }
                            },
                            .close => |cont| {
                                if (cont.current_err) |value| {
                                    if (GcObject.fromValue(value) != null) {
                                        try self.gcMarkValue(value);
                                    }
                                }
                                switch (cont.post) {
                                    .return_frame => |values| for (values) |value| {
                                        if (GcObject.fromValue(value) != null) {
                                            try self.gcMarkValue(value);
                                        }
                                    },
                                    else => {},
                                }
                            },
                            .hook => |cont| {
                                // While a hook frame is active the parent's
                                // RuntimeFrame.callee is temporarily replaced
                                // by the event callee. The real parent closure
                                // lives only in this continuation until the
                                // hook completes, so it is an explicit GC root.
                                const saved_parent = cont.saved_parent_callee;
                                if (GcObject.fromValue(saved_parent) != null) {
                                    try self.gcMarkValue(saved_parent);
                                }
                                for (cont.transfer) |value| {
                                    if (GcObject.fromValue(value) != null) {
                                        try self.gcMarkValue(value);
                                    }
                                }
                                switch (cont.post) {
                                    .store_results => |state| for (state.values) |value| {
                                        if (GcObject.fromValue(value) != null) {
                                            try self.gcMarkValue(value);
                                        }
                                    },
                                    .return_frame => |values| for (values) |value| {
                                        if (GcObject.fromValue(value) != null) {
                                            try self.gcMarkValue(value);
                                        }
                                    },
                                    else => {},
                                }
                            },
                            .coroutine_resume => |cont| {
                                try self.gcMarkValue(.{ .Thread = cont.target });
                                const saved_error = cont.saved_error.err_obj;
                                if (GcObject.fromValue(saved_error) != null) {
                                    try self.gcMarkValue(saved_error);
                                }
                            },
                            else => {},
                        }
                        if (pending.protection) |protection| {
                            const handler = protection.handler;
                            if (GcObject.fromValue(handler) != null) {
                                try self.gcMarkValue(handler);
                            }
                            const saved_error = protection.saved_error.err_obj;
                            if (GcObject.fromValue(saved_error) != null) {
                                try self.gcMarkValue(saved_error);
                            }
                        }
                    }
                }
                for (th.bytecode_unwinds.items) |unwind| {
                    const value = unwind.error_value;
                    if (GcObject.fromValue(value) != null) {
                        try self.gcMarkValue(value);
                    }
                }
            },
            .string => {}, // strings go straight to black in gcQueueScanObject; no children
            .cell => {
                // Closed cells are set black directly in gcQueueScanCell
                // (PUC reallymarkobject, lgc.c:347-354) and never enter
                // gc_gray. PUC propagatemark (lgc.c:727-740) has no
                // LUA_VUPVAL case. This arm exists for switch
                // exhaustiveness only.
            },
            .userdata => |u| {
                // PUC traverseudata (lgc.c:631-638): mark the metatable,
                // then mark each uservalue. The binary payload is opaque to
                // the GC (it never contains Lua references), so we skip it.
                if (u.metatable) |mt| try self.gcMarkValue(.{ .Table = mt });
                for (u.uservalues) |uv| try self.gcMarkValue(uv);
            },
        }
        // PUC propagatemark ends with gray2black(o): the object is fully
        // traversed, all children marked, so it becomes black.
        switch (cur) {
            .table => |t| gcSetBlack(&t.gc_marked),
            .closure => |c| gcSetBlack(&c.gc_marked),
            .thread => |th| gcSetBlack(&th.gc_marked),
            .string => {}, // already set black in gcQueueScanObject
            .cell => |cell| gcSetBlack(&cell.gc_marked),
            .userdata => |u| gcSetBlack(&u.gc_marked),
        }
        return true;
    }

    fn gcPropagateEphemerons(
        self: *Vm,
        weak_tables: *std.ArrayListUnmanaged(*Table),
    ) DispatchError!void {
        // Ephemeron propagation is a fixpoint: marking a value can make more
        // keys reachable only after that value's gray graph has been scanned.
        // Drain the persistent gray queue after every pass before deciding
        // whether another pass is necessary.
        //
        // Convergence signal: gc_mark_epoch is bumped whenever any white
        // object transitions to gray/black during a pass. If a full pass +
        // drainGray does not bump the epoch, no new objects were marked and
        // the fixpoint has settled. This is the per-object-bit replacement
        // for the old HashSet `.count()` growth check; PUC achieves the same
        // effect via its gray-list-driven `atomic` re-entry.
        while (true) {
            const epoch_before = self.gc_mark_epoch;

            var idx: usize = 0;
            while (idx < weak_tables.items.len) : (idx += 1) {
                const tbl = weak_tables.items[idx];
                const mode = self.gcWeakMode(tbl);
                if (!(mode.weak_k and !mode.weak_v)) continue;

                for (tbl.hash) |*node| {
                    if (node.key_tt == .empty or node.key_tt == .dead or node.value == .Nil) continue;
                    const key_marked = switch (node.key_tt) {
                        .table => blk: {
                            const table = node.key_val.table;
                            break :blk (self.gc_minor_cycle and !gcMinorCandidate(table.gc_age)) or !gcIsWhite(table.gc_marked);
                        },
                        .closure => blk: {
                            const closure = node.key_val.closure;
                            break :blk (self.gc_minor_cycle and !gcMinorCandidate(closure.gc_age)) or !gcIsWhite(closure.gc_marked);
                        },
                        .thread => blk: {
                            const thread = node.key_val.thread;
                            break :blk (self.gc_minor_cycle and !gcMinorCandidate(thread.gc_age)) or !gcIsWhite(thread.gc_marked);
                        },
                        else => true,
                    };
                    if (key_marked) try self.gcMarkValue(node.value);
                }
            }

            try self.gcDrainGray();
            if (self.gc_mark_epoch == epoch_before) break;
        }
    }

    fn gcPruneWeakValues(
        self: *Vm,
        weak_tbls: []const *Table,
    ) DispatchError!void {
        for (weak_tbls) |tbl| {
            const mode = self.gcWeakMode(tbl);
            if (!mode.weak_v) continue;
            // PUC iscleared (lgc.c:223): a value is cleared if it is white
            // (unmarked). For table/closure/thread, we use gc*Dead which
            // also checks age in minor cycles (though weak pruning only
            // runs in full cycles). For userdata, gcIsWhite matches PUC
            // iscleared exactly. No FINALIZEDBIT check for values — only
            // keys can be kept alive by finalization.

            // Array part: clear entries whose value is white (unmarked).
            for (tbl.array, 0..) |v, i| {
                const drop = switch (v) {
                    .Table => |t| self.gcTableDead(t),
                    .Closure => |cl| self.gcClosureDead(cl),
                    .Thread => |th| self.gcThreadDead(th),
                    .Userdata => |ud| self.gcUserdataDead(ud),
                    else => false,
                };
                if (drop) tbl.array[i] = .Nil;
            }

            // Hash part: drop entries whose value is white (unmarked).
            for (tbl.hash) |*node| {
                if (node.key_tt == .empty or node.key_tt == .dead) continue;
                if (node.value == .Nil) continue;
                const v = node.value;
                const drop = switch (v) {
                    .Table => |t| self.gcTableDead(t),
                    .Closure => |cl| self.gcClosureDead(cl),
                    .Thread => |th| self.gcThreadDead(th),
                    .Userdata => |ud| self.gcUserdataDead(ud),
                    else => false,
                };
                if (drop) node.value = .Nil;
            }
        }
    }

    fn gcPruneWeakKeys(
        self: *Vm,
        weak_tbls: []const *Table,
    ) DispatchError!void {
        for (weak_tbls) |tbl| {
            const mode = self.gcWeakMode(tbl);
            if (!mode.weak_k) continue;

            for (tbl.hash) |*node| {
                if (node.key_tt == .empty or node.key_tt == .dead) continue;
                if (node.value == .Nil) continue;
                // Drop entries whose collectable key is no longer reachable
                // (dead AND not pending finalization). FINALIZEDBIT on the
                // key object means it is reachable from a to-be-finalized
                // object and must survive this cycle.
                // For table/closure/thread, we use gc*Dead (checks OTHER
                // white bit + age). For userdata, we use gcIsWhite (checks
                // ANY white bit, matching PUC iscleared) because userdata
                // created in the current cycle with the current white bit
                // should be pruned from weak tables if unmarked.
                const drop = switch (node.key_tt) {
                    .table => blk: {
                        const t = node.key_val.table;
                        break :blk self.gcTableDead(t) and
                            (t.gc_marked & FINALIZEDBIT) == 0;
                    },
                    .closure => blk: {
                        const cl = node.key_val.closure;
                        break :blk self.gcClosureDead(cl) and
                            (cl.gc_marked & FINALIZEDBIT) == 0;
                    },
                    .thread => blk: {
                        const th = node.key_val.thread;
                        break :blk self.gcThreadDead(th) and
                            (th.gc_marked & FINALIZEDBIT) == 0;
                    },
                    .userdata => blk: {
                        const ud = node.key_val.userdata;
                        break :blk self.gcUserdataDead(ud) and
                            (ud.gc_marked & FINALIZEDBIT) == 0;
                    },
                    else => false,
                };
                if (drop) node.value = .Nil;
            }
        }
    }

    fn gcCollectFinalizables(self: *Vm) DispatchError![]GcObject {
        var to_finalize = std.ArrayListUnmanaged(GcObject).empty;
        var it = self.finalizables.iterator();
        while (it.next()) |entry| {
            const obj = entry.key_ptr.*;
            const p = gcPtr(obj);
            if (self.gc_minor_cycle and !gcMinorCandidate(p.age.*)) continue;
            // PUC finalize: skip objects already finalized (FINALIZEDBIT set).
            // They will be swept in the sweep phase instead.
            if ((p.marked.* & FINALIZEDBIT) != 0) continue;
            // After atomic-phase drain, all reachable objects are black.
            // A white object here is unreachable — queue it for __gc.
            if (gcIsWhite(p.marked.*)) {
                try to_finalize.append(self.alloc, obj);
            }
        }
        return to_finalize.toOwnedSlice(self.alloc);
    }

    fn gcMarkFinalizerReach(
        self: *Vm,
        objs: []const GcObject,
    ) DispatchError!void {
        for (objs) |obj| {
            if (obj.toValue()) |v| {
                try self.gcMarkValueFinalizerReach(v);
            }
        }
    }

    fn gcMarkValueFinalizerReach(self: *Vm, v: Value) DispatchError!void {
        switch (v) {
            .Table => |t| try self.gcMarkTableFinalizerReach(t),
            .Userdata => |ud| {
                // PUC markfinalizer: mark the userdata black (keep it alive
                // for finalization) and set FINALIZEDBIT. The bit serves as
                // the visited-flag for finalizer-reach marking (preventing
                // infinite recursion) and tells gcPruneWeakKeys that this
                // key is pending finalization (must survive this cycle).
                if ((ud.gc_marked & FINALIZEDBIT) != 0) return;
                ud.gc_marked |= FINALIZEDBIT;
                if (gcIsWhite(ud.gc_marked)) {
                    gcSetBlack(&ud.gc_marked);
                    self.gc_mark_epoch += 1;
                }
                // Also mark the metatable so __gc is reachable.
                if (ud.metatable) |mt| try self.gcMarkValueFinalizerReach(.{ .Table = mt });
                // Mark uservalues so they survive until __gc runs.
                for (ud.uservalues) |uv| try self.gcMarkValueFinalizerReach(uv);
            },
            .Closure => |cl| try self.gcMarkClosureFinalizerReach(cl),
            .Thread => |th| try self.gcMarkThreadFinalizerReach(th),
            .String => |str| if (gcIsWhite(str.gc_marked)) {
                gcSetBlack(&str.gc_marked);
                self.gc_mark_epoch += 1;
            },
            else => {},
        }
    }

    fn gcMarkClosureFinalizerReach(self: *Vm, cl: *Closure) DispatchError!void {
        // FINALIZEDBIT serves as the visited-flag for finalizer-reach marking,
        // exactly as PUC uses `testbit(o, FINALIZEDBIT)` in markfinalizer.
        if ((cl.gc_marked & FINALIZEDBIT) != 0) return;
        // Debug: check if closure is valid
        if (cl.gc_index >= self.gc_objects.items.len or
            self.gc_objects.items[cl.gc_index] != .closure or
            self.gc_objects.items[cl.gc_index].closure != cl)
        {
            return;
        }
        cl.gc_marked |= FINALIZEDBIT;
        // PUC markfinalizer: mark the object black (keep it alive for
        // finalization). Without this, the closure stays white and is
        // swept (freed) — causing use-after-free when its upvalues are
        // later traversed by another finalizable object.
        if (gcIsWhite(cl.gc_marked)) {
            gcSetBlack(&cl.gc_marked);
            self.gc_mark_epoch += 1;
        }
        for (cl.upvalues) |cell| {
            // PUC markfinalizer: mark upvalue cells and their values as
            // finalizer-reachable. Open upvalues kept gray (PUC model).
            if (gcIsWhite(cell.gc_marked)) {
                if (cell.isOpen()) {
                    gcSetGray(&cell.gc_marked);
                    try self.gc_grayagain.append(self.alloc, .{ .cell = cell });
                    // Open upvalue: value is on the thread's stack, scanned
                    // separately. Don't mark here.
                    continue;
                } else {
                    gcSetBlack(&cell.gc_marked);
                }
            }
            // Debug: log cell.value when it's a closure
            switch (cell.value) {
                else => {},
            }
            try self.gcMarkValueFinalizerReach(cell.value);
        }
    }

    fn gcMarkThreadFinalizerReach(self: *Vm, th: *Thread) DispatchError!void {
        if ((th.gc_marked & FINALIZEDBIT) != 0) return;
        th.gc_marked |= FINALIZEDBIT;
        // PUC markfinalizer: mark the object black (keep it alive).
        if (gcIsWhite(th.gc_marked)) {
            gcSetBlack(&th.gc_marked);
            self.gc_mark_epoch += 1;
        }
        try self.gcMarkValueFinalizerReach(th.callee);
        if (th.yielded) |ys| {
            for (ys) |yv| {
                try self.gcMarkValueFinalizerReach(yv);
            }
        }
        for (th.wrap_yields.items) |item| {
            for (item.values) |yv| {
                try self.gcMarkValueFinalizerReach(yv);
            }
        }
        if (th.wrap_final_values) |vals| {
            for (vals) |yv| {
                try self.gcMarkValueFinalizerReach(yv);
            }
        }
        if (th.wrap_repeat_closure) |cl| {
            try self.gcMarkValueFinalizerReach(.{ .Closure = cl });
        }
        if (th.dofile_entry_closure) |cl| {
            try self.gcMarkValueFinalizerReach(.{ .Closure = cl });
        }
        if (th.resume_inbox) |vals| {
            for (vals) |yv| {
                try self.gcMarkValueFinalizerReach(yv);
            }
        }
        if (th.tail_resume_inbox) |vals| {
            for (vals) |yv| {
                try self.gcMarkValueFinalizerReach(yv);
            }
        }
    }

    fn gcMarkTableFinalizerReach(self: *Vm, tbl: *Table) DispatchError!void {
        if ((tbl.gc_marked & FINALIZEDBIT) != 0) return;
        tbl.gc_marked |= FINALIZEDBIT;
        // PUC markfinalizer: mark the object black (keep it alive).
        if (gcIsWhite(tbl.gc_marked)) {
            gcSetBlack(&tbl.gc_marked);
            self.gc_mark_epoch += 1;
        }

        // Collect weak tables encountered during finalizer-reach traversal.
        // Previously done by iterating the gc_fin_tables HashSet afterwards;
        // now folded into the traversal to avoid the external side-table.
        const mode = self.gcWeakMode(tbl);
        if (mode.weak_k or mode.weak_v) {
            var seen = false;
            for (self.gc_fin_weak_tables.items) |t| {
                if (t == tbl) { seen = true; break; }
            }
            if (!seen) try self.gc_fin_weak_tables.append(self.alloc, tbl);
        }

        if (tbl.metatable) |mt| try self.gcMarkValueFinalizerReach(.{ .Table = mt });

        if (!mode.weak_v) {
            for (tbl.array) |vv| try self.gcMarkValueFinalizerReach(vv);
        }

        // Unified hash part: walk every live node. Same shape as gcMarkValue's
        // hash traversal — mark key (unless weak-k) and value (unless weak-v
        // and weak-k together, which makes the value an ephemeron).
        for (tbl.hash) |*node| {
            if (node.key_tt == .empty or node.key_tt == .dead) continue;
            if (node.value == .Nil) continue; // tombstone
            const k = node.getKey();
            const vv = node.value;
            if (!mode.weak_k) {
                try self.gcMarkValueFinalizerReach(k);
            }
            if (!mode.weak_v and !mode.weak_k) {
                try self.gcMarkValueFinalizerReach(vv);
            }
        }
    }

    fn gcFinalizeList(self: *Vm, to_finalize: []const GcObject) DispatchError!void {
        self.gc_finalizers_ran_count = to_finalize.len;
        const ordered = try self.alloc.dupe(GcObject, to_finalize);
        defer self.alloc.free(ordered);
        std.sort.block(GcObject, ordered, self, gcFinalizeLessThan);
        for (ordered) |obj| {
            _ = self.finalizables.remove(obj);
            // Get the metatable and __gc metamethod for this object type.
            const mt: ?*Table = switch (obj) {
                .table => |t| t.metatable,
                .userdata => |u| u.metatable,
                else => null,
            };
            const m = mt orelse continue;
            const gc = self.fasttm(m, .gc) orelse continue;
            // The self argument is the object being finalized.
            const self_val: Value = obj.toValue() orelse continue;
            const call_args = &[_]Value{self_val};
            _ = self.callFinalizer(gc, call_args) catch |e| switch (e) {
                // PUC lgc.c:988-991: errors in __gc finalizers are reported
                // through the warning channel via luaE_warnerror(L, "__gc"),
                // which produces "error in __gc (<error message>)". In @store
                // mode, this warning is saved in _WARN for the test to check.
                error.RuntimeError => {
                    const err_obj = self.protectedErrorValue();
                    const err_msg: []const u8 = switch (err_obj) {
                        .String => |s| s.bytes(),
                        else => "error object is not a string",
                    };
                    // Build "error in __gc (<msg>)" and pass to warn.
                    // PUC lstate.c:408-418 `luaE_warnerror` calls the warnf
                    // handler per piece ("error in ", where, " (", msg, ")").
                    // We build the full message and call `warnfHandler` once
                    // with tocont=false — equivalent output for both default
                    // and testC warnf (testC concatenates pieces into `buff`).
                    var warn_buf: std.ArrayListUnmanaged(u8) = .empty;
                    defer warn_buf.deinit(self.alloc);
                    warn_buf.appendSlice(self.alloc, "error in __gc (") catch return error.OutOfMemory;
                    warn_buf.appendSlice(self.alloc, err_msg) catch return error.OutOfMemory;
                    warn_buf.append(self.alloc, ')') catch return error.OutOfMemory;
                    self.warnfHandler(warn_buf.items, false) catch {};
                    self.err = null;
                    self.err_has_obj = false;
                    self.err_obj = .Nil;
                    continue;
                },
                else => return e,
            };
            // PUC udata2finalize (lgc.c:953): reset FINALIZEDBIT after
            // finalization. The object is "normal" again — in the next
            // cycle, if unreachable, it will be swept (freed).
            gcPtr(obj).marked.* &= ~FINALIZEDBIT;
        }
    }

    /// PUC finalization order: objects are prepended to 'finobj' (LIFO),
    /// then moved to 'tobefnz' preserving that order, and finalized from
    /// the beginning. So the most recently created finalizable object is
    /// finalized first. We use gc_seq (monotonic creation counter) descending.
    fn gcFinalizeLessThan(self: *Vm, lhs: GcObject, rhs: GcObject) bool {
        // For testC userdata rank (currently all objects return min rank,
        // so this is a no-op until Userdata rank support is added).
        const lr = self.testcFinalizeRankObj(lhs);
        const rr = self.testcFinalizeRankObj(rhs);
        if (lr != rr) return lr > rr;
        // Same rank: sort by gc_seq descending (LIFO creation order).
        // gc_seq is a monotonic counter set once at creation and never
        // changed, unlike gc_index which is corrupted by swapRemove.
        return gcPtr(lhs).seq.* > gcPtr(rhs).seq.*;
    }

    /// Rank helper for testC GC finalization ordering. Table-based userdata
    /// emulation has been removed — real Userdata and LightUserdata are not
    /// GcObject tables, so there is no table-ud ranking to do. All GcObject
    /// types return min (no special rank).
    fn testcFinalizeRankObj(_: *Vm, _: GcObject) i64 {
        return std.math.minInt(i64);
    }

    const TextCompileResult = union(enum) {
        closure: *Closure,
        diagnostic: []u8,
    };

    pub fn createBytecodeChunkClosure(self: *Vm, proto: *const bc.Proto) DispatchError!*Closure {
        const cells = try self.alloc.alloc(*Cell, proto.upvalues.len);
        for (cells) |*slot| {
            const cell = try self.alloc.create(Cell);
            cell.* = .{ .value = .Nil };
            try self.gcRegisterCell(cell);
            self.gcNoteAlloc(@sizeOf(Cell));
            slot.* = cell;
        }
        try self.testcChargeMemory(@sizeOf(Closure) + 64);
        const cl = try self.alloc.create(Closure);
        cl.* = .{
            .proto = proto,
            .upvalues = cells,
        };
        try self.gcRegisterClosure(cl);
        self.testc_obj_functions += 1;
        self.gcNoteAlloc(@sizeOf(Closure));
        return cl;
    }

    /// Shared compile pipeline used by both the Zig embedding API
    /// (`api.State.compileChunk`) and the C ABI shim (`c_api.compileChunk`).
    /// Parses and compiles a source chunk into a Closure `Value`. Returns
    /// `error.Syntax` on lex/parse/compile failure; callers map to their
    /// own error codes. Extracting this here eliminates two near-verbatim
    /// copies that had already drifted (api.zig returned `*Closure`
    /// instead of `Value`, causing a compile error).
    pub fn compileChunkValue(
        self: *Vm,
        bytes: []const u8,
        chunk_name: []const u8,
    ) !Value {
        const src: LuaSource = .{ .name = chunk_name, .bytes = bytes };
        var lex = LuaLexer.init(src);
        var p = LuaParser.init(&lex) catch return error.Syntax;
        var arena = lua_ast.AstArena.init(self.alloc);
        defer arena.deinit();
        const chunk = p.parseChunkAst(&arena) catch return error.Syntax;
        var cg_bc = lua_codegen_bc.Codegen.init(self.alloc, src.name, src.bytes);
        defer cg_bc.deinit();
        const proto = cg_bc.compileChunk(chunk) catch return error.Syntax;
        const cl = try self.createBytecodeChunkClosure(proto);
        // Set _ENV upvalue to the global environment, matching PUC's
        // lua_load behavior: the main chunk's first upvalue is _ENV = _G.
        // Without this, global lookups (GETTABUP on upvalue 0) return nil
        // because the _ENV cell is initialized to Nil by createBytecodeChunkClosure.
        try self.applyLoadEnv(cl, .{ .Table = self.global_env }, false);
        return Value{ .Closure = cl };
    }

    fn compileTextChunk(self: *Vm, source: LuaSource) DispatchError!TextCompileResult {
        var lex = LuaLexer.init(source);
        lex.global_reserved = self.testc_module_enabled;
        var p = LuaParser.init(&lex) catch {
            // Unified error formatting via Diag (PUC luaG_addinfo + near <token>).
            const diagnostic = try self.alloc.dupe(u8, lex.diagString());
            return .{ .diagnostic = @constCast(diagnostic) };
        };
        self.dynamic_ast_arena.resetRetainingCapacity();
        defer self.dynamic_ast_arena.resetRetainingCapacity();
        const chunk = p.parseChunkAst(&self.dynamic_ast_arena) catch {
            const diagnostic = try self.alloc.dupe(u8, p.diagString());
            return .{ .diagnostic = @constCast(diagnostic) };
        };

        if (self.dynamic_bytecode_compiler) |compile_bc| {
            const result = try compile_bc(self.alloc, source, chunk);
            return switch (result) {
                .proto => |proto| .{ .closure = try self.createBytecodeChunkClosure(proto) },
                .diagnostic => |diagnostic| .{ .diagnostic = diagnostic },
            };
        }

        // IR codegen fallback removed — bytecode compiler is always available.
        return self.fail("no bytecode compiler configured", .{});
    }

    fn builtinDofile(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        var entry_cl: ?*Closure = null;
        if (self.current_thread) |th| {
            if (th.callee == .Builtin and th.callee.Builtin == .dofile) {
                if (th.dofile_entry_closure) |cl| {
                    entry_cl = cl;
                }
            }
        }

        if (entry_cl == null) {
            const path = if (args.len > 0) switch (args[0]) {
                .String => |s| s.bytes(),
                else => return self.fail("dofile expects filename string", .{}),
            } else return self.fail("dofile expects filename string", .{});

            const source = LuaSource.loadFile(self.alloc, stdio.activeIo(), path) catch |e| return self.fail("dofile: cannot read '{s}': {s}", .{ path, @errorName(e) });

            const compiled = try self.compileTextChunk(source);
            const cl = switch (compiled) {
                .closure => |closure| closure,
                .diagnostic => |diagnostic| {
                    defer self.alloc.free(diagnostic);
                    return self.fail("{s}", .{diagnostic});
                },
            };
            try self.applyLoadEnv(cl, .{ .Table = self.global_env }, false);
            if (self.current_thread) |th| {
                if (th.callee == .Builtin and th.callee.Builtin == .dofile) {
                    th.dofile_entry_closure = cl;
                }
            }
            entry_cl = cl;
        }

        const cl = entry_cl.?;
        const ret = self.runClosure(cl, &.{}) catch |e| switch (e) {
            error.Yield => return error.Yield,
            else => return error.RuntimeError,
        };
        defer self.alloc.free(ret);
        const n = @min(outs.len, ret.len);
        for (0..n) |i| outs[i] = ret[i];
        self.last_builtin_out_count = ret.len;
    }

    const ChunkPrefix = struct {
        bytes: []const u8,
        had_shebang: bool = false,
    };

    fn stripChunkPrefix(bytes: []const u8, allow_shebang: bool) ChunkPrefix {
        var s = bytes;
        if (s.len >= 3 and s[0] == 0xEF and s[1] == 0xBB and s[2] == 0xBF) {
            s = s[3..];
        }
        if (allow_shebang and s.len > 0 and s[0] == '#') {
            var i: usize = 0;
            while (i < s.len and s[i] != '\n') : (i += 1) {}
            if (i < s.len) i += 1;
            s = s[i..];
            return .{ .bytes = s, .had_shebang = true };
        }
        return .{ .bytes = s };
    }

    fn builtinLoadfile(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        const path = if (args.len > 0) switch (args[0]) {
            .String => |s| s.bytes(),
            else => return self.fail("loadfile expects filename string", .{}),
        } else return self.fail("loadfile expects filename string", .{});

        const source = LuaSource.loadFile(self.alloc, stdio.activeIo(), path) catch |e| {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(try std.fmt.allocPrint(self.alloc, "loadfile: cannot read '{s}': {s}", .{ path, @errorName(e) })) };
            return;
        };
        var load_args: [4]Value = .{ .Nil, .Nil, .Nil, .Nil };
        load_args[0] = .{ .String = try self.internStr(source.bytes) };
        load_args[1] = .{ .String = try self.internStr(source.name) };
        var n: usize = 2;
        if (args.len > 1) {
            load_args[2] = args[1];
            n = 3;
        }
        if (args.len > 2) {
            load_args[3] = args[2];
            n = 4;
        }
        try self.builtinLoad(load_args[0..n], outs);
    }

    fn builtinStringDump(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("string.dump expects function", .{});
        const cl = switch (args[0]) {
            .Closure => |c| c,
            else => return self.fail("string.dump expects function", .{}),
        };
        const strip = if (args.len > 1) isTruthy(args[1]) else false;

        // PUC Lua's `luaU_dump` (ldump.c) serializes the Closure's Proto tree
        // into a binary chunk. When `strip` is set, it clones the Proto with
        // debug info removed first (so the original is untouched). We mirror
        // that: for `strip=true`, `cloneStrippedProto` produces a shallow
        // clone sharing the immutable `code`/`k` arrays but with empty
        // lineinfo/locvars/source_name. The clone is registered with the GC
        // so it survives until the dumped bytes are consumed by `load`.
        const dump_proto: ?*const bc.Proto = if (strip) blk: {
            var seen_bc = std.AutoHashMapUnmanaged(*const bc.Proto, *bc.Proto){};
            defer seen_bc.deinit(self.alloc);
            break :blk if (cl.proto) |proto|
                try self.cloneStrippedProto(proto, &seen_bc)
            else
                null;
        } else cl.proto;

        // Serialize the Proto tree via `DumpWriter.dumpChunk`. This writes the
        // 40-byte PUC Lua 5.5 header, the main function's upvalue count, then
        // the Proto body (source name, code, constants, upvalues, nested
        // protos, line info, locals). The result is a self-contained binary
        // chunk that `undump.UndumpReader.undumpChunk` can reconstruct.
        var writer = dump_mod.DumpWriter.init(self.alloc);
        defer writer.deinit();
        if (dump_proto) |proto| {
            try writer.dumpChunk(proto);
        } else {
            // C closures (no Proto) cannot be dumped. PUC Lua's `string.dump`
            // raises "unable to dump given function" for non-Lua functions.
            return self.fail("string.dump: unable to dump given function", .{});
        }
        const bytes = try writer.toOwnedSlice();
        // Intern the serialized bytes as a Lua string. The caller owns the
        // resulting string; `internStr` copies the bytes into a GC-managed
        // LuaString, so we free the temporary buffer.
        defer self.alloc.free(bytes);
        outs[0] = .{ .String = try self.internStr(bytes) };
    }

    fn defaultLoadEnv(self: *Vm, args: []const Value) Value {
        if (args.len >= 4) return args[3];
        return .{ .Table = self.global_env };
    }

    fn applyLoadEnv(self: *Vm, cl: *Closure, env_val: Value, force_first_on_missing: bool) DispatchError!void {
        const num_upvalues: usize = if (cl.proto) |proto| proto.upvalues.len else 0;
        if (num_upvalues == 0) {
            if (force_first_on_missing) try self.gcStoreClosureEnv(cl, env_val);
            return;
        }
        if (cl.upvalues.len < num_upvalues) {
            const cells = try self.alloc.alloc(*Cell, num_upvalues);
            var i: usize = 0;
            while (i < num_upvalues) : (i += 1) {
                const c = try self.alloc.create(Cell);
                c.* = .{ .value = .Nil };
                try self.gcRegisterCell(c);
                self.gcNoteAlloc(@sizeOf(Cell));
                cells[i] = c;
            }
            cl.upvalues = cells;
        }
        if (cl.proto) |proto| {
            for (proto.upvalues, 0..) |uv, i| {
                if (i >= cl.upvalues.len) break;
                if (std.mem.eql(u8, uv.name, "_ENV")) {
                    try self.gcStoreCellValue(cl.upvalues[i], env_val);
                    try self.gcStoreClosureEnv(cl, env_val);
                    return;
                }
            }
        }
        if (force_first_on_missing) {
            if (cl.upvalues.len > 0) try self.gcStoreCellValue(cl.upvalues[0], env_val);
            try self.gcStoreClosureEnv(cl, env_val);
        }
    }

    fn writeUIntBytes(out: *std.ArrayListUnmanaged(u8), alloc: std.mem.Allocator, v: u64, width: usize, little: bool) !void {
        if (little) {
            var i: usize = 0;
            while (i < width) : (i += 1) try out.append(alloc, @as(u8, @intCast((v >> @as(u6, @intCast(i * 8))) & 0xFF)));
        } else {
            var i: usize = 0;
            while (i < width) : (i += 1) {
                const shift = (width - 1 - i) * 8;
                try out.append(alloc, @as(u8, @intCast((v >> @as(u6, @intCast(shift))) & 0xFF)));
            }
        }
    }

    fn readUIntBytes(bytes: []const u8, pos: usize, width: usize, little: bool) u64 {
        var v: u64 = 0;
        if (little) {
            var i: usize = 0;
            while (i < width) : (i += 1) v |= (@as(u64, bytes[pos + i]) << @as(u6, @intCast(i * 8)));
        } else {
            var i: usize = 0;
            while (i < width) : (i += 1) {
                v = (v << 8) | bytes[pos + i];
            }
        }
        return v;
    }

    /// String interning callback for `undump.UndumpReader`. Interns the given
    /// bytes into the VM's string table and returns the resulting `*LuaString`
    /// as `*anyopaque`, so that `undump.zig` can stay free of a vm.zig import.
    /// This mirrors PUC Lua's `luaS_new` call in `lundump.c:loadString`, which
    /// interns each string constant during deserialization so the reconstructed
    /// Proto is immediately executable.
    pub fn undumpInternCallback(ctx: *anyopaque, bytes: []const u8) anyerror!*anyopaque {
        const v: *Vm = @ptrCast(@alignCast(ctx));
        // Use internStrAll (not internStr) so long strings (>40 bytes) are
        // deduplicated via long_string_cache. This ensures that identical
        // string constants in different protos share the same *LuaString
        // pointer, matching PUC's string table deduplication.
        const ls = try v.internStrAll(bytes);
        return @ptrCast(ls);
    }

    /// Fixed-buffer string interning callback. Used when the undump reader is
    /// in fixed-buffer mode (mode 'B'). For short strings (≤40 bytes), interns
    /// normally (copy + dedup). For long strings (>40 bytes), creates an
    /// external string (LSTRFIX variant) pointing directly into the source
    /// buffer, avoiding a copy. Mirrors PUC's `luaS_newextlstr(L, s, size, NULL, NULL)`.
    pub fn undumpFixedInternCallback(ctx: *anyopaque, bytes: []const u8) anyerror!*anyopaque {
        const v: *Vm = @ptrCast(@alignCast(ctx));
        if (bytes.len <= lua_string_max_short_len) {
            // Short strings are always interned (copied), matching PUC's
            // `luaS_newlstr` path in `loadString` for short strings.
            const ls = try v.internStrAll(bytes);
            return @ptrCast(ls);
        }
        // Long string: create an external string pointing into the source
        // buffer. falloc=null means LSTRFIX (no deallocation) — the caller
        // owns the buffer and keeps it alive via pinned_source_strings.
        const ls = try v.createExternalLuaString(bytes.ptr, bytes.len, null, null);
        return @ptrCast(ls);
    }

    /// Create a fresh Closure wrapping a deserialized Proto. The Closure owns
    /// its upvalue cells (initialized to Nil); the Proto is owned by the Closure
    /// and freed via GC when the Closure is collected. This is the load-side
    /// counterpart of `builtinStringDump`: dump serializes a Proto tree, undump
    /// reconstructs it, and this function wraps it in an executable Closure.
    fn closureFromProto(self: *Vm, proto: *bc.Proto) DispatchError!*Closure {
        try self.testcChargeMemory(@sizeOf(Closure) + 64);
        const cl = try self.alloc.create(Closure);
        self.testc_obj_functions += 1;
        const nups: usize = proto.upvalues.len;
        const cells = try self.alloc.alloc(*Cell, nups);
        for (0..nups) |i| {
            const c = try self.alloc.create(Cell);
            c.* = .{ .value = .Nil };
            try self.gcRegisterCell(c);
            self.gcNoteAlloc(@sizeOf(Cell));
            cells[i] = c;
        }
        cl.* = .{
            .proto = proto,
            .upvalues = cells,
            .env_override = null,
        };
        try self.gcRegisterClosure(cl);
        self.gcNoteAlloc(@sizeOf(Closure));
        return cl;
    }

    /// Pre-resolve constants for undumped protos. String constants were
    /// already VM-interned via `undumpInternCallback`, so we populate
    /// `resolved_values` directly and set `constants_resolved = true`.
    /// This prevents `resolveProtoConstants` from re-interning and freeing
    /// already-interned strings (which would corrupt the string table).
    pub fn preResolveUndumpedConstants(self: *Vm, proto: *bc.Proto) DispatchError!void {
        if (proto.constants_resolved) return;
        const vals = try self.alloc.alloc(Value, proto.k.len);
        for (proto.k, 0..) |c, i| {
            vals[i] = switch (c) {
                .nil => .Nil,
                .bool => |b| .{ .Bool = b },
                .int => |i64_val| .{ .Int = i64_val },
                .num_bits => |n| .{ .Num = @bitCast(n) },
                .str => |s| .{ .String = s },
            };
        }
        proto.resolved_values = vals;
        proto.constants_resolved = true;
        for (proto.p) |child| {
            try self.preResolveUndumpedConstants(@constCast(child));
        }
    }

    /// Duplicate all string fields in an undumped proto tree so the proto
    /// owns its strings (not borrowing from the binary buffer which may be
    /// GC'd). Recursively processes nested protos.
    pub fn cloneUndumpedStrings(self: *Vm, proto: *bc.Proto) DispatchError!void {
        // source_name and name
        if (proto.source_name.len > 0) {
            proto.source_name = try self.alloc.dupe(u8, proto.source_name);
        }
        if (proto.name.len > 0) {
            proto.name = try self.alloc.dupe(u8, proto.name);
        }
        // upvalue names — upvalues is []const, need mutable copy
        if (proto.upvalues.len > 0) {
            const uvs = try self.alloc.alloc(bc.Upvaldesc, proto.upvalues.len);
            for (proto.upvalues, 0..) |uv, i| {
                uvs[i] = .{
                    .instack = uv.instack,
                    .idx = uv.idx,
                    .is_const = uv.is_const,
                    .name = if (uv.name.len > 0) try self.alloc.dupe(u8, uv.name) else uv.name,
                };
            }
            proto.upvalues = uvs;
        }
        // locvar names — locvars is []const, need mutable copy
        if (proto.locvars.len > 0) {
            const lvs = try self.alloc.alloc(bc.LocVar, proto.locvars.len);
            for (proto.locvars, 0..) |lv, i| {
                lvs[i] = .{
                    .name = if (lv.name.len > 0) try self.alloc.dupe(u8, lv.name) else lv.name,
                    .reg = lv.reg,
                    .startpc = lv.startpc,
                    .endpc = lv.endpc,
                };
            }
            proto.locvars = lvs;
        }
        // recurse into nested protos
        for (proto.p) |child| {
            try self.cloneUndumpedStrings(@constCast(child));
        }
    }

    /// Clone a bytecode Proto while removing only debug metadata.
    ///
    /// PUC Lua's stripped chunks execute the exact same bytecode as the source
    /// function; stripping removes source names, line tables, local names, and
    /// upvalue names, but it must not switch execution to another backend.  The
    /// semantic arrays (`code` and constants) are immutable and can therefore be
    /// shared with the original Proto.  Child Proto nodes and the debug-bearing
    /// descriptor arrays are cloned recursively.
    pub fn cloneStrippedProto(
        self: *Vm,
        proto: *const bc.Proto,
        seen: *std.AutoHashMapUnmanaged(*const bc.Proto, *bc.Proto),
    ) DispatchError!*bc.Proto {
        if (seen.get(proto)) |existing| return existing;

        const cloned = try self.alloc.create(bc.Proto);
        try seen.put(self.alloc, proto, cloned);

        const children = try self.alloc.alloc(*bc.Proto, proto.p.len);
        for (proto.p, 0..) |child, i| {
            children[i] = try self.cloneStrippedProto(child, seen);
        }

        const upvalues = try self.alloc.alloc(bc.Upvaldesc, proto.upvalues.len);
        for (proto.upvalues, 0..) |uv, i| {
            upvalues[i] = .{
                .instack = uv.instack,
                .idx = uv.idx,
                .is_const = uv.is_const,
                .name = "",
            };
        }

        const locvars = try self.alloc.alloc(bc.LocVar, proto.locvars.len);
        for (proto.locvars, 0..) |local, i| {
            locvars[i] = .{
                .name = "",
                .reg = local.reg,
                .startpc = local.startpc,
                .endpc = local.endpc,
            };
        }

        cloned.* = .{
            .code = proto.code,
            .k = proto.k,
            .p = children,
            .upvalues = upvalues,
            .lineinfo = &.{},
            .locvars = locvars,
            .live_reg_top = proto.live_reg_top,
            .maxstacksize = proto.maxstacksize,
            .numparams = proto.numparams,
            .is_vararg = proto.is_vararg,
            .name = "",
            .source_name = "=?",
            .line_defined = proto.line_defined,
            .last_line_defined = proto.last_line_defined,
            .vararg_table_reg = proto.vararg_table_reg,
            // Share resolved_values and constants_resolved flag with the
            // original proto. The cloned proto borrows these slices — it
            // must NOT free them in deinit. Setting constants_resolved=true
            // prevents deinit from freeing strings in k (also borrowed).
            .constants_resolved = proto.constants_resolved,
            .resolved_values = proto.resolved_values,
        };
        return cloned;
    }

    fn builtinLoad(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        return self.builtinLoadEx(args, outs, false);
    }

    /// Extended load function. When `allow_fixed` is true, mode 'B' (uppercase
    /// binary-only) is accepted and enables fixed-buffer mode (PUC's C API
    /// `luaL_loadbufferx`). When false, 'B' is rejected with "invalid mode"
    /// (PUC's `getMode` in lbaselib.c, used by Lua's `load`/`loadfile`).
    fn builtinLoadEx(self: *Vm, args: []const Value, outs: []Value, allow_fixed: bool) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("load expects string or function", .{});
        var roots = self.gcTempRoots();
        defer roots.end();
        for (args) |arg| try roots.add(arg);
        const mode = if (args.len > 2) switch (args[2]) {
            .Nil => "bt",
            .String => |m| m.bytes(),
            else => return self.fail("load: mode must be string", .{}),
        } else "bt";
        // PUC's `luaB_load`/`luaB_loadfile` call `getMode` which rejects 'B'
        // (uppercase binary-only / fixed-buffer mode) with "invalid mode".
        // Only the C API (`luaL_loadbufferx`) supports 'B'. Since `builtinLoad`
        // is shared between Lua's `load` and testC's `loadstring`, we reject
        // 'B' here and have testC's `loadstring` call `builtinLoadEx(true)`.
        for (mode) |ch| {
            switch (ch) {
                'b', 't' => {},
                'B' => if (allow_fixed) {} else return self.fail("invalid mode", .{}),
                'T' => if (allow_fixed) {} else return self.fail("invalid mode", .{}),
                else => return self.fail("load: invalid mode", .{}),
            }
        }
        const allow_binary = if (allow_fixed) std.mem.indexOfAny(u8, mode, "bB") != null else std.mem.indexOfScalar(u8, mode, 'b') != null;
        const allow_text = if (allow_fixed) std.mem.indexOfAny(u8, mode, "tT") != null else std.mem.indexOfScalar(u8, mode, 't') != null;

        var source_owned: ?[]u8 = null;
        var prefixed_owned: ?[]u8 = null;
        const source_is_reader = args[0] != .String;
        const source_str: ?*LuaString = switch (args[0]) {
            .String => |x| x,
            else => null,
        };
        const s: []const u8 = switch (args[0]) {
            .String => |x| x.bytes(),
            else => blk: {
                var buf = std.ArrayList(u8).empty;
                defer buf.deinit(self.alloc);
                while (true) {
                    const resolved = self.resolveCallable(args[0], &.{}, null) catch {
                        outs[0] = .Nil;
                        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(self.errorString()) };
                        return;
                    };
                    defer if (resolved.owned_args) |owned| self.alloc.free(owned);

                    var piece: Value = .Nil;
                    switch (resolved.callee) {
                        .Builtin => |id| {
                            var out1 = [_]Value{.Nil};
                            self.callBuiltin(id, resolved.args, out1[0..]) catch {
                                outs[0] = .Nil;
                                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(self.errorString()) };
                                return;
                            };
                            piece = out1[0];
                        },
                        .Closure => |cl| {
                            const ret = self.runClosure(cl, resolved.args) catch {
                                outs[0] = .Nil;
                                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(self.errorString()) };
                                return;
                            };
                            defer self.alloc.free(ret);
                            piece = if (ret.len > 0) ret[0] else .Nil;
                        },
                        else => unreachable,
                    }
                    switch (piece) {
                        .Nil => break,
                        .String => |part| {
                            if (part.len == 0) break;
                            try buf.appendSlice(self.alloc, part.bytes());
                        },
                        else => {
                            outs[0] = .Nil;
                            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("reader function must return a string") };
                            return;
                        },
                    }
                }
                source_owned = try buf.toOwnedSlice(self.alloc);
                break :blk source_owned.?;
            },
        };
        const default_chunk_name: []const u8 = if (source_is_reader) "=(load)" else s;
        const chunk_name_hint = if (args.len > 1) switch (args[1]) {
            .Nil => default_chunk_name,
            .String => |nm| nm.bytes(),
            else => return self.fail("load: chunk name must be string", .{}),
        } else default_chunk_name;
        const allow_shebang = chunk_name_hint.len != 0 and chunk_name_hint[0] == '@';
        const prefix = stripChunkPrefix(s, allow_shebang);
        var chunk_bytes = prefix.bytes;
        if (prefix.had_shebang and !(chunk_bytes.len > 0 and chunk_bytes[0] == 0x1b)) {
            prefixed_owned = try self.alloc.alloc(u8, chunk_bytes.len + 1);
            prefixed_owned.?[0] = '\n';
            @memcpy(prefixed_owned.?[1..], chunk_bytes);
            chunk_bytes = prefixed_owned.?;
        }

        if (chunk_bytes.len > 0 and chunk_bytes[0] == 0x1b) {
            if (!allow_binary) {
                outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("attempt to load a binary chunk") };
                return;
            }
            // PUC Lua's `luaU_undump` (lundump.c) reconstructs the Proto tree
            // directly from the binary chunk. We mirror that: feed the bytes
            // to `UndumpReader.undumpChunk`, which validates the 40-byte header
            // and deserializes the body. String constants are interned into the
            // VM's string table during undump via `undumpInternCallback`, so the
            // reconstructed Proto is immediately executable (matching PUC's
            // `luaS_new` call in `loadString`).
            //
            // PUC's `f_parser` (ldo.c:1129-1131) sets `fixed=1` when the mode
            // contains 'B' (uppercase binary-only). In fixed mode, `luaU_undump`
            // points code/lineinfo/long-strings directly into the source buffer
            // instead of copying, keeping memory overhead minimal. The source
            // buffer must stay alive for the Proto's lifetime.
            const fixed = std.mem.indexOfScalar(u8, mode, 'B') != null;
            var reader = undump_mod.UndumpReader.init(self.alloc, chunk_bytes);
            reader.fixed = fixed;
            if (fixed) {
                reader.fixedInternFn = undumpFixedInternCallback;
            } else {
                reader.internFn = undumpInternCallback;
            }
            reader.internCtx = @ptrCast(self);
            const loaded_proto = reader.undumpChunk() catch |err| {
                outs[0] = .Nil;
                const msg: []const u8 = switch (err) {
                    error.TruncatedChunk => "truncated precompiled chunk",
                    error.BadHeader => "bad binary format (corrupted header)",
                    error.BadConstant => "bad binary format (corrupted constant)",
                    error.OutOfMemory => "out of memory",
                };
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(msg) };
                return;
            };
            if (fixed) {
                // In fixed-buffer mode, code/lineinfo/long-strings point into
                // the source buffer. Pin it so GC doesn't sweep it while the
                // Proto is alive. This mirrors PUC's assumption that the fixed
                // buffer remains valid for the Proto's lifetime.
                if (source_str) |x| try self.pinned_source_strings.append(self.alloc, x);
            } else {
                // The undumped proto's string fields (source_name, name, locvar
                // names, upvalue names) point into the binary buffer which may be
                // garbage-collected. Duplicate them so the proto owns its strings.
                try self.cloneUndumpedStrings(loaded_proto);
            }
            // String constants were already VM-interned during undump (via
            // undumpInternCallback or undumpFixedInternCallback). Pre-populate
            // resolved_values and mark constants_resolved=true so
            // resolveProtoConstants does NOT attempt to re-intern + free the
            // already-interned strings (which would corrupt the string table).
            try self.preResolveUndumpedConstants(loaded_proto);
            // Wrap the deserialized Proto in an executable Closure. The Closure
            // owns the Proto (freed via GC when the Closure is collected).
            const cl = try self.closureFromProto(loaded_proto);
            // lua_load always initializes the loaded main closure's first
            // upvalue with the selected environment. A stripped chunk has no
            // upvalue names, so name-based _ENV discovery is insufficient.
            try self.applyLoadEnv(cl, self.defaultLoadEnv(args), true);
            outs[0] = .{ .Closure = cl };
            if (outs.len > 1) outs[1] = .Nil;
            return;
        }
        if (!allow_text) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("attempt to load a text chunk") };
            return;
        }

        const chunk_name = if (args.len > 1) switch (args[1]) {
            .Nil => default_chunk_name,
            .String => |nm| nm.bytes(),
            else => return self.fail("load: chunk name must be string", .{}),
        } else default_chunk_name;
        // Pin the source LuaString as a GC root so it's not swept while the
        // compiled function's lexeme slices point into it. Binary chunks
        // don't need this — `cloneUndumpedStrings` makes the proto
        // self-contained. Same lifetime as PUC Lua's proto owning its source.
        if (source_str) |x| try self.pinned_source_strings.append(self.alloc, x);
        const source = LuaSource{ .name = chunk_name, .bytes = chunk_bytes };
        const compiled = try self.compileTextChunk(source);
        const cl = switch (compiled) {
            .closure => |closure| closure,
            .diagnostic => |diagnostic| {
                defer self.alloc.free(diagnostic);
                outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(diagnostic) };
                return;
            },
        };
        try self.applyLoadEnv(cl, self.defaultLoadEnv(args), true);
        outs[0] = .{ .Closure = cl };
        if (outs.len > 1) outs[1] = .Nil;
    }

    fn builtinRequire(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("require expects module name", .{});
        const name = switch (args[0]) {
            .String => |s| s.bytes(),
            else => return self.fail("require expects module name", .{}),
        };

        // PUC ll_require (loadlib.c:650-656): gets loaded/preload from
        // LUA_REGISTRYINDEX, NOT from the global `package` table. This means
        // require keeps working even if someone replaces `package = {}`.
        // We replicate this: canonical loaded/preload live in the registry.
        const reg = try self.ensureDebugRegistry();
        const loaded_v = self.getFieldOpt(reg, "_LOADED") orelse return self.fail("require: registry._LOADED missing", .{});
        const loaded_tbl = try self.expectTable(loaded_v);
        const preload_v = self.getFieldOpt(reg, "_PRELOAD") orelse return self.fail("require: registry._PRELOAD missing", .{});
        const preload_tbl = try self.expectTable(preload_v);

        // PUC ll_require checks package.searchers is a table.
        // Our search is hardcoded but we validate the field for compatibility.
        const package_v = self.getGlobal("package");
        if (package_v == .Table) {
            if (self.getFieldOpt(package_v.Table, "searchers")) |searchers| {
                if (searchers != .Table) {
                    return self.fail("'package.searchers' must be a table", .{});
                }
            }
        }

        // Built-in modules.
        if (std.mem.eql(u8, name, "debug")) {
            if (self.getFieldOpt(loaded_tbl, name)) |v| {
                if (v != .Nil) {
                    outs[0] = v;
                    return;
                }
            }

            const mod = try self.createDebugTable();
            const v: Value = .{ .Table = mod };
            try self.setField(loaded_tbl, name, v);
            outs[0] = v;
            return;
        }

        if (self.getFieldOpt(loaded_tbl, name)) |v| {
            // PUC ll_require (loadlib.c:655): uses lua_toboolean to check
            // if already loaded. This means false is treated as "not loaded"
            // — require will reload the module (matching PUC semantics).
            if (isTruthy(v)) {
                outs[0] = v;
                return;
            }
        }

        if (self.getFieldOpt(preload_tbl, name)) |loader| {
            const preload_str = try self.internStr(":preload:");
            switch (loader) {
                .Builtin => |id| {
                    var loader_args = [_]Value{ .{ .String = try self.internStr(name) }, .{ .String = preload_str } };
                    var loader_out: [2]Value = .{ .Nil, .Nil };
                    try self.callBuiltin(id, loader_args[0..], loader_out[0..]);
                    const v: Value = if (loader_out[0] != .Nil) loader_out[0] else .{ .Bool = true };
                    try self.setField(loaded_tbl, name, v);
                    outs[0] = v;
                    if (outs.len > 1) outs[1] = .{ .String = preload_str };
                    self.last_builtin_out_count = @min(outs.len, 2);
                    return;
                },
                .Closure => |cl| {
                    const loader_args = [_]Value{ .{ .String = try self.internStr(name) }, .{ .String = preload_str } };
                    const ret = try self.runClosure(cl, loader_args[0..]);
                    defer self.alloc.free(ret);
                    // PUC ll_require: if loader returned non-nil, set loaded.
                    // Then re-read loaded[name]; if nil, default to true.
                    if (ret.len > 0 and ret[0] != .Nil) {
                        try self.setField(loaded_tbl, name, ret[0]);
                    }
                    const final_val: Value = self.getFieldOpt(loaded_tbl, name) orelse v: {
                        try self.setField(loaded_tbl, name, .{ .Bool = true });
                        break :v .{ .Bool = true };
                    };
                    outs[0] = final_val;
                    if (outs.len > 1) outs[1] = .{ .String = preload_str };
                    self.last_builtin_out_count = @min(outs.len, 2);
                    return;
                },
                else => {},
            }
        }

        const pkg: ?*Table = if (package_v == .Table) package_v.Table else null;
        const path_val = if (pkg) |p| self.getFieldOpt(p, "path") else null;
        const path = switch (path_val orelse .Nil) {
            .String => |s| s,
            else => return self.fail("module '{s}' not found:\n\tno field package.preload['{s}']\n\tno file 'package.path'", .{ name, name }),
        };
        const cpath: []const u8 = if (pkg) |p| if (self.getFieldOpt(p, "cpath")) |cv| switch (cv) {
            .String => |s| s.bytes(),
            else => "",
        } else "" else "";

        var searchpath_out: [2]Value = .{ .Nil, .Nil };
        try self.builtinPackageSearchpath(&[_]Value{ .{ .String = try self.internStr(name) }, .{ .String = path } }, searchpath_out[0..]);
        if (searchpath_out[0] == .String) {
            const file_path = searchpath_out[0].String.bytes();
            var tmp: [2]Value = .{ .Nil, .Nil };
            try self.builtinLoadfile(&[_]Value{.{ .String = try self.internStr(file_path) }}, tmp[0..]);
            const cl = switch (tmp[0]) {
                .Closure => |c| c,
                else => {
                    // PUC ll_require (loadlib.c): when loadfile fails (syntax
                    // error or read error), format the message as:
                    //   "error loading module '{name}' from file '{path}':\n\t{err}"
                    const err_detail: []const u8 = if (tmp[1] == .String)
                        tmp[1].String.bytes()
                    else
                        "unknown error";
                    return self.fail(
                        "error loading module '{s}' from file '{s}':\n\t{s}",
                        .{ name, file_path, err_detail },
                    );
                },
            };

            // Pin the loaded closure against GC: the internStr calls below
            // can trigger a cycle, and the closure in tmp[0] is a Zig-local,
            // not a GC root.
            var roots = self.gcTempRoots();
            defer roots.end();
            try roots.add(tmp[0]);

            const run_args = [_]Value{ .{ .String = try self.internStr(name) }, .{ .String = try self.internStr(file_path) } };
            const ret = try self.runClosure(cl, run_args[0..]);
            defer self.alloc.free(ret);
            // PUC ll_require (loadlib.c:666-674): if the loader returned a
            // non-nil value, set loaded[name] = that value. Otherwise leave
            // loaded[name] alone — the loader may have set it itself (e.g.
            // C.lua: "package.loaded[...] = 25"). Then read loaded[name]
            // again; if still nil, default to true.
            //
            // TODO(refactor): extract finalizeLoaderResult(loaded_tbl, name, ret)
            // helper to deduplicate this block across preload/lua-path/C-path
            // (3 instances).
            if (ret.len > 0 and ret[0] != .Nil) {
                try self.setField(loaded_tbl, name, ret[0]);
            }
            const final_val: Value = self.getFieldOpt(loaded_tbl, name) orelse v: {
                try self.setField(loaded_tbl, name, .{ .Bool = true });
                break :v .{ .Bool = true };
            };
            outs[0] = final_val;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(file_path) };
            return;
        }

        // Copy error messages to safe buffers before any further GC-triggering
        // operations (internStr in cpath search can collect LuaStrings).
        // Using `?[]u8` (rather than a sentinel-empty slice) avoids two bugs:
        //  - `alloc.dupe(u8, "")` still allocates a 0-byte slice that must be
        //    freed; a `len > 0` guard on the defer would leak it.
        //  - Always allocating a 0-byte slice when the value is not a String
        //    wastes an allocation on every require.
        const perr_path: ?[]u8 = if (searchpath_out[1] == .String)
            try self.alloc.dupe(u8, searchpath_out[1].String.bytes())
        else
            null;
        defer if (perr_path) |p| self.alloc.free(p);
        var cpath_err: ?[]u8 = null;
        defer if (cpath_err) |e| self.alloc.free(e);

        // PUC ll_require searcher_C path (loadlib.c): try the C library path.
        // If package.cpath is set, search for a .so file and, if found, call
        // luaopen_<modname>(modname, filepath) via package.loadlib.
        if (cpath.len != 0) {
            var csearch_out: [2]Value = .{ .Nil, .Nil };
            try self.builtinPackageSearchpath(
                &[_]Value{ .{ .String = try self.internStr(name) }, .{ .String = try self.internStr(cpath) } },
                csearch_out[0..],
            );

            if (csearch_out[0] == .String) {
                if (try self.tryCLoad(csearch_out[0].String.bytes(), name, loaded_tbl, outs)) return;
            } else if (csearch_out[1] == .String) {
                cpath_err = try self.alloc.dupe(u8, csearch_out[1].String.bytes());
            }
        }

        // PUC searcher_Croot (loadlib.c:582-601): if the module name has a dot,
        // try the ROOT package. E.g. "lib1.sub" → search for "lib1" on cpath,
        // then look for luaopen_lib1_sub in that .so. This handles C submodules
        // where the parent .so contains all luaopen_*_child entry points.
        if (cpath.len != 0) {
            if (std.mem.indexOfScalar(u8, name, '.')) |dot_pos| {
                const root_name = name[0..dot_pos];
                var croot_out: [2]Value = .{ .Nil, .Nil };
                try self.builtinPackageSearchpath(
                    &[_]Value{ .{ .String = try self.internStr(root_name) }, .{ .String = try self.internStr(cpath) } },
                    croot_out[0..],
                );

                if (croot_out[0] == .String) {
                    if (try self.tryCLoad(croot_out[0].String.bytes(), name, loaded_tbl, outs)) return;
                }
            }
        }

        const msg = try std.fmt.allocPrint(
            self.alloc,
            "module '{s}' not found:\n\tno field package.preload['{s}']{s}{s}",
            .{ name, name, perr_path orelse "", cpath_err orelse "" },
        );
        return self.fail("{s}", .{msg});
    }

    /// Shared helper for searcher_C and searcher_Croot (PUC loadlib.c).
    /// Given a C library file path and module name, builds the `luaopen_*`
    /// symbol (dots→underscores, LUA_IGMARK candidate splitting), calls
    /// `package.loadlib`, and if successful invokes the loader and
    /// finalizes the result in `loaded[modname]`.
    /// Returns `true` if the loader was found and called successfully;
    /// `false` if the symbol wasn't found (caller continues searching).
    fn tryCLoad(
        self: *Vm,
        c_file_path: []const u8,
        modname: []const u8,
        loaded_tbl: *Table,
        outs: []Value,
    ) DispatchError!bool {
        // The caller passes `c_file_path` as a slice into a `LuaString`'s
        // backing buffer (e.g. `csearch_out[0].String.bytes()`). The
        // `internStr` / `allocPrint` / `builtinPackageLoadlib` calls below
        // can trigger a GC cycle, which may collect that LuaString and
        // invalidate the slice. Dupe it into a GC-independent buffer up
        // front so all subsequent uses are safe. This mirrors the `perr_path`
        // / `cpath_err` defensive copies in the caller.
        const file_path = try self.alloc.dupe(u8, c_file_path);
        defer self.alloc.free(file_path);

        // PUC loadfunc: dots → underscores in the module name.
        const modname_norm = try self.alloc.dupe(u8, modname);
        defer self.alloc.free(modname_norm);
        for (modname_norm) |*ch| if (ch.* == '.') { ch.* = '_'; };

        // LUA_IGMARK ('-'): try prefix before dash, then suffix.
        // E.g. "lib2-v2" → try "luaopen_lib2" first, then "luaopen_v2".
        var candidates: [2][]const u8 = .{ modname_norm, "" };
        var n_candidates: usize = 1;
        if (std.mem.indexOfScalar(u8, modname_norm, '-')) |dash_pos| {
            candidates[0] = modname_norm[0..dash_pos];
            candidates[1] = modname_norm[dash_pos + 1 ..];
            n_candidates = 2;
        }

        var loadlib_outs: [3]Value = .{ .Nil, .Nil, .Nil };
        for (candidates[0..n_candidates]) |cand| {
            if (cand.len == 0) continue;
            const open_name = try std.fmt.allocPrint(self.alloc, "luaopen_{s}", .{cand});
            defer self.alloc.free(open_name);

            loadlib_outs = .{ .Nil, .Nil, .Nil };
            try self.builtinPackageLoadlib(
                &[_]Value{
                    .{ .String = try self.internStr(file_path) },
                    .{ .String = try self.internStr(open_name) },
                },
                loadlib_outs[0..],
            );
            if (loadlib_outs[0] == .Closure) break;
        }

        if (loadlib_outs[0] != .Closure) return false;

        // Pin the C closure against GC (internStr calls below can trigger a cycle).
        var roots = self.gcTempRoots();
        defer roots.end();
        try roots.add(loadlib_outs[0]);

        // PUC ll_require: calls the loader with (modname, filepath).
        const call_args = [_]Value{
            .{ .String = try self.internStr(modname) },
            .{ .String = try self.internStr(file_path) },
        };
        const ret = try self.runClosure(loadlib_outs[0].Closure, call_args[0..]);
        defer self.alloc.free(ret);

        // PUC ll_require: if loader returned non-nil, set loaded[name].
        // Then read loaded[name]; default to true if still nil.
        if (ret.len > 0 and ret[0] != .Nil) {
            try self.setField(loaded_tbl, modname, ret[0]);
        }
        const final_val: Value = self.getFieldOpt(loaded_tbl, modname) orelse v: {
            try self.setField(loaded_tbl, modname, .{ .Bool = true });
            break :v .{ .Bool = true };
        };
        outs[0] = final_val;
        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(file_path) };
        return true;
    }

    fn builtinPackageSearchpath(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;
        if (args.len < 2) return self.fail("bad argument #2 to 'searchpath' (string expected)", .{});
        const name = switch (args[0]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #1 to 'searchpath' (string expected)", .{}),
        };
        const path = switch (args[1]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #2 to 'searchpath' (string expected)", .{}),
        };
        const sep = if (args.len > 2 and args[2] != .Nil) switch (args[2]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #3 to 'searchpath' (string expected)", .{}),
        } else ".";
        const rep = if (args.len > 3 and args[3] != .Nil) switch (args[3]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #4 to 'searchpath' (string expected)", .{}),
        } else "/";

        var modname_buf = std.ArrayList(u8).empty;
        defer modname_buf.deinit(self.alloc);
        if (sep.len != 0) {
            var i: usize = 0;
            while (i < name.len) {
                if (i + sep.len <= name.len and std.mem.eql(u8, name[i .. i + sep.len], sep)) {
                    try modname_buf.appendSlice(self.alloc, rep);
                    i += sep.len;
                } else {
                    try modname_buf.append(self.alloc, name[i]);
                    i += 1;
                }
            }
        } else {
            try modname_buf.appendSlice(self.alloc, name);
        }
        const modname = modname_buf.items;

        var err_buf = std.ArrayList(u8).empty;
        defer err_buf.deinit(self.alloc);
        var it = std.mem.splitScalar(u8, path, ';');
        while (it.next()) |templ| {
            var cand_buf = std.ArrayList(u8).empty;
            defer cand_buf.deinit(self.alloc);
            if (std.mem.indexOfScalar(u8, templ, '?')) |_| {
                var ti: usize = 0;
                while (ti < templ.len) : (ti += 1) {
                    if (templ[ti] == '?') {
                        try cand_buf.appendSlice(self.alloc, modname);
                    } else {
                        try cand_buf.append(self.alloc, templ[ti]);
                    }
                }
            } else {
                try cand_buf.appendSlice(self.alloc, templ);
            }
            const candidate = cand_buf.items;
            std.Io.Dir.cwd().access(stdio.activeIo(), candidate, .{}) catch {
                try appendFmt(self.alloc, &err_buf, "\n\tno file '{s}'", .{candidate});
                continue;
            };
            if (outs.len > 0) outs[0] = .{ .String = try self.internStr(try std.fmt.allocPrint(self.alloc, "{s}", .{candidate})) };
            if (outs.len > 1) outs[1] = .Nil;
            return;
        }

        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(try std.fmt.allocPrint(self.alloc, "{s}", .{err_buf.items})) };
    }

    /// PUC `ll_loadlib` (loadlib.c): dynamic library loading.
    ///
    /// `package.loadlib(libname, funcname)` opens the shared library at
    /// `libname` via `std.DynLib.open` (Zig's dlopen wrapper), looks up the
    /// C symbol `funcname` (typically `luaopen_<modname>`), and wraps the
    /// resulting function pointer in a `Closure` so it integrates with the
    /// existing C function dispatch (Task B1's `callCFunction`).
    ///
    /// **Return values** (matching PUC's `ll_loadlib`):
    ///   * Success: `(closure)` — a callable C closure wrapping the symbol.
    ///   * Failure: `(nil, errmsg, "open"|"init")` — `errmsg` describes the
    ///     failure; the third value is PUC's category string (`"open"` for
    ///     dlopen failure, `"init"` for symbol-not-found).
    ///
    /// **Probe mode** (`funcname == "*"`): opens the library, closes it
    /// immediately, and returns a dummy closure (`llAccessible`) if the
    /// open succeeded. This mirrors PUC's `LL_SYM_PREFIX "*"` path used by
    /// `package.searchpath`/`require` to check whether a library is loadable.
    ///
    /// **DynLib handle leak.** We intentionally never call `lib.close()` for
    /// the normal (non-probe) path. PUC never `dlclose`s either — C
    /// extensions may cache pointers to their own static/global data; closing
    /// the lib would invalidate those pointers for the rest of the process
    /// lifetime. The library stays mapped until the process exits, exactly as
    /// in PUC Lua. (The probe path DOES close the lib since no symbol is
    /// extracted.)
    fn builtinPackageLoadlib(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        // PUC uses luaL_checkstring which raises on wrong type. We match.
        if (args.len < 1) return self.fail("bad argument #1 to 'loadlib' (string expected)", .{});
        const lib_path = switch (args[0]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #1 to 'loadlib' (string expected)", .{}),
        };
        if (args.len < 2) return self.fail("bad argument #2 to 'loadlib' (string expected)", .{});
        const func_name = switch (args[1]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #2 to 'loadlib' (string expected)", .{}),
        };

        // PUC lookforfunc (loadlib.c:384): check the CLIBS cache first. If the
        // library at `lib_path` was already opened (by a previous probe or
        // load), reuse the cached handle instead of re-dlopen'ing. This is
        // essential for the probe→load pattern: the probe opens with
        // RTLD_GLOBAL, and subsequent loads must see those global symbols.
        const path_z = try self.alloc.dupeZ(u8, lib_path);
        defer self.alloc.free(path_z);

        const is_probe = std.mem.eql(u8, func_name, "*");
        const seeglb = is_probe; // PUC: lsys_load(L, path, *sym == '*')

        // Look up the cached handle. If found, use it. If not, dlopen with the
        // appropriate flags and cache the result permanently.
        const handle: ?*anyopaque = blk: {
            if (self.c_libs.get(lib_path)) |h| break :blk h;
            // PUC lsys_load (loadlib.c:109): RTLD_NOW resolves all symbols at
            // load time; RTLD_GLOBAL (seeglb) makes the library's symbols
            // visible to subsequently-loaded libraries. The probe mode ("*")
            // always uses GLOBAL so that inter-library dependencies (e.g.
            // lib11.so calling lib1.so's `lib1_export`) resolve correctly.
            const flags: std.c.RTLD = if (seeglb)
                .{ .NOW = true, .GLOBAL = true }
            else
                .{ .NOW = true };

            const h = std.c.dlopen(path_z, flags) orelse {
                if (outs.len > 0) outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(
                    try std.fmt.allocPrint(self.alloc, "\n\tcannot open '{s}'", .{lib_path}),
                ) };
                if (outs.len > 2) outs[2] = .{ .String = try self.internStr("open") };
                self.last_builtin_out_count = @min(outs.len, 3);
                return;
            };
            // Cache the handle permanently (PUC CLIBS never closes). The key
            // is owned by the HashMap; the path string is duped.
            const key = try self.alloc.dupe(u8, lib_path);
            try self.c_libs.put(self.alloc, key, h);
            break :blk h;
        };

        // PUC lookforfunc: probe mode ("*") just verifies the library loads.
        // Return a no-op closure (PUC's ll_accessible).
        if (is_probe) {
            const cl = try self.alloc.create(Closure);
            cl.* = .{ .upvalues = &.{}, .c_func = &llAccessible };
            try self.gcRegisterClosure(cl);
            if (outs.len > 0) outs[0] = .{ .Closure = cl };
            self.last_builtin_out_count = @min(outs.len, 1);
            return;
        }

        // Normal loadlib: look up the C symbol via dlsym. The type must match
        // our lua_CFunction signature: `fn (?*Vm) callconv(.c) c_int`.
        const func_name_z = try self.alloc.dupeZ(u8, func_name);
        defer self.alloc.free(func_name_z);
        const sym = std.c.dlsym(handle, func_name_z) orelse {
            if (outs.len > 0) outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(
                try std.fmt.allocPrint(self.alloc, "\n\tsymbol '{s}' not found in '{s}'", .{ func_name, lib_path }),
            ) };
            if (outs.len > 2) outs[2] = .{ .String = try self.internStr("init") };
            self.last_builtin_out_count = @min(outs.len, 3);
            return;
        };
        const c_func: *const fn (?*Vm) callconv(.c) c_int = @ptrCast(@alignCast(sym));

        // Wrap the C function pointer in a Closure so it can be called via
        // the normal runClosure → callCFunction dispatch path.
        const cl = try self.alloc.create(Closure);
        cl.* = .{ .upvalues = &.{}, .c_func = c_func };
        try self.gcRegisterClosure(cl);
        if (outs.len > 0) outs[0] = .{ .Closure = cl };
        self.last_builtin_out_count = @min(outs.len, 1);
    }

    fn builtinSetmetatable(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len < 2) return self.fail("bad argument #2 to 'setmetatable' (nil or table expected)", .{});
        const tbl = try self.expectTable(args[0]);
        if (tbl.metatable) |cur| {
            if (self.getFieldOpt(cur, "__metatable") != null) return self.fail("cannot change a protected metatable", .{});
        }
        switch (args[1]) {
            .Nil => {
                try self.gcStoreMetatable(tbl, null);
                _ = self.finalizables.remove(.{ .table = tbl });
            },
            .Table => |mt| {
                try self.gcStoreMetatable(tbl, mt);
                if (self.fasttm(mt, .gc) != null) {
                    try self.registerFinalizable(.{ .table = tbl });
                } else {
                    _ = self.finalizables.remove(.{ .table = tbl });
                }
            },
            else => return self.fail("bad argument #2 to 'setmetatable' (nil or table expected)", .{}),
        }
        if (outs.len > 0) outs[0] = args[0];
    }

    fn builtinGetmetatable(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("getmetatable expects value", .{});
        if (valueMetatable(self, args[0])) |mt| {
            outs[0] = self.getFieldOpt(mt, "__metatable") orelse .{ .Table = mt };
        } else {
            outs[0] = .Nil;
        }
    }

    fn debugInfoHasOpt(what: []const u8, c: u8) bool {
        return std.mem.indexOfScalar(u8, what, c) != null;
    }

    fn debugNameFromCallee(self: *Vm, callee: Value) ?[]const u8 {
        _ = self;
        return switch (callee) {
            .Builtin => |id| blk: {
                const full = id.name();
                if (std.mem.lastIndexOfScalar(u8, full, '.')) |dot| break :blk full[dot + 1 ..];
                break :blk full;
            },
            .Closure => |cl| blk: {
                const name = if (cl.proto) |proto| proto.name else "";
                if (name.len == 0 or std.mem.eql(u8, name, "<anon>") or std.mem.eql(u8, name, "<bytecode>")) break :blk null;
                break :blk name;
            },
            else => null,
        };
    }

    fn debugResolveFrameIndex(self: *Vm, level: usize) ?*CallFrame {
        // Walk Thread.call_frames (bytecode, most recent first).
        var visible: usize = 0;
        const th = self.activeBytecodeThread();
        var i = th.call_frames.len();
        while (i > 0) {
            i -= 1;
            if (th.call_frames.getConstPtr(i).hide_from_debug) continue;
            visible += 1;
            if (visible == level) return th.call_frames.getPtr(i);
        }
        return null;
    }

    const DebugName = struct {
        name: ?[]const u8 = null,
        namewhat: []const u8 = "",
    };

    fn debugFrameCalleeMatches(self: *Vm, candidate: Value, target: Frame) bool {
        _ = self;
        return switch (target.callee) {
            .Builtin => |target_id| candidate == .Builtin and candidate.Builtin == target_id,
            .Closure => |target_cl| candidate == .Closure and candidate.Closure == target_cl,
            else => false,
        };
    }

    fn debugBytecodeLocalAt(proto: *const bc.Proto, reg: u8, pc: u32) ?[]const u8 {
        var i = proto.locvars.len;
        while (i > 0) {
            i -= 1;
            const local = proto.locvars[i];
            if (local.reg != reg or local.name.len == 0) continue;
            if (pc < local.startpc or pc >= local.endpc) continue;
            return local.name;
        }
        return null;
    }

    fn debugBytecodeStringConstant(
        proto: *const bc.Proto,
        use_pc: usize,
        reg_in: u8,
    ) ?[]const u8 {
        var reg = reg_in;
        var cursor = use_pc;
        var remaining: usize = 32;
        while (cursor > 0 and remaining > 0) : (remaining -= 1) {
            cursor -= 1;
            const inst = proto.code[cursor];
            const op: bc.Op = @enumFromInt(inst.op);
            switch (op) {
                .move => {
                    if (inst.a != reg) continue;
                    reg = inst.b;
                },
                .loadk => {
                    if (inst.a != reg) continue;
                    const kidx: usize = inst.b;
                    if (kidx < proto.k.len and proto.k[kidx] == .str) {
                        return proto.k[kidx].str.bytes();
                    }
                    return null;
                },
                .loadkx => {
                    if (inst.a != reg) continue;
                    if (cursor + 1 >= proto.code.len) return null;
                    const extra = proto.code[cursor + 1];
                    if (@as(bc.Op, @enumFromInt(extra.op)) != .extraarg) return null;
                    const kidx: usize = extra.extraArg();
                    if (kidx < proto.k.len and proto.k[kidx] == .str) {
                        return proto.k[kidx].str.bytes();
                    }
                    return null;
                },
                else => {},
            }
        }
        return null;
    }

    fn debugBytecodeDefinitionIsConditional(
        proto: *const bc.Proto,
        definition_pc: usize,
        use_pc: usize,
    ) bool {
        var cursor: usize = 0;
        while (cursor < definition_pc) : (cursor += 1) {
            const inst = proto.code[cursor];
            if (@as(bc.Op, @enumFromInt(inst.op)) != .jmp) continue;
            const target_signed = @as(i64, @intCast(cursor)) + @as(i64, inst.jumpOffset()) + 1;
            if (target_signed < 0) continue;
            const target: usize = @intCast(target_signed);
            if (target > definition_pc and target <= use_pc) return true;
        }
        return false;
    }

    /// Resolve a bytecode operand register back to its source local/global/field.
    /// Codegen commonly copies a local/parameter into a temporary call base,
    /// so comparing closure values across every live local chooses the wrong
    /// alias. PUC's getobjname follows MOVE definitions from the call operand;
    /// mirror that core rule here.
    fn debugBytecodeOperandName(proto: *const bc.Proto, call_pc: usize, call_reg_in: u8) DebugName {
        const call_pc_u32: u32 = @intCast(@min(call_pc, std.math.maxInt(u32)));
        if (debugBytecodeLocalAt(proto, call_reg_in, call_pc_u32)) |name| {
            return .{ .name = name, .namewhat = "local" };
        }

        var reg = call_reg_in;
        var cursor = call_pc;
        var remaining: usize = 32;
        while (cursor > 0 and remaining > 0) : (remaining -= 1) {
            cursor -= 1;
            const inst = proto.code[cursor];
            const op: bc.Op = @enumFromInt(inst.op);
            switch (op) {
                .move => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    reg = inst.b;
                    const pc: u32 = @intCast(@min(cursor, std.math.maxInt(u32)));
                    if (debugBytecodeLocalAt(proto, reg, pc)) |name| {
                        return .{ .name = name, .namewhat = "local" };
                    }
                },
                .getupval => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const idx: usize = inst.b;
                    if (idx < proto.upvalues.len and proto.upvalues[idx].name.len != 0) {
                        return .{ .name = proto.upvalues[idx].name, .namewhat = "upvalue" };
                    }
                    return .{};
                },
                .gettabup => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const kidx: usize = inst.c;
                    if (kidx < proto.k.len and proto.k[kidx] == .str) {
                        // PUC getfuncname: GETTABUP reports "global" when the
                        // upvalue is _ENV, "field" otherwise (e.g. upvalue.x).
                        const upidx: usize = inst.b;
                        const is_env = upidx < proto.upvalues.len and
                            std.mem.eql(u8, proto.upvalues[upidx].name, "_ENV");
                        if (is_env) {
                            return .{ .name = proto.k[kidx].str.bytes(), .namewhat = "global" };
                        }
                        return .{ .name = proto.k[kidx].str.bytes(), .namewhat = "field" };
                    }
                    return .{};
                },
                .gettable => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const key = debugBytecodeStringConstant(proto, cursor, inst.c) orelse return .{};
                    const object_name = debugBytecodeOperandName(proto, cursor, inst.b);
                    if (object_name.name) |name| {
                        if (std.mem.eql(u8, name, "_ENV") and
                            (std.mem.eql(u8, object_name.namewhat, "local") or
                                std.mem.eql(u8, object_name.namewhat, "upvalue")))
                        {
                            return .{ .name = key, .namewhat = "global" };
                        }
                    }
                    return .{ .name = key, .namewhat = "field" };
                },
                .getfield => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const kidx: usize = inst.c;
                    if (kidx < proto.k.len and proto.k[kidx] == .str) {
                        const key = proto.k[kidx].str.bytes();
                        // A global access through a lexically shadowed `_ENV`
                        // uses GETFIELD instead of GETTABUP. PUC still reports
                        // the accessed key as a global, not as an ordinary field.
                        const object_name = debugBytecodeOperandName(proto, cursor, inst.b);
                        if (object_name.name) |name| {
                            if (std.mem.eql(u8, name, "_ENV") and
                                (std.mem.eql(u8, object_name.namewhat, "local") or
                                    std.mem.eql(u8, object_name.namewhat, "upvalue")))
                            {
                                return .{ .name = key, .namewhat = "global" };
                            }
                        }
                        return .{ .name = key, .namewhat = "field" };
                    }
                    return .{};
                },
                .self => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const kidx: usize = inst.c;
                    if (kidx < proto.k.len and proto.k[kidx] == .str) {
                        return .{ .name = proto.k[kidx].str.bytes(), .namewhat = "method" };
                    }
                    return .{};
                },
                // TESTSET may choose between the previous value in R[A]
                // and R[B]. Once it defines the operand register, there is no
                // single source name to report (for example `(a or a)`).
                .testset => if (inst.a == reg) return .{},
                // GETVARG defines R[A] from the virtual vararg parameter.
                // Report the vararg parameter's name (stored in locvars
                // at register numparams).
                .getvarg => {
                    if (inst.a != reg) continue;
                    if (debugBytecodeDefinitionIsConditional(proto, cursor, call_pc)) return .{};
                    const pc: u32 = @intCast(@min(cursor, std.math.maxInt(u32)));
                    if (debugBytecodeLocalAt(proto, proto.numparams, pc)) |name| {
                        return .{ .name = name, .namewhat = "local" };
                    }
                    return .{};
                },
                else => {},
            }
        }
        return .{};
    }

    fn debugInferNameFromCaller(self: *Vm, caller_opt: ?*const CallFrame, target: Frame) DebugName {
        const caller = caller_opt orelse return .{};
        // PUC's funcnamefromcall returns NULL for C frames (pcall/xpcall).
        // When the caller frame has a pending protected call, the actual
        // caller is the C function (pcall/xpcall), not this Lua frame.
        // Return empty name so pushfuncname falls through to
        // pushglobalfuncname or "function <src:linedefined>".
        if (caller.pending_call.get()) |pending| {
            if (pending.protection != null) return .{};
        }

        if (caller.proto) |proto| {
            // Prefer the register named by the active CALL instruction.
            // Comparing closure values across all locals is ambiguous when the
            // same function has aliases (for example `g(f)`, followed by a
            // call through parameter `x`). PUC resolves the call operand at
            // the call site, so the parameter name must win over another local
            // that happens to hold the same closure.
            if (caller.pc < proto.code.len) {
                const call_inst = proto.code[caller.pc];
                const call_op: bc.Op = @enumFromInt(call_inst.op);
                if (call_op == .tforcall) {
                    const iter_reg = call_inst.a;
                    if (iter_reg < caller.regs.len and self.debugFrameCalleeMatches(caller.regs[iter_reg], target)) {
                        return .{ .name = "for iterator", .namewhat = "for iterator" };
                    }
                } else if (call_op == .call or call_op == .tailcall) {
                    const call_reg = call_inst.a;
                    if (call_reg < caller.regs.len and self.debugFrameCalleeMatches(caller.regs[call_reg], target)) {
                        const resolved_name = debugBytecodeOperandName(proto, caller.pc, call_reg);
                        if (resolved_name.name != null) return resolved_name;
                    }
                }
            }

            // PUC's getobjname resolves a called register through the active
            // LocVar ranges of the caller.  Bytecode frames do not have the IR
            // `locals` slice, so use Proto debug ranges plus the live register
            // file instead of comparing every closure.
            for (proto.locvars) |local| {
                if (local.name.len == 0 or local.reg >= caller.regs.len) continue;
                const pc: u32 = @intCast(@min(caller.pc, std.math.maxInt(u32)));
                if (pc < local.startpc or pc >= local.endpc) continue;
                if (self.debugFrameCalleeMatches(caller.regs[local.reg], target)) {
                    return .{ .name = local.name, .namewhat = "local" };
                }
            }
        }

        // PUC getfuncname does NOT do a global table walk as a fallback.
        // It only resolves globals through the call instruction's register
        // (GETTABUP/GETTABLE with _ENV). If the register can't be resolved,
        // namewhat stays empty, and pushfuncname falls through to
        // pushglobalfuncname (which searches loaded tables) or
        // "function <src:linedefined>".
        return .{};
    }

    fn debugInfoValidateOpts(self: *Vm, what: []const u8) DispatchError!void {
        for (what) |ch| {
            if (ch == '>') return self.fail("bad option '>' to 'getinfo'", .{});
            if (std.mem.indexOfScalar(u8, "nSluftLr", ch) == null) {
                return self.fail("bad option '{c}' to 'getinfo'", .{ch});
            }
        }
    }

    /// Extended version: `is_stripped`=true when the proto has no debug info
    /// (lineinfo empty). In that case, PUC's lua_getinfo uses "?" as source.
    fn debugShortSourceEx(self: *Vm, src: []const u8, is_stripped: bool) DispatchError![]const u8 {
        const idsize: usize = 60;
        // PUC lua_getinfo: (ar->source == NULL) ? "?" : ar->source
        // Stripped chunks have source=NULL in PUC; we detect them via
        // empty source_name + is_stripped flag.
        if (is_stripped) return "?";
        if (src.len == 0) return try std.fmt.allocPrint(self.alloc, "[string \"\"]", .{});

        if (src[0] == '=') {
            const raw = src[1..];
            if (raw.len <= idsize) return raw;
            return raw[0..idsize];
        }

        if (src[0] == '@') {
            const raw = src[1..];
            if (raw.len <= idsize) return raw;
            const keep = if (idsize > 3) idsize - 3 else 0;
            return try std.fmt.allocPrint(self.alloc, "...{s}", .{raw[raw.len - keep ..]});
        }

        // File-loaded chunks should behave like "@file.lua" even when the
        // current bootstrap pipeline passes raw file names.
        const looks_like_path = std.mem.endsWith(u8, src, ".lua") or
            std.mem.indexOfScalar(u8, src, '/') != null or
            std.mem.indexOfScalar(u8, src, '\\') != null;
        if (looks_like_path) {
            if (src.len <= idsize) return src;
            const keep = if (idsize > 3) idsize - 3 else 0;
            return try std.fmt.allocPrint(self.alloc, "...{s}", .{src[src.len - keep ..]});
        }

        if (src[0] == '\n' or src[0] == '\r') return "[string \"...\"]";

        const nl = std.mem.indexOfAny(u8, src, "\r\n") orelse src.len;
        var body_end = nl;
        var truncated = nl < src.len;
        const max_body = if (idsize > "[string \"".len + "\"]".len + 3) idsize - "[string \"".len - "\"]".len - 3 else 0;
        if (body_end > max_body) {
            body_end = max_body;
            truncated = true;
        }

        return if (truncated)
            try std.fmt.allocPrint(self.alloc, "[string \"{s}...\"]", .{src[0..body_end]})
        else
            try std.fmt.allocPrint(self.alloc, "[string \"{s}\"]", .{src[0..body_end]});
    }

    fn debugFillInfoFromFunction(self: *Vm, t: *Table, fnv: Value, what: []const u8) DispatchError!void {
        switch (fnv) {
            .Builtin => |id| {
                const has_s = what.len == 0 or debugInfoHasOpt(what, 'S');
                const has_f = what.len == 0 or debugInfoHasOpt(what, 'f');
                const has_u = what.len == 0 or debugInfoHasOpt(what, 'u');
                if (has_s) {
                    try self.setField(t, "what", .{ .String = try self.internStr("C") });
                    try self.setField(t, "source", .{ .String = try self.internStr("=[C]") });
                    try self.setField(t, "short_src", .{ .String = try self.internStr("[C]") });
                    try self.setField(t, "linedefined", .{ .Int = -1 });
                    try self.setField(t, "lastlinedefined", .{ .Int = -1 });
                }
                if (has_u) {
                    const nups: i64 = if (id == .string_match or id == .string_gmatch_iter) 1 else 0;
                    try self.setField(t, "nups", .{ .Int = nups });
                    try self.setField(t, "nparams", .{ .Int = 0 });
                    try self.setField(t, "isvararg", .{ .Bool = true });
                }
                if (debugInfoHasOpt(what, 'L')) {
                    try self.setField(t, "activelines", .Nil);
                }
                if (has_f) try self.setField(t, "func", fnv);
            },
            .Closure => |cl| {
                const has_f = what.len == 0 or debugInfoHasOpt(what, 'f');
                if (cl.proto) |p| {
                    // Bytecode closure: fill from Proto fields.
                    const has_s = what.len == 0 or debugInfoHasOpt(what, 'S');
                    const has_u = what.len == 0 or debugInfoHasOpt(what, 'u');
                    if (has_s) {
                        // PUC: stripped chunks (source=NULL) get short_src="?".
                        // We detect stripped protos by empty source_name AND
                        // empty lineinfo (cloneStrippedProto clears both).
                        const is_stripped = p.source_name.len == 0 and p.lineinfo.len == 0;
                        const short_src = try self.debugShortSourceEx(p.source_name, is_stripped);
                        const looks_like_path = p.source_name.len != 0 and
                            (std.mem.endsWith(u8, p.source_name, ".lua") or
                                std.mem.indexOfScalar(u8, p.source_name, '/') != null or
                                std.mem.indexOfScalar(u8, p.source_name, '\\') != null);
                        const src = if (p.source_name.len != 0 and p.source_name[0] != '@' and p.source_name[0] != '=' and looks_like_path)
                            try std.fmt.allocPrint(self.alloc, "@{s}", .{p.source_name})
                        else
                            p.source_name;
                        const what_str: []const u8 = if (p.line_defined == 0) "main" else "Lua";
                        try self.setField(t, "what", .{ .String = try self.internStr(what_str) });
                        try self.setField(t, "source", .{ .String = try self.internStr(src) });
                        try self.setField(t, "short_src", .{ .String = try self.internStr(short_src) });
                        try self.setField(t, "linedefined", .{ .Int = @intCast(p.line_defined) });
                        try self.setField(t, "lastlinedefined", .{ .Int = @intCast(p.last_line_defined) });
                    }
                    if (has_u) {
                        const is_main_like = p.line_defined == 0 and p.is_vararg and p.numparams == 0;
                        var nups: i64 = @intCast(cl.upvalues.len);
                        if (is_main_like and nups == 0) nups = 1;
                        try self.setField(t, "nups", .{ .Int = nups });
                        try self.setField(t, "nparams", .{ .Int = @intCast(p.numparams) });
                        const is_vararg = if (p.line_defined == 0) true else p.is_vararg;
                        try self.setField(t, "isvararg", .{ .Bool = is_vararg });
                    }
                    if (debugInfoHasOpt(what, 'L')) {
                        // Build activelines from Proto's line info.
                        const act = try self.allocTable();
                        for (p.lineinfo) |line| {
                            if (line > 0) {
                                try self.rawSet(act, .{ .Int = @intCast(line) }, .{ .Bool = true });
                            }
                        }
                        try self.setField(t, "activelines", .{ .Table = act });
                    }
                }
                if (has_f) try self.setField(t, "func", fnv);
            },
            else => return self.fail("bad argument #1 to 'getinfo' (function or level expected)", .{}),
        }
    }

    fn builtinDebugGetinfo(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'getinfo' (function or level expected)", .{});

        var i: usize = 0;
        var target_thread: ?*Thread = null;
        if (args.len > 0 and args[0] == .Thread) {
            target_thread = try self.expectThread(args[0]);
            i = 1;
        }
        if (i >= args.len) return self.fail("bad argument #1 to 'getinfo' (function or level expected)", .{});

        const what = if (i + 1 < args.len) switch (args[i + 1]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #2 to 'getinfo' (string expected)", .{}),
        } else "";
        try self.debugInfoValidateOpts(what);

        // Temp roots: protect `t` across calls to debugFillInfoFromIrFunction
        // which internally allocates an activelines table (triggering GC).
        var roots = self.gcTempRoots();
        defer roots.end();

        const t = try self.allocTable();
        try roots.add(.{ .Table = t });

        try self.setField(t, "currentline", .{ .Int = 0 });

        switch (args[i]) {
            .Int => |level| {
                if (target_thread) |th| {
                    if (level < 0 or level > 1) {
                        outs[0] = .Nil;
                        return;
                    }
                    if (threadCurrentParkedRuntimeFrame(th)) |fr| {
                        // P15.68: If the coroutine yielded from a builtin (e.g.
                        // testC `yield`) NOT inside a debug hook, the builtin
                        // is the "current function" (level 0), and the Lua
                        // frame is level 1. This mirrors PUC where a C
                        // function's CallInfo is on top when it yields. Our
                        // builtins don't push frames, so we detect this via
                        // th.suspended_builtin and !th.capture_from_debug_hook.
                        // For hook yields (capture_from_debug_hook=true), the
                        // hook frame was already popped by P15.67, so level 0
                        // is the interrupted Lua function.
                        if (th.suspended_builtin != null and !th.yielded_from_debug_hook) {
                            // Level 0: the builtin (linedefined = -1)
                            if (level == 0) {
                                try self.setField(t, "name", .Nil);
                                try self.setField(t, "namewhat", .{ .String = try self.internStr("") });
                                try self.setField(t, "currentline", .{ .Int = -1 });
                                if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                                    try self.setField(t, "istailcall", .{ .Bool = false });
                                    try self.setField(t, "extraargs", .{ .Int = 0 });
                                }
                                const callee: Value = .{ .Builtin = th.suspended_builtin.? };
                                try self.debugFillInfoFromFunction(t, callee, what);
                                if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                                    try self.setField(t, "func", callee);
                                }
                                if (outs.len > 0) outs[0] = .{ .Table = t };
                                return;
                            }
                            // Level 1: the Lua frame that called the builtin
                            if (level >= 1) {
                                if (th.call_frames.len() < 1) {
                                    outs[0] = .Nil;
                                    return;
                                }
                                // Use the Lua frame's info
                            } else {
                                outs[0] = .Nil;
                                return;
                            }
                        } else {
                            // No suspended builtin or hook yield: level 1 is
                            // the caller. PUC debug.getinfo: level 1 is the
                            // caller of the current frame. If the coroutine is
                            // suspended at the top level (only one frame),
                            // there is no level 1.
                            if (level >= 1 and th.call_frames.len() < 2) {
                                outs[0] = .Nil;
                                return;
                            }
                        }
                        try self.setField(t, "name", .Nil);
                        try self.setField(t, "namewhat", .{ .String = try self.internStr("") });
                        // Re-derive current_line from lineinfo (fast path no longer updates it).
                        if (fr.proto) |proto| {
                            if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                                fr.current_line = @intCast(proto.lineinfo[fr.pc]);
                            }
                        }
                        const current_line: i64 = if (fr.proto) |proto|
                            (if (proto.lineinfo.len == 0) -1 else fr.current_line)
                        else
                            fr.current_line;
                        try self.setField(t, "currentline", .{ .Int = current_line });
                        if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                        const extraargs: i64 = if (fr.isVararg()) @intCast(fr.varargs.len) else 0;
                            try self.setField(t, "istailcall", .{ .Bool = fr.is_tailcall });
                            try self.setField(t, "extraargs", .{ .Int = extraargs });
                        }
                        try self.debugFillInfoFromFunction(t, fr.callee, what);
                        if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                            try self.setField(t, "func", fr.callee);
                        }
                        if (outs.len > 0) outs[0] = .{ .Table = t };
                        return;
                    }
                    // No parked runtime frame. If the coroutine suspended in a
                    // C builtin (e.g. testC `yield`), report that builtin.
                    if (th.suspended_builtin) |id| {
                        try self.setField(t, "name", .Nil);
                        try self.setField(t, "namewhat", .{ .String = try self.internStr("") });
                        try self.setField(t, "currentline", .{ .Int = -1 });
                        if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                            try self.setField(t, "istailcall", .{ .Bool = false });
                            try self.setField(t, "extraargs", .{ .Int = 0 });
                        }
                        const callee: Value = .{ .Builtin = id };
                        try self.debugFillInfoFromFunction(t, callee, what);
                        if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                            try self.setField(t, "func", callee);
                        }
                        if (outs.len > 0) outs[0] = .{ .Table = t };
                        return;
                    }
                    outs[0] = .Nil;
                    return;
                }
                if (level < 1) {
                    outs[0] = .Nil;
                    return;
                }
                const lv: usize = @intCast(level);
                if (lv == 2 and self.activeProtectedCallDepth() > 0 and self.activeCloseMetamethodDepth() > 0) {
                    try self.setField(t, "name", .{ .String = try self.internStr("pcall") });
                    try self.setField(t, "namewhat", .{ .String = try self.internStr("global") });
                    try self.setField(t, "currentline", .{ .Int = -1 });
                    if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                        try self.setField(t, "istailcall", .{ .Bool = false });
                        try self.setField(t, "extraargs", .{ .Int = 0 });
                    }
                    const pcall_f: Value = .{ .Builtin = .pcall };
                    try self.debugFillInfoFromFunction(t, pcall_f, what);
                    if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                        try self.setField(t, "func", pcall_f);
                    }
                    if (outs.len > 0) outs[0] = .{ .Table = t };
                    return;
                }
                const fr = self.debugResolveFrameIndex(lv) orelse {
                    if (lv == 2 and self.activeProtectedCallDepth() > 0) {
                        try self.setField(t, "name", .{ .String = try self.internStr("pcall") });
                        try self.setField(t, "namewhat", .{ .String = try self.internStr("global") });
                        try self.setField(t, "currentline", .{ .Int = -1 });
                        if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                            try self.setField(t, "istailcall", .{ .Bool = false });
                            try self.setField(t, "extraargs", .{ .Int = 0 });
                        }
                        const pcall_f: Value = .{ .Builtin = .pcall };
                        try self.debugFillInfoFromFunction(t, pcall_f, what);
                        if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                            try self.setField(t, "func", pcall_f);
                        }
                        if (outs.len > 0) outs[0] = .{ .Table = t };
                        return;
                    }
                    outs[0] = .Nil;
                    return;
                };
                if (self.isInDebugHook() and lv == 1) {
                    try self.setField(t, "name", .Nil);
                    try self.setField(t, "namewhat", .{ .String = try self.internStr("hook") });
                } else if (self.isInDebugHook() and lv == 2 and self.debugNameFromCallee(fr.callee) != null) {
                    // Synthetic call/return events for a builtin temporarily
                    // replace the paused Lua frame's callee. That event name
                    // is more specific than the frame's continuation label
                    // (for example `return sethook` while inside __close).
                    try self.setField(t, "name", .{ .String = try self.internStr(self.debugNameFromCallee(fr.callee).?) });
                    try self.setField(t, "namewhat", .{ .String = try self.internStr("global") });
                } else if (fr.debug_namewhat) |nwo| {
                    // Continuation-entered frames carry their call-site name
                    // on the RuntimeFrame itself. It must win at every debug
                    // level: a return hook asks for level 2 to inspect the
                    // function that is returning (not the hook frame).
                    try self.setField(t, "namewhat", .{ .String = try self.internStr(nwo) });
                    if (fr.debug_name) |nmo| {
                        try self.setField(t, "name", .{ .String = try self.internStr(nmo) });
                    } else {
                        try self.setField(t, "name", .Nil);
                    }
                } else {
                    if (lv == 1) {
                        if (self.debug_namewhat_override) |nwo| {
                            try self.setField(t, "namewhat", .{ .String = try self.internStr(nwo) });
                            if (self.debug_name_override) |nmo| {
                                try self.setField(t, "name", .{ .String = try self.internStr(nmo) });
                            } else {
                                try self.setField(t, "name", .Nil);
                            }
                        } else {
                            const inferred = self.debugInferNameFromCaller(self.debugResolveFrameIndex(lv + 1), fr.*);
                            if (inferred.name) |nm| {
                                try self.setField(t, "name", .{ .String = try self.internStr(nm) });
                            } else if (fr.proto != null and fr.funcName().len != 0 and
                                !std.mem.eql(u8, fr.funcName(), "main") and
                                !std.mem.eql(u8, fr.funcName(), "<bytecode>"))
                            {
                                try self.setField(t, "name", .{ .String = try self.internStr(fr.funcName()) });
                            } else if (self.isInDebugHook() and lv == 2) {
                                try self.setField(t, "name", .{ .String = try self.internStr("?") });
                            } else {
                                try self.setField(t, "name", .Nil);
                            }
                            const namewhat = if (inferred.name == null and fr.proto != null and fr.funcName().len != 0 and
                                !std.mem.eql(u8, fr.funcName(), "main") and
                                !std.mem.eql(u8, fr.funcName(), "<bytecode>"))
                                "local"
                            else
                                inferred.namewhat;
                            try self.setField(t, "namewhat", .{ .String = try self.internStr(namewhat) });
                        }
                    } else {
                        // For lv > 1: try name inference first. Only fall back
                        // to synthetic pcall name when the frame has no proto
                        // (pcall boundary frame from tryPushBytecodeProtectedCall).
                        if (fr.proto == null and lv == 2 and self.activeProtectedCallDepth() > 0) {
                            try self.setField(t, "name", .{ .String = try self.internStr("pcall") });
                            try self.setField(t, "namewhat", .{ .String = try self.internStr("global") });
                        } else {
                            const inferred = self.debugInferNameFromCaller(self.debugResolveFrameIndex(lv + 1), fr.*);
                            if (self.isInDebugHook() and lv == 2 and self.debugNameFromCallee(fr.callee) != null) {
                                try self.setField(t, "name", .{ .String = try self.internStr(self.debugNameFromCallee(fr.callee).?) });
                            } else if (self.isInDebugHook() and lv == 2 and self.debug_name_override != null) {
                                const raw = self.debug_name_override.?;
                                if (std.mem.eql(u8, raw, "__close") and self.testc_close_metamethod_depth != 0) {
                                    try self.setField(t, "name", .{ .String = try self.internStr("?") });
                                } else {
                                    const nm = if (std.mem.startsWith(u8, raw, "__") and raw.len > 2) raw[2..] else raw;
                                    try self.setField(t, "name", .{ .String = try self.internStr(nm) });
                                }
                            } else if (inferred.name) |nm| {
                                try self.setField(t, "name", .{ .String = try self.internStr(nm) });
                            } else if (self.isInDebugHook() and lv == 2) {
                                try self.setField(t, "name", .{ .String = try self.internStr("?") });
                            } else {
                                try self.setField(t, "name", .Nil);
                            }
                            try self.setField(t, "namewhat", .{ .String = try self.internStr(inferred.namewhat) });
                        }
                    }
                }
                // Re-derive current_line from lineinfo (fast path no longer updates it).
                if (fr.proto) |proto| {
                    if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                        fr.current_line = @intCast(proto.lineinfo[fr.pc]);
                    }
                }
                const cur_line: i64 = if (fr.proto) |proto|
                    (if (proto.lineinfo.len == 0) -1 else fr.current_line)
                else
                    fr.current_line;
                try self.setField(t, "currentline", .{ .Int = cur_line });
                if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                    const is_tail = if (self.isInDebugHook() and lv == 2 and self.activeDebugHookEventCalllike())
                        self.activeDebugHookEventTailcall()
                    else
                        fr.is_tailcall;
                    const extraargs: i64 = if (fr.isVararg()) @intCast(self.frameVarargs(fr).len) else 0;
                    try self.setField(t, "istailcall", .{ .Bool = is_tail });
                    try self.setField(t, "extraargs", .{ .Int = extraargs });
                }
                if (debugInfoHasOpt(what, 'r')) {
                    if (self.isInDebugHook() and lv == 2) {
                        if (self.activeDebugTransferValues()) |vals| {
                            try self.setField(t, "ftransfer", .{ .Int = self.activeDebugTransferStart() });
                            try self.setField(t, "ntransfer", .{ .Int = @intCast(vals.len) });
                        } else {
                            try self.setField(t, "ftransfer", .{ .Int = 1 });
                            try self.setField(t, "ntransfer", .{ .Int = 0 });
                        }
                    } else {
                        try self.setField(t, "ftransfer", .{ .Int = 1 });
                        try self.setField(t, "ntransfer", .{ .Int = 0 });
                    }
                }
                if (what.len == 0 or debugInfoHasOpt(what, 'f')) {
                    try self.setField(t, "func", fr.callee);
                }
                if (fr.proto != null and fr.callee == .Closure) {
                    // Bytecode source/debug metadata belongs to Proto.
                    try self.debugFillInfoFromFunction(t, fr.callee, what);
                }
            },
            .Builtin, .Closure => {
                if (target_thread != null) {
                    return self.fail("bad argument #1 to 'getinfo' (function or level expected)", .{});
                }
                try self.setField(t, "name", .Nil);
                try self.setField(t, "namewhat", .{ .String = try self.internStr("") });
                if (what.len == 0 or debugInfoHasOpt(what, 't')) {
                    try self.setField(t, "istailcall", .{ .Bool = false });
                    try self.setField(t, "extraargs", .{ .Int = 0 });
                }
                try self.debugFillInfoFromFunction(t, args[i], what);
            },
            else => return self.fail("bad argument #1 to 'getinfo' (function or level expected)", .{}),
        }

        if (outs.len > 0) outs[0] = .{ .Table = t };
    }

    fn debugInstructionDestination(proto: *const bc.Proto, pc: usize) ?usize {
        if (pc >= proto.code.len) return null;
        const inst = proto.code[pc];
        const op: bc.Op = @enumFromInt(inst.op);
        return switch (op) {
            .move,
            .loadk,
            .loadkx,
            .loadi,
            .loadf,
            .loadnil,
            .loadtrue,
            .loadfalse,
            .lfalseskip,
            .gettabup,
            .getupval,
            .gettable,
            .geti,
            .getfield,
            .newtable,
            .self,
            .add,
            .sub,
            .mul,
            .div,
            .mod,
            .pow,
            .idiv,
            .addi,
            .addk,
            .subk,
            .mulk,
            .modk,
            .powk,
            .divk,
            .idivk,
            .band,
            .bor,
            .bxor,
            .shl,
            .shr,
            .bandk,
            .bork,
            .bxork,
            .shli,
            .shri,
            .unm,
            .bnot,
            .not,
            .len,
            .concat,
            .testset,
            .closure,
            .vararg,
            => inst.a,
            else => null,
        };
    }

    fn debugGetLocalFromBytecodeFrame(self: *Vm, fr: *const Frame, proto: *const bc.Proto, idx: i64, outs: []Value) DispatchError!void {
        if (idx == 0) return;
        if (idx < 0) {
            if (!proto.is_vararg) return;
            const pos_i = -idx - 1;
            if (pos_i < 0) return;
            const pos: usize = @intCast(pos_i);
            if (pos >= self.frameVarargs(fr).len) return;
            if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg)") };
            if (outs.len > 1) outs[1] = self.frameVarargs(fr)[pos];
            return;
        }

        const pc: u32 = @intCast(@min(fr.pc, std.math.maxInt(u32)));
        var rank: i64 = 0;
        const exposes_vararg_table = proto.is_vararg and proto.line_defined != 0;
        var inserted_vararg_table = false;
        var has_named_active_local = false;
        var active_regs = std.StaticBitSet(256).initEmpty();
        for (proto.locvars) |local| {
            if (local.name.len == 0 or local.reg >= fr.regs.len) continue;
            if (pc < local.startpc or pc >= local.endpc) continue;
            if (exposes_vararg_table and !inserted_vararg_table and local.reg >= proto.numparams) {
                inserted_vararg_table = true;
                rank += 1;
                if (rank == idx) {
                    if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg table)") };
                    if (outs.len > 1) outs[1] = .Nil;
                    return;
                }
            }
            active_regs.set(local.reg);
            has_named_active_local = true;
            rank += 1;
            if (rank == idx) {
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr(local.name) };
                if (outs.len > 1) outs[1] = fr.regs[local.reg];
                return;
            }
        }
        if (exposes_vararg_table and !inserted_vararg_table) {
            rank += 1;
            if (rank == idx) {
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg table)") };
                if (outs.len > 1) outs[1] = .Nil;
                return;
            }
        }

        // PUC exposes the destination of the current instruction as a
        // temporary before a lexical local becomes active. Its value may still
        // be nil (for example immediately before OP_CLOSURE initializes a
        // local-function slot), so value-based scanning alone is insufficient.
        const instruction_temp = debugInstructionDestination(proto, fr.pc);
        if (instruction_temp) |reg| {
            if (reg < fr.regs.len and !(reg < 256 and active_regs.isSet(reg))) {
                rank += 1;
                if (rank == idx) {
                    if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(temporary)") };
                    if (outs.len > 1) outs[1] = fr.regs[reg];
                    return;
                }
            }
        }

        // PUC exposes other live unnamed registers after lexical locals as
        // temporaries. Keep this fallback for debug-suite arithmetic and hook
        // checks, but never let it displace a named active LocVar.
        // Bound the scan by live_reg_top[pc] (our equivalent of PUC's L->top):
        // only registers below the live boundary are valid roots. Without this
        // bound, stale values from a previous frame's window would be exposed
        // as phantom temporaries. Fall back to full window for legacy/external
        // protos that lack live_reg_top.
        const live_top: usize = if (fr.pc < proto.live_reg_top.len)
            @min(proto.live_reg_top[fr.pc], fr.regs.len)
        else if (proto.live_reg_top.len > 0)
            fr.nvarstack
        else
            fr.regs.len;
        var reg: usize = 0;
        while (reg < live_top) : (reg += 1) {
            if (instruction_temp != null and instruction_temp.? == reg) continue;
            if ((reg < 256 and active_regs.isSet(reg)) or fr.regs[reg] == .Nil) continue;
            switch (fr.regs[reg]) {
                .Builtin => continue,
                .Closure => if (has_named_active_local) continue,
                else => {},
            }
            rank += 1;
            if (rank == idx) {
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(temporary)") };
                if (outs.len > 1) outs[1] = fr.regs[reg];
                return;
            }
        }
    }

    fn debugSetLocalInBytecodeFrame(self: *Vm, fr: *Frame, proto: *const bc.Proto, idx: i64, value: Value, outs: []Value) DispatchError!void {
        if (idx == 0) return;
        if (idx < 0) {
            if (!proto.is_vararg) return;
            const pos_i = -idx - 1;
            if (pos_i < 0) return;
            const pos: usize = @intCast(pos_i);
            if (pos >= self.frameVarargs(fr).len) return;
            self.frameVarargs(fr)[pos] = value;
            if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg)") };
            return;
        }

        const pc: u32 = @intCast(@min(fr.pc, std.math.maxInt(u32)));
        var rank: i64 = 0;
        const exposes_vararg_table = proto.is_vararg and proto.line_defined != 0;
        var inserted_vararg_table = false;
        var has_named_active_local = false;
        var active_regs = std.StaticBitSet(256).initEmpty();
        for (proto.locvars) |local| {
            if (local.name.len == 0 or local.reg >= fr.regs.len) continue;
            if (pc < local.startpc or pc >= local.endpc) continue;
            if (exposes_vararg_table and !inserted_vararg_table and local.reg >= proto.numparams) {
                inserted_vararg_table = true;
                rank += 1;
                if (rank == idx) {
                    if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg table)") };
                    return;
                }
            }
            active_regs.set(local.reg);
            has_named_active_local = true;
            rank += 1;
            if (rank == idx) {
                fr.regs[local.reg] = value;
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr(local.name) };
                return;
            }
        }
        if (exposes_vararg_table and !inserted_vararg_table) {
            rank += 1;
            if (rank == idx) {
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(vararg table)") };
                return;
            }
        }

        const instruction_temp = debugInstructionDestination(proto, fr.pc);
        if (instruction_temp) |reg| {
            if (reg < fr.regs.len and !(reg < 256 and active_regs.isSet(reg))) {
                rank += 1;
                if (rank == idx) {
                    fr.regs[reg] = value;
                    if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(temporary)") };
                    return;
                }
            }
        }

        // Bound the temp-scan by live_reg_top[pc] — same as getlocal.
        // Fall back to full window for legacy/external protos without it.
        const live_top: usize = if (fr.pc < proto.live_reg_top.len)
            @min(proto.live_reg_top[fr.pc], fr.regs.len)
        else if (proto.live_reg_top.len > 0)
            fr.nvarstack
        else
            fr.regs.len;
        var reg: usize = 0;
        while (reg < live_top) : (reg += 1) {
            if (instruction_temp != null and instruction_temp.? == reg) continue;
            if ((reg < 256 and active_regs.isSet(reg)) or fr.regs[reg] == .Nil) continue;
            switch (fr.regs[reg]) {
                .Builtin => continue,
                .Closure => if (has_named_active_local) continue,
                else => {},
            }
            rank += 1;
            if (rank == idx) {
                fr.regs[reg] = value;
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(temporary)") };
                return;
            }
        }
    }

    fn debugGetLocalFromFrame(self: *Vm, fr: *const Frame, idx: i64, outs: []Value) DispatchError!void {
        // All frames are bytecode frames; delegate to the bytecode path.
        const proto = fr.proto orelse return;
        return self.debugGetLocalFromBytecodeFrame(fr, proto, idx, outs);
    }

    fn threadCurrentParkedRuntimeFrame(th: *Thread) ?*CallFrame {
        // P15.40b-full: Bytecode frames are in th.call_frames.
        if (!th.bytecode_inplace_suspended or th.call_frames.len() == 0) return null;
        return th.call_frames.getPtr(th.call_frames.len() - 1);
    }

    fn debugGetLocalNameFromProto(self: *Vm, proto: *const bc.Proto, idx: i64, outs: []Value) DispatchError!void {
        if (idx <= 0) return;
        const wanted: usize = @intCast(idx - 1);
        if (wanted >= proto.numparams) return;

        // Parameters occupy registers 0..numparams-1. LocVar includes the
        // exact register, so do not depend on declaration-list ordering when
        // answering debug.getlocal(function, n).
        for (proto.locvars) |local| {
            if (local.reg != wanted or local.name.len == 0) continue;
            if (outs.len > 0) outs[0] = .{ .String = try self.internStr(local.name) };
            if (outs.len > 1) outs[1] = .Nil;
            return;
        }
    }

    fn debugSetLocalInFrame(self: *Vm, fr: *Frame, idx: i64, val: Value, outs: []Value) DispatchError!void {
        // All frames are bytecode frames; delegate to the bytecode path.
        const proto = fr.proto orelse return;
        return self.debugSetLocalInBytecodeFrame(fr, proto, idx, val, outs);
    }

    fn builtinDebugGetlocal(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;

        var i: usize = 0;
        var target_thread: ?*Thread = null;
        if (args.len > 0 and args[0] == .Thread) {
            target_thread = try self.expectThread(args[0]);
            i = 1;
        }
        if (i + 1 >= args.len) return self.fail("debug.getlocal expects (level|func, local)", .{});
        const target = args[i];
        const local_index = switch (args[i + 1]) {
            .Int => |idx| idx,
            else => return self.fail("bad argument #2 to 'getlocal' (integer expected)", .{}),
        };

        switch (target) {
            .Int => |level| {
                if (target_thread) |th| {
                    if (level < 0 or level > 1 or local_index < 1) return;
                    if (threadCurrentParkedRuntimeFrame(th)) |fr| {
                        const proto = fr.proto orelse return;
                        try self.debugGetLocalFromBytecodeFrame(fr, proto, local_index, outs);
                        return;
                    }
                    if (th.suspended_builtin != null) {
                        if (local_index == 1) {
                            if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(C temporary)") };
                            if (outs.len > 1) outs[1] = .Nil;
                            return;
                        }
                        if (th.suspended_builtin_args) |vals| {
                            const pos: usize = @intCast(local_index - 1);
                            if (pos < vals.len) {
                                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(C temporary)") };
                                if (outs.len > 1) outs[1] = vals[pos];
                            }
                        }
                    }
                    return;
                }
                if (level < 0) return self.fail("bad level", .{});
                if (level == 0) {
                    if (local_index == 1) {
                        if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(C temporary)") };
                        if (outs.len > 1) outs[1] = .{ .Int = 0 };
                        return;
                    }
                    if (local_index == 2) {
                        if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(C temporary)") };
                        if (outs.len > 1) outs[1] = .{ .Int = 2 };
                        return;
                    }
                    return;
                }
                const lv: usize = @intCast(level);
                const fr = self.debugResolveFrameIndex(lv) orelse return self.fail("bad level", .{});
                if (self.isInDebugHook() and lv == 2) {
                    if (self.activeDebugTransferValues()) |vals| {
                        const start = self.activeDebugTransferStart();
                        if (local_index >= start) {
                            const rel = local_index - start;
                            if (rel >= 0 and @as(usize, @intCast(rel)) < vals.len) {
                                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("(temporary)") };
                                if (outs.len > 1) outs[1] = vals[@intCast(rel)];
                                return;
                            }
                        }
                    }
                }
                try self.debugGetLocalFromFrame(fr, local_index, outs);
            },
            .Closure => |cl| {
                if (cl.proto) |proto| {
                    try self.debugGetLocalNameFromProto(proto, local_index, outs);
                }
            },
            .Builtin => {},
            else => return self.fail("bad argument #1 to 'getlocal' (function or level expected)", .{}),
        }
    }

    fn builtinDebugSetlocal(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;

        var i: usize = 0;
        var target_thread: ?*Thread = null;
        if (args.len > 0 and args[0] == .Thread) {
            target_thread = try self.expectThread(args[0]);
            i = 1;
        }
        if (i + 2 >= args.len) return self.fail("debug.setlocal expects (level|func, local, value)", .{});
        const target = args[i];
        const local_index = switch (args[i + 1]) {
            .Int => |idx| idx,
            else => return self.fail("bad argument #2 to 'setlocal' (integer expected)", .{}),
        };
        const new_value = args[i + 2];

        switch (target) {
            .Int => |level| {
                if (target_thread) |th| {
                    if (level < 0 or level > 1 or local_index < 1) return;
                    if (threadCurrentParkedRuntimeFrame(th)) |fr| {
                        const proto = fr.proto orelse return;
                        try self.debugSetLocalInBytecodeFrame(fr, proto, local_index, new_value, outs);
                        return;
                    }
                    return;
                }
                if (level < 1) return self.fail("bad level", .{});
                const lv: usize = @intCast(level);
                const fr = self.debugResolveFrameIndex(lv) orelse return self.fail("bad level", .{});
                try self.debugSetLocalInFrame(fr, local_index, new_value, outs);
            },
            .Closure, .Builtin => {},
            else => return self.fail("bad argument #1 to 'setlocal' (function or level expected)", .{}),
        }
    }

    fn debugUpvalueName(cl: *const Closure, uidx: usize) []const u8 {
        // For bytecode closures, upvalue names live in the Proto.
        if (cl.proto) |p| {
            if (uidx < p.upvalues.len) {
                const nm = p.upvalues[uidx].name;
                if (nm.len != 0) return nm;
            }
            if (uidx == 0 and p.line_defined == 0) return "_ENV";
            return "(no name)";
        }
        return "(no name)";
    }

    fn builtinDebugGetupvalue(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;
        if (args.len < 2) return self.fail("debug.getupvalue expects (func, up)", .{});
        const idx = switch (args[1]) {
            .Int => |i| i,
            else => return self.fail("bad argument #2 to 'getupvalue' (integer expected)", .{}),
        };
        if (idx < 1) return;
        const uidx: usize = @intCast(idx - 1);
        switch (args[0]) {
            .Closure => |cl| {
                if (uidx >= cl.upvalues.len) {
                    return;
                }
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr(debugUpvalueName(cl, uidx)) };
                if (outs.len > 1) outs[1] = cl.upvalues[uidx].get(self);
            },
            .Builtin => {
                if (uidx != 0) return;
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr("") };
            },
            else => return self.fail("bad argument #1 to 'getupvalue' (function expected)", .{}),
        }
    }

    fn builtinDebugSetupvalue(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (args.len < 3) return self.fail("debug.setupvalue expects (func, up, value)", .{});
        const idx = switch (args[1]) {
            .Int => |i| i,
            else => return self.fail("bad argument #2 to 'setupvalue' (integer expected)", .{}),
        };
        if (idx < 1) return;
        const uidx: usize = @intCast(idx - 1);
        switch (args[0]) {
            .Closure => |cl| {
                if (uidx >= cl.upvalues.len) {
                    return;
                }
                try self.gcStoreCellValue(cl.upvalues[uidx], args[2]);
                if (outs.len > 0) outs[0] = .{ .String = try self.internStr(debugUpvalueName(cl, uidx)) };
            },
            .Builtin => {},
            else => return self.fail("bad argument #1 to 'setupvalue' (function expected)", .{}),
        }
    }

    fn builtinDebugUpvalueid(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (args.len < 2) return self.fail("debug.upvalueid expects (func, up)", .{});
        const idx = switch (args[1]) {
            .Int => |i| i,
            else => return self.fail("bad argument #2 to 'upvalueid' (integer expected)", .{}),
        };
        if (idx < 1) return;
        const uidx: usize = @intCast(idx - 1);
        switch (args[0]) {
            .Closure => |cl| {
                if (uidx >= cl.upvalues.len) {
                    return;
                }
                if (outs.len > 0) outs[0] = try self.debugLightUserdataForId(@intCast(@intFromPtr(cl.upvalues[uidx])));
            },
            .Builtin => |id| {
                if (uidx != 0) return;
                if (outs.len > 0) outs[0] = try self.debugLightUserdataForId(0x4000_0000 + @as(u64, @intFromEnum(id)));
            },
            else => return self.fail("bad argument #1 to 'upvalueid' (function expected)", .{}),
        }
    }

    fn debugLightUserdataForId(self: *Vm, id: u64) DispatchError!Value {
        _ = self;
        return .{ .LightUserdata = @ptrFromInt(id) };
    }

    fn builtinDebugUpvaluejoin(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = outs;
        if (args.len < 4) return self.fail("debug.upvaluejoin expects (f1,n1,f2,n2)", .{});
        const f1 = switch (args[0]) {
            .Closure => |cl| cl,
            else => return self.fail("bad argument #1 to 'upvaluejoin' (function expected)", .{}),
        };
        const n1 = switch (args[1]) {
            .Int => |i| i,
            else => return self.fail("bad argument #2 to 'upvaluejoin' (integer expected)", .{}),
        };
        const f2 = switch (args[2]) {
            .Closure => |cl| cl,
            else => return self.fail("bad argument #3 to 'upvaluejoin' (function expected)", .{}),
        };
        const n2 = switch (args[3]) {
            .Int => |i| i,
            else => return self.fail("bad argument #4 to 'upvaluejoin' (integer expected)", .{}),
        };
        if (n1 < 1 or n2 < 1) return self.fail("invalid upvalue index", .{});
        const idx1: usize = @intCast(n1 - 1);
        const idx2: usize = @intCast(n2 - 1);
        if (idx1 >= f1.upvalues.len or idx2 >= f2.upvalues.len) return self.fail("invalid upvalue index", .{});
        @constCast(f1.upvalues)[idx1] = f2.upvalues[idx2];
        try self.gcForwardBarrierCell(f1, f2.upvalues[idx2]);
    }

    fn debugDispatchHookTransfer(self: *Vm, event: []const u8, line: ?i64, transfer: ?[]const Value, transfer_start: i64) DispatchError!void {
        // P15.38f: Fast path — if no hooks are active on the current thread,
        // skip the whole hook dispatch (linear search + string compare + deref).
        // Mirrors PUC Lua's `if (l_unlikely(hookmask & mask))` check: when
        // hookmask is 0, no hook can fire. `hooks_active_cached` is refreshed
        // by refreshHooksCached() on every sethook and thread switch.
        if (!self.hooks_active_cached) return;
        if (self.debug_hooks_suppressed != 0) return;
        if (self.isInDebugHook()) return;
        const hook_state = self.activeHookState();
        const hook = hook_state.func orelse return;
        if (hook == .Nil) return;

        const match = if (std.mem.eql(u8, event, "call") or std.mem.eql(u8, event, "tail call"))
            hook_state.has_call
        else if (std.mem.eql(u8, event, "return"))
            hook_state.has_return
        else if (std.mem.eql(u8, event, "line"))
            hook_state.has_line
        else if (std.mem.eql(u8, event, "count"))
            hook_state.count > 0
        else
            true;
        if (!match) return;

        var argv_buf: [2]Value = undefined;
        argv_buf[0] = .{ .String = try self.internStr(event) };
        var argc: usize = 1;
        const hook_line = line;
        if (hook_line) |l| {
            argv_buf[1] = .{ .Int = l };
            argc = 2;
        }

        const saved_transfer = self.debug_transfer_values;
        const saved_transfer_start = self.debug_transfer_start;
        const saved_calllike = self.debug_hook_event_calllike;
        const saved_tailcall = self.debug_hook_event_tailcall;
        const saved_is_count = self.debug_hook_event_is_count;
        const saved_allow_yield = self.debug_hook_allow_yield;
        self.debug_transfer_values = transfer;
        self.debug_transfer_start = transfer_start;
        self.debug_hook_event_calllike = std.mem.eql(u8, event, "call") or std.mem.eql(u8, event, "tail call");
        self.debug_hook_event_tailcall = std.mem.eql(u8, event, "tail call");
        self.debug_hook_event_is_count = std.mem.eql(u8, event, "count");
        self.debug_hook_allow_yield = hook_state.allow_yield;
        defer {
            self.debug_transfer_values = saved_transfer;
            self.debug_transfer_start = saved_transfer_start;
            self.debug_hook_event_calllike = saved_calllike;
            self.debug_hook_event_tailcall = saved_tailcall;
            self.debug_hook_event_is_count = saved_is_count;
            self.debug_hook_allow_yield = saved_allow_yield;
        }

        // P15.38f: Set per-thread in_debug_hook (PUC's allowhook=0) so that
        // isInDebugHook() returns true without a linear frame search.
        const hook_state_for_flag = self.activeHookState();
        hook_state_for_flag.in_debug_hook = true;
        defer hook_state_for_flag.in_debug_hook = false;

        switch (hook) {
            .Builtin => |id| {
                var outs: [0]Value = .{};
                try self.callBuiltin(id, argv_buf[0..argc], outs[0..]);
            },
            .Closure => |cl| {
                const ret = try self.runClosure(cl, argv_buf[0..argc]);
                self.alloc.free(ret);
            },
            else => {},
        }
    }

    fn debugCallTransferArgsForClosure(cl: *const Closure, call_args: []const Value) []const Value {
        const nparams: usize = if (cl.proto) |proto| proto.numparams else 0;
        const n = @min(call_args.len, nparams);
        return call_args[0..n];
    }

    fn debugDispatchHookWithCalleeTransfer(self: *Vm, event: []const u8, line: ?i64, callee: Value, transfer: ?[]const Value, transfer_start: i64) DispatchError!void {
        // P15.38f: Fast path — no hooks active, skip callee save/restore + dispatch.
        if (!self.hooks_active_cached) return;
        _ = callee; // Callee save/restore was only meaningful for IR frames
                    // (Vm.call_frames), which is always empty now. The hook
                    // receives the event/line/transfer directly.
        try self.debugDispatchHookTransfer(event, line, transfer, transfer_start);
    }

    fn builtinDebugGethook(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        const target_thread = if (args.len > 0) try self.expectThread(args[0]) else null;
        const hook_state = self.hookStateFor(target_thread);
        if (outs.len == 0) return;
        if (hook_state.func) |f| {
            outs[0] = f;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(hook_state.mask) };
            if (outs.len > 2) outs[2] = .{ .Int = hook_state.count };
            return;
        }
        outs[0] = .Nil;
    }

    fn ensureDebugRegistry(self: *Vm) DispatchError!*Table {
        if (self.debug_registry) |r| return r;
        var roots = self.gcTempRoots();
        defer roots.end();

        const reg = try self.allocTable();
        try roots.add(.{ .Table = reg });

        const hookkey = try self.allocTable();
        try roots.add(.{ .Table = hookkey });

        const mt = try self.allocTable();
        try self.setField(mt, "__mode", .{ .String = try self.internStr("k") });
        hookkey.metatable = mt;
        try self.setField(reg, "_HOOKKEY", .{ .Table = hookkey });
        self.debug_registry = reg;
        return reg;
    }

    fn builtinDebugGetregistry(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = args;
        if (outs.len == 0) return;
        const reg = try self.ensureDebugRegistry();
        outs[0] = .{ .Table = reg };
    }

    fn builtinDebugSetmetatable(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len < 2) return self.fail("debug.setmetatable expects (value, metatable)", .{});
        const mt: ?*Table = switch (args[1]) {
            .Nil => null,
            .Table => |t| t,
            else => return self.fail("bad argument #2 to 'setmetatable' (nil or table expected)", .{}),
        };
        switch (args[0]) {
            .Table => |tbl| {
                try self.gcStoreMetatable(tbl, mt);
                if (mt) |m| {
                    if (self.fasttm(m, .gc) != null) {
                        try self.registerFinalizable(.{ .table = tbl });
                    } else {
                        _ = self.finalizables.remove(.{ .table = tbl });
                    }
                } else {
                    _ = self.finalizables.remove(.{ .table = tbl });
                }
            },
            .String => {
                if (mt) |m| {
                    self.string_metatable = m;
                    self.string_metatable_enabled = true;
                } else {
                    self.string_metatable_enabled = false;
                }
            },
            .Int, .Num => self.number_metatable = mt,
            .Bool => self.boolean_metatable = mt,
            .Nil => self.nil_metatable = mt,
            .Builtin, .Closure => self.function_metatable = mt,
            .Thread => self.thread_metatable = mt,
            .LightUserdata => self.light_userdata_metatable = mt,
            .Userdata => |ud| {
                // PUC debug.setmetatable on userdata sets the per-object
                // metatable directly (ldblib.c:354-357). Unlike tables,
                // userdata metatables don't use the BITRAS flags cache.
                ud.metatable = mt;
                // PUC luaC_objbarrier: forward write barrier — if the userdata
                // is old/black and the metatable is young/white, the barrier
                // marks the metatable (generational) or restores the tri-color
                // invariant (incremental). Without this, a young metatable
                // could be swept while still referenced by an old userdata.
                if (mt) |m| {
                    try self.gcForwardBarrierValue(.{ .Userdata = ud }, .{ .Table = m });
                    // PUC: if the metatable has __gc, register the userdata
                    // (not the metatable) as finalizable. The userdata is
                    // what becomes unreachable; the metatable stays alive
                    // through the userdata. During the atomic phase, white
                    // (unreachable) userdatas in the finalizables set are
                    // queued for __gc finalization.
                    if (self.fasttm(m, .gc) != null) {
                        try self.registerFinalizable(.{ .userdata = ud });
                    } else {
                        _ = self.finalizables.remove(.{ .userdata = ud });
                    }
                } else {
                    _ = self.finalizables.remove(.{ .userdata = ud });
                }
            },
        }
        if (outs.len > 0) outs[0] = args[0];
    }

    fn builtinDebugTraceback(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;

        var i: usize = 0;
        var thread_arg: ?*Thread = null;
        if (args.len > 0 and args[0] == .Thread) {
            thread_arg = try self.expectThread(args[0]);
            i = 1;
        }

        var msg: []const u8 = "";
        if (i < args.len) {
            switch (args[i]) {
                .String => |s| msg = s.bytes(),
                .Nil => {},
                else => {
                    // Lua: if first non-thread argument is not a string (and
                    // not nil), traceback returns it unchanged.
                    outs[0] = args[i];
                    return;
                },
            }
            i += 1;
        }

        var level: i64 = if (thread_arg != null) 0 else 1;
        if (i < args.len and args[i] != .Nil) {
            level = switch (args[i]) {
                .Int => |n| n,
                .Num => |n| @as(i64, @intFromFloat(@floor(n))),
                else => level,
            };
        }
        if (level < 0) level = 0;

        const body = if (thread_arg) |th|
            try self.debugBuildThreadTraceback(th, level)
        else if (self.err_traceback) |tb|
            // During xpcall message handling the original traceback was
            // captured at error point. Reuse it to avoid losing deep frames
            // after unwind.
            try self.alloc.dupe(u8, tb)
        else
            try self.debugBuildCurrentTraceback(level);

        if (msg.len != 0) {
            outs[0] = .{ .String = try self.internStr(try std.fmt.allocPrint(self.alloc, "{s}\n{s}", .{ msg, body })) };
        } else {
            outs[0] = .{ .String = try self.internStr(body) };
        }
    }

    /// PUC `db_debug` (ldblib.c:423-435): interactive debugger REPL.
    ///
    /// Reads lines from stdin, compiles+executes each as Lua code with chunk
    /// name "=(debug command)", and prints any error message to stderr.
    /// Exits on EOF or when the line is "cont".
    ///
    /// Like PUC, the prompt "lua_debug> " is written to stderr (via
    /// `lua_writestringerror`), and error messages are followed by a newline.
    /// The executed chunk runs with `_ENV` bound to the global environment,
    /// matching PUC's `luaL_loadbuffer` + `lua_pcall` semantics.
    fn builtinDebugDebug(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = args;
        _ = outs;

        const io = stdio.activeIo();
        const alloc = self.alloc;
        var line_buf = std.ArrayListUnmanaged(u8).empty;
        defer line_buf.deinit(alloc);

        while (true) {
            // Print the prompt to stderr (no newline, matching PUC
            // lua_writestringerror("%s", "lua_debug> ")).
            var errw = stdio.stderr();
            errw.print("lua_debug> ", .{}) catch {};

            // Read one line from stdin (without the trailing newline).
            line_buf.clearRetainingCapacity();
            if (!debugReadLine(io, alloc, &line_buf)) break;

            // Exit on "cont" command (PUC compares "cont\n" including the
            // newline; we strip the newline and compare "cont", which is
            // equivalent for piped input and more robust at EOF).
            if (std.mem.eql(u8, line_buf.items, "cont")) break;

            // Skip empty lines (PUC's luaL_loadbuffer would succeed but do
            // nothing; avoiding the compile call is a harmless optimization).
            if (line_buf.items.len == 0) continue;

            // Compile the line as a Lua text chunk with the canonical
            // debug-command chunk name "=(debug command)".
            const source = LuaSource{ .name = "=(debug command)", .bytes = line_buf.items };
            const compiled = try self.compileTextChunk(source);
            const cl = switch (compiled) {
                .closure => |closure| closure,
                .diagnostic => |diagnostic| {
                    defer alloc.free(diagnostic);
                    var e2 = stdio.stderr();
                    e2.print("{s}\n", .{diagnostic}) catch {};
                    continue;
                },
            };

            // Apply _ENV = _G so the debug command sees globals.
            try self.applyLoadEnv(cl, .{ .Table = self.global_env }, false);

            // Run the chunk in a protected context (pcall semantics).
            // PUC uses lua_pcall(L, 0, 0, 0); on error, the message is on the
            // stack and printed via luaL_tolstring. We mirror this by catching
            // the error and printing the formatted error string to stderr.
            const prev_err = self.err;
            const prev_err_obj = self.err_obj;
            const prev_err_has_obj = self.err_has_obj;
            const prev_err_source = self.err_source;
            const prev_err_line = self.err_line;
            const prev_err_traceback = self.err_traceback;
            self.err_traceback = null;

            self.protected_call_depth += 1;
            defer self.protected_call_depth -= 1;
            self.enterProtectedCFrame();
            defer self.leaveProtectedCFrame();
            defer self.shrinkBcStack();

            const ret = self.runClosure(cl, &.{}) catch |e| switch (e) {
                error.Yield => return error.Yield,
                else => {
                    // Error: print the error message + newline to stderr,
                    // matching PUC's lua_writestringerror("%s\n", ...).
                    const msg = self.protectedErrorString();
                    var e3 = stdio.stderr();
                    e3.print("{s}\n", .{msg}) catch {};
                    // Restore preserved error state (pcall swallows the error).
                    self.clearErrorTraceback();
                    self.err = prev_err;
                    self.err_obj = prev_err_obj;
                    self.err_has_obj = prev_err_has_obj;
                    self.err_source = prev_err_source;
                    self.err_line = prev_err_line;
                    self.err_traceback = prev_err_traceback;
                    continue;
                },
            };
            defer alloc.free(ret);

            // PUC lua_settop(L, 0): discard any return values. Our ret slice
            // is freed by the defer above, so nothing else to do.

            // Restore preserved error state (no error occurred, but clear any
            // transient state set during execution).
            self.clearErrorTraceback();
            self.err = prev_err;
            self.err_obj = prev_err_obj;
            self.err_has_obj = prev_err_has_obj;
            self.err_source = prev_err_source;
            self.err_line = prev_err_line;
            self.err_traceback = prev_err_traceback;
        }
    }

    /// Read one line from stdin (without the trailing newline) into `buf`.
    /// Returns false on EOF (no bytes read), true otherwise.
    /// Mirrors PUC's fgets-based line reading but uses Zig's native std.Io API.
    fn debugReadLine(io: std.Io, alloc: std.mem.Allocator, buf: *std.ArrayListUnmanaged(u8)) bool {
        var byte: [1]u8 = undefined;
        while (true) {
            const n = std.Io.File.stdin().readStreaming(io, &.{byte[0..]}) catch return false;
            if (n == 0) {
                // EOF: if we read any bytes, return them; otherwise signal EOF.
                return buf.items.len > 0;
            }
            if (byte[0] == '\n') return true;
            buf.append(alloc, byte[0]) catch return false;
        }
    }

    fn tracebackFrameLabel(self: *Vm, fr: *const Frame, caller_opt: ?*const Frame, top_hook_frame: bool) DispatchError![]const u8 {
        if (top_hook_frame and self.isInDebugHook()) {
            return try std.fmt.allocPrint(self.alloc, "hook", .{});
        }

        // Resolve source name via PUC luaO_chunkid (lobject.c:682-718).
        // This produces the short_src used in tracebacks: strips '@'/'='
        // prefixes and truncates long file names with '...' prefix.
        const src_raw = fr.sourceName();
        var id_buf: [59]u8 = undefined;
        const src = diag.chunkId(id_buf[0..], src_raw);
        const shown_src: []const u8 = if (src.len != 0) src else "?";

        // Re-derive current_line from lineinfo (fast path no longer updates it).
        const cur_line: i64 = blk: {
            if (fr.proto) |proto| {
                if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                    break :blk @intCast(proto.lineinfo[fr.pc]);
                }
            }
            break :blk fr.current_line;
        };
        const line: i64 = if (cur_line > 0) cur_line else @as(i64, fr.lineDefined());

        // PUC pushfuncname (lauxlib.c:96-109): resolve function name from the
        // call site (caller frame). debugInferNameFromCaller returns namewhat
        // ("global", "local", "upvalue", "field", "method", "for iterator")
        // and the corresponding name.
        //
        // Debug hooks may set debug_namewhat/debug_name directly; prefer those
        // when available (they include "metamethod" which inference doesn't).
        var namewhat: ?[]const u8 = null;
        var name: ?[]const u8 = null;
        if (fr.debug_namewhat) |nw| {
            namewhat = nw;
            name = fr.debug_name;
        }
        if (namewhat == null) {
            const inferred = self.debugInferNameFromCaller(caller_opt, fr.*);
            namewhat = inferred.namewhat;
            name = inferred.name;
        }

        // Builtin (C) frames: format as [C]: in {namewhat} '{name}' or [C]: in ?
        if (fr.callee == .Builtin) {
            if (namewhat) |nw| {
                if (name) |nm| {
                    return try std.fmt.allocPrint(self.alloc, "\t[C]: in {s} '{s}'", .{ nw, nm });
                }
            }
            return try std.fmt.allocPrint(self.alloc, "\t[C]: in ?", .{});
        }

        // Lua frames: PUC pushfuncname logic
        if (namewhat) |nw| {
            if (name) |nm| {
                if (std.mem.eql(u8, nw, "metamethod")) {
                    return try std.fmt.allocPrint(self.alloc, "\t{s}:{d}: in metamethod '{s}'", .{ shown_src, line, nm });
                }
                return try std.fmt.allocPrint(self.alloc, "\t{s}:{d}: in {s} '{s}'", .{ shown_src, line, nw, nm });
            }
        }

        // No name from code: main chunk, anonymous function, or ?
        if (fr.lineDefined() == 0) {
            return try std.fmt.allocPrint(self.alloc, "\t{s}:{d}: in main chunk", .{ shown_src, line });
        }

        // PUC pushglobalfuncname: try to find the function in _G (loaded table).
        // If found, show "function 'name'". Otherwise, show "function <src:linedefined>".
        if (self.debugFindGlobalFuncName(fr.callee)) |gname| {
            return try std.fmt.allocPrint(self.alloc, "\t{s}:{d}: in function '{s}'", .{ shown_src, line, gname });
        }

        // PUC: for Lua functions without a name, use function <src:linedefined>
        return try std.fmt.allocPrint(self.alloc, "\t{s}:{d}: in function <{s}:{d}>", .{ shown_src, line, shown_src, fr.lineDefined() });
    }

    /// PUC pushglobalfuncname (lauxlib.c:74-93): search _G for a function
    /// value matching `callee`. Returns the global name if found, null otherwise.
    /// PUC searches the registry's LUA_LOADED_TABLE; we search _G directly
    /// since that's where user-defined globals live.
    fn debugFindGlobalFuncName(self: *Vm, callee: Value) ?[]const u8 {
        if (callee != .Closure) return null;
        const target_cl = callee.Closure;
        for (self.global_env.hash) |*node| {
            if (node.key_tt != .string) continue;
            if (node.value == .Nil) continue;
            if (node.value == .Closure and node.value.Closure == target_cl) {
                return node.key_val.string.bytes();
            }
        }
        return null;
    }

    fn debugBuildCurrentTraceback(self: *Vm, level: i64) DispatchError![]const u8 {
        // When running inside a coroutine, only include frames created after
        // the latest resume boundary; caller frames outside the coroutine
        // should not leak into this traceback.
        const start: usize = if (self.current_thread) |th|
            if (self.main_thread) |main_th|
                if (th != main_th) th.resume_base_depth else 0
            else
                0
        else
            0;

        // Walk bytecode frames (Thread.call_frames) (most recent first).
        // Build a list of *const CallFrame pointers so we can reference
        // frames from the array.
        var visible: usize = 0;
        const th_bc = self.activeBytecodeThread();
        const bc_len = th_bc.call_frames.len();
        for (start..bc_len) |i| {
            if (!th_bc.call_frames.getConstPtr(i).hide_from_debug) visible += 1;
        }

        // Lua's traceback level skips its own frame plus `level` caller frames.
        const skip: usize = if (level <= 0) 0 else @intCast(level + 1);
        var nl_count: i64 = @as(i64, @intCast(visible)) - @as(i64, @intCast(skip));
        if (nl_count < 0) nl_count = 0;
        if (level > 0 and nl_count < 1) nl_count = 1;
        if (level <= 0 and nl_count < 2) nl_count = 2;

        var aw: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer aw.deinit();
        var w = &aw.writer;
        w.writeAll("stack traceback:\n") catch return error.OutOfMemory;

        // Collect frame pointers (most recent first).
        var frame_ptrs = std.ArrayListUnmanaged(*const CallFrame).empty;
        defer frame_ptrs.deinit(self.alloc);
        {
            var i: usize = th_bc.call_frames.len();
            while (i > start) {
                i -= 1;
                if (th_bc.call_frames.getConstPtr(i).hide_from_debug) continue;
                try frame_ptrs.append(self.alloc, th_bc.call_frames.getPtr(i));
            }
        }
        var first: usize = @min(skip, frame_ptrs.items.len);
        if (frame_ptrs.items.len != 0 and first >= frame_ptrs.items.len) first = frame_ptrs.items.len - 1;
        const shown = if (frame_ptrs.items.len > first) frame_ptrs.items[first..] else frame_ptrs.items[0..0];
        var has_pcall = false;
        for (shown) |fr_ptr| {
            const fr = fr_ptr.*;
            if (fr.callee == .Builtin and fr.callee.Builtin == .pcall) {
                has_pcall = true;
                break;
            }
        }
        const need_pcall = self.activeProtectedCallDepth() > 0 and !has_pcall;

        // Lua truncates large stack traces around the middle.
        // db.lua checks for a split of 10 lines before "...(skip ...)"
        // and 11 lines from that marker onward.
        if (shown.len + @as(usize, @intFromBool(need_pcall)) > 22) {
            for (shown[0..10], 0..) |fr_ptr, k| {
                const caller_opt: ?*const Frame = if (k + 1 < shown.len) shown[k + 1] else null;
                const line = try self.tracebackFrameLabel(fr_ptr, caller_opt, k == 0);
                defer self.alloc.free(line);
                w.print("{s}\n", .{line}) catch return error.OutOfMemory;
            }
            w.writeAll("...\t(skip levels)\n") catch return error.OutOfMemory;
            const tail = shown[shown.len - 10 ..];
            for (tail, 0..) |fr_ptr, k| {
                const tail_idx = shown.len - 10 + k;
                const caller_opt: ?*const Frame = if (tail_idx + 1 < shown.len) shown[tail_idx + 1] else null;
                const line = try self.tracebackFrameLabel(fr_ptr, caller_opt, false and k == 0);
                defer self.alloc.free(line);
                w.print("{s}\n", .{line}) catch return error.OutOfMemory;
            }
            return try aw.toOwnedSlice();
        }

        if (shown.len == 0) {
            if (level <= 0) w.writeAll("\t[C]: in global 'traceback'\n") catch return error.OutOfMemory;
            if (self.activeProtectedCallDepth() > 0) w.writeAll("\t[C]: in global 'pcall'\n") catch return error.OutOfMemory;
            return try aw.toOwnedSlice();
        }

        if (level <= 0) {
            w.writeAll("\t[C]: in global 'traceback'\n") catch return error.OutOfMemory;
        }
        // If the error was raised by a C function (error(), yield, etc.),
        // insert the synthetic [C]: in {label} frame.
        if (self.err_cfunc_label) |label| {
            if (level <= 0) {
                w.print("\t[C]: in {s}\n", .{label}) catch return error.OutOfMemory;
            }
        }
        for (shown, 0..) |fr_ptr, k| {
            // Insert synthetic [C]: in global 'pcall'/'xpcall' before a frame
            // that has a pending protected call.
            if (fr_ptr.pending_call.get()) |pending| {
                if (pending.protection) |prot| {
                    const cname: []const u8 = if (prot.kind == .pcall) "pcall" else "xpcall";
                    w.print("\t[C]: in global '{s}'\n", .{cname}) catch return error.OutOfMemory;
                }
            }
            const caller_opt: ?*const Frame = if (k + 1 < shown.len) shown[k + 1] else null;
            const line = try self.tracebackFrameLabel(fr_ptr, caller_opt, k == 0);
            defer self.alloc.free(line);
            w.print("{s}\n", .{line}) catch return error.OutOfMemory;
        }
        if (need_pcall) {
            // Fallback: if no frame had a pending protection (e.g., the
            // protected call was set up via builtinPcall, not the fast path),
            // append [C]: in global 'pcall' at the end.
            w.writeAll("\t[C]: in global 'pcall'\n") catch return error.OutOfMemory;
        }
        return try aw.toOwnedSlice();
    }

    fn debugBuildThreadTraceback(self: *Vm, th: *Thread, level: i64) DispatchError![]const u8 {
        // Pragmatic traceback used by db.lua coroutine checks:
        // first line is the header, following lines are scanned with string.gmatch.
        var aw: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer aw.deinit();
        var w = &aw.writer;
        w.writeAll("stack traceback:\n") catch return error.OutOfMemory;

        if (th.status == .suspended) {
            if (level <= 0) w.writeAll("\t[C]: in function 'yield'\n") catch return error.OutOfMemory;
            const names = th.trace_frame_names[0..th.trace_stack_depth];
            const depth_raw: usize = if (names.len > 0) names.len else 1;
            const depth: i64 = if (depth_raw > 0) @intCast(depth_raw) else 1;
            const drop: i64 = if (level <= 1) 0 else level - 1;
            const db_lines: i64 = @max(0, depth - drop);
            var k: i64 = 0;
            while (k < db_lines) : (k += 1) {
                const idx: usize = @intCast(k);
                const nm = if (idx < names.len) names[idx] else null;
                if (nm) |name| {
                    w.print("\tdb.lua: in function '{s}'\n", .{name}) catch return error.OutOfMemory;
                } else {
                    w.writeAll("\tdb.lua: in function <db.lua>\n") catch return error.OutOfMemory;
                }
            }
        } else if (th.status == .dead) {
            if (th.trace_had_error) {
                w.writeAll("\t[C]: in function 'error'\n") catch return error.OutOfMemory;
                const names = th.trace_frame_names[0..th.trace_stack_depth];
                if (names.len != 0 and names[0] != null) {
                    w.print("\tdb.lua: in function '{s}'\n", .{names[0].?}) catch return error.OutOfMemory;
                }
                for (names) |nm| {
                    if (nm) |name| {
                        w.print("\tdb.lua: in function '{s}'\n", .{name}) catch return error.OutOfMemory;
                    } else {
                        w.writeAll("\tdb.lua: in function <db.lua>\n") catch return error.OutOfMemory;
                    }
                }
                if (names.len == 0) {
                    w.writeAll("\tdb.lua: in function <db.lua>\n") catch return error.OutOfMemory;
                }
            }
        }

        return try aw.toOwnedSlice();
    }

    fn builtinDebugSethook(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = outs;
        var i: usize = 0;
        var target_thread: ?*Thread = null;
        if (args.len > 0 and args[0] == .Thread) {
            target_thread = try self.expectThread(args[0]);
            i = 1;
        }
        const hook_state = self.hookStateFor(target_thread);

        if (i >= args.len or args[i] == .Nil) {
            hook_state.clear();
            self.refreshHooksCached();
            return;
        }

        const hook = args[i];
        switch (hook) {
            .Builtin, .Closure => {},
            else => return self.fail("debug.sethook expects function or nil", .{}),
        }
        hook_state.func = hook;
        // Every public debug.sethook installation is a Lua hook by default.
        // Native-hook compatibility callers opt in atomically after this call.
        hook_state.allow_yield = false;
        i += 1;

        if (i < args.len) {
            const mask = switch (args[i]) {
                .String => |s| s.bytes(),
                else => return self.fail("debug.sethook expects mask string", .{}),
            };
            hook_state.setMask(mask);
            i += 1;
        } else {
            hook_state.setMask("");
        }
        hook_state.has_call = std.mem.indexOfScalar(u8, hook_state.mask, 'c') != null;
        hook_state.has_return = std.mem.indexOfScalar(u8, hook_state.mask, 'r') != null;
        hook_state.has_line = std.mem.indexOfScalar(u8, hook_state.mask, 'l') != null;

        if (i < args.len) {
            hook_state.count = switch (args[i]) {
                .Nil => 0,
                .Int => |n| n,
                .Num => |n| blk: {
                    if (!std.math.isFinite(n)) return self.fail("debug.sethook expects integer count", .{});
                    const t = std.math.trunc(n);
                    if (t != n) return self.fail("debug.sethook expects integer count", .{});
                    if (t < @as(f64, @floatFromInt(std.math.minInt(i64))) or t > @as(f64, @floatFromInt(std.math.maxInt(i64)))) {
                        return self.fail("debug.sethook expects integer count", .{});
                    }
                    break :blk @as(i64, @intFromFloat(t));
                },
                else => return self.fail("debug.sethook expects integer count", .{}),
            };
        } else {
            hook_state.count = 0;
        }
        if (hook_state.count < 0 or hook_state.count > (1 << 24) - 1) {
            return self.fail("debug.sethook: count out of range", .{});
        }
        hook_state.budget = hook_state.count;
        hook_state.tick = 0;
        hook_state.skip_line_once = false;
        hook_state.skip_line_until_depth = 0;
        hook_state.skip_count_once = false;
        hook_state.skip_bc_line_once = false;
        if (hook_state.has_line) {
            if (target_thread == null and self.activeBytecodeThread().call_frames.len() != 0) {
                const seed_th = self.activeBytecodeThread();
                for (0..seed_th.call_frames.len()) |sfi| {
                    const fr = seed_th.call_frames.getPtr(sfi);
                    // Re-derive current_line from lineinfo (fast path no longer updates it).
                    if (fr.proto) |proto| {
                        if (fr.pc < proto.lineinfo.len and proto.lineinfo[fr.pc] != 0) {
                            fr.current_line = @intCast(proto.lineinfo[fr.pc]);
                        }
                    }
                    fr.last_hook_line = fr.current_line;
                }
            }

            // PUC lua_sethook: `if (isLua(L->ci)) L->oldpc = L->ci->u.l.savedpc`.
            // When sethook is called from a C function (e.g. T._allowhookyield
            // called from T.sethook), PUC does NOT update L->oldpc. But PUC's
            // L->oldpc is a single per-thread value that was already being
            // updated by luaG_traceexec on every instruction (not just when
            // hooks fire). Our per-frame last_line_pc is only updated when
            // hooks_active is true, so frames that ran before the hook was
            // installed have last_line_pc = null. After sethook returns to
            // such a frame, the null last_line_pc makes should_dispatch true,
            // firing a spurious line hook on the sethook line itself.
            //
            // Fix: seed last_line_pc for ALL Lua frames on the call stack,
            // not just the top one. This mirrors PUC's invariant that
            // L->oldpc is always valid for the current Lua function.
            const seeded_thread = target_thread orelse self.activeBytecodeThread();
            if (seeded_thread.call_frames.len() != 0) {
                // First, find the seed frame (skip debug hook frames).
                // This is the frame that PUC's L->ci would point to.
                var seed_index = seeded_thread.call_frames.len() - 1;
                if (target_thread == null) {
                    var search = seeded_thread.call_frames.len();
                    while (search > 0) {
                        search -= 1;
                        const candidate = seeded_thread.call_frames.getPtr(search);
                        if (candidate.is_debug_hook) {
                            if (search > 0) seed_index = search - 1;
                            break;
                        }
                    }
                }

                // Seed last_line_pc for ALL Lua frames below the seed frame
                // (inclusive). Each frame's last_line_pc is set to its own
                // current pc, so when execution returns to that frame, the
                // line-change check sees the correct oldpc.
                var seed_i: usize = 0;
                while (seed_i <= seed_index) : (seed_i += 1) {
                    const fr = seeded_thread.call_frames.getPtr(seed_i);
                    fr.last_line_pc = fr.pc;
                }

                // Set skip_line_hook_pc on the seed frame to prevent the
                // very next instruction from firing a spurious line hook.
                const exec_fr = seeded_thread.call_frames.getPtr(seed_index);
                if (target_thread == null) exec_fr.skip_line_hook_pc = exec_fr.pc;
            }
        }
        // P15.33: Update cached hooks_active flag so the dispatch loop's fast
        // path picks up the new hook state without calling activeHookState().
        self.refreshHooksCached();
    }

    fn builtinDebugSetuservalue(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("debug.setuservalue expects (u, value)", .{});
        const target = args[0];
        if (target == .Nil) return self.fail("bad argument #1 to 'setuservalue' (userdata expected, got nil)", .{});
        if (target == .Int or target == .Num) return self.fail("bad argument #1 to 'setuservalue' (userdata expected, got number)", .{});
        if (isTestcLightUserdata(self, target)) {
            return self.fail("bad argument #1 to 'setuservalue' (full userdata expected, got light userdata)", .{});
        }
        // Real Userdata path: store into the uservalues slice (PUC `uvalue`).
        // PUC debug.setuservalue (ldblib.c:db_setuservalue) requires idx <=
        // nuvalue; we enforce the same bound against the slice length.
        if (target == .Userdata) {
            const ud = target.Userdata;
            const idx: i64 = if (args.len >= 3 and args[2] == .Int)
                args[2].Int
            else if (args.len >= 3 and args[2] == .Num and @floor(args[2].Num) == args[2].Num)
                @intFromFloat(args[2].Num)
            else
                1;
            if (idx < 1 or idx > @as(i64, @intCast(ud.uservalues.len))) {
                if (outs.len > 0) outs[0] = .{ .Bool = false };
                return;
            }
            const val = if (args.len >= 2) args[1] else .Nil;
            ud.uservalues[@intCast(idx - 1)] = val;
            // PUC luaC_barrierback (lapi.c:1015): backward barrier — turn
            // the userdata gray if it is black and the value is white.
            try self.gcWriteBarrierUserdata(ud, val);
            if (outs.len > 0) outs[0] = .{ .Bool = true };
            return;
        }
        // Not a full userdata: PUC returns an error. We return false.
        if (outs.len > 0) outs[0] = .{ .Bool = false };
    }

    fn builtinDebugGetuservalue(_: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return;
        const target = args[0];
        const idx: i64 = if (args.len >= 2 and args[1] == .Int)
            args[1].Int
        else if (args.len >= 2 and args[1] == .Num and @floor(args[1].Num) == args[1].Num)
            @intFromFloat(args[1].Num)
        else
            1;
        // Real Userdata path: read from the uservalues slice (PUC `uvalue`).
        if (target == .Userdata) {
            const ud = target.Userdata;
            if (idx < 1 or idx > @as(i64, @intCast(ud.uservalues.len))) {
                if (outs.len > 0) outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .Bool = false };
                return;
            }
            if (outs.len > 0) outs[0] = ud.uservalues[@intCast(idx - 1)];
            if (outs.len > 1) outs[1] = .{ .Bool = true };
            return;
        }
        // Not a full userdata (nil, light userdata, table, etc.): PUC
        // lua_getiuservalue returns LUA_TNONE for non-userdata. We return
        // nil, false.
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .{ .Bool = false };
    }

    fn builtinPairs(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'pairs' (value expected)", .{});
        if (args[0] != .Table) return self.fail("bad argument #1 to 'pairs' (table expected, got {s})", .{self.valueTypeName(args[0])});
        for (outs) |*out| out.* = .Nil;
        const mm = metamethodValue(self, args[0], "__pairs");
        if (mm) |mmv| {
            var mm_args = [_]Value{args[0]};
            const resolved = try self.resolveCallable(mmv, mm_args[0..], .{ .namewhat = "metamethod", .name = "__pairs" });
            defer if (resolved.owned_args) |owned| self.alloc.free(owned);
        switch (resolved.callee) {
            .Builtin => |id| {
                     try self.callBuiltin(id, resolved.args, outs);
                    if (builtinHasDynamicOutCount(id)) {
                        var i = self.last_builtin_out_count;
                        while (i < outs.len) : (i += 1) outs[i] = .Nil;
                    }
                },
                .Closure => |cl| {
                    const ret = try self.runClosure(cl, resolved.args);
                    defer self.alloc.free(ret);
                    const n = @min(outs.len, ret.len);
                    for (0..n) |i| outs[i] = ret[i];
                },
                else => unreachable,
            }
            return;
        }
        if (outs.len == 0) return;
        outs[0] = .{ .Builtin = .next };
        if (outs.len > 1) outs[1] = args[0];
        if (outs.len > 2) outs[2] = .Nil;
    }

    fn builtinIpairs(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'ipairs' (value expected)", .{});
        if (args[0] != .Table) return self.fail("bad argument #1 to 'ipairs' (table expected, got {s})", .{self.valueTypeName(args[0])});
        outs[0] = .{ .Builtin = .ipairs_iter };
        if (outs.len > 1) outs[1] = args[0];
        if (outs.len > 2) outs[2] = .{ .Int = 0 };
    }

    fn builtinPairsIter(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len < 2) return self.fail("pairs iterator: expected state and control", .{});
        const state = try self.expectTable(args[0]);
        const keys_v = self.getFieldOpt(state, "__keys") orelse return self.fail("pairs iterator: missing keys", .{});
        const target_v = self.getFieldOpt(state, "__target") orelse return self.fail("pairs iterator: missing target", .{});
        const keys = try self.expectTable(keys_v);
        const target = try self.expectTable(target_v);

        var idx: isize = -1;
        const control = args[1];
        if (control != .Nil) {
            for (keys.array, 0..) |k, i| {
                if (valuesEqual(k, control)) {
                    idx = @intCast(i);
                    break;
                }
            }
            if (idx < 0) return;
        }

        const next_idx: usize = @intCast(idx + 1);
        if (next_idx >= keys.array.len) return;
        const key = keys.array[next_idx];
        const val = try self.tableGetValue(target, key);

        outs[0] = key;
        if (outs.len > 1) outs[1] = val;
    }

    fn builtinIpairsIter(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;
        if (args.len < 2) return self.fail("ipairs iterator: expected state and control", .{});
        const tbl = try self.expectTable(args[0]);
        const control = args[1];
        const cur: i64 = switch (control) {
            .Nil => 0,
            .Int => |i| i,
            else => return self.fail("ipairs iterator: invalid control type {s}", .{control.typeName()}),
        };
        const next = cur +% 1;
        const val = try self.tableGetValue(tbl, .{ .Int = next });
        if (val == .Nil) return;
        outs[0] = .{ .Int = next };
        if (outs.len > 1) outs[1] = val;
    }

    fn builtinRawget(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len < 2) return self.fail("rawget expects (table, key)", .{});
        const tbl = try self.expectTable(args[0]);
        outs[0] = try self.tableGetRawValue(tbl, args[1]);
    }

    // ─────────────────────────────────────────────────────────────────────
    // Unified hash part: raw get / set / next / length.
    //
    // These mirror PUC Lua 5.5 `ltable.c`:
    //   - rawGet      ≈ luaH_get (getgeneric / getintfromhash)
    //   - rawSet      ≈ luaH_set / luaH_newkey + array-part promotion
    //   - rawNext     ≈ luaH_next (array scan then hash scan)
    //   - tableBorderLen ≈ luaH_getn (boundary search; array + hash)
    //
    // All int/pointer keys hash through `ltable.keyHash` using `self.hash_seed`,
    // which is invariant across the Vm's lifetime (see field doc).
    // ─────────────────────────────────────────────────────────────────────

    // PUC luaH_get: look up `key` without invoking any __index metamethod.
    // Returns Nil if absent (including a logically-deleted node with value Nil).
    fn rawGet(self: *Vm, tbl: *const Table, key: Value) Value {
        switch (key) {
            .Int => |k| {
                if (k >= 1) {
                    const arr_len: i64 = @intCast(tbl.asize);
                    if (k <= arr_len) {
                        return tbl.array[@intCast(k - 1)];
                    }
                }
            },
            .Num => |n| {
                // Integer-valued floats coerce to int keys (PUC luaV_tointeger).
                // NaN handled by caller (table index is NaN); non-integer
                // floats fall through to the hash part as raw bit-pattern keys.
                if (std.math.isFinite(n) and
                    n >= -9_223_372_036_854_775_808.0 and
                    n < 9_223_372_036_854_775_808.0 and
                    @floor(n) == n)
                {
                    return self.rawGet(tbl, .{ .Int = @as(i64, @intFromFloat(n)) });
                }
            },
            .Nil => return .Nil,
            else => {},
        }
        const node = ltable.nodeLookup(tbl.hash, key, self.hash_seed) orelse return .Nil;
        return node.value;
    }

    /// PUC `luaH_set` / `luaH_newkey` (ltable.c:914). Store `val` at `key`.
    ///
    /// Flow mirrors PUC `luaH_newkey`:
    ///   1. `insertkey` — try to place the key in an existing free slot.
    ///   2. On overflow → `rehash` (grow table, redistribute keys between
    ///      array/hash parts via `computeSizes`).
    ///   3. `newcheckedkey` — after rehash, integer keys that now fall in the
    ///      array range go to the array part; everything else goes through
    ///      `insertkey` again (guaranteed to succeed in the grown table).
    ///
    /// Integer keys in [1..asize] go directly to the array part (PUC
    /// `keyinarray` fast path, also used by `luaH_set` before calling
    /// `luaH_newkey`). Setting val==.Nil deletes the entry (PUC: do not
    /// insert nils); deleting an absent key is a no-op.
    fn rawSet(self: *Vm, tbl: *Table, key: Value, val: Value) DispatchError!void {
        try self.gcTableWriteBarrier(tbl, key, val);
        switch (key) {
            .Nil => return self.fail("table index is nil", .{}),
            .Num => |n| {
                if (std.math.isNan(n)) return self.fail("table index is NaN", .{});
                if (std.math.isFinite(n) and
                    n >= -9_223_372_036_854_775_808.0 and
                    n < 9_223_372_036_854_775_808.0 and
                    @floor(n) == n)
                {
                    return self.rawSet(tbl, .{ .Int = @as(i64, @intFromFloat(n)) }, val);
                }
                // Non-integer float key: hash via hashNum (matching keyHash's
                // .Num branch and Node.rawHash's .num branch — see ltable.zig).
            },
            else => {},
        }

        // Integer keys in [1..asize] go to the array part (PUC keyinarray).
        // This is the fast path that `luaH_set` takes before `luaH_newkey`.
        if (key == .Int) {
            const k = key.Int;
            if (k >= 1 and @as(u64, @intCast(k)) <= tbl.asize) {
                tbl.array[@intCast(k - 1)] = val;
                return;
            }
        }

        // Hash-part lookup: update existing node, or delete if val==.Nil.
        if (ltable.nodeLookup(tbl.hash, key, self.hash_seed)) |node| {
            if (val == .Nil) {
                // Logical delete: leave node in chain with value Nil (PUC).
                _ = ltable.nodeDelete(tbl.hash, key, self.hash_seed);
            } else {
                // PUC luaV_finishset (lvm.c:347) calls invalidateTMcache
                // unconditionally after luaH_finishset. The fast path
                // (luaH_psetshortstr returning HOK for non-nil→non-nil
                // updates) skips invalidation — but that's safe because
                // updating a non-nil value to another non-nil value cannot
                // change whether a metamethod is present.
                // The case that matters: nil→non-nil (reviving a dead node).
                // That goes through luaH_finishset → invalidateTMcache.
                // We replicate this here: invalidate when the old value was
                // nil (dead node being revived).
                if (node.value == .Nil) {
                    tbl.flags &= ~TableFlags.MASK;
                }
                node.value = val;
            }
            return;
        }
        if (val == .Nil) return; // PUC: deleting an absent key is a no-op.

        // New key: try insertkey (PUC `insertkey`). If the hash part is empty
        // (PUC "dummy"), insertkey returns 0 (no free place) — this forces a
        // rehash, which is exactly what PUC does: the first insert into a
        // table triggers rehash so `computeSizes` can decide whether the key
        // belongs in the array part (e.g. `t[1]=x` → asize=1 → array).
        if (tbl.hash.len != 0) {
            if (ltable.nodeInsert(tbl.hash, &tbl.hash_lastfree, key, val, self.hash_seed)) |_| {
                // P15.37c: new key inserted — invalidate metamethod cache.
                // (PUC ltable.c:1112 calls invalidateTMcache after insertkey.)
                tbl.flags &= ~TableFlags.MASK;
                return;
            }
            // Hash full: fall through to rehash.
        }

        // Rehash (PUC `rehash` — grow table, redistribute keys between
        // array/hash parts via `computeSizes`). Drops deleted/Nil entries
        // and rebuilds chains from scratch. `tableResize` charges
        // `testcConsumeAllocCount` for each actual allocation (hash and/or
        // array) it makes, matching PUC's allocation model.
        try self.tableRehash(tbl, key);

        // newcheckedkey: after rehash, integer keys that now fall in the
        // array range go to the array part; everything else goes through
        // insertkey again (guaranteed to succeed in the grown table).
        if (key == .Int) {
            const k = key.Int;
            if (k >= 1 and @as(u64, @intCast(k)) <= tbl.asize) {
                tbl.array[@intCast(k - 1)] = val;
                tbl.flags &= ~TableFlags.MASK;
                return;
            }
        }
        // The key is not an array index, so rehash must have allocated a
        // hash part with room for it (nsize >= 1).
        std.debug.assert(tbl.hash.len != 0);
        const inserted = ltable.nodeInsert(tbl.hash, &tbl.hash_lastfree, key, val, self.hash_seed);
        std.debug.assert(inserted != null);
        tbl.flags &= ~TableFlags.MASK;
    }

    // PUC luaH_next: given a control key (Nil for the start of iteration),
    // return the next (key, value) pair in PUC's defined order — first the
    // array part (keys 1..n), then the hash part in node-memory order.
    //
    // Returns null when iteration is complete. Returns error.RuntimeError if
    // the control key is non-Nil and not present in the table.
    fn rawNext(self: *Vm, tbl: *Table, control_key: Value) DispatchError!?struct { key: Value, value: Value } {
        const cc = canonicalizeNextControl(control_key);

        // Determine where to start scanning, based on the control key.
        // Nil → start of array (index 0). Int in array range → just past it.
        // Otherwise → just past the control key's hash-node slot.
        var array_idx: usize = 0;
        var hash_idx: usize = 0;
        var in_array = true;
        if (cc != .Nil) {
            if (cc == .Int) {
                const k = cc.Int;
                if (k >= 1 and k <= @as(i64, @intCast(tbl.asize))) {
                    const arr_idx0: usize = @intCast(k - 1);
                    // Array keys in range are always valid control positions for
                    // `next`, even if the slot is nil (a hole) — PUC `keyinarray`
                    // is a pure range check (ltable.c:329-339). Scan past it.
                    array_idx = arr_idx0 + 1;
                } else {
                    // Int outside array: must be (or have been) a hash key.
                    in_array = false;
                    const node = ltable.nodeLookup(tbl.hash, cc, self.hash_seed) orelse {
                        return self.fail("invalid key to 'next'", .{});
                    };
                    // PUC `getgeneric(key, deadok=1)` accepts a deleted (Nil-
                    // valued) node as a valid control (ltable.c:291-303). Use its
                    // position; do not reject on value==.Nil.
                    hash_idx = indexNodeInHash(tbl.hash, node, self.hash_seed);
                    if (hash_idx == tbl.hash.len) return null;
                    hash_idx += 1;
                }
            } else {
                in_array = false;
                const node = ltable.nodeLookup(tbl.hash, cc, self.hash_seed) orelse {
                    return self.fail("invalid key to 'next'", .{});
                };
                // Deleted (Nil-valued) node is a valid control (see above).
                hash_idx = indexNodeInHash(tbl.hash, node, self.hash_seed);
                if (hash_idx == tbl.hash.len) return null;
                hash_idx += 1;
            }
        }

        // Array part scan.
        if (in_array) {
            while (array_idx < tbl.asize) : (array_idx += 1) {
                const v = tbl.array[array_idx];
                if (v != .Nil) {
                    return .{ .key = .{ .Int = @intCast(array_idx + 1) }, .value = v };
                }
            }
            // Fall through to hash part, starting from index 0.
            hash_idx = 0;
        }

        // Hash part scan (memory order, skipping empty + value-Nil nodes).
        if (ltable.nextLiveIndex(tbl.hash, hash_idx)) |hi| {
            const node = tbl.hash[hi];
            return .{ .key = node.getKey(), .value = node.value };
        }
        return null;
    }

    // Linear scan to find the array index of a known-present node pointer.
    // PUC `luaH_next` doesn't need this (it walks in chain order); our hash
    // next() iterates memory order so we must translate node-pointer → index.
    // Returns hash.len if not found (shouldn't happen for a fresh lookup).
    fn indexNodeInHash(nodes: []ltable.Node, target: *const ltable.Node, seed: u64) usize {
        _ = seed;
        const base: usize = @intFromPtr(nodes.ptr);
        const off: usize = (@intFromPtr(target) - base) / @sizeOf(ltable.Node);
        return off;
    }

    // Thin compatibility wrappers around the new primitives — kept so the many
    // existing call sites continue to compile unchanged. They carry the same
    // signatures as before the refactor.
    fn tableSetValue(self: *Vm, tbl: *Table, key: Value, val: Value) DispatchError!void {
        return self.rawSet(tbl, key, val);
    }

    // ─────────────────────────────────────────────────────────────────────
    // String-key convenience helpers.
    //
    // The old `Table.fields` was a StringHashMap keyed by raw []const u8. Many
    // call sites read/wrote fields by literal name (e.g. `self.getFieldOpt(mt, "__gc")`
    // or `tbl.fields.put(alloc, "n", ...)`). The unified hash part keys
    // everything by `Value.String` (an interned *LuaString), so we provide
    // thin name→key adapters that the ported call sites can use verbatim.
    // ─────────────────────────────────────────────────────────────────────

    // Read a string-keyed field. Returns Nil if absent.
    fn getField(self: *Vm, tbl: *Table, name: []const u8) Value {
        const key: Value = .{ .String = self.internStrAssume(name) };
        return self.rawGet(tbl, key);
    }

    // Read a string-keyed field as option (Nil → null). Matches the old
    // `self.getFieldOpt(tbl, name) orelse ...` pattern.
    pub fn getFieldOpt(self: *Vm, tbl: *Table, name: []const u8) ?Value {
        const v = self.getField(tbl, name);
        return if (v == .Nil) null else v;
    }

    // Write a string-keyed field. Interns `name` once; the existing value (if
    // any) is overwritten. Writing Nil deletes the entry (rawSet semantics).
    fn setField(self: *Vm, tbl: *Table, name: []const u8, val: Value) DispatchError!void {
        const key: Value = .{ .String = try self.internStr(name) };
        return self.rawSet(tbl, key, val);
    }

    // Coerce a `next()`/`rawnext()` control key into the canonical form used
    // internally: integer-valued floats become Int, everything else is left
    // alone. PUC `luaV_tointeger` does the same coercion for table keys.
    fn canonicalizeNextControl(control: Value) Value {
        return switch (control) {
            .Num => |n| blk: {
                if (!std.math.isNan(n) and
                    std.math.isFinite(n) and
                    n >= -9_223_372_036_854_775_808.0 and
                    n < 9_223_372_036_854_775_808.0 and
                    @floor(n) == n)
                {
                    break :blk .{ .Int = @as(i64, @intFromFloat(n)) };
                }
                break :blk control;
            },
            else => control,
        };
    }

    fn builtinRawset(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len < 3) return self.fail("rawset expects (table, key, value)", .{});
        const tbl = try self.expectTable(args[0]);
        try self.tableSetValue(tbl, args[1], args[2]);
        if (outs.len > 0) outs[0] = args[0];
    }

    fn builtinIoWrite(self: *Vm, to_stderr: bool, args: []const Value, outs: []Value) DispatchError!void {
        var out = if (to_stderr) stdio.stderr() else stdio.stdout();
        var target_file_v: Value = .Nil;
        var i: usize = 0;
        var argn: usize = 0;
        var ret_file: Value = .Nil;
        if (!to_stderr and args.len > 0 and asFileTable(self, args[0]) != null) {
            // Method call syntax: <file>:write(...). Handle stdout/stderr objects.
            const io_v = self.getGlobal("io");
            if (io_v == .Table) {
                const io_tbl = io_v.Table;
                ret_file = args[0];
                if (self.getFieldOpt(io_tbl, "stderr")) |stderr_v| {
                    if (stderr_v == .Table and stderr_v.Table == args[0].Table) out = stdio.stderr();
                }
                if (self.getFieldOpt(io_tbl, "stdout")) |stdout_v| {
                    if (!(stdout_v == .Table and stdout_v.Table == args[0].Table)) {
                        _ = self.getManagedFile(args[0]) orelse return self.fail("closed file", .{});
                        target_file_v = args[0];
                    }
                }
            }
            i = 1;
        } else if (!to_stderr) {
            // io.write(...) writes to current default output stream.
            const io_v = self.getGlobal("io");
            if (io_v == .Table) {
                const io_tbl = io_v.Table;
                const out_v = self.getFieldOpt(io_tbl, "stdout") orelse .Nil;
                const cur_v = self.getFieldOpt(io_tbl, "output_stream") orelse out_v;
                ret_file = cur_v;
                if (self.getFieldOpt(io_tbl, "stderr")) |stderr_v| {
                    if (stderr_v == .Table and cur_v == .Table and stderr_v.Table == cur_v.Table) out = stdio.stderr();
                }
                if (cur_v != .Nil and !(cur_v == .Table and out_v == .Table and cur_v.Table == out_v.Table)) {
                    _ = self.getManagedFile(cur_v) orelse return self.fail(" output file is closed", .{});
                    target_file_v = cur_v;
                }
            }
        }
        while (i < args.len) : (i += 1) {
            // For method calls, first arg is the receiver (file object). Ignore it.
            if (to_stderr and i == 0 and args[i] == .Table) continue;
            argn += 1;
            switch (args[i]) {
                .String, .Int, .Num => {},
                else => return self.fail("bad argument #{d} to '{s}' (string expected, got {s})", .{ argn, if (to_stderr) "io.stderr:write" else "io.write", self.valueTypeName(args[i]) }),
            }
            const s = try self.valueToStringAlloc(args[i]);
            if (target_file_v != .Nil) {
                if (!(try self.writeBufferedFile(target_file_v, s))) {
                    return self.fail("file write error: write error", .{});
                }
            } else {
                out.writeAll(s) catch |e| switch (e) {
                    error.BrokenPipe => return,
                    else => return self.fail("{s} write error: {s}", .{ if (to_stderr) "stderr" else "stdout", @errorName(e) }),
                };
            }
        }
        if (to_stderr) {
            const io_v = self.getGlobal("io");
            if (io_v == .Table) ret_file = self.getFieldOpt(io_v.Table, "stderr") orelse .Nil;
        }
        if (outs.len > 0 and ret_file != .Nil) outs[0] = ret_file;
    }

    fn builtinIoInput(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        const io_v = self.getGlobal("io");
        if (io_v != .Table) {
            outs[0] = .Nil;
            return;
        }
        const io_tbl = io_v.Table;
        if (args.len == 0) {
            outs[0] = self.getFieldOpt(io_tbl, "input_stream") orelse (self.getFieldOpt(io_tbl, "stdin") orelse .Nil);
            return;
        }
        const old_in = self.getFieldOpt(io_tbl, "input_stream") orelse (self.getFieldOpt(io_tbl, "stdin") orelse .Nil);
        if (args[0] == .String) {
            var open_out = [_]Value{ .Nil, .Nil, .Nil };
            const file_v = try self.ioOpenPath(args[0].String.bytes(), "r", open_out[0..]) orelse {
                const msg = if (open_out[1] == .String) ioErrText(open_out[1].String.bytes()) else "cannot open file";
                return self.fail("cannot open file '{s}' ({s})", .{ args[0].String.bytes(), msg });
            };
            try self.setField(io_tbl, "input_stream", file_v);
            self.maybeCloseReplacedDefault(old_in, file_v);
            outs[0] = file_v;
            return;
        }
        const name = self.valueTypeName(args[0]);
        if (!std.mem.startsWith(u8, name, "FILE")) {
            return self.fail("bad argument #1 to 'input' (FILE* expected, got {s})", .{name});
        }
        try self.setField(io_tbl, "input_stream", args[0]);
        self.maybeCloseReplacedDefault(old_in, args[0]);
        outs[0] = args[0];
    }

    fn asFileTable(self: *Vm, v: Value) ?*Table {
        if (v != .Table) return null;
        const t = v.Table;
        const mt = t.metatable orelse return null;
        const nm = self.getFieldOpt(mt, "__name") orelse return null;
        if (nm != .String or nm.String != self.internStrAssume("FILE*")) return null;
        return t;
    }

    fn fileIdFromTable(self: *Vm, tbl: *Table) ?i64 {
        const idv = self.getFieldOpt(tbl, "__file_id") orelse return null;
        return switch (idv) {
            .Int => |id| id,
            else => null,
        };
    }

    fn fileCanRead(self: *Vm, v: Value) bool {
        const tbl = asFileTable(self, v) orelse return false;
        const cv = self.getFieldOpt(tbl, "__can_read") orelse return self.fileIdFromTable(tbl) == null;
        return cv == .Bool and cv.Bool;
    }

    fn fileCanWrite(self: *Vm, v: Value) bool {
        const tbl = asFileTable(self, v) orelse return false;
        const cv = self.getFieldOpt(tbl, "__can_write") orelse return self.fileIdFromTable(tbl) == null;
        return cv == .Bool and cv.Bool;
    }

    fn getManagedFile(self: *Vm, v: Value) ?*std.Io.File {
        const tbl = asFileTable(self, v) orelse return null;
        const id = self.fileIdFromTable(tbl) orelse return null;
        return self.open_files.getPtr(id);
    }

    fn getFileBuffer(self: *Vm, v: Value) ?*FileBuffer {
        const tbl = asFileTable(self, v) orelse return null;
        const id = self.fileIdFromTable(tbl) orelse return null;
        return self.file_buffers.getPtr(id);
    }

    fn flushBufferedFile(self: *Vm, v: Value) bool {
        const f = self.getManagedFile(v) orelse return false;
        const fb = self.getFileBuffer(v) orelse return false;
        if (fb.pending.items.len == 0) return true;
        if (fb.sequential) {
            f.writeStreamingAll(stdio.activeIo(), fb.pending.items) catch return false;
        } else {
            f.writePositionalAll(stdio.activeIo(), fb.pending.items, fb.pos) catch return false;
        }
        fb.pos += fb.pending.items.len;
        fb.pending.clearRetainingCapacity();
        return true;
    }

    fn writeBufferedFile(self: *Vm, v: Value, bytes: []const u8) DispatchError!bool {
        const f = self.getManagedFile(v) orelse return false;
        const fb = self.getFileBuffer(v) orelse return false;
        switch (fb.mode) {
            .no => {
                if (fb.sequential) {
                    f.writeStreamingAll(stdio.activeIo(), bytes) catch return false;
                } else {
                    f.writePositionalAll(stdio.activeIo(), bytes, fb.pos) catch return false;
                }
                fb.pos += bytes.len;
            },
            .full => try fb.pending.appendSlice(self.alloc, bytes),
            .line => {
                try fb.pending.appendSlice(self.alloc, bytes);
                if (std.mem.indexOfScalar(u8, bytes, '\n') != null and !self.flushBufferedFile(v)) return false;
            },
        }
        return true;
    }

    fn readByte(file: *std.Io.File, fb: *FileBuffer) !?u8 {
        if (fb.unread_byte) |b| {
            fb.unread_byte = null;
            fb.pos += 1;
            return b;
        }
        var byte: [1]u8 = undefined;
        const n = if (fb.sequential)
            file.readStreaming(stdio.activeIo(), &.{byte[0..]}) catch |err| switch (err) {
                error.EndOfStream => 0,
                else => return err,
            }
        else
            try file.readPositionalAll(stdio.activeIo(), byte[0..], fb.pos);
        if (n == 0) return null;
        fb.pos += 1;
        return byte[0];
    }

    fn unreadByte(fb: *FileBuffer, byte: u8) void {
        if (fb.pos > 0) fb.pos -= 1;
        if (fb.sequential) fb.unread_byte = byte;
    }

    fn readLineAlloc(self: *Vm, file: *std.Io.File, fb: *FileBuffer, keep_newline: bool) DispatchError!?*LuaString {
        var out = std.ArrayList(u8).empty;
        defer out.deinit(self.alloc);
        var saw_input = false;
        while (true) {
            const b = readByte(file, fb) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
            if (b == null) break;
            saw_input = true;
            const c = b.?;
            if (c == '\n') {
                if (keep_newline) out.append(self.alloc, c) catch return error.OutOfMemory;
                break;
            }
            out.append(self.alloc, c) catch return error.OutOfMemory;
        }
        if (!saw_input) return null;
        return try self.internStr(out.items);
    }

    fn readCountAlloc(self: *Vm, file: *std.Io.File, fb: *FileBuffer, n: usize) DispatchError!?*LuaString {
        if (n == 0) {
            if (!fb.sequential) {
                const end = file.length(stdio.activeIo()) catch return try self.internStr("");
                if (fb.pos >= end) return null;
                return try self.internStr("");
            }
            const b = readByte(file, fb) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
            if (b == null) return null;
            unreadByte(fb, b.?);
            return try self.internStr("");
        }
        const buf = try self.alloc.alloc(u8, n);
        defer self.alloc.free(buf);
        if (fb.sequential) {
            var got: usize = 0;
            while (got < n) {
                const b = readByte(file, fb) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
                if (b == null) break;
                buf[got] = b.?;
                got += 1;
            }
            if (got == 0) return null;
            return try self.internStr(buf[0..got]);
        }
        const got = file.readPositionalAll(stdio.activeIo(), buf, fb.pos) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
        if (got == 0) return null;
        fb.pos += got;
        return try self.internStr(buf[0..got]);
    }

    fn readAllAlloc(self: *Vm, file: *std.Io.File, fb: *FileBuffer) DispatchError!*LuaString {
        var out = std.ArrayList(u8).empty;
        defer out.deinit(self.alloc);
        var tmp: [4096]u8 = undefined;
        while (true) {
            const got = if (fb.sequential)
                file.readStreaming(stdio.activeIo(), &.{tmp[0..]}) catch |err| switch (err) {
                    error.EndOfStream => 0,
                    else => return self.fail("read error: {s}", .{@errorName(err)}),
                }
            else
                file.readPositionalAll(stdio.activeIo(), tmp[0..], fb.pos) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
            if (got == 0) break;
            fb.pos += got;
            try out.appendSlice(self.alloc, tmp[0..got]);
        }
        return try self.internStr(out.items);
    }

    fn closeManagedFile(self: *Vm, tbl: *Table) ManagedFileClose {
        const id = self.fileIdFromTable(tbl) orelse return .regular;
        // Flush pending writes (if any) and remove the buffer. Std files are
        // never actually closed — see the fd guard below and `isStdFile` checks
        // in every caller. PUC Lua marks std files with `isstd` in `liolib.c`
        // and `closefunc` skips them.
        if (self.file_buffers.fetchRemove(id)) |fb| {
            if (self.open_files.getPtr(id)) |file| {
                if (fb.value.sequential) {
                    _ = file.writeStreamingAll(stdio.activeIo(), fb.value.pending.items) catch {};
                } else {
                    _ = file.writePositionalAll(stdio.activeIo(), fb.value.pending.items, fb.value.pos) catch {};
                }
            }
            var buf = fb.value;
            buf.pending.deinit(self.alloc);
        }
        if (self.open_files.fetchRemove(id)) |entry| {
            // Never close stdin/stdout/stderr — they are shared process-level
            // file descriptors. Sub-VMs (checkpanic) register them too, and
            // closing here would break the parent VM's I/O.
            const fd = entry.value.handle;
            if (fd != std.posix.STDIN_FILENO and
                fd != std.posix.STDOUT_FILENO and
                fd != std.posix.STDERR_FILENO)
            {
                entry.value.close(stdio.activeIo());
            }
        }
        _ = self.finalizables.remove(.{ .table = tbl });

        if (self.open_processes.fetchRemove(id)) |entry| {
            var child = entry.value;
            const term = child.wait(stdio.activeIo()) catch |err| {
                child.kill(stdio.activeIo());
                return .{ .wait_error = @errorName(err) };
            };
            return .{ .process = term };
        }
        return .regular;
    }

    fn allocManagedFileObject(self: *Vm, file: std.Io.File, can_read: bool, can_write: bool, sequential: bool) DispatchError!Value {
        var file_owned_locally = true;
        errdefer if (file_owned_locally) file.close(stdio.activeIo());

        const file_mt = self.file_metatable orelse return self.fail("file metatable missing", .{});
        const tbl = try self.allocTableNoGc();
        tbl.metatable = file_mt;
        try self.registerFinalizable(.{ .table = tbl });
        // Protect tbl from GC while setField populates it. setField may
        // allocate strings/tables internally, which can trigger a GC step.
        // tbl is not yet in any Lua root (not in outs, not in a register),
        // so it must be explicitly protected — PUC keeps newly allocated
        // objects on L->top; we use gcTempRoots as the equivalent.
        var roots = self.gcTempRoots();
        defer roots.end();
        try roots.add(.{ .Table = tbl });
        try self.setField(tbl, "close", .{ .Builtin = .file_close });
        try self.setField(tbl, "write", .{ .Builtin = .file_write });
        try self.setField(tbl, "read", .{ .Builtin = .file_read });
        try self.setField(tbl, "seek", .{ .Builtin = .file_seek });
        try self.setField(tbl, "flush", .{ .Builtin = .file_flush });
        try self.setField(tbl, "lines", .{ .Builtin = .file_lines });
        try self.setField(tbl, "setvbuf", .{ .Builtin = .file_setvbuf });

        const id = self.next_file_id;
        self.next_file_id += 1;
        try self.open_files.put(self.alloc, id, file);
        file_owned_locally = false;
        errdefer {
            if (self.open_files.fetchRemove(id)) |entry| entry.value.close(stdio.activeIo());
        }
        try self.file_buffers.put(self.alloc, id, .{ .sequential = sequential });
        errdefer {
            if (self.file_buffers.fetchRemove(id)) |entry| {
                var buf = entry.value;
                buf.pending.deinit(self.alloc);
            }
        }
        try self.setField(tbl, "__file_id", .{ .Int = id });
        try self.setField(tbl, "__can_read", .{ .Bool = can_read });
        try self.setField(tbl, "__can_write", .{ .Bool = can_write });
        return .{ .Table = tbl };
    }

    fn writeProcessResult(self: *Vm, term: std.process.Child.Term, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;
        if (outs.len > 2) outs[2] = .Nil;

        switch (term) {
            .exited => |code| {
                if (outs.len > 0 and code == 0) outs[0] = .{ .Bool = true };
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("exit") };
                if (outs.len > 2) outs[2] = .{ .Int = code };
            },
            .signal => |signal| {
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("signal") };
                if (outs.len > 2) outs[2] = .{ .Int = @intFromEnum(signal) };
            },
            .stopped => |signal| {
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("signal") };
                if (outs.len > 2) outs[2] = .{ .Int = @intFromEnum(signal) };
            },
            .unknown => |status| {
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("exit") };
                if (outs.len > 2) outs[2] = .{ .Int = status };
            },
        }
        self.last_builtin_out_count = @min(outs.len, 3);
    }

    fn writeManagedCloseResult(self: *Vm, result: ManagedFileClose, outs: []Value) DispatchError!void {
        switch (result) {
            .regular => {
                if (outs.len > 0) outs[0] = .{ .Bool = true };
                self.last_builtin_out_count = @min(outs.len, 1);
            },
            .process => |term| try self.writeProcessResult(term, outs),
            .wait_error => |message| {
                if (outs.len > 0) outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr(message) };
                if (outs.len > 2) outs[2] = .{ .Int = 1 };
                self.last_builtin_out_count = @min(outs.len, 3);
            },
        }
    }

    const IoOpenBase = enum { r, w, a };
    const IoOpenMode = struct {
        base: IoOpenBase,
        plus: bool,
    };

    fn parseIoMode(mode: []const u8) ?IoOpenMode {
        if (mode.len == 0) return null;
        var i: usize = 0;
        const base: IoOpenBase = switch (mode[i]) {
            'r' => .r,
            'w' => .w,
            'a' => .a,
            else => return null,
        };
        i += 1;
        var plus = false;
        if (i < mode.len and mode[i] == '+') {
            plus = true;
            i += 1;
        }
        if (i < mode.len and mode[i] == 'b') i += 1;
        if (i != mode.len) return null;
        return .{ .base = base, .plus = plus };
    }

    fn ioOpenPath(self: *Vm, path: []const u8, mode_s: []const u8, outs: []Value) DispatchError!?Value {
        const mode = parseIoMode(mode_s) orelse return self.fail("bad argument #2 to 'open' (invalid mode)", .{});
        const io = stdio.activeIo();
        const cwd = std.Io.Dir.cwd();
        const abs = std.fs.path.isAbsolute(path);
        const file = (switch (mode.base) {
            .r => if (abs)
                std.Io.Dir.openFileAbsolute(io, path, .{ .mode = if (mode.plus) .read_write else .read_only })
            else
                cwd.openFile(io, path, .{ .mode = if (mode.plus) .read_write else .read_only }),
            .w => blk: {
                var f = (if (abs)
                    std.Io.Dir.openFileAbsolute(io, path, .{ .mode = if (mode.plus) .read_write else .write_only })
                else
                    cwd.openFile(io, path, .{ .mode = if (mode.plus) .read_write else .write_only })) catch |e| switch (e) {
                    error.FileNotFound => (if (abs)
                        std.Io.Dir.createFileAbsolute(io, path, .{ .truncate = true, .read = mode.plus })
                    else
                        cwd.createFile(io, path, .{ .truncate = true, .read = mode.plus })) catch |e2| {
                        if (outs.len > 0) outs[0] = .Nil;
                        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e2)) };
                        if (outs.len > 2) outs[2] = .{ .Int = 1 };
                        return null;
                    },
                    else => {
                        if (outs.len > 0) outs[0] = .Nil;
                        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e)) };
                        if (outs.len > 2) outs[2] = .{ .Int = 1 };
                        return null;
                    },
                };
                f.setLength(stdio.activeIo(), 0) catch |e| {
                    if (e == error.NonResizable) {
                        _ = stdio.activeIo().vtable.fileSeekTo(stdio.activeIo().userdata, f, 0) catch {};
                        break :blk f;
                    }
                    f.close(stdio.activeIo());
                    if (outs.len > 0) outs[0] = .Nil;
                    if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e)) };
                    if (outs.len > 2) outs[2] = .{ .Int = 1 };
                    return null;
                };
                _ = stdio.activeIo().vtable.fileSeekTo(stdio.activeIo().userdata, f, 0) catch {};
                break :blk f;
            },
            .a => blk: {
                var f = (if (abs)
                    std.Io.Dir.openFileAbsolute(io, path, .{ .mode = if (mode.plus) .read_write else .write_only })
                else
                    cwd.openFile(io, path, .{ .mode = if (mode.plus) .read_write else .write_only })) catch |e| switch (e) {
                    error.FileNotFound => (if (abs)
                        std.Io.Dir.createFileAbsolute(io, path, .{ .truncate = false, .read = mode.plus })
                    else
                        cwd.createFile(io, path, .{ .truncate = false, .read = mode.plus })) catch |e2| {
                        if (outs.len > 0) outs[0] = .Nil;
                        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e2)) };
                        if (outs.len > 2) outs[2] = .{ .Int = 1 };
                        return null;
                    },
                    else => {
                        if (outs.len > 0) outs[0] = .Nil;
                        if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e)) };
                        if (outs.len > 2) outs[2] = .{ .Int = 1 };
                        return null;
                    },
                };
                stdio.activeIo().vtable.fileSeekTo(stdio.activeIo().userdata, f, f.length(stdio.activeIo()) catch 0) catch |e| {
                    f.close(stdio.activeIo());
                    if (outs.len > 0) outs[0] = .Nil;
                    if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e)) };
                    if (outs.len > 2) outs[2] = .{ .Int = 1 };
                    return null;
                };
                break :blk f;
            },
        }) catch |e| {
            if (outs.len > 0) outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(e)) };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return null;
        };
        const can_read = mode.base == .r or mode.plus;
        const can_write = mode.base != .r or mode.plus;
        const file_v = try self.allocManagedFileObject(file, can_read, can_write, false);
        if (self.getFileBuffer(file_v)) |fb| {
            fb.pos = if (mode.base == .a) file.length(stdio.activeIo()) catch 0 else 0;
        }
        return file_v;
    }

    fn ioErrText(err_name: []const u8) []const u8 {
        if (std.mem.eql(u8, err_name, "AccessDenied")) return "Permission denied";
        if (std.mem.eql(u8, err_name, "FileNotFound")) return "No such file or directory";
        if (std.mem.eql(u8, err_name, "PathAlreadyExists")) return "File exists";
        return err_name;
    }

    fn builtinIoOpen(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0 or args[0] != .String) {
            return self.fail("bad argument #1 to 'open' (string expected)", .{});
        }
        const path = args[0].String.bytes();
        const mode_s: []const u8 = if (args.len >= 2) switch (args[1]) {
            .String => |s| s.bytes(),
            else => return self.fail("bad argument #2 to 'open' (string expected)", .{}),
        } else "r";
        const file_v = try self.ioOpenPath(path, mode_s, outs) orelse return;
        outs[0] = file_v;
    }

    fn builtinIoPopen(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .Nil;
        if (outs.len > 1) outs[1] = .Nil;
        if (outs.len > 2) outs[2] = .Nil;
        if (args.len == 0 or args[0] != .String) {
            return self.fail("bad argument #1 to 'popen' (string expected)", .{});
        }

        const mode = if (args.len >= 2) switch (args[1]) {
            .String => |value| value.bytes(),
            else => return self.fail("bad argument #2 to 'popen' (string expected)", .{}),
        } else "r";
        const read_mode = std.mem.eql(u8, mode, "r") or std.mem.eql(u8, mode, "rb");
        const write_mode = std.mem.eql(u8, mode, "w") or std.mem.eql(u8, mode, "wb");
        if (!read_mode and !write_mode) return self.fail("invalid mode", .{});

        const command = args[0].String.bytes();
        var posix_argv = [_][]const u8{ "sh", "-c", command };
        var windows_argv = [_][]const u8{ "cmd.exe", "/D", "/S", "/C", command };
        const argv: []const []const u8 = switch (@import("builtin").os.tag) {
            .windows => windows_argv[0..],
            else => posix_argv[0..],
        };
        var child = std.process.spawn(stdio.activeIo(), .{
            .argv = argv,
            .stdin = if (write_mode) .pipe else .inherit,
            .stdout = if (read_mode) .pipe else .inherit,
            .stderr = .inherit,
        }) catch |err| {
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr(@errorName(err)) };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            self.last_builtin_out_count = @min(outs.len, 3);
            return;
        };

        const pipe = if (read_mode) child.stdout.? else child.stdin.?;
        if (read_mode) child.stdout = null else child.stdin = null;
        const file_v = self.allocManagedFileObject(pipe, read_mode, write_mode, true) catch |err| {
            child.kill(stdio.activeIo());
            return err;
        };
        const file_tbl = file_v.Table;
        const id = self.fileIdFromTable(file_tbl).?;
        self.open_processes.put(self.alloc, id, child) catch |err| {
            _ = self.closeManagedFile(file_tbl);
            child.kill(stdio.activeIo());
            return err;
        };

        if (outs.len > 0) outs[0] = file_v;
        self.last_builtin_out_count = @min(outs.len, 1);
    }

    fn builtinIoTmpfile(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = args;
        if (outs.len == 0) return;
        var tmp_out = [_]Value{.Nil};
        try self.builtinOsTmpname(&.{}, tmp_out[0..]);
        if (tmp_out[0] != .String) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("tmpname failed") };
            return;
        }
        const tmp = tmp_out[0].String.bytes();
        const f = try self.ioOpenPath(tmp, "w+", outs) orelse return;
        outs[0] = f;
    }

    fn readOneFormat(self: *Vm, file_v: Value, spec: Value) DispatchError!Value {
        const f = self.getManagedFile(file_v) orelse return self.fail("closed file", .{});
        const fb = self.getFileBuffer(file_v) orelse return self.fail("closed file", .{});
        if (spec == .Int) {
            if (spec.Int < 0) return self.fail("bad argument to 'read' (invalid format)", .{});
            const s = try self.readCountAlloc(f, fb, @intCast(spec.Int));
            return if (s) |ls| .{ .String = ls } else .Nil;
        }
        const fmt: []const u8 = if (spec == .String) spec.String.bytes() else return self.fail("bad argument to 'read' (invalid format)", .{});
        if (std.mem.eql(u8, fmt, "l") or std.mem.eql(u8, fmt, "*l")) {
            const s = try self.readLineAlloc(f, fb, false);
            return if (s) |ls| .{ .String = ls } else .Nil;
        }
        if (std.mem.eql(u8, fmt, "L") or std.mem.eql(u8, fmt, "*L")) {
            const s = try self.readLineAlloc(f, fb, true);
            return if (s) |ls| .{ .String = ls } else .Nil;
        }
        if (std.mem.eql(u8, fmt, "a") or std.mem.eql(u8, fmt, "*a") or std.mem.eql(u8, fmt, "all")) {
            const s = try self.readAllAlloc(f, fb);
            return .{ .String = s };
        }
        if (std.mem.eql(u8, fmt, "n") or std.mem.eql(u8, fmt, "*n")) {
            var tok = std.ArrayList(u8).empty;
            defer tok.deinit(self.alloc);
            while (true) {
                const b = readByte(f, fb) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
                if (b == null) break;
                if (std.ascii.isWhitespace(b.?)) continue;
                unreadByte(fb, b.?);
                break;
            }
            while (true) {
                const b = readByte(f, fb) catch |e| return self.fail("read error: {s}", .{@errorName(e)});
                if (b == null) break;
                const c = b.?;
                const ok = std.ascii.isDigit(c) or c == '+' or c == '-' or c == '.' or c == 'x' or c == 'X' or c == 'p' or c == 'P' or (c >= 'a' and c <= 'f') or (c >= 'A' and c <= 'F');
                if (!ok) {
                    unreadByte(fb, c);
                    break;
                }
                try tok.append(self.alloc, c);
            }
            if (tok.items.len == 0) return .Nil;
            const sfull = tok.items;
            var i: usize = 0;
            if (sfull[i] == '+' or sfull[i] == '-') {
                i += 1;
                if (i >= sfull.len) return .Nil;
            }
            var consume_len: usize = 0;
            var parsed: ?Value = null;

            const is_hex = i + 1 < sfull.len and sfull[i] == '0' and (sfull[i + 1] == 'x' or sfull[i + 1] == 'X');
            if (is_hex) {
                i += 2; // consume 0x
                var has_hex = false;
                while (i < sfull.len and ((sfull[i] >= '0' and sfull[i] <= '9') or (sfull[i] >= 'a' and sfull[i] <= 'f') or (sfull[i] >= 'A' and sfull[i] <= 'F'))) : (i += 1) has_hex = true;
                var had_dot = false;
                if (i < sfull.len and sfull[i] == '.') {
                    had_dot = true;
                    i += 1;
                    while (i < sfull.len and ((sfull[i] >= '0' and sfull[i] <= '9') or (sfull[i] >= 'a' and sfull[i] <= 'f') or (sfull[i] >= 'A' and sfull[i] <= 'F'))) : (i += 1) has_hex = true;
                }
                var had_exp = false;
                var exp_digits: usize = 0;
                if (has_hex and i < sfull.len and (sfull[i] == 'p' or sfull[i] == 'P')) {
                    had_exp = true;
                    i += 1;
                    if (i < sfull.len and (sfull[i] == '+' or sfull[i] == '-')) i += 1;
                    while (i < sfull.len and (sfull[i] >= '0' and sfull[i] <= '9')) : (i += 1) exp_digits += 1;
                }
                consume_len = i;
                const complete = has_hex and ((!had_dot and !had_exp) or (had_exp and exp_digits > 0));
                if (complete) {
                    const s = sfull[0..consume_len];
                    if (parseHexStringIntWrap(s)) |iv| {
                        parsed = .{ .Int = iv };
                    } else if (std.fmt.parseFloat(f64, s)) |n| {
                        parsed = .{ .Num = n };
                    } else |_| {}
                } else if (consume_len == 0) {
                    consume_len = 1;
                }
            } else {
                i = 0;
                if (sfull[i] == '+' or sfull[i] == '-') i += 1;
                var has_dec = false;
                while (i < sfull.len and (sfull[i] >= '0' and sfull[i] <= '9')) : (i += 1) has_dec = true;
                if (i < sfull.len and sfull[i] == '.') {
                    i += 1;
                    while (i < sfull.len and (sfull[i] >= '0' and sfull[i] <= '9')) : (i += 1) has_dec = true;
                }
                var had_exp = false;
                var exp_digits: usize = 0;
                if (has_dec and i < sfull.len and (sfull[i] == 'e' or sfull[i] == 'E')) {
                    had_exp = true;
                    i += 1;
                    if (i < sfull.len and (sfull[i] == '+' or sfull[i] == '-')) i += 1;
                    while (i < sfull.len and (sfull[i] >= '0' and sfull[i] <= '9')) : (i += 1) exp_digits += 1;
                }
                consume_len = i;
                const complete = has_dec and (!had_exp or exp_digits > 0);
                if (complete) {
                    const s = sfull[0..consume_len];
                    if (std.mem.indexOfAny(u8, s, ".eE") == null) {
                        if (std.fmt.parseInt(i64, s, 10)) |iv| {
                            parsed = .{ .Int = iv };
                        } else |_| {}
                    }
                    if (parsed == null) {
                        if (std.fmt.parseFloat(f64, s)) |n| {
                            parsed = .{ .Num = n };
                        } else |_| {}
                    }
                } else {
                    if (consume_len == 0) {
                        consume_len = if (sfull[0] == '+' or sfull[0] == '-' or sfull[0] == '.') 1 else 0;
                    }
                    if (consume_len == 0) return .Nil;
                }
            }
            // Overlong numerals: fail, but keep tail in stream.
            if (consume_len > 200) {
                const keep: usize = @min(@as(usize, 32), consume_len);
                const unread_n = sfull.len - keep;
                if (unread_n != 0) fb.pos -|= unread_n;
                return .Nil;
            }
            const unread_n = sfull.len - consume_len;
            if (unread_n != 0) fb.pos -|= unread_n;
            return parsed orelse .Nil;
        }
        return self.fail("bad argument to 'read' (invalid format)", .{});
    }

    fn currentInputFile(self: *Vm) Value {
        const io_v = self.getGlobal("io");
        if (io_v != .Table) return .Nil;
        return self.getFieldOpt(io_v.Table, "input_stream") orelse (self.getFieldOpt(io_v.Table, "stdin") orelse .Nil);
    }

    fn currentOutputFile(self: *Vm) Value {
        const io_v = self.getGlobal("io");
        if (io_v != .Table) return .Nil;
        const io_tbl = io_v.Table;
        return self.getFieldOpt(io_tbl, "output_stream") orelse (self.getFieldOpt(io_tbl, "stdout") orelse .Nil);
    }

    fn builtinIoRead(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        const file_v = self.currentInputFile();
        if (asFileTable(self, file_v) != null and !self.isStdFile(file_v) and self.getManagedFile(file_v) == null) {
            return self.fail(" input file is closed", .{});
        }
        if (!fileCanRead(self, file_v)) return self.fail(" input file is closed", .{});
        if (args.len == 0) {
            if (outs.len > 0) outs[0] = try self.readOneFormat(file_v, .{ .String = try self.internStr("l") });
            return;
        }
        var out_i: usize = 0;
        var i: usize = 0;
        while (i < args.len and out_i < outs.len) : (i += 1) {
            const v = try self.readOneFormat(file_v, args[i]);
            outs[out_i] = v;
            if (v == .Nil) break;
            out_i += 1;
        }
        self.last_builtin_out_count = out_i + @intFromBool(out_i < outs.len and out_i < args.len and outs[out_i] == .Nil);
    }

    fn makeLinesIter(self: *Vm, file_v: Value, auto_close: bool, fmts: []const Value) DispatchError!Value {
        const obj = try self.allocTableNoGc();
        const mt = try self.allocTableNoGc();
        const fmts_tbl = try self.allocTableNoGc();
        try self.setField(mt, "__call", .{ .Builtin = .io_lines_iter });
        obj.metatable = mt;
        try self.setField(obj, "__file", file_v);
        try self.setField(obj, "__auto_close", .{ .Bool = auto_close });
        try self.setField(obj, "__closed_error", .{ .Bool = false });
        const nfmts: usize = fmts.len;
        try self.tableResizeArray(fmts_tbl, @intCast(nfmts));
        for (0..nfmts) |i| fmts_tbl.array[i] = fmts[i];
        try self.setField(obj, "__fmts", .{ .Table = fmts_tbl });
        return .{ .Table = obj };
    }

    fn builtinIoLines(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        var file_v: Value = .Nil;
        var auto_close = false;
        var fmt_start: usize = 0;
        if (args.len == 0 or args[0] == .Nil) {
            file_v = self.currentInputFile();
            fmt_start = if (args.len == 0) 0 else 1;
        } else if (args[0] == .String) {
            var open_out = [_]Value{ .Nil, .Nil, .Nil };
            file_v = (try self.ioOpenPath(args[0].String.bytes(), "r", open_out[0..])) orelse {
                const msg = if (open_out[1] == .String) ioErrText(open_out[1].String.bytes()) else "cannot open file";
                return self.fail("cannot open file '{s}' ({s})", .{ args[0].String.bytes(), msg });
            };
            auto_close = true;
            fmt_start = 1;
        } else {
            file_v = args[0];
            fmt_start = 1;
        }
        if (asFileTable(self, file_v) == null) return self.fail("bad argument #1 to 'lines' (FILE* expected)", .{});
        const fmts = args[fmt_start..];
        if (fmts.len > 250) return self.fail("too many arguments", .{});
        const iter = try self.makeLinesIter(file_v, auto_close, fmts);
        outs[0] = iter;
        if (outs.len > 1) outs[1] = file_v;
        if (outs.len > 2) outs[2] = .Nil;
        if (auto_close and outs.len > 3) outs[3] = file_v;
        self.last_builtin_out_count = @min(if (auto_close) @as(usize, 4) else @as(usize, 3), outs.len);
    }

    fn builtinIoLinesIter(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0 or args[0] != .Table) return self.fail("bad argument #1 to 'lines' iterator", .{});
        const it = args[0].Table;
        const file_v = self.getFieldOpt(it, "__file") orelse .Nil;
        const closed_error = if (self.getFieldOpt(it, "__closed_error")) |v| (v == .Bool and v.Bool) else false;
        if (file_v == .Nil) {
            if (closed_error) return self.fail("file is already closed", .{});
            self.last_builtin_out_count = 0;
            return;
        }
        const fmt_tbl = if (self.getFieldOpt(it, "__fmts")) |v| if (v == .Table) v.Table else null else null;
        const fmt_count: usize = if (fmt_tbl) |t| t.asize else 0;
        const cnt = if (fmt_count == 0) 1 else fmt_count;
        var out_i: usize = 0;
        while (out_i < cnt and out_i < outs.len) : (out_i += 1) {
            const spec = if (fmt_count == 0) Value{ .String = try self.internStr("l") } else fmt_tbl.?.array[out_i];
            const v = try self.readOneFormat(file_v, spec);
            if (out_i == 0 and v == .Nil) {
                const auto_close = if (self.getFieldOpt(it, "__auto_close")) |av| (av == .Bool and av.Bool) else false;
                if (auto_close) {
                    if (asFileTable(self, file_v)) |t| {
                        _ = self.closeManagedFile(t);
                        _ = self.setField(t, "__closed", .{ .Bool = true }) catch {};
                    }
                    try self.setField(it, "__closed_error", .{ .Bool = true });
                }
                try self.setField(it, "__file", .Nil);
                self.last_builtin_out_count = 0;
                return;
            }
            outs[out_i] = v;
            if (v == .Nil) break;
        }
        self.last_builtin_out_count = out_i;
    }

    fn builtinIoFlush(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = args;
        if (outs.len == 0) return;
        const out_v = self.currentOutputFile();
        _ = self.getManagedFile(out_v) orelse {
            outs[0] = .{ .Bool = true };
            return;
        };
        if (!self.flushBufferedFile(out_v)) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("write error") };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return;
        }
        outs[0] = .{ .Bool = true };
    }

    fn builtinIoOutput(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        const io_v = self.getGlobal("io");
        if (io_v != .Table) {
            outs[0] = .Nil;
            return;
        }
        const io_tbl = io_v.Table;
        if (args.len == 0) {
            outs[0] = self.getFieldOpt(io_tbl, "output_stream") orelse (self.getFieldOpt(io_tbl, "stdout") orelse .Nil);
            return;
        }
        const old_out = self.getFieldOpt(io_tbl, "output_stream") orelse (self.getFieldOpt(io_tbl, "stdout") orelse .Nil);
        if (args[0] == .String) {
            var open_out = [_]Value{ .Nil, .Nil, .Nil };
            const file_v = try self.ioOpenPath(args[0].String.bytes(), "w", open_out[0..]) orelse {
                const msg = if (open_out[1] == .String) ioErrText(open_out[1].String.bytes()) else "cannot open file";
                return self.fail("cannot open file '{s}' ({s})", .{ args[0].String.bytes(), msg });
            };
            try self.setField(io_tbl, "output_stream", file_v);
            self.maybeCloseReplacedDefault(old_out, file_v);
            outs[0] = file_v;
            return;
        }
        const name = self.valueTypeName(args[0]);
        if (!std.mem.startsWith(u8, name, "FILE")) {
            return self.fail("bad argument #1 to 'output' (FILE* expected, got {s})", .{name});
        }
        try self.setField(io_tbl, "output_stream", args[0]);
        self.maybeCloseReplacedDefault(old_out, args[0]);
        outs[0] = args[0];
    }

    fn isStdFile(self: *Vm, v: Value) bool {
        const io_v = self.getGlobal("io");
        if (io_v != .Table) return false;
        const io_tbl = io_v.Table;
        const stdin_v = self.getFieldOpt(io_tbl, "stdin") orelse .Nil;
        const stdout_v = self.getFieldOpt(io_tbl, "stdout") orelse .Nil;
        const stderr_v = self.getFieldOpt(io_tbl, "stderr") orelse .Nil;
        return valuesEqual(v, stdin_v) or valuesEqual(v, stdout_v) or valuesEqual(v, stderr_v);
    }

    fn maybeCloseReplacedDefault(self: *Vm, old_v: Value, new_v: Value) void {
        if (valuesEqual(old_v, new_v) or self.isStdFile(old_v)) return;
        if (asFileTable(self, old_v)) |t| {
            _ = self.closeManagedFile(t);
            _ = self.setField(t, "__closed", .{ .Bool = true }) catch {};
        }
    }

    fn builtinIoClose(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .Nil;
            if (outs.len > 2) outs[2] = .Nil;
        }
        const io_v = self.getGlobal("io");
        if (io_v != .Table) return;
        const io_tbl = io_v.Table;
        const file_v = if (args.len == 0) (self.getFieldOpt(io_tbl, "output_stream") orelse (self.getFieldOpt(io_tbl, "stdout") orelse .Nil)) else args[0];
        const file_tbl = asFileTable(self, file_v) orelse {
            return self.fail("bad argument #1 to 'close' (FILE* expected, got {s})", .{self.valueTypeName(file_v)});
        };
        if (self.isStdFile(file_v)) {
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("cannot close standard file") };
            self.last_builtin_out_count = @min(outs.len, 2);
            return;
        }
        if (self.getFieldOpt(file_tbl, "__closed")) |v| {
            if (v == .Bool and v.Bool) {
                return self.fail("closed file", .{});
            }
        }
        try self.setField(file_tbl, "__closed", .{ .Bool = true });
        try self.writeManagedCloseResult(self.closeManagedFile(file_tbl), outs);
    }

    fn builtinFileClose(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .Nil;
        }
        if (args.len == 0) {
            return self.fail("bad argument #1 to 'close' (FILE* expected, got no value)", .{});
        }
        const file_v = args[0];
        const file_tbl = asFileTable(self, file_v) orelse {
            return self.fail("bad argument #1 to 'close' (FILE* expected, got {s})", .{self.valueTypeName(file_v)});
        };
        if (self.isStdFile(file_v)) {
            if (outs.len > 1) {
                outs[1] = .{ .String = try self.internStr("cannot close standard file") };
            }
            self.last_builtin_out_count = @min(outs.len, 2);
            return;
        }
        if (self.getFieldOpt(file_tbl, "__closed")) |v| {
            if (v == .Bool and v.Bool) {
                return self.fail("closed file", .{});
            }
        }
        try self.setField(file_tbl, "__closed", .{ .Bool = true });
        try self.writeManagedCloseResult(self.closeManagedFile(file_tbl), outs);
    }

    fn builtinFileMetaClose(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return;
        const file_tbl = asFileTable(self, args[0]) orelse return;
        if (self.isStdFile(args[0])) return;
        if (self.getFieldOpt(file_tbl, "__closed")) |v| {
            if (v == .Bool and v.Bool) return;
        }
        try self.setField(file_tbl, "__closed", .{ .Bool = true });
        _ = self.closeManagedFile(file_tbl);
        if (outs.len > 0) outs[0] = .{ .Bool = true };
    }

    fn builtinFileWrite(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'write' (FILE* expected)", .{});
        const file_v = args[0];
        if (!fileCanWrite(self, file_v)) {
            if (outs.len > 0) outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("bad file descriptor") };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return;
        }
        if (args.len == 1) {
            if (outs.len > 0) outs[0] = file_v;
            return;
        }
        _ = self.getManagedFile(file_v) orelse return self.fail("closed file", .{});
        var i: usize = 1;
        while (i < args.len) : (i += 1) {
            switch (args[i]) {
                .String, .Int, .Num => {},
                else => return self.fail("bad argument #{d} to 'write' (string expected)", .{i}),
            }
            const s = try self.valueToStringAlloc(args[i]);
            if (!(try self.writeBufferedFile(file_v, s))) {
                if (outs.len > 0) outs[0] = .Nil;
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("write error") };
                if (outs.len > 2) outs[2] = .{ .Int = 1 };
                return;
            }
        }
        if (outs.len > 0) outs[0] = file_v;
    }

    fn builtinFileRead(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'read' (FILE* expected)", .{});
        const file_v = args[0];
        if (!fileCanRead(self, file_v)) {
            if (outs.len > 0) outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("bad file descriptor") };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return;
        }
        if (args.len == 1) {
            if (outs.len > 0) outs[0] = try self.readOneFormat(file_v, .{ .String = try self.internStr("l") });
            return;
        }
        var out_i: usize = 0;
        var i: usize = 1;
        while (i < args.len and out_i < outs.len) : (i += 1) {
            const v = try self.readOneFormat(file_v, args[i]);
            outs[out_i] = v;
            if (v == .Nil) break;
            out_i += 1;
        }
        self.last_builtin_out_count = out_i + @intFromBool(out_i < outs.len and out_i + 1 < args.len and outs[out_i] == .Nil);
    }

    fn builtinFileSeek(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        // PUC Lua `f_seek` (liolib.c) calls C `fseek` which delegates to the
        // OS `lseek` syscall. On success it queries `ftell` for the new
        // position and returns it. On failure it returns `nil, err, errno`.
        //
        // We mirror that by computing the absolute target position from
        // `whence`/`offset` and then calling the OS seek via the Zig std.Io
        // vtable (`fileSeekTo`). If the OS rejects the seek (e.g. ESPIPE on a
        // pipe, ENVAL on a non-seekable fd) we return `nil, "Illegal seek",
        // errno` exactly like PUC Lua. On success we update `fb.pos` and
        // return it.
        //
        // Note: the Zig `fileSeekTo` wrapper discards the position returned by
        // the underlying `lseek` syscall, so for non-seekable-but-succeeding
        // fds (e.g. Linux ttys where `lseek` returns 0 regardless of offset)
        // we report the requested target rather than the true position. This
        // only affects stdin/stdout/stderr on interactive terminals; regular
        // files and pipes (the cases the test suite exercises) are exact.
        if (outs.len > 0) outs[0] = .Nil;
        if (args.len == 0) return self.fail("bad argument #1 to 'seek' (FILE* expected)", .{});
        const file_v = args[0];
        const f = self.getManagedFile(file_v) orelse {
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("closed file") };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return;
        };
        if (self.getFileBuffer(file_v)) |fb| {
            if (fb.pending.items.len != 0 and !self.flushBufferedFile(file_v)) {
                if (outs.len > 1) outs[1] = .{ .String = try self.internStr("write error") };
                if (outs.len > 2) outs[2] = .{ .Int = 1 };
                return;
            }
        }
        const whence: []const u8 = if (args.len >= 2 and args[1] == .String) args[1].String.bytes() else "cur";
        const offs: i64 = if (args.len >= 3) switch (args[2]) {
            .Int => |i| i,
            else => return self.fail("bad argument #3 to 'seek' (integer expected)", .{}),
        } else 0;
        const fb = self.getFileBuffer(file_v) orelse return;

        // Compute the absolute target position. For "cur" we use the tracked
        // `fb.pos`; for "end" we query the file length. A negative target is
        // rejected before touching the OS, matching PUC `fseek` semantics.
        const new_pos_i: i128 = if (std.mem.eql(u8, whence, "set"))
            @as(i128, @max(offs, 0))
        else if (std.mem.eql(u8, whence, "cur"))
            @as(i128, @intCast(fb.pos)) + offs
        else if (std.mem.eql(u8, whence, "end"))
            @as(i128, @intCast(f.length(stdio.activeIo()) catch 0)) + offs
        else
            return self.fail("bad argument #2 to 'seek' (invalid option)", .{});
        if (new_pos_i < 0) {
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("Invalid argument") };
            if (outs.len > 2) outs[2] = .{ .Int = if (@import("builtin").os.tag == .windows) 1 else 22 };
            return;
        }
        const target_pos: u64 = @intCast(new_pos_i);

        // Delegate to the OS seek. On pipes/sockets this fails with
        // `error.Unseekable` (ESPIPE/EINVAL), which we surface as
        // "Illegal seek" with errno 29 — the same string/errno PUC Lua
        // produces via `fseek` → `lseek` → `luaL_fileresult`.
        const io = stdio.activeIo();
        io.vtable.fileSeekTo(io.userdata, f.*, target_pos) catch {
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("Illegal seek") };
            if (outs.len > 2) outs[2] = .{ .Int = if (@import("builtin").os.tag == .windows) 1 else 29 };
            return;
        };

        // Seek succeeded: update the tracked position and return it.
        fb.pos = target_pos;
        if (outs.len > 0) outs[0] = .{ .Int = @intCast(fb.pos) };
    }

    fn builtinFileFlush(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'flush' (FILE* expected)", .{});
        _ = self.getManagedFile(args[0]) orelse {
            outs[0] = .Nil;
            return;
        };
        if (!self.flushBufferedFile(args[0])) {
            outs[0] = .Nil;
            if (outs.len > 1) outs[1] = .{ .String = try self.internStr("write error") };
            if (outs.len > 2) outs[2] = .{ .Int = 1 };
            return;
        }
        outs[0] = .{ .Bool = true };
    }

    fn builtinFileLines(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (args.len == 0) return self.fail("bad argument #1 to 'lines' (FILE* expected)", .{});
        if (args.len - 1 > 250) return self.fail("too many arguments", .{});
        if (outs.len > 0) {
            outs[0] = try self.makeLinesIter(args[0], false, args[1..]);
            if (outs.len > 1) outs[1] = args[0];
            if (outs.len > 2) outs[2] = .Nil;
            self.last_builtin_out_count = @min(@as(usize, 3), outs.len);
        }
    }

    fn builtinFileSetvbuf(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len > 0) outs[0] = .{ .Bool = true };
        if (args.len < 2 or args[1] != .String) return self.fail("bad argument #2 to 'setvbuf' (string expected)", .{});
        const fb = self.getFileBuffer(args[0]) orelse return;
        if (args[1].String == self.internStrAssume("full")) {
            fb.mode = .full;
        } else if (args[1].String == self.internStrAssume("no")) {
            fb.mode = .no;
        } else if (args[1].String == self.internStrAssume("line")) {
            fb.mode = .line;
        } else {
            return self.fail("bad argument #2 to 'setvbuf' (invalid option)", .{});
        }
    }

    fn builtinIoType(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) {
            outs[0] = .Nil;
            return;
        }
        const file_tbl = asFileTable(self, args[0]) orelse {
            outs[0] = .Nil;
            return;
        };
        if (self.getFieldOpt(file_tbl, "__closed")) |v| {
            if (v == .Bool and v.Bool) {
                outs[0] = .{ .String = try self.internStr("closed file") };
                return;
            }
        }
        outs[0] = .{ .String = try self.internStr("file") };
    }

    fn builtinFileGc(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        _ = outs;
        if (args.len == 0) return self.fail("no value", .{});
        const file_tbl = asFileTable(self, args[0]) orelse return;
        // Standard streams are long-lived (referenced from `io.stdin`/
        // `io.stdout`/`io.stderr`) and must never be closed by GC, matching
        // PUC Lua where `io.stdin`/`io.stdout`/`io.stderr` are never finalized.
        if (self.isStdFile(args[0])) return;
        _ = self.closeManagedFile(file_tbl);
        _ = self.setField(file_tbl, "__closed", .{ .Bool = true }) catch {};
    }

    fn mathArgToInt(self: *Vm, v: Value, what: []const u8) DispatchError!i64 {
        return switch (v) {
            .Int => |i| i,
            .Num => |n| blk: {
                if (!std.math.isFinite(n)) return self.fail("math.{s} expects integer", .{what});
                break :blk @intFromFloat(std.math.trunc(n));
            },
            else => return self.fail("math.{s} expects integer", .{what}),
        };
    }

    fn rotl64(x: u64, n: u6) u64 {
        return std.math.rotl(u64, x, n);
    }

    fn nextRandomU64(self: *Vm) u64 {
        const s0 = self.rng_state[0];
        const s1 = self.rng_state[1];
        const s2 = self.rng_state[2] ^ s0;
        const s3 = self.rng_state[3] ^ s1;
        const res = rotl64(s1 *% 5, 7) *% 9;
        self.rng_state[0] = s0 ^ s3;
        self.rng_state[1] = s1 ^ s2;
        self.rng_state[2] = s2 ^ (s1 << 17);
        self.rng_state[3] = rotl64(s3, 45);
        return res;
    }

    fn randomI2d(x: u64) f64 {
        const sx: i64 = @bitCast(x >> 11); // keep top 53 bits
        const scale = 0.5 / @as(f64, @floatFromInt(@as(u64, 1) << 52));
        var res = @as(f64, @floatFromInt(sx)) * scale;
        if (sx < 0) res += 1.0;
        return res;
    }

    fn randomProject(self: *Vm, ran0: u64, n: u64) u64 {
        var ran = ran0;
        var lim = n;
        var sh: u8 = 1;
        while ((lim & (lim +% 1)) != 0 and sh < 64) : (sh *= 2) {
            lim |= (lim >> @as(u6, @intCast(sh)));
        }
        while (true) {
            ran &= lim;
            if (ran <= n) return ran;
            ran = self.nextRandomU64();
        }
    }

    fn randomSetSeed(self: *Vm, n1: u64, n2: u64) void {
        self.rng_state[0] = n1;
        self.rng_state[1] = 0xff;
        self.rng_state[2] = n2;
        self.rng_state[3] = 0;
        var i: usize = 0;
        while (i < 16) : (i += 1) _ = self.nextRandomU64();
    }

    fn builtinMathRandom(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len > 2) return self.fail("wrong number of arguments", .{});
        const r = self.nextRandomU64();
        if (args.len == 0) {
            outs[0] = .{ .Num = randomI2d(r) };
            return;
        }
        if (args.len == 1) {
            const hi = try self.mathArgToInt(args[0], "random");
            if (hi == 0) {
                outs[0] = .{ .Int = @as(i64, @bitCast(r)) };
                return;
            }
            if (hi < 1) return self.fail("bad argument #1 to 'random' (interval is empty)", .{});
            const span: u64 = @intCast(hi);
            outs[0] = .{ .Int = @as(i64, @intCast((r % span) + 1)) };
            return;
        }
        const lo = try self.mathArgToInt(args[0], "random");
        const hi = try self.mathArgToInt(args[1], "random");
        if (lo > hi) return self.fail("bad arguments to 'random' (interval is empty)", .{});
        const low_u: u64 = @bitCast(lo);
        const hi_u: u64 = @bitCast(hi);
        const p = self.randomProject(r, hi_u -% low_u);
        outs[0] = .{ .Int = @bitCast(p +% low_u) };
    }

    fn builtinMathRandomseed(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        var n1: u64 = 0;
        var n2: u64 = 0;
        if (args.len == 0) {
            n1 = self.nextRandomU64();
            n2 = self.nextRandomU64();
        } else {
            const s1: i64 = try self.mathArgToInt(args[0], "randomseed");
            const s2: i64 = if (args.len >= 2) try self.mathArgToInt(args[1], "randomseed") else 0;
            n1 = @bitCast(s1);
            n2 = @bitCast(s2);
        }
        self.randomSetSeed(n1, n2);
        if (outs.len > 0) outs[0] = .{ .Int = @bitCast(n1) };
        if (outs.len > 1) outs[1] = .{ .Int = @bitCast(n2) };
    }

    fn builtinMathTointeger(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) {
            outs[0] = .Nil;
            return;
        }
        switch (args[0]) {
            .Int => |i| outs[0] = .{ .Int = i },
            .Num => |n| {
                if (std.math.isFinite(n) and @floor(n) == n and n >= -9_223_372_036_854_775_808.0 and n < 9_223_372_036_854_775_808.0) {
                    outs[0] = .{ .Int = @as(i64, @intFromFloat(n)) };
                } else {
                    outs[0] = .Nil;
                }
            },
            .String => {
                var tmp: [1]Value = .{.Nil};
                try self.builtinTonumber(args[0..1], tmp[0..]);
                switch (tmp[0]) {
                    .Int => outs[0] = tmp[0],
                    .Num => |n| {
                        if (std.math.isFinite(n) and @floor(n) == n and n >= -9_223_372_036_854_775_808.0 and n < 9_223_372_036_854_775_808.0) {
                            outs[0] = .{ .Int = @as(i64, @intFromFloat(n)) };
                        } else {
                            outs[0] = .Nil;
                        }
                    },
                    else => outs[0] = .Nil,
                }
            },
            else => outs[0] = .Nil,
        }
    }

    fn builtinMathSin(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'sin' (number expected, got nil)", .{});
        const x: f64 = switch (args[0]) {
            .Int => |i| @floatFromInt(i),
            .Num => |n| n,
            else => return self.fail("bad argument #1 to 'sin' (number expected, got {s})", .{self.valueTypeName(args[0])}),
        };
        outs[0] = .{ .Num = std.math.sin(x) };
    }

    fn builtinMathCos(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'cos' (number expected, got nil)", .{});
        const x: f64 = switch (args[0]) {
            .Int => |i| @floatFromInt(i),
            .Num => |n| n,
            else => return self.fail("bad argument #1 to 'cos' (number expected, got {s})", .{self.valueTypeName(args[0])}),
        };
        outs[0] = .{ .Num = std.math.cos(x) };
    }

    fn mathArgToNum(self: *Vm, v: Value, what: []const u8, argn: usize) DispatchError!f64 {
        return switch (v) {
            .Int => |i| @floatFromInt(i),
            .Num => |n| n,
            else => self.fail("bad argument #{d} to '{s}' (number expected, got {s})", .{ argn, what, self.valueTypeName(v) }),
        };
    }

    fn builtinMathTan(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'tan' (number expected, got nil)", .{});
        const x = try self.mathArgToNum(args[0], "tan", 1);
        outs[0] = .{ .Num = std.math.tan(x) };
    }

    fn builtinMathAsin(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("bad argument #1 to 'asin' (number expected, got nil)", .{});
