    fn builtinMathMin(self: *Vm, args: []const Value, outs: []Value) DispatchError!void {
        if (outs.len == 0) return;
        if (args.len == 0) return self.fail("value expected", .{});
        // Keep it simple: treat numbers as f64 if any arg is float.
        var use_float = false;
        for (args) |v| switch (v) {
            .Int => {},
            .Num => use_float = true,
            else => return self.fail("math.min expects numbers", .{}),
        };
        if (use_float) {
            var m: f64 = switch (args[0]) {
                .Int => |i| @floatFromInt(i),
                .Num => |n| n,
                else => unreachable,
            };
            for (args[1..]) |v| {
                const x: f64 = switch (v) {
                    .Int => |i| @floatFromInt(i),
                    .Num => |n| n,
                    else => unreachable,
                };
                if (x < m) m = x;
            }
            outs[0] = .{ .Num = m };
        } else {
            var m: i64 = args[0].Int;
            for (args[1..]) |v| {
                const x: i64 = v.Int;
                if (x < m) m = x;
            }
            outs[0] = .{ .Int = m };
        }
    }

