            };
            if (iv < 0 or iv > 255) return self.fail("string.char value out of range", .{});
            try out.append(self.alloc, @intCast(iv));
        }
        outs[0] = .{ .String = try self.internStr(try out.toOwnedSlice(self.alloc)) };
    }

