                else => if (try self.callBinaryMetamethod(lhs, rhs, "__mul", "mul")) |v| v else self.failArithmeticOperands(lhs, rhs),
            },
            .Num => |ln| switch (r) {
                .Int => |ri| .{ .Num = ln * @as(f64, @floatFromInt(ri)) },
                .Num => |rn| .{ .Num = ln * rn },
                else => if (try self.callBinaryMetamethod(lhs, rhs, "__mul", "mul")) |v| v else self.failArithmeticOperands(lhs, rhs),
