    defer arena.deinit();
    const aalloc = arena.allocator();

    const src = Source{
        .name = "<test>",
        .bytes = "x = {a = 1, [2] = 3, 4}\n" ++
            "return x.a + x[2]\n",
    };

    var lex = Lexer.init(src);
    var p = try Parser.init(&lex);

    var ast_arena = ast.AstArena.init(aalloc);
